    'zanzibar_why_1_title' => 'Contraste parfait',
    'zanzibar_why_1_desc' => 'Échangez les game drives à l\'aube contre des matinées tranquilles et une eau chaude, et la poussière de la savane contre l\'air marin.',
    'zanzibar_why_2_title' => 'Un voyage, deux mondes',
    'zanzibar_why_2_desc' => 'Même visa, même devise, un simple vol intérieur : pas de séjour séparé à organiser.',
    'zanzibar_why_3_title' => 'Nous gérons la logistique',
    'zanzibar_why_3_desc' => 'Vols, transferts et hôtel réservés dans le cadre de votre itinéraire. Vous n\'avez qu\'à arriver et déballer vos affaires.',

    'zanzibar_gallery_badge' => 'L\'île',
