    'zanzibar_beaches_badge' => 'Choisissez votre côte',
    'zanzibar_beaches_title' => 'Quelle plage vous convient',
    'zanzibar_beaches_intro' => 'L\'île est petite, mais les côtes sont très différentes. Les marées comptent plus que ne l\'imaginent la plupart des visiteurs.',
    'zanzibar_beach_north_region' => 'Nord',
    'zanzibar_beach_north_name' => 'Nungwi et Kendwa',
    'zanzibar_beach_north_desc' => 'Les seules plages où l\'on peut se baigner à toute heure de marée. La partie la plus animée de l\'île, avec le plus d\'hôtels et de restaurants, et les plus beaux couchers de soleil.',
    'zanzibar_beach_north_best' => 'Idéal pour : première visite, baignade, vie nocturne',
    'zanzibar_beach_se_region' => 'Sud-est',
    'zanzibar_beach_se_name' => 'Paje et Jambiani',
    'zanzibar_beach_se_desc' => 'Vaste lagon, marées fortes et vent constant : la côte du kitesurf. Plus calme, plus jeune et plus détendue que le nord.',
    'zanzibar_beach_se_best' => 'Idéal pour : kitesurf, longues promenades, bon rapport qualité-prix',
    'zanzibar_beach_east_region' => 'Est et Sud',
    'zanzibar_beach_east_name' => 'Matemwe et Kizimkazi',
    'zanzibar_beach_east_desc' => 'Matemwe fait face à l\'atoll de Mnemba, le meilleur spot de snorkeling de l\'île. Kizimkazi est le point de départ des excursions dauphins.',
    'zanzibar_beach_east_best' => 'Idéal pour : snorkeling, plongée, tranquillité',
    'zanzibar_tide_note' => '<strong>À propos des marées :</strong> sur les côtes est et sud-est, la mer se retire de plusieurs centaines de mètres à marée basse et la baignade est impossible une partie de la journée. Ce n\'est pas un problème, c\'est simplement le fonctionnement de l\'île, mais si pouvoir nager à tout moment est important pour vous, choisissez le nord.',

    'zanzibar_excursions_badge' => 'Au-delà de la plage',
    'zanzibar_excursions_title' => 'Excursions à ne pas manquer',
    'zanzibar_exc_stonetown_title' => 'Stone Town',
    'zanzibar_exc_stonetown_desc' => 'Un site classé au patrimoine mondial de l\'UNESCO : portes sculptées, ancien marché aux esclaves, marché nocturne de Forodhani. Une demi-journée avec un guide local.',
    'zanzibar_exc_spice_title' => 'Tour des épices',
    'zanzibar_exc_spice_desc' => 'Les plantations qui ont donné son nom à l\'île : girofle, vanille, muscade et cannelle, dégustées directement sur l\'arbre.',
    'zanzibar_exc_safariblue_title' => 'Safari Blue',
    'zanzibar_exc_safariblue_desc' => 'Une journée complète en dhow : bancs de sable, snorkeling, déjeuner de fruits de mer sur l\'île de Kwale et canaux de mangrove.',
    'zanzibar_exc_jozani_title' => 'Forêt de Jozani',
    'zanzibar_exc_jozani_desc' => 'Le dernier habitat du colobe rouge, présent nulle part ailleurs sur terre. Deux heures, facilement combinées avec la côte sud.',
    'zanzibar_exc_mnemba_title' => 'Atoll de Mnemba',
    'zanzibar_exc_mnemba_desc' => 'Le meilleur spot de snorkeling et de plongée de l\'île, accessible en bateau depuis Matemwe.',
    'zanzibar_exc_prison_title' => 'Prison Island',
    'zanzibar_exc_prison_desc' => 'Des tortues géantes d\'Aldabra, certaines âgées de plus d\'un siècle, à une courte traversée en bateau de Stone Town.',

    'zanzibar_when_badge' => 'Planification',
    'zanzibar_when_title' => 'Quand y aller',
    'zanzibar_when_dry_period' => 'Juin – Octobre',
    'zanzibar_when_dry_temp' => '26–30°C',
    'zanzibar_when_dry_desc' => 'Sec, ensoleillé et moins humide. La haute saison, prolongement naturel d\'un safari en saison sèche.',
    'zanzibar_when_dry_tag' => 'Idéal',
    'zanzibar_when_summer_period' => 'Décembre – Février',
    'zanzibar_when_summer_temp' => '28–32°C',
    'zanzibar_when_summer_desc' => 'Chaud, mer calme, excellente visibilité pour la plongée. Averses courtes possibles.',
    'zanzibar_when_summer_tag' => 'Très bon',
    'zanzibar_when_long_rains_period' => 'Mars – Mai',
    'zanzibar_when_long_rains_temp' => '27–31°C',
    'zanzibar_when_long_rains_desc' => 'La grande saison des pluies. Prix les plus bas et plages désertes, mais certains hôtels ferment en avril et mai.',
    'zanzibar_when_long_rains_tag' => 'Basse saison',
    'zanzibar_when_nov_period' => 'Novembre',
    'zanzibar_when_nov_temp' => '27–31°C',
    'zanzibar_when_nov_desc' => 'Petites pluies : brèves averses en après-midi, sinon ensoleillé. Bon rapport qualité-prix avant l\'affluence de décembre.',
    'zanzibar_when_nov_tag' => 'Bon rapport qualité-prix',

    'zanzibar_featured_badge' => 'Combinaison la plus demandée',
    'zanzibar_featured_title' => 'Safari 7 jours + Zanzibar',
    'zanzibar_featured_desc' => '5 nuits de safari sur le circuit nord, 2 nuits de détente à Zanzibar, vol intérieur inclus.',
    'zanzibar_featured_price' => 'à partir de 2 200 € par personne',
    'zanzibar_featured_cta' => 'Voir ce forfait',

    'zanzibar_practical_badge' => 'Bon à savoir',
    'zanzibar_practical_title' => 'Informations pratiques',
    'zanzibar_practical_entry_title' => 'Conditions d\'entrée',
    'zanzibar_practical_entry_desc' => 'Zanzibar fait partie de la Tanzanie, le même visa s\'applique donc. Depuis 2024, une assurance émise par un prestataire agréé de Zanzibar est également requise à l\'arrivée ; elle coûte environ 44 USD et nous pouvons l\'organiser avec votre réservation.',
    'zanzibar_practical_dress_title' => 'Tenue et coutumes',
    'zanzibar_practical_dress_desc' => 'Zanzibar est à majorité musulmane. Le maillot de bain convient sur la plage et à votre hôtel, mais couvrez les épaules et les genoux à Stone Town et dans les villages. Pendant le Ramadan, de nombreux restaurants hors des complexes hôteliers ferment en journée.',
    'zanzibar_practical_flight_title' => 'Comment s\'y rendre depuis le safari',
    'zanzibar_practical_flight_desc' => 'Un vol direct depuis les pistes du Serengeti prend environ 1 heure 30 ; depuis Arusha ou l\'aéroport du Kilimandjaro, environ une heure. Nous réservons ces vols intérieurs dans le cadre de votre itinéraire.',
    'zanzibar_practical_malaria_title' => 'Paludisme',
    'zanzibar_practical_malaria_desc' => 'Zanzibar est une zone à risque de paludisme. Une prophylaxie est recommandée (demandez à votre médecin ou à un centre de vaccination) et utilisez un répulsif au crépuscule. Buvez de l\'eau en bouteille ou filtrée.',

    'zanzibar_faq_title' => 'Questions courantes',
    'zanzibar_faq_q1' => 'Combien de jours ajouter pour Zanzibar ?',
    'zanzibar_faq_a1' => 'Trois nuits est le minimum pour que cela ressemble à des vacances plutôt qu\'à une escale. Quatre à cinq jours vous laissent le temps pour une journée plage, une excursion et Stone Town sans vous presser.',
    'zanzibar_faq_q2' => 'Zanzibar est-il inclus dans le prix du safari ?',
    'zanzibar_faq_a2' => 'Non, c\'est une extension optionnelle. Nous la chiffrons séparément de votre safari afin que vous voyiez exactement ce qu\'elle ajoute, vol intérieur inclus.',
    'zanzibar_faq_q3' => 'Quelle plage choisir pour une première visite ?',
    'zanzibar_faq_a3' => 'Nungwi ou Kendwa au nord : baignade possible à toute heure de marée, le plus grand choix d\'hôtels et de restaurants, et l\'introduction la plus simple à l\'île.',
    'zanzibar_faq_q4' => 'Faut-il des vaccins supplémentaires pour Zanzibar ?',
    'zanzibar_faq_a4' => 'Aucun vaccin au-delà de ce qui est requis pour la Tanzanie continentale. La prophylaxie antipaludique est recommandée, et l\'assurance locale est obligatoire à l\'arrivée.',

    'zanzibar_cta_title' => 'Organisez votre voyage avec nous',
    'zanzibar_cta_intro' => 'Envoyez-nous vos dates, la taille de votre groupe et votre budget. Nous répondons avec un itinéraire détaillé et une répartition complète des prix, sans engagement.',
    'zanzibar_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'zanzibar_cta_contact_form' => 'Formulaire de contact',

    'trekking_meta_title' => 'Trekking au Kilimandjaro et au mont Meru | Serengeti Budget Safari',
    'trekking_meta_description' => 'Gravissez le Kilimandjaro avec un opérateur local d\'Arusha : itinéraires Machame, Lemosho, Marangu, Rongai et Northern Circuit, ainsi que le mont Meru, l\'Ol Doinyo Lengai et les monts Usambara.',
    'trekking_hero_badge' => 'Trekking',
    'trekking_hero_title_1' => 'Trekking au',
    'trekking_hero_title_2' => 'Kilimandjaro',
    'trekking_hero_sub' => "Le plus haut sommet d'Afrique à 5 895 m, ainsi que le mont Meru, l'Ol Doinyo Lengai et les collines Usambara, gravis avec notre propre équipe de montagne.",
    'trekking_hero_cta_quote' => 'Demander un devis',

    'trekking_routes_badge' => 'Choisissez votre voie',
    'trekking_routes_title' => 'Choisissez votre itinéraire',
    'trekking_routes_intro' => 'La montagne n\'est pas technique : le défi, c\'est l\'altitude. Plus l\'itinéraire est long, mieux votre corps s\'acclimate et plus vos chances d\'atteindre Uhuru Peak augmentent.',

    'trekking_route_lemosho_tagline' => 'Meilleurs paysages et acclimatation',
    'trekking_route_lemosho_name' => 'Lemosho',
    'trekking_route_lemosho_days' => '7 à 8 jours',
    'trekking_route_lemosho_desc' => 'Un départ tranquille à travers la forêt, rejoignant Machame plus haut. Le meilleur profil d\'acclimatation de tous les itinéraires.',
    'trekking_route_lemosho_success' => 'Le plus élevé',

    'trekking_route_machame_tagline' => 'La « Whiskey Route » · la plus populaire',
    'trekking_route_machame_name' => 'Machame',
    'trekking_route_machame_days' => '6 à 7 jours',
    'trekking_route_machame_desc' => 'Panoramique, escarpé par endroits, un bon profil d\'acclimatation. L\'itinéraire choisi par la plupart des grimpeurs.',
    'trekking_route_machame_success' => 'Élevé',

    'trekking_route_northern_tagline' => 'Sentiers les plus calmes, itinéraire le plus long',
    'trekking_route_northern_name' => 'Northern Circuit',
    'trekking_route_northern_days' => '9 jours',
    'trekking_route_northern_desc' => 'Presque un tour complet de la montagne. L\'itinéraire le plus long, avec très peu d\'autres groupes sur le sentier.',
    'trekking_route_northern_success' => 'Le plus élevé',

    'trekking_route_rongai_tagline' => 'Le plus sec pendant les mois pluvieux',
    'trekking_route_rongai_name' => 'Rongai',
    'trekking_route_rongai_days' => '6 à 7 jours',
    'trekking_route_rongai_desc' => 'Approche par le versant nord, plus sec. Le meilleur choix si vous grimpez en dehors de la principale saison sèche.',
    'trekking_route_rongai_success' => 'Bon',

    'trekking_route_marangu_tagline' => 'Des huttes plutôt que des tentes',
    'trekking_route_marangu_name' => 'Marangu',
    'trekking_route_marangu_days' => '5 à 6 jours',
    'trekking_route_marangu_desc' => 'Le seul itinéraire avec hébergement en huttes. Même chemin à la montée et à la descente, et l\'option la plus courte.',
    'trekking_route_marangu_success' => 'Plus faible',

    'trekking_routes_note' => 'Si vous avez les jours disponibles, prenez l\'itinéraire le plus long. La nuit supplémentaire est l\'assurance la moins chère contre le mal des montagnes.',

    'trekking_included_title' => 'Ce que comprend chaque ascension',
    'trekking_included_subtitle' => 'La même tarification transparente que nos safaris, sans frais cachés une fois sur la montagne.',
    'trekking_included_heading' => 'Inclus',
    'trekking_included_1' => 'Frais de parc, frais de camping ou d\'hébergement en hutte et frais de secours',
    'trekking_included_2' => 'Guide de montagne certifié, guides assistants, cuisinier et porteurs',
    'trekking_included_3' => 'Tous les repas sur la montagne et l\'eau potable',
    'trekking_included_4' => 'Tentes, matelas de couchage, tente-cantine et équipement de cuisine',
    'trekking_included_5' => 'Contrôles à l\'oxymètre de pouls et une trousse de premiers secours portée par le guide',
    'trekking_included_6' => 'Transferts entre Arusha et le point de départ',
    'trekking_included_7' => 'Deux nuits à Arusha, avant et après l\'ascension',
    'trekking_excluded_heading' => 'Non inclus',
    'trekking_excluded_1' => 'Vols internationaux et visa',
    'trekking_excluded_2' => 'Assurance voyage couvrant le trekking jusqu\'à 6 000 m (obligatoire)',
    'trekking_excluded_3' => 'Équipement personnel et sac de couchage (location disponible)',
    'trekking_excluded_4' => 'Pourboires pour l\'équipe de montagne',
    'trekking_excluded_5' => 'Oxygène portable ou porteur personnel, sur demande',

    'trekking_other_badge' => 'Au-delà du Kilimandjaro',
    'trekking_other_title' => 'Autres montagnes',
    'trekking_meru_name' => 'Mont Meru, 4 566 m',
    'trekking_meru_desc' => 'Trois ou quatre jours dans le parc national d\'Arusha, en marchant avec un ranger armé au milieu des buffles et des girafes. La meilleure acclimatation possible avant le Kilimandjaro.',
    'trekking_lengai_name' => 'Ol Doinyo Lengai, 2 962 m',
    'trekking_lengai_desc' => 'La « Montagne de Dieu » des Maasaï, un volcan actif gravi de nuit pour atteindre le bord du cratère au lever du soleil. Raide, chaud et vraiment exigeant.',
    'trekking_usambara_name' => 'Usambara et Udzungwa',
    'trekking_usambara_desc' => 'Montagnes verdoyantes, cascades et villages, parcourus sur deux à quatre jours à basse altitude. Une bonne option pendant la saison des pluies ou avec des enfants.',

    'trekking_guide_badge' => 'Aller plus loin',
    'trekking_guide_title' => 'Lire le guide complet du parc',
    'trekking_guide_intro' => 'Tout sur le parc national du Kilimandjaro en un seul endroit : les sept itinéraires comparés avec leurs taux de réussite, les frais de parc 2026 détaillés, le mal des montagnes expliqué, et comment traiter les porteurs.',
    'trekking_guide_kili_badge' => 'Guide du parc',
    'trekking_guide_kili_title' => 'Parc national du Kilimandjaro',
    'trekking_guide_kili_desc' => 'Cinq zones climatiques, sept itinéraires, 5 895 m. Les frais de parc seuls s\'élèvent à environ 956 $ pour une ascension de sept jours. Nous vous montrons exactement comment ce montant est calculé.',
    'trekking_guide_kili_cta' => 'Guide complet du Kilimandjaro',
    'trekking_guide_meru_badge' => 'Guide du parc',
    'trekking_guide_meru_title' => 'Parc national d\'Arusha et mont Meru',
    'trekking_guide_meru_desc' => 'Le Meru, à 4 566 m, offre la meilleure acclimatation possible avant le Kilimandjaro, et constitue à lui seul une montagne superbe et presque déserte.',
    'trekking_guide_meru_cta' => 'Guide complet du parc national d\'Arusha',

    'trekking_faq_title' => 'Avant de réserver',
    'trekking_faq_q1' => 'Ai-je besoin d\'expérience en escalade ?',
    'trekking_faq_a1' => 'Non. Le Kilimandjaro est une longue marche, pas une escalade : aucune technique de corde ni terrain technique. Ce qu\'il demande, c\'est une endurance pour six à neuf jours de marche et la capacité à supporter l\'air raréfié. Entraînez-vous en marchant en montée pendant plusieurs heures d\'affilée.',
    'trekking_faq_q2' => 'Quelle est la meilleure période pour grimper ?',
    'trekking_faq_a2' => 'De janvier à début mars et de juin à octobre. Avril, mai et novembre sont les mois humides : la montagne reste praticable, mais les sentiers sont glissants et les vues souvent bouchées. Rongai est l\'itinéraire le plus sec dans des conditions limites.',
    'trekking_faq_q3' => 'Qu\'en est-il du mal des montagnes ?',
    'trekking_faq_a3' => 'Maux de tête légers et essoufflement sont normaux au-dessus de 4 000 m. Nos guides vérifient la saturation en oxygène deux fois par jour et portent une trousse de premiers secours. La règle sur nos ascensions est simple : si un guide juge que vous devez redescendre, vous redescendez. Personne n\'est poussé à continuer.',

    'trekking_cta_title' => 'Organisez votre voyage avec nous',
    'trekking_cta_intro' => 'Envoyez-nous vos dates, la taille de votre groupe et votre budget. Nous répondons avec un itinéraire détaillé et une répartition complète des prix, sans engagement.',
    'trekking_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'trekking_cta_contact_form' => 'Formulaire de contact',

    'groups_meta_title' => 'Safaris en groupe partagé Tanzanie | Serengeti Budget Safari',
    'groups_meta_description' => 'Rejoignez un safari en groupe programmé en Tanzanie et partagez le coût d\'un 4x4 privé sans partager l\'expérience. Départs fixes, petits groupes, adapté aux voyageurs seuls.',
    'groups_hero_badge' => 'Safaris en groupe partagé',
    'groups_hero_title_1' => 'Rejoignez un safari,',
    'groups_hero_title_2' => 'pas une foule',
    'groups_hero_sub' => 'Petits départs partagés pour voyageurs seuls et couples : le prix d\'un groupe, la sensation d\'un voyage privé.',
    'groups_hero_cta_quote' => 'Renseignez-vous sur le prochain départ',

    'groups_how_badge' => 'Comment ça marche',
    'groups_how_title' => 'De la demande au véhicule',
    'groups_how_1_title' => 'Indiquez-nous vos dates',
    'groups_how_1_desc' => 'Envoyez-nous le mois où vous souhaitez voyager et le nombre de jours dont vous disposez.',
    'groups_how_2_title' => 'Nous vous associons à un départ',
    'groups_how_2_desc' => 'Nous vérifions quel groupe programmé est le plus proche de vos dates et confirmons les places disponibles.',
    'groups_how_3_title' => 'Vous rejoignez un petit groupe',
    'groups_how_3_desc' => 'Maximum 6 personnes par véhicule, réparties entre voyageurs partageant les mêmes dates.',
    'groups_how_4_title' => 'Un 4x4 partagé, un guide',
    'groups_how_4_desc' => 'Même guide, même véhicule et même itinéraire qu\'un safari privé, à un prix partagé.',

    'groups_why_badge' => 'Pourquoi rejoindre un groupe',
    'groups_why_title' => 'Conçu pour les voyageurs seuls et les couples',
    'groups_why_1_title' => 'Coût par personne réduit',
    'groups_why_1_desc' => 'Les frais de parc et le véhicule sont des coûts fixes ; les partager avec 3 à 5 autres voyageurs réduit considérablement votre prix.',
    'groups_why_2_title' => 'Rencontrer des gens, pas des inconnus',
    'groups_why_2_desc' => 'Les groupes restent petits (max 6) et sont assortis par dates de voyage, non assemblés au hasard. La plupart des clients se connaissent dès le deuxième jour.',
    'groups_why_3_title' => 'Même qualité, aucun compromis',
    'groups_why_3_desc' => 'Le même standard de guide, de 4x4 et d\'itinéraire que nos safaris privés. Vous partagez le véhicule, pas l\'expérience.',

