    'groups_faq_title' => 'Questions courantes',
    'groups_faq_q1' => 'Que se passe-t-il si un départ ne se remplit pas ?',
    'groups_faq_a1' => 'Nos départs programmés fonctionnent avec un minimum de 2 voyageurs. Si moins de personnes ont réservé, nous vous en informerons à l\'avance plutôt que d\'annuler à la dernière minute. Vous pourrez attendre la prochaine date ou demander un safari privé à un prix ajusté.',
    'groups_faq_q2' => 'Puis-je réserver un safari en groupe seul ?',
    'groups_faq_a2' => 'Oui, la plupart de nos voyageurs en groupe sont des voyageurs seuls. Vous partagerez le véhicule et le guide avec un petit nombre d\'autres voyageurs aux mêmes dates, sans être le seul client.',
    'groups_faq_q3' => 'Combien de temps à l\'avance dois-je réserver ?',
    'groups_faq_a3' => 'Pour juin à octobre (haute saison), visez 2 à 3 mois à l\'avance. En dehors de cette période, 3 à 4 semaines suffisent généralement, mais écrivez-nous tôt si vos dates sont fixes.',
    'groups_faq_q4' => 'Les couples ou amis peuvent-ils voyager ensemble dans un safari en groupe ?',
    'groups_faq_a4' => 'Oui, vous partagerez le véhicule avec d\'autres voyageurs mais serez assis ensemble en couple ou petit groupe. Nous complétons simplement les places restantes avec d\'autres clients aux mêmes dates.',

    'pkg3d_meta_title' => 'Safari Serengeti 3 jours | Serengeti Budget Safari',
    'pkg3d_meta_description' => 'Un safari de 3 jours à travers le Serengeti central et le cratère du Ngorongoro : Big Five, prédateurs, 4x4 privé, à partir de 1 000 € par personne. Le prix baisse automatiquement pour les groupes plus grands.',
    'pkg3d_hero_badge' => 'Meilleure vente',
    'pkg3d_hero_title' => 'Safari Serengeti 3 jours',
    'pkg3d_hero_sub' => 'Serengeti central et cratère du Ngorongoro : le moyen le plus rapide de voir les Big Five sans précipiter le voyage.',

    'pkg3d_fact_duration' => 'Durée',
