    'pkg3d_calc_wa_template' => "Bonjour, je suis intéressé(e) par le Safari Serengeti 3 jours pour {people} personnes. Prix estimé : {pp} p.p. ({total} au total). Pouvez-vous confirmer la disponibilité ?",

    'pkg3d_itinerary_badge' => 'Jour par jour',
    'pkg3d_itinerary_title' => 'Votre itinéraire',
    'pkg3d_itinerary_intro' => 'Chaque étape, chaque trajet, chaque repas : voici exactement à quoi ressembleront vos trois jours.',

    'pkg3d_day1_title' => 'Arusha au Serengeti',
    'pkg3d_day1_mood' => 'Karibu Sana, bienvenue en Tanzanie.',
    'pkg3d_day1_tl1_time' => '07h00',
    'pkg3d_day1_tl1_title' => 'Prise en charge à Arusha',
    'pkg3d_day1_tl1_desc' => 'Votre chauffeur-guide vous retrouve à votre hôtel, Land Cruiser chargé et prêt. C\'est le moment où le voyage commence réellement, tout ce qui précède n\'était que planification.',
    'pkg3d_day1_tl2_time' => '09h30',
    'pkg3d_day1_tl2_title' => 'Hautes terres du Ngorongoro',
    'pkg3d_day1_tl2_desc' => 'La route grimpe dans une forêt d\'altitude fraîche et brumeuse. Un court arrêt au point de vue du cratère vous offre votre premier regard sur la caldeira, et la plupart des clients se taisent un instant à cet endroit.',
    'pkg3d_day1_tl3_time' => '12h00',
    'pkg3d_day1_tl3_title' => 'Descente vers le Serengeti',
    'pkg3d_day1_tl3_desc' => 'Les hautes terres disparaissent derrière vous et les plaines s\'ouvrent : c\'est le « Serengeti » que les Maasaï ont nommé pour son immensité. Le déjeuner est un pique-nique avec une vue que peu de restaurants peuvent égaler.',
    'pkg3d_day1_tl4_time' => '15h30',
    'pkg3d_day1_tl4_title' => 'Premier game drive',
    'pkg3d_day1_tl4_desc' => 'Vous rejoindrez le camp en passant par la brousse, pas par la route, lors d\'un game drive de l\'après-midi qui a produit plus d\'observations de lions le premier jour que nous ne pouvons en compter. Lentement, le camp apparaît.',
    'pkg3d_day1_tl5_time' => '18h30',
    'pkg3d_day1_tl5_title' => 'Camp, dîner, première nuit sous la tente',
    'pkg3d_day1_tl5_desc' => 'Installez-vous dans votre tente avant la tombée de la nuit. Le dîner est servi sous les étoiles, et quelque part là-bas, le Serengeti est déjà éveillé. Vous vous endormirez probablement à son rythme.',
    'pkg3d_day1_drive' => '4 à 5 heures de route',
    'pkg3d_day1_meals' => 'Déjeuner et dîner',
    'pkg3d_day1_stay' => 'Camp tenté du Serengeti',

    'pkg3d_day2_title' => 'Journée complète, Serengeti central',
    'pkg3d_day2_mood' => 'Il y a tant à voir que chaque heure en vaut la peine.',
    'pkg3d_day2_tl1_time' => '06h00',
    'pkg3d_day2_tl1_title' => 'Game drive au lever du soleil',
    'pkg3d_day2_tl1_desc' => 'La meilleure heure de toute journée de safari. Les prédateurs qui ont chassé la nuit sont encore dehors, la lumière est douce et dorée, et les plaines de Seronera, la plus forte densité de prédateurs d\'Afrique, commencent à s\'animer.',
    'pkg3d_day2_tl2_time' => '08h30',
    'pkg3d_day2_tl2_title' => 'Petit-déjeuner en brousse',
    'pkg3d_day2_tl2_desc' => 'Une table est dressée là où le matin vous trouve, parfois avec une vue sur des zèbres en train de paître. C\'est, sans exception, le meilleur cadre de petit-déjeuner que nos clients aient jamais connu.',
    'pkg3d_day2_tl3_time' => '10h00',
    'pkg3d_day2_tl3_title' => 'Exploration toute la journée',
    'pkg3d_day2_tl3_desc' => 'Le reste de la journée se déroule sans hâte : votre guide décrypte les échanges radio et les traces dans la terre pour décider où aller ensuite. C\'est le moment où le Serengeti cesse d\'être un lieu que l\'on visite pour devenir un lieu que l\'on vit.',
    'pkg3d_day2_tl4_time' => '13h00',
    'pkg3d_day2_tl4_title' => 'Déjeuner à emporter, où que vous soyez',
    'pkg3d_day2_tl4_desc' => 'Pas besoin de se précipiter au camp. Le déjeuner vient à vous, sous un acacia, avec les plaines qui s\'étendent dans toutes les directions.',
    'pkg3d_day2_tl5_time' => '19h00',
    'pkg3d_day2_tl5_title' => 'Dîner sous les étoiles',
    'pkg3d_day2_tl5_desc' => 'De retour au camp, le feu de camp est allumé et les histoires de la journée sont racontées et reracontées. Demandez à votre guide l\'origine du nom du Serengeti, « plaines sans fin » en maasaï, et pourquoi il en mérite chaque syllabe.',
    'pkg3d_day2_drive' => 'Journée complète, hors piste',
    'pkg3d_day2_meals' => 'Petit-déjeuner, déjeuner et dîner',
    'pkg3d_day2_stay' => 'Camp tenté du Serengeti',

    'pkg3d_day3_title' => 'Cratère du Ngorongoro à Arusha',
    'pkg3d_day3_mood' => 'Aujourd\'hui, la huitième merveille du monde.',
    'pkg3d_day3_tl1_time' => '05h30',
    'pkg3d_day3_tl1_title' => 'Départ matinal',
    'pkg3d_day3_tl1_desc' => 'Un départ avant l\'aube vaut vraiment le coup aujourd\'hui. Le petit-déjeuner est emballé, et vous serez sur la route pendant que le Serengeti se réveille encore autour de vous.',
    'pkg3d_day3_tl2_time' => '08h00',
    'pkg3d_day3_tl2_title' => 'Bord du cratère, premières lueurs',
    'pkg3d_day3_tl2_desc' => 'La vue depuis le bord donne la chair de poule à presque tout le monde, et pas seulement à cause du froid à 2 300 mètres. En contrebas, 264 km² de caldeira abritent l\'une des concentrations de faune les plus denses de la planète.',
    'pkg3d_day3_tl3_time' => '09h00',
    'pkg3d_day3_tl3_title' => 'Descente vers le fond du cratère',
    'pkg3d_day3_tl3_desc' => 'La piste descend en serpentant jusqu\'à 1 700 mètres. C\'est votre meilleure chance en Tanzanie de voir le rhinocéros noir, aux côtés du lion, de l\'éléphant et des troupeaux de zèbres et de gnous qui ne quittent jamais le fond du cratère.',
    'pkg3d_day3_tl4_time' => '12h30',
    'pkg3d_day3_tl4_title' => 'Pique-nique, fond du cratère',
    'pkg3d_day3_tl4_desc' => 'Le déjeuner est pris avec les parois du cratère s\'élevant tout autour de vous, l\'une des salles à manger les plus surréalistes où vous vous assiérez jamais.',
    'pkg3d_day3_tl5_time' => '14h30',
    'pkg3d_day3_tl5_title' => 'Remontée, route vers Arusha',
    'pkg3d_day3_tl5_desc' => 'La sortie du cratère est aussi spectaculaire que l\'entrée, alors jetez un dernier regard en arrière. D\'ici, ce sont quelques heures de route jusqu\'à Arusha, avec une arrivée en fin d\'après-midi et trois jours d\'histoires à raconter.',
    'pkg3d_day3_drive' => '4 à 5 heures de route',
    'pkg3d_day3_meals' => 'Petit-déjeuner et déjeuner',
    'pkg3d_day3_stay' => 'Fin du voyage, Arusha',

    'pkg3d_included_heading' => 'Inclus',
    'pkg3d_included_1' => 'Land Cruiser 4x4 avec toit ouvrant et place fenêtre garantie',
    'pkg3d_included_2' => 'Chauffeur-guide anglophone (italien sur demande)',
    'pkg3d_included_3' => 'Tous les frais d\'entrée et de conservation des parcs',
    'pkg3d_included_4' => '2 nuits en camp tenté, pension complète',
    'pkg3d_included_5' => 'Eau potable pendant les game drives',
    'pkg3d_included_6' => 'Prise en charge et dépose à Arusha',
    'pkg3d_excluded_heading' => 'Non inclus',
    'pkg3d_excluded_1' => 'Vols internationaux et visa tanzanien',
    'pkg3d_excluded_2' => 'Assurance voyage (obligatoire)',
    'pkg3d_excluded_3' => 'Boissons autres que l\'eau, et dépenses personnelles',
    'pkg3d_excluded_4' => 'Pourboires pour le guide et le personnel du camp',
    'pkg3d_excluded_5' => 'Vol en montgolfière optionnel au-dessus du Serengeti',

    'pkg3d_gallery_badge' => 'Ce que vous verrez',
    'pkg3d_gallery_title' => 'Serengeti et Ngorongoro en images',

    'pkg3d_faq_title' => 'Questions sur ce safari',
    'pkg3d_faq_q1' => '3 jours suffisent-ils pour voir le Serengeti ?',
    'pkg3d_faq_a1' => 'C\'est le minimum pratique. Vous bénéficiez d\'une journée complète dans le parc plus le cratère du Ngorongoro, qui couvrent ensemble les plus fortes concentrations de faune en Tanzanie. Les voyages plus longs ajoutent d\'autres parcs, pas davantage de Serengeti lui-même.',
    'pkg3d_faq_q2' => 'Verrai-je les Big Five ?',
    'pkg3d_faq_a2' => 'Lion, éléphant, buffle et léopard sont observés régulièrement sur cet itinéraire. Le rhinocéros noir n\'est réaliste que dans le cratère du Ngorongoro, c\'est pourquoi cet itinéraire l\'inclut. Aucun opérateur ne peut garantir l\'observation d\'un animal sauvage, mais cette combinaison vous offre les meilleures chances du pays.',
    'pkg3d_faq_q3' => 'Puis-je prolonger ce safari sur plus de jours ?',
    'pkg3d_faq_a3' => 'Oui, cet itinéraire est la base de nos forfaits 4, 5 et 8 jours, qui ajoutent Tarangire, davantage de jours au Serengeti, ou l\'itinéraire de la migration. Indiquez-nous vos dates et nous l\'ajusterons.',

    'pkg3d_cta_title' => 'Prêt à réserver ce safari ?',
    'pkg3d_cta_intro' => 'Envoyez-nous vos dates et la taille de votre groupe. Nous répondons avec un itinéraire détaillé et le prix final, sans engagement.',
    'pkg3d_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'pkg3d_cta_contact_form' => 'Réserver maintenant',

    'pkg5d_meta_title' => 'Safari Serengeti & Ngorongoro 5 jours | Serengeti Budget Safari',
    'pkg5d_meta_description' => 'Safari de 5 jours en Tanzanie à travers Tarangire, le Serengeti et le Ngorongoro : Big Five, 4x4 privé, tous les frais de parc inclus, à partir de 650 € par personne.',

    'pkg5d_type' => 'Safari Privé',
    'pkg5d_budget' => 'Économique',
    'pkg5d_hero_title' => 'Safari Serengeti & Ngorongoro 5 jours',
    'pkg5d_hero_days_nights' => '5 jours / 4 nuits',
    'pkg5d_hero_route' => 'Arusha → Tarangire → Serengeti → Ngorongoro → Arusha',
    'pkg5d_hero_from' => 'À partir de',
    'pkg5d_hero_pp' => '/ personne',
    'pkg5d_hero_book' => 'Réserver ce safari',
    'pkg5d_hero_whatsapp' => 'Demander sur WhatsApp',
    'pkg5d_qf_days' => '5 jours',
    'pkg5d_qf_private' => 'Privé',
    'pkg5d_qf_jeep' => 'Jeep 4x4',
    'pkg5d_qf_max' => 'Max 6 personnes',
    'pkg5d_qf_guide' => 'Guide anglophone',

    'pkg5d_gallery_view_all' => 'Voir toutes les photos',

    'pkg5d_overview_badge' => 'Aperçu',
    'pkg5d_overview_title' => 'Découvrez le cœur sauvage de la Tanzanie',
    'pkg5d_overview_p1' => 'Vivez un safari inoubliable de 5 jours en Tanzanie à travers Tarangire, le Serengeti et le Ngorongoro. Partez à la recherche des Big Five, explorez des paysages à couper le souffle et profitez d\'un hébergement confortable en voyageant dans un véhicule de safari 4x4 privé.',
    'pkg5d_overview_p2' => 'Chaque game drive est mené par nos propres guides, dans nos propres véhicules : la même équipe depuis la première prise en charge à Arusha jusqu\'à la dernière dépose. Aucun véhicule sous-traité, aucun itinéraire partagé avec des inconnus sauf si vous choisissez un départ en groupe.',
    'pkg5d_love_title' => "Pourquoi vous allez adorer ce safari",
    'pkg5d_love_1' => 'Opportunités Big Five',
    'pkg5d_love_2' => 'Guide de safari professionnel',
    'pkg5d_love_3' => 'Véhicule 4x4 privé',
    'pkg5d_love_4' => 'Tous les frais de parc inclus',
    'pkg5d_love_5' => 'Itinéraire flexible',
    'pkg5d_love_6' => 'Camps tentés confortables',

    'pkg5d_route_badge' => 'Le voyage',
    'pkg5d_route_title' => 'Itinéraire du safari',
    'pkg5d_route_arusha' => 'Arusha',
    'pkg5d_route_tarangire' => 'Tarangire',
    'pkg5d_route_serengeti' => 'Serengeti',
    'pkg5d_route_ngorongoro' => 'Ngorongoro',

    'pkg5d_itinerary_badge' => 'Jour par jour',
    'pkg5d_itinerary_title' => 'Votre itinéraire',
    'pkg5d_itinerary_intro' => 'Appuyez sur un jour pour le développer.',

    'pkg5d_day1_title' => 'Arusha → Parc national de Tarangire',
    'pkg5d_day1_mood' => 'Karibu Sana, bienvenue en Tanzanie.',
    'pkg5d_day1_drive' => '2 à 3 heures de route',
    'pkg5d_day1_meals' => 'Déjeuner et dîner',
    'pkg5d_day1_stay' => 'Marera Valley Lodge',
    'pkg5d_day1_desc' => 'Prise en charge à votre hôtel d\'Arusha en milieu de matinée et route vers le parc national de Tarangire, célèbre pour ses baobabs et ses immenses troupeaux d\'éléphants. Game drive de l\'après-midi le long de la rivière Tarangire avant l\'installation à votre lodge.',
    'pkg5d_day1_act1' => 'Game drive',
    'pkg5d_day1_act2' => 'Observation de la faune',
    'pkg5d_day1_tl1_time' => '09h30',
    'pkg5d_day1_tl1_title' => 'Prise en charge à Arusha',
    'pkg5d_day1_tl1_desc' => 'Un départ en milieu de matinée signifie pas de réveil avant l\'aube pour votre premier jour. Votre chauffeur-guide charge le Land Cruiser et le voyage devient enfin, réellement, une réalité.',
    'pkg5d_day1_tl2_time' => '12h00',
    'pkg5d_day1_tl2_title' => 'Entrée dans le Tarangire',
    'pkg5d_day1_tl2_desc' => 'La porte du parc marque le début du pays des baobabs, et certains de ces arbres se dressent depuis plus de mille ans. Les éléphants s\'y rassemblent en nombre presque inégalé ailleurs en Tanzanie.',
    'pkg5d_day1_tl3_time' => '14h30',
    'pkg5d_day1_tl3_title' => 'Game drive de l\'après-midi',
    'pkg5d_day1_tl3_desc' => 'En longeant la rivière Tarangire, où la faune se concentre même pendant les mois secs. Observez les familles d\'éléphants traversant en file indienne, et les baobabs se dressant comme des sentinelles au-dessus de tout cela.',
    'pkg5d_day1_tl4_time' => '17h30',
    'pkg5d_day1_tl4_title' => 'Installation, Marera Valley Lodge',
    'pkg5d_day1_tl4_desc' => 'Votre première nuit donne le ton du voyage : dîner avec vue sur la vallée, et le son du Tarangire s\'installant dans l\'obscurité.',

    'pkg5d_day2_title' => 'Tarangire → Serengeti central',
    'pkg5d_day2_mood' => 'Des baobabs aux plaines sans fin.',
    'pkg5d_day2_drive' => '4 à 5 heures de route',
    'pkg5d_day2_meals' => 'Petit-déjeuner, déjeuner et dîner',
    'pkg5d_day2_stay' => 'Camp tenté du Serengeti',
    'pkg5d_day2_desc' => 'Trajet matinal vers l\'ouest à travers la grande vallée du Rift jusqu\'au Serengeti central, avec un arrêt à un point de vue maasaï. Game drive de l\'après-midi à l\'arrivée, à l\'affût des lions et guépards dans les plaines ouvertes.',
    'pkg5d_day2_act1' => 'Trajet panoramique',
    'pkg5d_day2_act2' => 'Game drive de l\'après-midi',
    'pkg5d_day2_tl1_time' => '07h30',
    'pkg5d_day2_tl1_title' => 'Vers l\'ouest à travers la vallée du Rift',
    'pkg5d_day2_tl1_desc' => 'La route descend des hautes terres vers la grande vallée du Rift, l\'un des rares endroits sur Terre où l\'on peut observer l\'histoire tectonique de la planète simplement en regardant par la fenêtre.',
    'pkg5d_day2_tl2_time' => '10h00',
    'pkg5d_day2_tl2_title' => 'Point de vue maasaï',
    'pkg5d_day2_tl2_desc' => 'Un court arrêt où le paysage s\'ouvre devant vous : votre premier véritable aperçu de ce que signifient réellement les « plaines sans fin ».',
    'pkg5d_day2_tl3_time' => '13h00',
    'pkg5d_day2_tl3_title' => 'Arrivée, Serengeti central',
    'pkg5d_day2_tl3_desc' => 'Vous êtes maintenant au pays des grands félins. Un game drive de l\'après-midi le jour de l\'arrivée a l\'habitude de produire des observations de lions et de guépards avant même que vous ayez déballé vos affaires.',
    'pkg5d_day2_tl4_time' => '18h30',
    'pkg5d_day2_tl4_title' => 'Camp, première nuit au Serengeti',
    'pkg5d_day2_tl4_desc' => 'Dîner sous la tente, avec les plaines s\'étendant sombres et silencieuses dans toutes les directions au-delà de la lumière du feu.',

    'pkg5d_day3_title' => 'Journée complète au Serengeti',
    'pkg5d_day3_mood' => 'Il y a tant à voir que chaque heure en vaut la peine.',
    'pkg5d_day3_drive' => 'Game drives dans le parc',
    'pkg5d_day3_meals' => 'Petit-déjeuner, déjeuner et dîner',
    'pkg5d_day3_stay' => 'Camp tenté du Serengeti',
    'pkg5d_day3_desc' => 'Une journée complète à explorer la région de Seronera, la plus forte densité de prédateurs du parc. Déjeuner à emporter en brousse, avec la possibilité de prolonger le trajet de l\'après-midi vers la rivière Mara en saison de migration.',
    'pkg5d_day3_act1' => 'Game drive toute la journée',
    'pkg5d_day3_act2' => 'Déjeuner en brousse',
    'pkg5d_day3_tl1_time' => '06h00',
    'pkg5d_day3_tl1_title' => 'Game drive au lever du soleil',
    'pkg5d_day3_tl1_desc' => 'La meilleure heure de toute journée de safari. Les prédateurs qui ont chassé la nuit sont souvent encore visibles, et la région de Seronera s\'éveille autour de vous dans une lumière dorée.',
    'pkg5d_day3_tl2_time' => '09h00',
    'pkg5d_day3_tl2_title' => 'Petit-déjeuner en brousse',
    'pkg5d_day3_tl2_desc' => 'Une table dressée là où le matin vous trouve. C\'est un sérieux candidat pour la meilleure vue de petit-déjeuner que vous ayez jamais eue.',
    'pkg5d_day3_tl3_time' => '11h00',
    'pkg5d_day3_tl3_title' => 'Exploration toute la journée',
    'pkg5d_day3_tl3_desc' => 'Votre guide décrypte la radio et les traces dans la terre pour décider où mène la journée. En saison de migration, c\'est le moment où le trajet peut s\'étendre vers le nord jusqu\'aux traversées de la rivière Mara.',
    'pkg5d_day3_tl4_time' => '19h00',
    'pkg5d_day3_tl4_title' => 'Dîner, histoires autour du feu de camp',
    'pkg5d_day3_tl4_desc' => 'De retour au camp, les observations de la journée sont racontées et reracontées autour du feu. Demandez à votre guide ce que signifie « Serengeti » en maasaï, et pourquoi ce nom mérite chaque syllabe.',

    'pkg5d_day4_title' => 'Serengeti → Ngorongoro',
    'pkg5d_day4_mood' => 'Un dernier regard sur les plaines, puis vers les nuages.',
    'pkg5d_day4_drive' => '3 à 4 heures de route',
    'pkg5d_day4_meals' => 'Petit-déjeuner, déjeuner et dîner',
    'pkg5d_day4_stay' => 'Ngorongoro Rim Lodge',
    'pkg5d_day4_desc' => 'Dernier game drive matinal dans le Serengeti avant de monter vers les hautes terres du Ngorongoro. Après-midi libre à votre lodge sur le bord du cratère, avec des vues panoramiques sur la caldeira.',
    'pkg5d_day4_act1' => 'Game drive matinal',
    'pkg5d_day4_act2' => 'Vues sur le bord du cratère',
    'pkg5d_day4_tl1_time' => '06h30',
    'pkg5d_day4_tl1_title' => 'Dernier game drive au Serengeti',
    'pkg5d_day4_tl1_desc' => 'Un dernier lever de soleil sur les plaines avant de partir, une façon appropriée de dire au revoir à un lieu qu\'il est difficile de quitter.',
    'pkg5d_day4_tl2_time' => '10h00',
    'pkg5d_day4_tl2_title' => 'Montée vers les hautes terres',
    'pkg5d_day4_tl2_desc' => 'La route s\'élève depuis les plaines vers une forêt d\'altitude fraîche et brumeuse, une Tanzanie complètement différente de celle que vous avez quittée ce matin-là.',
    'pkg5d_day4_tl3_time' => '14h00',
    'pkg5d_day4_tl3_title' => 'Installation, bord du cratère',
    'pkg5d_day4_tl3_desc' => 'Votre lodge se trouve sur le bord du cratère du Ngorongoro, l\'une des vues les plus extraordinaires de tout le safari, avec un après-midi tranquille pour en profiter.',
    'pkg5d_day4_tl4_time' => '19h00',
    'pkg5d_day4_tl4_title' => 'Dîner avec vue',
    'pkg5d_day4_tl4_desc' => 'Alors que la lumière décline sur la caldeira en contrebas, la plupart des clients s\'accordent à dire que c\'est le cadre de dîner dont ils se souviennent le plus longtemps.',

    'pkg5d_day5_title' => 'Ngorongoro → Arusha',
    'pkg5d_day5_mood' => 'Aujourd\'hui, la huitième merveille du monde.',
    'pkg5d_day5_drive' => '3 heures de route',
    'pkg5d_day5_meals' => 'Petit-déjeuner et déjeuner',
    'pkg5d_day5_stay' => 'Départ',
    'pkg5d_day5_desc' => 'Descente dans le cratère du Ngorongoro à l\'aube pour la meilleure chance de voir le rhinocéros noir, aux côtés de fortes concentrations de lions, éléphants et buffles. Remontée en milieu de matinée et retour en voiture vers Arusha, arrivée dans l\'après-midi.',
    'pkg5d_day5_act1' => 'Game drive au fond du cratère',
    'pkg5d_day5_act2' => 'Dépose à Arusha',
    'pkg5d_day5_tl1_time' => '06h00',
    'pkg5d_day5_tl1_title' => 'Descente vers le fond du cratère',
    'pkg5d_day5_tl1_desc' => 'La piste descend en serpentant jusqu\'à 1 700 mètres, dans une caldeira de 264 km² abritant l\'une des concentrations de faune les plus denses de la planète, et votre meilleure chance en Tanzanie de voir le rhinocéros noir.',
    'pkg5d_day5_tl2_time' => '09h30',
    'pkg5d_day5_tl2_title' => 'Le fond du cratère',
    'pkg5d_day5_tl2_desc' => 'Lion, éléphant, buffle et les troupeaux de zèbres et de gnous qui ne quittent jamais le fond du cratère, le tout dans un espace assez petit pour donner l\'impression d\'une réserve privée.',
    'pkg5d_day5_tl3_time' => '11h30',
    'pkg5d_day5_tl3_title' => 'Remontée',
    'pkg5d_day5_tl3_desc' => 'La sortie est aussi spectaculaire que la descente, alors jetez un dernier regard en arrière avant que la route ne prenne la direction d\'Arusha.',
    'pkg5d_day5_tl4_time' => '15h00',
    'pkg5d_day5_tl4_title' => 'Dépose à Arusha',
    'pkg5d_day5_tl4_desc' => 'Votre voyage se termine là où il a commencé, avec cinq jours d\'histoires et, si vous êtes comme nos clients précédents, déjà en train de planifier votre retour.',

