    'pkg5d_migration_in_season_desc' => 'Vous voyagez pendant la période de migration (juillet à octobre), une bonne chance de voir les troupeaux traverser la région de la Mara.',
    'pkg5d_migration_out_season' => 'Grande Migration : juillet – octobre',
