    'contact_meta_title' => 'Contactez-nous | Serengeti Budget Safari',
    'contact_meta_description' => 'Contactez Serengeti Budget Safari : envoyez-nous vos dates de voyage et la taille de votre groupe pour un itinéraire et un prix détaillés, ou écrivez-nous directement sur WhatsApp.',
