    'contact_info_title' => 'Autres façons de nous contacter',
    'contact_info_whatsapp' => 'WhatsApp',
    'contact_info_whatsapp_desc' => 'Le moyen le plus rapide de nous joindre, généralement une réponse en moins d\'une heure.',
    'contact_info_email' => 'E-mail',
    'contact_info_email_desc' => 'Pour les demandes d\'itinéraire détaillées ou les documents.',
