    'contact_faq_title' => 'Avant de nous écrire',
    'contact_faq_q1' => 'À quelle vitesse recevrai-je une réponse ?',
    'contact_faq_a1' => 'Les messages WhatsApp reçoivent généralement une réponse en moins d\'une heure pendant nos heures de travail. Les demandes par formulaire de contact et e-mail reçoivent une réponse sous 24 heures.',
    'contact_faq_q2' => 'Dois-je payer quelque chose pour obtenir un devis ?',
    'contact_faq_a2' => 'Non. Chaque devis et itinéraire détaillé est gratuit et sans engagement de réservation.',
    'contact_faq_q3' => "Que faire si je ne connais pas encore mes dates exactes ?",
    'contact_faq_a3' => 'Ce n\'est pas un problème. Indiquez-nous votre mois approximatif ou une plage de dates et nous vous conseillerons sur la disponibilité et les prix pour cette période.',

    'arusha_meta_title' => 'Guide du parc national d\'Arusha (2026) | Serengeti Budget Safari',
    'arusha_meta_description' => 'Guide du parc national d\'Arusha : mont Meru, lacs Momella, safaris à pied, lions grimpeurs d\'arbres, frais de parc 2026, quand y aller et où loger. À 40 minutes de la ville d\'Arusha.',
    'arusha_hero_badge' => 'Parc national d\'Arusha',
    'arusha_hero_title' => 'Parc national d\'Arusha',
    'arusha_hero_sub' => "Le parc le plus sous-estimé de Tanzanie : le mont Meru, les lacs Momella et les safaris à pied, à seulement 40 minutes d'Arusha.",
    'arusha_hero_cta_quote' => 'Demander un devis',

    'arusha_intro_badge' => 'Aperçu',
    'arusha_intro_title' => 'Un petit parc à la diversité de paysages exceptionnelle',
    'arusha_intro_p1' => "Le parc national d'Arusha est le parc le plus pratique de Tanzanie, à 40 minutes de la ville d'Arusha et souvent visité en une demi-journée ou comme journée d'acclimatation avant une ascension du Kilimandjaro ou du Meru. Malgré sa taille, il couvre quatre paysages distincts en une seule visite : le cratère de Ngurdoto, les lacs Momella, la forêt montagnarde et les contreforts du mont Meru lui-même.",
    'arusha_intro_p2' => "C'est aussi l'un des trois seuls parcs de Tanzanie où les safaris à pied sont autorisés, et le seul endroit près d'Arusha où l'on peut faire du canoë parmi les hippopotames et les flamants roses sur les lacs Momella.",
    'arusha_intro_p3' => "La plupart des visiteurs le combinent avec un itinéraire d'une demi-journée, bien qu'il serve aussi de trek d'acclimatation avant l'ascension du mont Meru, dont le sommet se trouve à l'intérieur des limites du parc.",
    'arusha_fact_area' => 'Superficie',
    'arusha_fact_established' => 'Créé en',
    'arusha_fact_meru' => 'Sommet du mont Meru',
    'arusha_fact_birds' => 'Espèces d\'oiseaux',
    'arusha_fact_lions' => 'Prédateurs',
    'arusha_fact_lions_value' => 'Léopard, présent mais rarement observé',
    'arusha_fact_stay' => 'Visite typique',
    'arusha_fact_stay_value' => 'Demi-journée, ou 3 à 4 jours pour le Meru',
    'arusha_fact_from_arusha' => 'Depuis la ville d\'Arusha',
    'arusha_fact_from_airport' => 'Depuis l\'aéroport du Kilimandjaro',

    'arusha_regions_badge' => 'Trois paysages en un seul parc',
    'arusha_regions_title' => 'Que voir',
    'arusha_regions_intro' => 'Arusha regroupe une diversité de terrains inhabituelle dans une petite zone. Organisez votre itinéraire autour de ces trois zones.',
    'arusha_region_ngurdoto_name' => 'Cratère de Ngurdoto',
    'arusha_region_ngurdoto_desc' => 'Un fond de cratère luxuriant et marécageux entouré de forêt, souvent appelé « petit Ngorongoro ». Les véhicules ne peuvent pas y descendre, l\'observation se fait donc depuis le bord, en surplombant buffles, phacochères et cobes à croissant en train de paître en contrebas.',
    'arusha_region_momella_name' => 'Lacs Momella',
    'arusha_region_momella_desc' => 'Une chaîne de lacs alcalins peu profonds, chacun d\'une teinte différente de vert ou de bleu selon sa teneur en algues et en minéraux. Flamants roses, girafes et buffles se rassemblent sur les rives, et c\'est de là que partent les safaris en canoë.',
    'arusha_region_meru_name' => 'Mont Meru',
    'arusha_region_meru_desc' => "Le cinquième plus haut sommet d'Afrique à 4 566 m, et la toile de fond spectaculaire de la majeure partie du parc. Ascension possible en 3 à 4 jours, avec beaucoup moins de randonneurs que le Kilimandjaro et une vue superbe sur le Kilimandjaro lui-même par temps clair.",

    'arusha_walking_badge' => 'Une permission rare',
    'arusha_walking_title' => 'Safaris à pied',
    'arusha_walking_intro' => 'Arusha est l\'un des trois seuls parcs de Tanzanie où les safaris à pied sont autorisés. La plupart des parcs du circuit nord exigent de rester dans le véhicule.',
    'arusha_walking_p1' => 'Des randonnées guidées avec un ranger armé vous permettent d\'approcher girafes, zèbres et buffles à pied, en lisant les traces et les excréments, et en entendant la brousse au niveau du sol plutôt qu\'à travers un pare-brise.',
    'arusha_walking_p2' => 'Les grands prédateurs étant largement absents, marcher ici est plus sûr que dans les grands parcs. Les rencontres dangereuses concernent presque toujours les buffles, que le ranger est formé à gérer à distance de sécurité.',

    'arusha_wildlife_badge' => 'Ce qui y vit',
    'arusha_wildlife_title' => 'Faune',
    'arusha_wildlife_intro' => 'Arusha n\'a pas de lion et très peu du « grand gibier » classique du Serengeti. Son attrait faunique est différent : primates, oiseaux et espèces forestières que vous ne verrez pas lors d\'un safari de savane.',
    'arusha_animal_giraffe' => 'Girafe',
    'arusha_animal_colobus' => 'Colobe noir et blanc',
    'arusha_animal_zebra' => 'Zèbre',
    'arusha_animal_buffalo' => 'Buffle',
    'arusha_animal_waterbuck' => 'Cobe à croissant',
    'arusha_animal_flamingo' => 'Flamant rose',
    'arusha_animal_elephant' => 'Éléphant (occasionnel)',
    'arusha_animal_warthog' => 'Phacochère',
    'arusha_wildlife_p1' => "La véritable spécialité du parc, ce sont ses troupes de colobes noirs et blancs, facilement observables dans la forêt montagnarde, avec plus de 400 espèces d'oiseaux recensées rien qu'autour des lacs Momella.",
    'arusha_wildlife_p2' => 'Les observations d\'éléphants se produisent mais restent occasionnelles plutôt que garanties. Ce n\'est pas le parc à choisir si les Big Five sont votre priorité, mais il récompense les visiteurs intéressés par les paysages, les oiseaux et un rythme plus tranquille.',

    'arusha_when_badge' => 'Planification',
    'arusha_when_title' => 'Quand y aller',
    'arusha_when_intro' => 'Arusha est un parc ouvert toute l\'année : sa faible altitude et sa proximité avec la ville font qu\'il ferme rarement, contrairement aux treks en haute altitude.',
    'arusha_when_p1' => 'De juin à octobre (saison sèche), les vues sur le mont Meru et le Kilimandjaro sont les plus dégagées, et les conditions de marche les plus faciles.',
    'arusha_when_p2' => 'Les mois plus humides (mars à mai) donnent au cratère et aux abords des lacs une teinte verte éclatante et attirent davantage d\'oiseaux, bien que les pistes puissent être boueuses et les vues sur la montagne moins fiables.',

    'arusha_stay_badge' => 'Où loger',
    'arusha_stay_title' => 'Hébergement',
    'arusha_stay_intro' => "La plupart des visiteurs s'installent en ville d'Arusha et visitent le parc à la journée, mais quelques établissements se trouvent près de l'entrée du parc pour ceux qui gravissent le Meru ou le combinent avec un autre parc.",
    'arusha_stay_town_title' => 'Ville d\'Arusha',
    'arusha_stay_town_price' => 'Économique – Luxe',
    'arusha_stay_town_desc' => 'Le choix le plus courant : à 30-40 minutes de l\'entrée du parc, avec le plus large choix d\'hôtels et des transferts faciles vers l\'aéroport du Kilimandjaro ou le circuit nord.',
    'arusha_stay_lodge_title' => 'Lodges près de l\'entrée',
    'arusha_stay_lodge_price' => 'Milieu de gamme – Luxe',
    'arusha_stay_lodge_desc' => 'Quelques lodges se trouvent à courte distance en voiture de l\'entrée du parc, utiles pour un départ matinal lors d\'une ascension du Meru ou d\'un safari à pied à l\'aube.',
    'arusha_stay_camp_title' => 'Huttes de montagne du Meru',
    'arusha_stay_camp_price' => 'Inclus dans le forfait trek',
    'arusha_stay_camp_desc' => 'Les grimpeurs passent la nuit dans une série de huttes de montagne pendant l\'ascension, Miriakamba et Saddle Hut, incluses dans tout forfait de trekking du mont Meru.',
    'arusha_stay_note' => 'Nous pouvons organiser un hébergement à n\'importe quel niveau dans le cadre d\'une excursion à la journée ou d\'un forfait trekking au Meru. Demandez-nous la disponibilité actuelle.',

    'arusha_fees_badge' => 'Frais 2026',
    'arusha_fees_title' => 'Frais d\'entrée du parc',
    'arusha_fees_intro' => 'Les frais sont par personne et par période de 24 heures et incluent 18 % de TVA. Payables par carte ou carte de parc prépayée. Les espèces ne sont pas acceptées à l\'entrée.',
    'arusha_table_category' => 'Catégorie',
    'arusha_table_adult' => 'Adulte',
    'arusha_table_child' => 'Enfant (5-15 ans)',
    'arusha_fee_entry' => 'Entrée du parc',
    'arusha_fee_concession' => 'Concession de trekking du Meru',
    'arusha_fee_campsite' => 'Frais de camping',
    'arusha_fees_note' => 'Lorsque vous voyagez avec nous, tous les frais de parc sont calculés et inclus dans le prix indiqué, sans paiement séparé nécessaire à l\'entrée.',

    'arusha_gallery_badge' => 'Arusha en images',
    'arusha_gallery_title' => 'Ce que vous verrez',
    'arusha_gallery_caption_1' => 'Colobes dans la forêt',
    'arusha_gallery_caption_2' => 'Savane au lever du soleil',
    'arusha_gallery_caption_3' => 'Canoë sur les lacs Momella',
    'arusha_gallery_caption_4' => 'Zèbres dans la plaine',
    'arusha_gallery_caption_5' => 'Éléphant sous un acacia',
    'arusha_gallery_caption_6' => 'Un bord de cratère, de forme similaire à celui de Ngurdoto',

    'arusha_back_to_parks' => 'Comparer les neuf parcs',

    'arusha_faq_badge' => 'FAQ',
    'arusha_faq_title' => 'Questions fréquentes',
    'arusha_faq_q1' => 'Puis-je visiter le parc national d\'Arusha en une demi-journée ?',
    'arusha_faq_a1' => "Oui, c'est la façon la plus courante de le visiter, généralement combinée avec un départ matinal depuis la ville d'Arusha et un retour en début d'après-midi.",
    'arusha_faq_q2' => 'Verrai-je les Big Five ici ?',
    'arusha_faq_a2' => 'Non. Arusha n\'a ni lion ni rhinocéros, et les observations d\'éléphants sont occasionnelles. Il est choisi pour ses paysages, ses safaris à pied, ses colobes et ses oiseaux plutôt que pour les Big Five.',
    'arusha_faq_q3' => 'La marche est-elle sûre ici ?',
    'arusha_faq_a3' => 'Oui, relativement. L\'absence de lion fait d\'Arusha l\'un des parcs les plus sûrs pour la marche, bien que les buffles nécessitent toujours de la prudence et qu\'un ranger armé accompagne toujours les groupes de marcheurs.',
    'arusha_faq_q4' => 'Puis-je gravir le mont Meru sans gravir le Kilimandjaro ?',
    'arusha_faq_a4' => 'Oui, le Meru est un trek autonome et un choix populaire en soi. De nombreux grimpeurs le préfèrent pour ses sentiers plus calmes et sa marche spectaculaire sur le bord du cratère.',
    'arusha_faq_q5' => 'Comment le Meru se compare-t-il au Kilimandjaro comme ascension ?',
    'arusha_faq_a5' => 'Le Meru est plus court (3 à 4 jours contre 5 à 9), plus raide par endroits, et bien moins fréquenté. Il est aussi couramment utilisé comme entraînement d\'acclimatation avant une tentative du Kilimandjaro.',
    'arusha_faq_q6' => 'Puis-je combiner Arusha avec d\'autres parcs ?',
    'arusha_faq_a6' => 'Oui, sa proximité avec la ville en fait un ajout facile à un itinéraire Tarangire ou Ngorongoro, ou une première/dernière journée détendue d\'un safari plus long.',
    'arusha_faq_q7' => 'Y a-t-il des safaris en canoë ?',
    'arusha_faq_a7' => 'Oui, sur les lacs Momella : une façon paisible d\'observer hippopotames, flamants roses et oiseaux aquatiques depuis l\'eau, généralement combinée avec une partie de la visite à pied ou en véhicule.',
    'arusha_faq_q8' => 'Un guide est-il obligatoire ?',
    'arusha_faq_a8' => 'Oui pour les safaris à pied et le trek du Meru (un ranger armé est obligatoire), et fortement recommandé pour les game drives étant donné la signalisation limitée à l\'intérieur du parc.',

    'arusha_cta_title' => 'Prêt à visiter le parc national d\'Arusha ?',
    'arusha_cta_intro' => 'Envoyez-nous vos dates et la taille de votre groupe. Nous répondons avec un itinéraire détaillé et le prix complet, sans engagement.',
    'arusha_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'arusha_cta_safaris' => 'Voir les forfaits safari',

    'kilimanjaro_meta_title' => 'Guide du parc national du Kilimandjaro (2026) | Serengeti Budget Safari',
    'kilimanjaro_meta_description' => 'Guide du parc national du Kilimandjaro : les sept itinéraires comparés, frais de parc 2026, taux de réussite, mal des montagnes, quand grimper et où dormir sur la montagne.',
    'kilimanjaro_hero_badge' => 'Parc national du Kilimandjaro',
    'kilimanjaro_hero_title' => 'Parc national du Kilimandjaro',
    'kilimanjaro_hero_sub' => "Le plus haut sommet d'Afrique à 5 895 m : cinq zones climatiques, sept itinéraires, et un sommet à la portée de tout marcheur raisonnablement en forme.",
    'kilimanjaro_hero_cta_quote' => 'Demander un devis',

    'kilimanjaro_intro_badge' => 'Aperçu',
    'kilimanjaro_intro_title' => 'Le toit de l\'Afrique',
    'kilimanjaro_intro_p1' => "Le Kilimandjaro est la plus haute montagne d'Afrique et le plus haut sommet isolé du monde, s'élevant de la savane à environ 900 m jusqu'à un sommet englacé à 5 895 m sans chaîne de montagnes connectée. L'ascension est une longue marche, pas une escalade technique : pas de cordes, pas de matériel d'escalade, juste plusieurs jours de marche régulière en montée à travers cinq zones climatiques distinctes.",
    'kilimanjaro_intro_p2' => "Ces zones (terres cultivées, forêt tropicale, lande, désert alpin et zone sommitale arctique) font qu'un trek au Kilimandjaro donne l'impression de marcher de l'équateur aux pôles en moins d'une semaine.",
    'kilimanjaro_intro_p3' => "Le véritable défi, c'est l'altitude, pas la forme physique ou la technique. Le facteur le plus déterminant pour atteindre le sommet est de choisir un itinéraire avec suffisamment de jours pour que votre corps s'acclimate.",
    'kilimanjaro_fact_area' => 'Superficie du parc',
    'kilimanjaro_fact_summit' => 'Sommet',
    'kilimanjaro_fact_status' => 'Statut',
    'kilimanjaro_fact_routes' => 'Itinéraires',
    'kilimanjaro_fact_duration' => 'Durée typique',
    'kilimanjaro_fact_success' => 'Plage du taux de réussite',
    'kilimanjaro_fact_climbers' => 'Grimpeurs par an',
    'kilimanjaro_fact_days' => 'Minimum recommandé',
    'kilimanjaro_fact_year' => '5 jours et plus',
    'kilimanjaro_fact_from_arusha' => 'Depuis Arusha',

    'kilimanjaro_routes_badge' => 'Choisissez votre voie',
    'kilimanjaro_routes_title' => 'Les itinéraires',
    'kilimanjaro_routes_intro' => 'Sept itinéraires officiels atteignent le sommet. Ces quatre-là sont ceux que nous proposons, choisis pour leur profil d\'acclimatation et leur fiabilité.',
    'kilimanjaro_route_marangu_name' => 'Marangu',
    'kilimanjaro_route_marangu_desc' => 'Le seul itinéraire avec hébergement en huttes plutôt qu\'en tentes, et le même chemin utilisé pour la montée et la descente. L\'option la plus courte, ce qui lui donne aussi le taux de réussite le plus bas : moins de temps pour s\'acclimater.',
    'kilimanjaro_route_machame_name' => 'Machame',
    'kilimanjaro_route_machame_desc' => 'Connue sous le nom de « Whiskey Route » pour sa réputation d\'ascension plus difficile. Panoramique et variée, camping sous tente, et l\'itinéraire le plus populaire de la montagne grâce à son solide profil d\'acclimatation.',
    'kilimanjaro_route_lemosho_name' => 'Lemosho',
    'kilimanjaro_route_lemosho_desc' => 'Un départ plus calme à travers une forêt tropicale intacte, rejoignant l\'itinéraire Machame plus haut. Largement considéré comme la meilleure combinaison de paysages et d\'acclimatation.',
    'kilimanjaro_route_rongai_name' => 'Rongai',
    'kilimanjaro_route_rongai_desc' => 'Approche par le versant nord, plus sec, de la montagne, proche de la frontière kényane. Le meilleur choix pendant les mois de transition pluvieux, lorsque les itinéraires sud sont plus humides.',

    'kilimanjaro_compare_badge' => 'Côte à côte',
    'kilimanjaro_compare_title' => 'Comparer tous les itinéraires',
    'kilimanjaro_compare_intro' => 'Les taux de réussite sont indicatifs. Ils augmentent fortement avec davantage de jours sur la montagne, quel que soit l\'itinéraire.',
    'kilimanjaro_table_route' => 'Itinéraire',
    'kilimanjaro_table_days' => 'Jours',
    'kilimanjaro_table_sleeping' => 'Hébergement',
    'kilimanjaro_table_scenery' => 'Paysage',
    'kilimanjaro_table_success' => 'Taux de réussite',
    'kilimanjaro_sleep_tents' => 'Tentes',
    'kilimanjaro_sleep_huts' => 'Huttes',
    'kilimanjaro_scenery_varied' => 'Varié, raide par endroits',
    'kilimanjaro_scenery_best' => 'Meilleur dans l\'ensemble',
    'kilimanjaro_scenery_full' => 'Circuit complet de la montagne',
    'kilimanjaro_scenery_direct' => 'Direct, moins varié',
    'kilimanjaro_scenery_dry' => 'Plus sec, sentiers plus calmes',
    'kilimanjaro_northern_circuit' => 'Northern Circuit',
    'kilimanjaro_compare_note' => 'La nuit supplémentaire sur un itinéraire plus long est l\'assurance la moins chère contre le mal des montagnes. Si votre emploi du temps le permet, choisissez l\'option la plus longue.',

    'kilimanjaro_wildlife_badge' => 'En montant',
    'kilimanjaro_wildlife_title' => 'La faune sur la montagne',
    'kilimanjaro_wildlife_intro' => "Le Kilimandjaro n'est pas une destination d'observation de la faune, mais les zones forestières inférieures présentent un réel intérêt faunique. La plupart des grimpeurs sont surpris de la vie présente sur les flancs de la montagne.",
    'kilimanjaro_animal_colobus' => 'Colobe noir et blanc',
    'kilimanjaro_animal_blue_monkey' => 'Cercopithèque à diadème',
    'kilimanjaro_animal_bushbuck' => 'Guib harnaché',
    'kilimanjaro_animal_buffalo' => 'Buffle (zone forestière)',
    'kilimanjaro_animal_elephant' => 'Éléphant (zone forestière, rare)',
    'kilimanjaro_animal_sunbird' => 'Souimanga malachite',
    'kilimanjaro_animal_raven' => 'Corbeau à nuque blanche',
    'kilimanjaro_animal_groundsel' => 'Séneçon géant (plante)',
    'kilimanjaro_wildlife_p1' => 'La zone de forêt tropicale, traversée le premier ou le deuxième jour sur la plupart des itinéraires, abrite colobes et cercopithèques à diadème, antilopes forestières et occasionnellement buffles ou éléphants, tous rencontrés sur le sentier plutôt que recherchés.',
    'kilimanjaro_wildlife_p2' => 'Au-dessus de la forêt, la lande et les zones alpines sont plus étranges que sauvages : séneçons géants et lobélies que l\'on ne trouve nulle part ailleurs, et oiseaux comme le corbeau à nuque blanche qui suivent les grimpeurs pour des restes de nourriture dans les camps d\'altitude.',

    'kilimanjaro_when_badge' => 'Planification',
    'kilimanjaro_when_title' => 'Quand grimper',
    'kilimanjaro_when_intro' => "Le Kilimandjaro peut techniquement être gravi toute l'année, mais les conditions varient considérablement selon la saison.",
    'kilimanjaro_when_p1' => 'De janvier à début mars et de juin à octobre sont les deux périodes sèches : les conditions les plus fiables, les vues les plus dégagées sur le sommet et les sentiers les plus fréquentés, surtout de juillet à septembre.',
    'kilimanjaro_when_p2' => 'Avril, mai et novembre sont les mois humides. La montagne reste ouverte et praticable, mais les sentiers sont glissants et la couverture nuageuse cache souvent le sommet. Rongai, sur le versant nord plus sec, est le meilleur choix si vous devez grimper pendant cette période.',

    'kilimanjaro_stay_badge' => 'Où vous dormez',
    'kilimanjaro_stay_title' => 'Hébergement sur la montagne',
    'kilimanjaro_stay_intro' => 'Votre hébergement dépend entièrement de l\'itinéraire choisi. C\'est fixe, pas une question de niveau de budget.',
    'kilimanjaro_stay_huts_title' => 'Huttes de montagne (Marangu uniquement)',
    'kilimanjaro_stay_huts_price' => 'Inclus dans l\'itinéraire Marangu',
    'kilimanjaro_stay_huts_desc' => 'Huttes de type dortoir avec lits superposés, salles à manger communes et installations basiques. Le seul itinéraire offrant cette option, ce qui explique en partie pourquoi il est le plus court et le plus abordable.',
    'kilimanjaro_stay_camping_title' => 'Camping en montagne (tous les autres itinéraires)',
    'kilimanjaro_stay_camping_price' => 'Inclus dans le prix de l\'itinéraire',
    'kilimanjaro_stay_camping_desc' => 'Tentes pour deux personnes transportées et montées par l\'équipe à chaque camp, avec une tente-cantine séparée pour les repas. La norme pour Machame, Lemosho, Rongai et le Northern Circuit.',
    'kilimanjaro_stay_private_title' => 'Arusha, avant et après',
    'kilimanjaro_stay_private_price' => 'Inclus dans chaque forfait',
    'kilimanjaro_stay_private_desc' => 'Une nuit d\'hôtel à Arusha avant l\'ascension et après votre descente est incluse dans chaque forfait Kilimandjaro que nous proposons, pour une douche chaude et un vrai lit de part et d\'autre de la montagne.',
    'kilimanjaro_stay_note' => 'Tout l\'hébergement en montagne, huttes ou tentes, est inclus dans le prix de votre forfait trekking, ainsi que tous les frais de camping et de huttes.',

    'kilimanjaro_fees_badge' => 'Frais 2026',
    'kilimanjaro_fees_title' => 'Frais de parc',
    'kilimanjaro_fees_intro' => 'Les frais sont détaillés par personne et inclus dans votre forfait trekking, indiqués ici pour que vous sachiez exactement ce que vous payez.',
    'kilimanjaro_table_category' => 'Frais',
    'kilimanjaro_table_basis' => 'Base',
    'kilimanjaro_table_adult' => 'Adulte (USD)',
    'kilimanjaro_table_child' => 'Enfant (5-15 ans)',
    'kilimanjaro_fee_conservation' => 'Frais de conservation',
    'kilimanjaro_fee_camping' => 'Frais de camping',
    'kilimanjaro_fee_huts' => 'Frais de hutte (Marangu)',
    'kilimanjaro_fee_rescue' => 'Frais de secours',
    'kilimanjaro_fee_basis_day' => 'Par jour',
    'kilimanjaro_fee_basis_night' => 'Par nuit',
    'kilimanjaro_fee_basis_once' => 'Une fois par trek',
    'kilimanjaro_fees_example' => 'Pour une ascension Lemosho de 7 jours, les frais de parc seuls s\'élèvent à environ 956 $ par personne. Ceci est entièrement séparé des coûts de guide, porteur, nourriture et équipement.',
    'kilimanjaro_fees_note' => 'Lorsque vous grimpez avec nous, tous les frais de parc sont calculés et inclus dans le prix de trekking indiqué, sans paiement séparé nécessaire à l\'entrée.',

    'kilimanjaro_gallery_badge' => 'Le Kilimandjaro en images',
    'kilimanjaro_gallery_title' => 'La montagne',
    'kilimanjaro_gallery_caption_1' => 'Savane au pied de la montagne',
    'kilimanjaro_gallery_caption_2' => 'Faune dans les plaines environnantes',
    'kilimanjaro_gallery_caption_3' => 'Un guide avec des grimpeurs avant l\'ascension',

    'kilimanjaro_back_to_parks' => 'Comparer les neuf parcs',

    'kilimanjaro_faq_badge' => 'FAQ',
    'kilimanjaro_faq_title' => 'Questions fréquentes',
    'kilimanjaro_faq_q1' => 'Ai-je besoin d\'expérience en escalade ?',
    'kilimanjaro_faq_a1' => 'Non. Le Kilimandjaro est une longue marche, pas une escalade technique : aucune technique de corde ni d\'escalade libre. Ce qu\'il demande, c\'est une endurance pour cinq à neuf jours de marche et la capacité à supporter l\'air raréfié.',
    'kilimanjaro_faq_q2' => 'Quel itinéraire a le taux de réussite le plus élevé ?',
    'kilimanjaro_faq_a2' => 'Le Northern Circuit et Lemosho, tous deux autour de 90 à 95 %, grâce à leur profil d\'acclimatation plus long. Marangu, l\'itinéraire le plus court, a le taux de réussite le plus bas, environ 50 à 60 %.',
    'kilimanjaro_faq_q3' => 'Qu\'en est-il du mal des montagnes ?',
    'kilimanjaro_faq_a3' => 'Maux de tête légers et essoufflement sont normaux au-dessus de 4 000 m. Nos guides vérifient la saturation en oxygène deux fois par jour et portent une trousse de premiers secours. Si un guide juge que vous devez redescendre, vous redescendez, sans exception.',
    'kilimanjaro_faq_q4' => 'Quelle forme physique me faut-il ?',
    'kilimanjaro_faq_a4' => 'Aucune condition physique technique n\'est requise, mais plusieurs heures d\'entraînement de randonnée au préalable font une réelle différence. Le défi, c\'est l\'endurance et l\'altitude, pas la force.',
    'kilimanjaro_faq_q5' => 'Quel est le nombre minimum de jours ?',
    'kilimanjaro_faq_a5' => 'Cinq jours (Marangu) est le minimum légal, mais nous recommandons au moins six à sept jours pour une chance nettement meilleure d\'atteindre le sommet.',
    'kilimanjaro_faq_q6' => 'Les débutants peuvent-ils gravir le Kilimandjaro ?',
    'kilimanjaro_faq_a6' => 'Oui, aucune expérience de trekking préalable n\'est requise, bien qu\'une certaine condition physique de randonnée aide. Beaucoup de nos grimpeurs n\'avaient jamais fait de trek de plusieurs jours auparavant.',
    'kilimanjaro_faq_q7' => 'Qu\'est-ce qui est inclus dans un forfait trekking ?',
    'kilimanjaro_faq_a7' => 'Tous les frais de parc, un guide certifié, un cuisinier et des porteurs, les repas et l\'eau potable sur la montagne, les frais de camping ou de huttes, et les transferts à Arusha. Voir la liste complète inclus/non inclus sur notre page trekking.',
    'kilimanjaro_faq_q8' => 'L\'oxygène portable est-il utilisé ?',
    'kilimanjaro_faq_a8' => 'Pas systématiquement. Il est disponible sur demande comme mesure de sécurité supplémentaire, mais une acclimatation adéquate grâce au choix de l\'itinéraire est la stratégie principale sur laquelle nous nous appuyons.',

    'kilimanjaro_cta_title' => 'Prêt à gravir le Kilimandjaro ?',
    'kilimanjaro_cta_intro' => 'Envoyez-nous vos dates et l\'itinéraire préféré. Nous répondons avec un itinéraire détaillé et le prix complet, sans engagement.',
    'kilimanjaro_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'kilimanjaro_cta_safaris' => 'Voir les forfaits trekking',

    'ruaha_meta_title' => 'Guide du parc national de Ruaha (2026) | Serengeti Budget Safari',
    'ruaha_meta_description' => "Guide du parc national de Ruaha : le plus grand parc de Tanzanie, environ 10 % des lions du monde, immenses troupeaux d'éléphants, lycaon, frais de parc 2026 et où loger.",
    'ruaha_hero_badge' => 'Parc national de Ruaha',
    'ruaha_hero_title' => 'Parc national de Ruaha',
    'ruaha_hero_sub' => "Le plus grand parc national de Tanzanie : accidenté, isolé, et abritant environ un dixième des lions restants dans le monde.",
    'ruaha_hero_cta_quote' => 'Demander un devis',

    'ruaha_intro_badge' => 'Aperçu',
    'ruaha_intro_title' => 'Grand, sauvage et presque désert',
    'ruaha_intro_p1' => "Ruaha est le plus grand parc national de Tanzanie avec plus de 20 000 km², plus grand que le Serengeti, mais il reçoit une fraction des visiteurs, en raison du vol supplémentaire requis depuis Dar es Salaam plutôt qu'un transfert routier depuis Arusha.",
    'ruaha_intro_p2' => "Cet isolement fait exactement son attrait : de vastes plaines parsemées de baobabs, la grande rivière Ruaha, et certaines des plus fortes densités de prédateurs d'Afrique, observées depuis un véhicule que vous aurez souvent entièrement pour vous.",
    'ruaha_intro_p3' => "Il récompense les voyageurs ayant déjà fait le circuit nord et souhaitant un lieu véritablement différent : des ciels plus vastes, des pistes plus rudes, et une faune qui réagit aux véhicules comme il se doit, comme une nouveauté plutôt qu'une habitude quotidienne.",
    'ruaha_fact_area' => 'Superficie',
    'ruaha_fact_rank' => 'Classement par taille',
    'ruaha_fact_rank_value' => "Le plus grand parc de Tanzanie",
    'ruaha_fact_lions' => 'Population de lions',
    'ruaha_fact_lions_of_world' => '~10 % des lions sauvages du monde',
    'ruaha_fact_elephants' => 'Population d\'éléphants',
    'ruaha_fact_kudu' => 'Espèces notables',
    'ruaha_fact_kudu_value' => 'Grand et petit koudou',
    'ruaha_fact_visitors' => 'Densité de visiteurs',
    'ruaha_fact_visitors_value' => 'Très faible',
    'ruaha_fact_stay' => 'Séjour recommandé',
    'ruaha_fact_days' => '3 à 4 jours',
    'ruaha_fact_from_dar' => 'Depuis Dar es Salaam',
    'ruaha_fact_by_air' => 'En avion léger',

    'ruaha_regions_badge' => 'Le paysage',
    'ruaha_regions_title' => 'Que voir',
    'ruaha_regions_intro' => 'Ruaha alterne entre trois paysages distincts sur sa vaste étendue.',
    'ruaha_region_river_name' => 'La grande rivière Ruaha',
    'ruaha_region_river_desc' => 'La ligne de vie du parc. Pendant la saison sèche, la faune se concentre le long de ses berges et bancs de sable en nombre rivalisant avec n\'importe quelle traversée de rivière du circuit nord, sans la foule.',
    'ruaha_region_baobab_name' => 'Plaines de baobabs',
    'ruaha_region_baobab_desc' => 'Collines ondulantes parsemées de baobabs anciens, certains estimés à plus de mille ans, donnant à Ruaha une silhouette distinctive contrairement à tout parc du nord.',
    'ruaha_region_miombo_name' => 'Forêt de miombo',
    'ruaha_region_miombo_desc' => 'De vastes étendues de forêt de miombo couvrent une grande partie de l\'intérieur du parc, abritant des espèces comme le grand koudou et l\'antilope rouanne qui préfèrent cet habitat à la prairie ouverte.',

    'ruaha_wildlife_badge' => 'Ce qui y vit',
    'ruaha_wildlife_title' => 'Faune',
    'ruaha_wildlife_intro' => 'Ruaha se situe au chevauchement des espèces d\'Afrique de l\'Est et australe, ce qui lui confère l\'une des listes fauniques les plus diversifiées de tous les parcs tanzaniens.',
    'ruaha_animal_lion' => 'Lion',
    'ruaha_animal_elephant' => 'Éléphant',
    'ruaha_animal_leopard' => 'Léopard',
    'ruaha_animal_cheetah' => 'Guépard',
    'ruaha_animal_wilddog' => 'Lycaon',
    'ruaha_animal_buffalo' => 'Buffle',
    'ruaha_animal_giraffe' => 'Girafe',
    'ruaha_animal_zebra' => 'Zèbre',
    'ruaha_animal_kudu' => 'Grand koudou',
    'ruaha_animal_hippo' => 'Hippopotame',
    'ruaha_wildlife_p1' => "Ruaha abrite environ 10 % des lions sauvages restants dans le monde et une population d'éléphants parmi les plus importantes d'Afrique de l'Est, ainsi que de bonnes populations de léopards et l'une des meilleures chances de Tanzanie de rencontrer le lycaon.",
    'ruaha_wildlife_p2' => 'Le mélange d\'espèces d\'Afrique de l\'Est (lion, girafe, zèbre) et d\'Afrique australe (grand koudou, antilope rouanne, hippotrague) que l\'on ne trouve nulle part ailleurs dans le circuit nord fait partie de ce qui rend Ruaha véritablement unique.',

    'ruaha_when_badge' => 'Planification',
    'ruaha_when_title' => 'Quand y aller',
    'ruaha_when_intro' => 'Ruaha se visite mieux en saison sèche, lorsque la faune se concentre de manière prévisible le long de la rivière.',
    'ruaha_when_p1' => 'De juin à octobre, c\'est le pic de la saison sèche : la rivière se réduit à des mares et des bancs de sable, attirant de grandes concentrations de gibier et les meilleures observations de prédateurs de l\'année.',
    'ruaha_when_p2' => 'De novembre à mai, ce sont les pluies : le parc devient vert, de nombreux camps ferment pour la saison, et les routes peuvent devenir impraticables. Ce n\'est pas une période réaliste pour la plupart des visiteurs.',

    'ruaha_stay_badge' => 'Où loger',
    'ruaha_stay_title' => 'Hébergement',
    'ruaha_stay_intro' => "L'isolement de Ruaha signifie moins d'établissements que le circuit nord, mais une bonne répartition entre les niveaux de budget près de la rivière.",
    'ruaha_stay_budget_title' => 'Camps économiques',
    'ruaha_stay_budget_price' => 'Camping / tente basique',
    'ruaha_stay_budget_desc' => 'Camps tentés simples avec installations partagées, gérés par de petits opérateurs locaux. La façon la plus abordable de découvrir le parc.',
    'ruaha_stay_mid_title' => 'Camps milieu de gamme',
    'ruaha_stay_mid_price' => 'Camp tenté, salle de bain privée',
    'ruaha_stay_mid_desc' => 'Camps tentés permanents confortables avec salles de bain privées, souvent situés le long de la rivière pour observer la faune depuis le camp lui-même.',
    'ruaha_stay_luxury_title' => 'Camps de luxe',
    'ruaha_stay_luxury_price' => 'Camp tenté haut de gamme',
    'ruaha_stay_luxury_desc' => 'Un petit nombre de camps haut de gamme offrent un guidage privé, des terrasses d\'observation surélevées et une sensation vraiment exclusive étant donné le peu de visiteurs que reçoit le parc.',
    'ruaha_stay_note' => 'Nous pouvons organiser un hébergement à n\'importe quel niveau dans le cadre de votre itinéraire à Ruaha, y compris le transfert en avion léger depuis Dar es Salaam.',

    'ruaha_fees_badge' => 'Frais 2026',
    'ruaha_fees_title' => 'Frais d\'entrée du parc',
    'ruaha_fees_intro' => 'Les frais sont par personne et par période de 24 heures et incluent 18 % de TVA. Payables par carte ou carte de parc prépayée. Les espèces ne sont pas acceptées à l\'entrée.',
    'ruaha_table_category' => 'Catégorie',
    'ruaha_table_adult' => 'Adulte',
    'ruaha_table_child' => 'Enfant (5-15 ans)',
    'ruaha_fee_entry' => 'Entrée du parc',
    'ruaha_fee_concession' => 'Frais de concession',
    'ruaha_fee_campsite' => 'Frais de camping',
    'ruaha_fees_note' => 'Lorsque vous voyagez avec nous, tous les frais de parc sont calculés et inclus dans le prix indiqué, sans paiement séparé nécessaire à l\'entrée.',

    'ruaha_gallery_badge' => 'Ruaha en images',
    'ruaha_gallery_title' => 'Ce que vous verrez',
    'ruaha_gallery_caption_1' => 'Troupe de lions dans la plaine',
    'ruaha_gallery_caption_2' => 'Troupeau d\'éléphants au bord de la rivière',
    'ruaha_gallery_caption_3' => 'Léopard se reposant dans un arbre',
    'ruaha_gallery_caption_4' => 'Zèbres traversant la prairie',
    'ruaha_gallery_caption_5' => 'Un paysage parsemé de baobabs',
    'ruaha_gallery_caption_6' => 'Guépard scrutant la savane',

    'ruaha_back_to_parks' => 'Comparer les neuf parcs',

    'ruaha_faq_badge' => 'FAQ',
    'ruaha_faq_title' => 'Questions fréquentes',
    'ruaha_faq_q1' => 'Comment se rendre à Ruaha ?',
    'ruaha_faq_a1' => 'En avion léger depuis Dar es Salaam. Il n\'existe pas d\'itinéraire routier pratique depuis Arusha. Les vols durent généralement environ deux heures.',
    'ruaha_faq_q2' => 'Ruaha vaut-il le coût du vol supplémentaire ?',
    'ruaha_faq_a2' => 'Pour les voyageurs ayant déjà vu le circuit nord, oui. La densité de faune rivalise avec le Serengeti avec une fraction des véhicules, ce qui constitue une expérience véritablement différente.',
    'ruaha_faq_q3' => 'Combien de jours me faut-il ?',
    'ruaha_faq_a3' => 'Trois à quatre jours vous permettent d\'explorer correctement les zones riveraines et boisées sans vous sentir pressé, étant donné les distances de conduite impliquées.',
    'ruaha_faq_q4' => 'Puis-je combiner Ruaha avec d\'autres parcs du sud ?',
    'ruaha_faq_a4' => 'Oui, Ruaha se combine naturellement avec Nyerere (Selous) pour un safari du circuit sud, tous deux accessibles depuis Dar es Salaam.',
    'ruaha_faq_q5' => 'Verrai-je des lycaons ?',
    'ruaha_faq_a5' => 'Ruaha est l\'un des meilleurs endroits de Tanzanie pour le lycaon, bien que les observations ne soient jamais garanties pour aucun animal sauvage. Un séjour de plusieurs jours améliore considérablement vos chances.',
    'ruaha_faq_q6' => 'Ruaha est-il bon pour la photographie ?',
    'ruaha_faq_a6' => 'Très. La faible densité de véhicules signifie des observations ininterrompues et le paysage de baobabs offre des arrière-plans spectaculaires rarement disponibles dans les parcs du nord plus fréquentés.',
    'ruaha_faq_q7' => 'Quelle est la meilleure période pour voir les lions ?',
    'ruaha_faq_a7' => 'Toute l\'année, mais la saison sèche (juin à octobre) les concentre plus prévisiblement le long de la rivière, où les proies se rassemblent également.',
    'ruaha_faq_q8' => 'Ruaha convient-il pour un premier safari ?',
    'ruaha_faq_a8' => "Cela peut être le cas, mais la plupart des primo-visiteurs sont mieux servis en commençant par le circuit nord pour ses transferts plus courts et son infrastructure plus développée. Ruaha récompense les voyageurs qui savent déjà ce qu'ils attendent d'un safari.",

    'ruaha_cta_title' => 'Prêt à visiter Ruaha ?',
    'ruaha_cta_intro' => 'Envoyez-nous vos dates et la taille de votre groupe. Nous répondons avec un itinéraire détaillé et le prix complet, sans engagement.',
    'ruaha_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'ruaha_cta_safaris' => 'Voir les forfaits safari',

    'mikumi_meta_title' => 'Guide du parc national de Mikumi (2026) | Serengeti Budget Safari',
    'mikumi_meta_description' => "Guide du parc national de Mikumi : le safari authentique le plus abordable de Tanzanie, à quatre heures de Dar es Salaam par la route, sans vol nécessaire. Frais 2026, faune et quand y aller.",
    'mikumi_hero_badge' => 'Parc national de Mikumi',
    'mikumi_hero_title' => 'Parc national de Mikumi',
    'mikumi_hero_sub' => "Le safari authentique le moins cher de Tanzanie : à quatre heures de Dar es Salaam par la route, sans vol intérieur nécessaire.",
    'mikumi_hero_cta_quote' => 'Demander un devis',

    'mikumi_intro_badge' => 'Aperçu',
    'mikumi_intro_title' => 'Un vrai safari sans le vol',
    'mikumi_intro_p1' => "Mikumi est le plus accessible des parcs du sud de la Tanzanie : un trajet simple de quatre heures depuis Dar es Salaam sur route goudronnée, sans vol intérieur nécessaire. Cette accessibilité, combinée à des frais de parc inférieurs à ceux du circuit nord, en fait le safari authentique le plus abordable du pays.",
    'mikumi_intro_p2' => "Sa pièce maîtresse est la plaine inondable de Mkata, une prairie ouverte souvent comparée à un Serengeti miniature : de larges horizons, une observation facile de la faune, et aucune des contraintes logistiques de vol de Ruaha ou Nyerere.",
    'mikumi_intro_p3' => "Il fonctionne bien comme safari de week-end depuis Dar es Salaam, comme étape sur la route vers Ruaha ou Nyerere, ou comme introduction économique à la faune tanzanienne.",
    'mikumi_fact_area' => 'Superficie',
    'mikumi_fact_established' => 'Créé en',
    'mikumi_fact_status' => 'Accès',
    'mikumi_fact_status_value' => 'Par la route, sans vol nécessaire',
    'mikumi_fact_lions' => 'Prédateurs',
    'mikumi_fact_lions_value' => 'Lion, léopard présent',
    'mikumi_fact_birds' => 'Espèces d\'oiseaux',
    'mikumi_fact_entry' => 'Niveau des frais d\'entrée',
    'mikumi_fact_stay' => 'Séjour recommandé',
    'mikumi_fact_days' => '1 à 2 jours',
    'mikumi_fact_from_dar' => 'Depuis Dar es Salaam',

    'mikumi_regions_badge' => 'Le paysage',
    'mikumi_regions_title' => 'Que voir',
    'mikumi_regions_intro' => 'Mikumi est centré sur deux habitats contrastés.',
    'mikumi_region_mkata_name' => 'Plaine inondable de Mkata',
    'mikumi_region_mkata_desc' => "Le cœur du parc : prairie ouverte flanquée des montagnes Uluguru et Lumango, abritant les plus fortes concentrations de faune et l'observation la plus facile du parc.",
    'mikumi_region_miombo_name' => 'Forêt de miombo',
    'mikumi_region_miombo_desc' => 'La forêt de miombo des collines entoure la plaine inondable, abritant des espèces moins souvent observées comme l\'élan du Cap et l\'antilope rouanne pour les visiteurs qui explorent au-delà de la plaine.',

    'mikumi_wildlife_badge' => 'Ce qui y vit',
    'mikumi_wildlife_title' => 'Faune',
    'mikumi_wildlife_intro' => 'Mikumi abrite un véritable échantillon de la faune est-africaine, concentré sur la plaine inondable ouverte de Mkata.',
    'mikumi_animal_lion' => 'Lion',
    'mikumi_animal_elephant' => 'Éléphant',
    'mikumi_animal_leopard' => 'Léopard',
    'mikumi_animal_wilddog' => 'Lycaon',
    'mikumi_animal_buffalo' => 'Buffle',
    'mikumi_animal_giraffe' => 'Girafe',
    'mikumi_animal_zebra' => 'Zèbre',
    'mikumi_animal_wildebeest' => 'Gnou',
    'mikumi_animal_hippo' => 'Hippopotame',
    'mikumi_wildlife_p1' => 'La plaine inondable accueille de grands troupeaux de buffles, zèbres et gnous toute l\'année, avec des éléphants couramment observés le long des cours d\'eau saisonniers traversant la prairie.',
    'mikumi_wildlife_p2' => 'Lion et léopard sont tous deux présents et observés régulièrement, et Mikumi est l\'un des rares parcs où le lycaon passe occasionnellement. Jamais garanti, mais une réelle possibilité.',

    'mikumi_when_badge' => 'Planification',
    'mikumi_when_title' => 'Quand y aller',
    'mikumi_when_intro' => 'Mikumi est une destination toute l\'année étant donné sa faible altitude et son accès routier facile.',
    'mikumi_when_p1' => 'De juin à octobre (saison sèche), l\'observation de la faune est la meilleure, car elle se concentre autour des points d\'eau restants sur la plaine inondable.',
    'mikumi_when_p2' => 'De novembre à mai, c\'est plus vert et plus calme, avec des tarifs plus bas dans la plupart des camps : une bonne option pour une visite plus courte et plus abordable si l\'observation de la faune en haute saison n\'est pas la priorité.',

    'mikumi_stay_badge' => 'Où loger',
    'mikumi_stay_title' => 'Hébergement',
    'mikumi_stay_intro' => "L'accès facile de Mikumi depuis Dar es Salaam a attiré une bonne diversité d'hébergements à tous les niveaux de budget.",
    'mikumi_stay_budget_title' => 'Camps économiques',
    'mikumi_stay_budget_price' => 'Camping / tente basique',
    'mikumi_stay_budget_desc' => 'Campings simples et options de tentes basiques près de l\'entrée du parc, la façon la plus abordable de vous baser pour une visite de type excursion à la journée.',
    'mikumi_stay_mid_title' => 'Lodges milieu de gamme',
    'mikumi_stay_mid_price' => 'Lodge, salle de bain privée',
    'mikumi_stay_mid_desc' => 'Lodges confortables surplombant la plaine inondable, offrant un bon équilibre entre confort et prix pour un séjour d\'une ou deux nuits.',
    'mikumi_stay_luxury_title' => 'Lodges de luxe',
    'mikumi_stay_luxury_price' => 'Lodge haut de gamme',
    'mikumi_stay_luxury_desc' => 'Un plus petit nombre d\'établissements haut de gamme offrent des vérandas privées et des vues surélevées sur la plaine, pour les voyageurs souhaitant plus de confort près de Dar.',
    'mikumi_stay_note' => 'Nous pouvons organiser un hébergement à n\'importe quel niveau dans le cadre de votre itinéraire à Mikumi, y compris le transport depuis Dar es Salaam.',

    'mikumi_access_badge' => 'Comment s\'y rendre',
    'mikumi_access_title' => 'Accès depuis Dar es Salaam',
    'mikumi_access_intro' => "Le plus grand avantage de Mikumi par rapport à Ruaha et Nyerere est qu'il ne nécessite aucun vol intérieur.",
    'mikumi_access_p1' => 'Une route goudronnée relie Dar es Salaam à Mikumi en environ quatre heures, ce qui en fait une option réaliste pour un voyage de week-end ou une étape sur un itinéraire du circuit sud plus long vers Ruaha.',
    'mikumi_access_p2' => 'Cet accès routier est la principale raison pour laquelle Mikumi est le safari authentique le plus économique de Tanzanie. Aucun coût de vol charter à intégrer dans votre voyage.',

    'mikumi_fees_badge' => 'Frais 2026',
    'mikumi_fees_title' => 'Frais d\'entrée du parc',
    'mikumi_fees_intro' => 'Les frais sont par personne et par période de 24 heures et incluent 18 % de TVA, parmi les plus bas de tous les parcs nationaux tanzaniens. Payables par carte ou carte de parc prépayée. Les espèces ne sont pas acceptées à l\'entrée.',
    'mikumi_table_category' => 'Catégorie',
    'mikumi_table_adult' => 'Adulte',
