    'mikumi_fee_entry' => 'Entrée du parc',
    'mikumi_fee_campsite' => 'Frais de camping',
    'mikumi_fees_note' => 'Lorsque vous voyagez avec nous, tous les frais de parc sont calculés et inclus dans le prix indiqué, sans paiement séparé nécessaire à l\'entrée.',

    'mikumi_gallery_badge' => 'Mikumi en images',
    'mikumi_gallery_title' => 'Ce que vous verrez',
    'mikumi_gallery_caption_1' => 'Gnous et zèbres sur la plaine inondable',
    'mikumi_gallery_caption_2' => 'Éléphant traversant la prairie',
    'mikumi_gallery_caption_3' => 'Lion se reposant à l\'ombre',
    'mikumi_gallery_caption_4' => 'Troupeau de buffles au crépuscule',
