    'mikumi_back_to_parks' => 'Comparer les neuf parcs',

    'mikumi_faq_badge' => 'FAQ',
    'mikumi_faq_title' => 'Questions fréquentes',
    'mikumi_faq_q1' => 'Dois-je prendre l\'avion pour Mikumi ?',
    'mikumi_faq_a1' => 'Non. Mikumi est accessible par un trajet de quatre heures sur route goudronnée depuis Dar es Salaam, ce qui en fait exactement l\'option safari la plus abordable de Tanzanie.',
    'mikumi_faq_q2' => 'Mikumi convient-il pour un voyage de week-end ?',
    'mikumi_faq_a2' => 'Oui, son trajet court depuis Dar es Salaam en fait une option réaliste pour un safari de week-end de deux jours, ce qu\'aucun autre parc du sud ou du nord ne peut facilement offrir.',
    'mikumi_faq_q3' => 'Verrai-je les Big Five ?',
    'mikumi_faq_a3' => 'Lion, éléphant et buffle sont observés régulièrement. Le léopard est présent mais insaisissable, et le rhinocéros ne se trouve pas à Mikumi. Pour une chance réaliste de voir les Big Five, le Ngorongoro reste le meilleur choix.',
    'mikumi_faq_q4' => 'Comment Mikumi se compare-t-il à Ruaha ou Nyerere ?',
    'mikumi_faq_a4' => 'Mikumi est plus petit et plus facile d\'accès, avec des frais moins élevés, mais Ruaha et Nyerere offrent une plus grande densité de faune et une sensation plus isolée. Mikumi est le choix économique et pratique des trois.',
    'mikumi_faq_q5' => 'Puis-je combiner Mikumi avec Ruaha ?',
    'mikumi_faq_a5' => 'Oui, Mikumi se trouve sur la route vers Ruaha, ce qui en fait une étape naturelle sur un itinéraire du circuit sud plus long.',
    'mikumi_faq_q6' => 'Quelle est la meilleure période pour visiter ?',
    'mikumi_faq_a6' => 'De juin à octobre pour la meilleure observation de la faune, bien que le parc soit accessible et intéressant toute l\'année étant donné sa faible altitude et son accès routier facile.',
    'mikumi_faq_q7' => 'Mikumi convient-il pour un premier safari ?',
    'mikumi_faq_a7' => 'Oui, son accessibilité et son coût plus bas en font une introduction sensée à la faune tanzanienne, en particulier pour les voyageurs basés à ou arrivant via Dar es Salaam.',
    'mikumi_faq_q8' => 'Un véhicule 4x4 est-il nécessaire ?',
    'mikumi_faq_a8' => "Oui, comme pour tout parc national tanzanien, nous fournissons un 4x4 privé avec chauffeur-guide en standard sur chaque itinéraire à Mikumi.",

    'mikumi_cta_title' => 'Prêt à visiter Mikumi ?',
    'mikumi_cta_intro' => 'Envoyez-nous vos dates et la taille de votre groupe. Nous répondons avec un itinéraire détaillé et le prix complet, sans engagement.',
    'mikumi_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
