    'pkg5d_faq_title' => 'Questions fréquentes',
    'pkg5d_faq_q1' => 'Ce safari est-il privé ?',
    'pkg5d_faq_a1' => 'Oui, le véhicule et le guide sont privés pour votre groupe, sauf si vous réservez spécifiquement un départ en groupe partagé. Vous définissez le rythme et les arrêts.',
    'pkg5d_faq_q2' => 'Puis-je personnaliser le safari ?',
    'pkg5d_faq_a2' => 'Oui, des jours supplémentaires, des parcs différents ou une extension à Zanzibar peuvent tous être ajoutés. Dites-nous ce que vous avez en tête et nous ajusterons l\'itinéraire et le prix.',
    'pkg5d_faq_q3' => 'Puis-je commencer à n\'importe quelle date ?',
    'pkg5d_faq_a3' => 'Oui, les safaris privés partent à la date de votre choix, sous réserve de disponibilité des lodges en haute saison (juin-octobre).',
    'pkg5d_faq_q4' => 'La prise en charge à l\'aéroport est-elle incluse ?',
    'pkg5d_faq_a4' => 'Oui, la prise en charge depuis l\'aéroport international du Kilimandjaro ou votre hôtel à Arusha est incluse dans le prix.',
    'pkg5d_faq_q5' => 'Que dois-je apporter ?',
    'pkg5d_faq_a5' => 'Des vêtements de couleurs neutres, une couche chaude pour les matinées fraîches, de la crème solaire, un chapeau, des jumelles et un appareil photo. Nous envoyons une liste complète une fois votre voyage confirmé.',
    'pkg5d_faq_q6' => 'Ce safari convient-il aux enfants ?',
    'pkg5d_faq_a6' => 'Oui, la plupart des lodges sur cet itinéraire accueillent les enfants de tous âges, bien que certains aient un âge minimum pour les game drives. Indiquez-nous les âges des voyageurs et nous confirmerons.',

