    'safari_meta_title' => 'Safaris en Tanzanie | Serengeti, Ngorongoro et Tarangire | Serengeti Budget Safari',
    'safari_meta_description' => 'Forfaits safari en Tanzanie à partir de 200 € par personne et par jour : Serengeti, cratère du Ngorongoro, Tarangire et lac Manyara. Safaris économiques, familiaux, de luxe, de lune de miel et en avion privé organisés par un opérateur local à Arusha.',
