    'safari_park_serengeti_desc' => 'La Grande Migration, la plus forte densité de prédateurs d\'Afrique, et 14 763 km² de plaines.',
    'safari_park_ngorongoro_desc' => '25 000 animaux dans une caldeira de 260 km², et la seule chance réaliste de voir un rhinocéros noir en Tanzanie.',
    'safari_park_tarangire_desc' => 'Baobabs, 3 000 éléphants et 550 espèces d\'oiseaux, à deux heures d\'Arusha et rarement fréquenté.',
