    'safari_park_mikumi_desc' => 'À quatre heures de Dar par la route, sans vol nécessaire : le safari authentique le moins cher de Tanzanie.',

    'safari_included_title' => 'Ce qu\'inclut un safari avec nous',
    'safari_included_subtitle' => 'Sauf indication contraire dans votre devis, chaque prix sur cette page couvre les éléments suivants.',
    'safari_included_heading' => 'Inclus',
    'safari_included_1' => 'Land Cruiser 4x4 avec toit ouvrant et place fenêtre garantie pour tous',
