    'safari_excluded_1' => 'Vols internationaux et visa tanzanien',
    'safari_excluded_2' => 'Assurance voyage (obligatoire)',
    'safari_excluded_3' => 'Boissons autres que l\'eau, et dépenses personnelles',
    'safari_excluded_4' => 'Pourboires pour le guide et le personnel du lodge',
    'safari_excluded_5' => 'Extras optionnels : vol en montgolfière, visites culturelles, vols intérieurs',

    'safari_parks_title' => 'Lisez d\'abord sur les parcs',
    'safari_parks_subtitle' => 'Avant de choisir un itinéraire, il est utile de savoir ce que chaque parc offre réellement. Ces guides sont rédigés par nos propres guides et couvrent la faune, les frais 2026, quand y aller et où loger.',
    'safari_parks_beyond_title' => 'Au-delà du circuit nord',
    'safari_parks_beyond_desc' => 'Trois autres parcs sont accessibles depuis Dar es Salaam plutôt qu\'Arusha. Plus grands, plus déserts et moins chers à l\'entrée, avec des safaris en bateau et à pied que les parcs du nord ne peuvent pas offrir.',
    'safari_parks_full_guide' => 'Guide complet',
    'safari_parks_compare_all' => 'Comparer les neuf parcs côte à côte',

    'safari_faq_title' => 'Questions fréquentes',
    'safari_faq_q1' => 'Combien coûte réellement un safari en Tanzanie ?',
    'safari_faq_a1' => 'Économique à partir d\'environ 200 € par personne et par jour, milieu de gamme 250-350 €, et luxe à partir de 600 €. Les plus grandes variables sont le standing de l\'hébergement et la taille de votre groupe : les frais de parc et le véhicule sont des coûts fixes, donc quatre personnes qui partagent paient nettement moins chacune que deux.',
    'safari_faq_q2' => 'Quelle est la meilleure période pour venir ?',
    'safari_faq_a2' => 'De juin à octobre, c\'est la saison sèche classique avec l\'observation de la faune la plus facile. Janvier et février apportent la saison des naissances à Ndutu. De novembre à mai, c\'est plus vert, plus calme et moins cher, avec quelques pluies l\'après-midi.',
    'safari_faq_q3' => 'Verrons-nous les Big Five ?',
    'safari_faq_a3' => 'Lion, éléphant, buffle et léopard sont observés régulièrement lors d\'un safari du circuit nord de quatre jours. Le rhinocéros noir est le plus difficile : le cratère du Ngorongoro offre la meilleure chance en Tanzanie, mais aucun opérateur ne peut garantir l\'observation d\'un animal sauvage.',
    'safari_faq_q4' => 'Combien de jours nous faut-il ?',
    'safari_faq_a4' => 'Trois jours est le minimum pratique pour atteindre le Serengeti sans passer tout le voyage à conduire. Quatre à cinq jours est l\'idéal. Toute durée plus courte est mieux consacrée à Tarangire, Manyara et le cratère du Ngorongoro, bien plus proches d\'Arusha.',

    'safari_cta_title' => 'Organisez votre voyage avec nous',
    'safari_cta_intro' => 'Envoyez-nous vos dates, la taille de votre groupe et votre budget. Nous répondons avec un itinéraire détaillé et une répartition complète des prix, sans engagement.',
    'safari_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'safari_cta_contact_form' => 'Formulaire de contact',

