    'parks_meta_title' => 'Parcs nationaux de Tanzanie : les 9 parcs comparés (2026) | Serengeti Budget Safari',
    'parks_meta_description' => 'Comparez les parcs nationaux de Tanzanie côte à côte : Serengeti, Ngorongoro, Tarangire, Manyara, Arusha, Kilimandjaro, Nyerere, Ruaha et Mikumi. Frais 2026, faune et jours nécessaires.',

    'parks_hero_badge' => 'Guides des parcs',
    'parks_hero_title' => 'Les parcs nationaux de Tanzanie',
    'parks_hero_sub' => 'Neuf parcs comparés côte à côte : faune, frais 2026, jours nécessaires et lequel convient à votre voyage. Puis lisez le guide complet de ceux qui vous intéressent.',

    'parks_northern_badge' => 'Parcs du nord',
    'parks_northern_title' => 'Le circuit nord',
    'parks_northern_intro' => 'Cinq parcs à moins d\'une journée de route d\'Arusha, et la destination de l\'immense majorité des safaris tanzaniens.',

    'parks_southern_badge' => 'Parcs du sud',
    'parks_southern_title' => 'Le circuit sud',
    'parks_southern_intro' => 'Accessibles depuis Dar es Salaam plutôt qu\'Arusha. Plus grands, plus déserts, moins chers à l\'entrée et plus coûteux à atteindre. Où aller lors d\'un second voyage.',

    'parks_full_guide' => 'Guide complet',

    'parks_serengeti_name' => 'Serengeti',
    'parks_serengeti_desc' => '14 763 km² de plaines, la Grande Migration, et la plus forte densité de grands prédateurs d\'Afrique. Nécessite trois jours minimum.',
    'parks_ngorongoro_name' => 'Ngorongoro',
    'parks_ngorongoro_desc' => 'La plus grande caldeira intacte au monde avec 25 000 animaux à l\'intérieur, et la seule chance réaliste de voir un rhinocéros noir en Tanzanie.',
    'parks_tarangire_name' => 'Tarangire',
    'parks_tarangire_desc' => 'Baobabs et 2 500 à 3 000 éléphants, à deux heures d\'Arusha, et le plus tranquille des quatre parcs principaux.',
    'parks_manyara_name' => 'Lac Manyara',
    'parks_manyara_desc' => 'Forêt d\'eaux souterraines, flamants roses, immenses troupes de babouins, et le seul safari de nuit et passerelle en canopée du circuit.',
    'parks_arusha_name' => 'Parc national d\'Arusha',
    'parks_arusha_desc' => 'À quarante minutes de la ville, et le seul endroit du circuit où l\'on peut marcher, faire du canoë et grimper. Pas de lions.',
    'parks_kilimanjaro_name' => 'Kilimandjaro',
    'parks_kilimanjaro_desc' => 'La plus haute montagne d\'Afrique à 5 895 m, gravie en cinq à neuf jours sur sept itinéraires officiels.',
    'parks_nyerere_name' => 'Nyerere (Selous)',
    'parks_nyerere_desc' => 'Le plus grand parc national d\'Afrique, où vous pouvez faire un safari en bateau, un safari à pied et un game drive le même jour.',
    'parks_ruaha_name' => 'Ruaha',
    'parks_ruaha_desc' => 'Le plus grand parc de Tanzanie, abritant environ 10 % des lions du monde et 12 000 éléphants, avec presque aucun autre véhicule.',
    'parks_mikumi_name' => 'Mikumi',
    'parks_mikumi_desc' => 'Le seul grand parc accessible depuis une ville par la route en une matinée. Plaines ouvertes, lions résidents, safari authentique le moins cher de Tanzanie.',

