    'parks_want_walking' => 'Marcher, pas conduire',
    'parks_why_walking' => 'Les trois autorisent de véritables safaris à pied.',
    'parks_want_oneday' => 'Une seule journée seulement',
    'parks_why_oneday' => 'Les deux sont accessibles et gratifiants en une journée depuis Arusha.',
    'parks_want_budget' => 'Sans vol, petit budget',
    'parks_why_budget' => 'Quatre heures de Dar par la route, les frais d\'entrée les moins chers.',

    'parks_see_safaris' => 'Voir nos itinéraires de safari',

    'parks_faq_badge' => 'FAQ',
    'parks_faq_title' => 'Parcs nationaux tanzaniens : questions fréquentes',
    'parks_faq_q1' => 'Quel est le meilleur parc national de Tanzanie ?',
    'parks_faq_a1' => 'Cela dépend de ce que vous voulez. Le Serengeti pour la migration et les prédateurs, le Ngorongoro pour la densité et le rhinocéros, Tarangire pour les éléphants, Ruaha pour les lions et la solitude, Nyerere pour les safaris en bateau. La plupart des bons itinéraires en combinent deux ou trois plutôt que d\'en choisir un seul.',
    'parks_faq_q2' => 'Combien coûtent les frais de parc tanzaniens en 2026 ?',
    'parks_faq_a2' => 'Serengeti, Ngorongoro et Kilimandjaro sont à 82,60 $ par adulte et par jour ; Tarangire, lac Manyara, parc national d\'Arusha et Nyerere sont à 59,00 $ ; Ruaha et Mikumi sont à 35,40 $. Tous incluent 18 % de TVA. Le Ngorongoro ajoute 295 $ par véhicule pour descendre dans le cratère.',
    'parks_faq_q3' => 'Quelle est la différence entre les circuits nord et sud ?',
    'parks_faq_a3' => 'Le circuit nord part d\'Arusha et comprend le Serengeti, le Ngorongoro, Tarangire, Manyara, le parc national d\'Arusha et le Kilimandjaro. Le circuit sud part de Dar es Salaam et couvre Nyerere, Ruaha et Mikumi : plus grands, plus déserts, moins chers à l\'entrée et plus coûteux à atteindre.',
    'parks_faq_q4' => 'Quels parcs puis-je visiter en une journée depuis Arusha ?',
    'parks_faq_a4' => 'Le parc national d\'Arusha à 40 minutes, Tarangire et le lac Manyara à deux heures, et le Ngorongoro à trois-quatre heures. Le Serengeti est à 7-8 heures et n\'est pas réaliste comme excursion à la journée.',
    'parks_faq_q5' => 'Quel est le parc le moins cher ?',
    'parks_faq_a5' => 'Ruaha et Mikumi à 35,40 $ par adulte. Mais l\'entrée n\'est qu\'une partie du coût : Mikumi ne nécessite aucun vol et est véritablement le safari le moins cher de Tanzanie, tandis que Ruaha nécessite un vol de deux heures depuis Dar.',
    'parks_faq_q6' => 'Quel parc est le meilleur pour les Big Five ?',
    'parks_faq_a6' => 'Le Ngorongoro, car c\'est le seul où le rhinocéros noir est réellement accessible. Le Serengeti vous donne facilement quatre des cinq mais essentiellement aucun rhinocéros. Combiner les deux est la solution standard.',
    'parks_faq_q7' => 'Quelle est la meilleure période pour visiter les parcs tanzaniens ?',
    'parks_faq_a7' => 'De juin à octobre, c\'est la saison sèche et la plus facile partout. Janvier et février conviennent à la saison des naissances du Serengeti. De mars à mai, c\'est humide : les parcs du nord restent ouverts, mais la plupart des camps de Ruaha et Nyerere ferment entièrement.',
    'parks_faq_q8' => 'Combien de jours me faut-il pour un safari tanzanien ?',
    'parks_faq_a8' => 'Deux jours couvrent bien Tarangire et le Ngorongoro. Quatre à cinq ajoutent le Serengeti correctement. Six à huit vous permettent de suivre la migration ou de faire le circuit sud.',
    'parks_faq_q9' => 'Puis-je payer les frais de parc en espèces ?',
    'parks_faq_a9' => 'Non. Les entrées TANAPA et NCAA sont sans espèces. Les frais sont payés par carte ou cartes de parc prépayées. Lorsque vous voyagez avec nous, cela est géré pour vous et inclus dans le prix indiqué.',
    'parks_faq_q10' => 'Dois-je visiter tous les parcs ?',
    'parks_faq_a10' => 'Non, et sur un court voyage, il ne faut pas essayer. Deux parcs bien faits valent mieux que quatre précipités. Une erreur courante est de caser le Serengeti dans un voyage de quatre jours et d\'en passer la majeure partie dans le véhicule.',

    'parks_cta_title' => 'Pas sûr des parcs à choisir ?',
    'parks_cta_intro' => 'Dites-nous combien de jours vous avez et ce que vous voulez le plus voir. Nous vous dirons honnêtement quels parcs valent la peine pour vos dates, y compris quand la réponse est « sautez celui-là ».',
    'parks_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'parks_cta_contact_form' => 'Formulaire de contact',

    // ---------- Serengeti National Park page ----------
    'serengeti_meta_title' => 'Parc national du Serengeti : le guide complet (2026) | Serengeti Budget Safari',
    'serengeti_meta_description' => 'Tout sur le parc national du Serengeti : la Grande Migration mois par mois, les cinq régions, la faune, les frais de parc 2026, où loger et quand y aller.',

    'serengeti_hero_badge' => 'Guide du parc',
    'serengeti_hero_title' => 'Parc national du Serengeti',
    'serengeti_hero_sub' => 'Le guide complet du parc le plus célèbre de Tanzanie : la Grande Migration mois par mois, où loger, ce que ça coûte et quand venir.',
    'serengeti_hero_cta_quote' => 'Demander un devis',

    'serengeti_intro_badge' => 'Introduction',
    'serengeti_intro_title' => 'Qu\'est-ce que le Serengeti ?',
    'serengeti_intro_p1' => 'Le parc national du Serengeti couvre 14 763 km² dans le nord de la Tanzanie, à peu près la taille de l\'Irlande du Nord, et c\'est le plus ancien parc national du pays, créé en 1951. Son nom vient du mot maasaï siringet, « l\'endroit où la terre s\'étend à l\'infini ».',
    'serengeti_intro_p2' => 'Il est célèbre pour une chose avant tout : la Grande Migration, le mouvement continu d\'environ 1,3 million de gnous, 250 000 zèbres et plusieurs centaines de milliers de gazelles suivant les pluies sur un itinéraire à peu près circulaire entre les plaines du sud et le Masai Mara au Kenya. C\'est le plus grand mouvement terrestre d\'animaux restant sur terre, et il se produit en continu. Il n\'y a aucun mois où il s\'arrête.',
    'serengeti_intro_p3' => 'Le Serengeti abrite aussi l\'une des populations de lions les plus denses d\'Afrique (environ 3 000 individus) et plus de 500 espèces d\'oiseaux recensées. Avec la zone de conservation du Ngorongoro, il forme un seul écosystème d\'environ 30 000 km², et il est classé au patrimoine mondial de l\'UNESCO depuis 1981.',

    'serengeti_fact_area' => 'Superficie',
    'serengeti_fact_established' => 'Créé en',
    'serengeti_fact_status' => 'Statut',
    'serengeti_fact_lions' => 'Lions',
    'serengeti_fact_wildebeest' => 'Gnous',
    'serengeti_fact_stay' => 'Séjour suggéré',
    'serengeti_fact_nights' => 'nuits',
    'serengeti_fact_from_arusha' => 'Depuis Arusha',
    'serengeti_fact_by_air' => 'Par avion',

    'serengeti_regions_badge' => 'Où aller',
    'serengeti_regions_title' => 'Les cinq régions du Serengeti',
    'serengeti_regions_intro' => 'Le parc est plus grand que certains pays, et l\'endroit où vous logez détermine ce que vous verrez. Voici les principales zones, et quand chacune est à son meilleur.',
    'serengeti_region_seronera_name' => 'Seronera (Serengeti central)',
    'serengeti_region_seronera_desc' => 'Le cœur du parc et le choix le plus sûr pour une première visite. La vallée fluviale retient de l\'eau toute l\'année, donc la faune résidente ne part jamais : lions, léopards, éléphants, buffles et guépards sont ici chaque mois. Idéal toute l\'année, parfait pour un premier séjour de 2 à 3 nuits.',
    'serengeti_region_ndutu_name' => 'Ndutu et les plaines du sud',
    'serengeti_region_ndutu_desc' => 'De décembre à mars, les troupeaux de la migration s\'y concentrent pour mettre bas, et la densité de prédateurs qui les suit est extraordinaire. C\'est le meilleur moment et le meilleur endroit en Tanzanie pour observer une chasse. En dehors de ces mois, les plaines se vident presque complètement.',
    'serengeti_region_western_name' => 'Corridor occidental et rivière Grumeti',
    'serengeti_region_western_desc' => 'Un long bras du parc s\'étendant vers l\'ouest en direction du lac Victoria. Les troupeaux y passent d\'environ mai à juillet, et les traversées de la Grumeti s\'y produisent, plus petites que celles de la Mara, mais avec certains des plus grands crocodiles d\'Afrique attendant dans les mares.',
    'serengeti_region_kogatende_name' => 'Kogatende et le Serengeti du Nord',
    'serengeti_region_kogatende_desc' => 'Collines ondulantes et brousse dense le long de la rivière Mara, à la frontière kényane. De juillet à octobre, c\'est ici que se produisent les traversées de rivière. En dehors de la saison des traversées, c\'est l\'une des parties les plus calmes et les plus belles du parc.',

    'serengeti_migration_badge' => 'Grande Migration',
    'serengeti_migration_title' => 'La Grande Migration, mois par mois',
    'serengeti_migration_intro' => 'La migration n\'est pas un événement avec une date. C\'est un circuit continu dicté par les précipitations, et les troupeaux se trouvent quelque part dans l\'écosystème chaque mois de l\'année.',
    'serengeti_table_months' => 'Mois',
    'serengeti_table_where' => 'Où sont les troupeaux',
    'serengeti_table_what_happens' => 'Ce qui se passe',
    'serengeti_mig_ndutu' => 'Ndutu et plaines du sud',
    'serengeti_mig_calving' => 'Saison des naissances. Environ 400 000 petits naissent, avec l\'activité des prédateurs à son maximum de l\'année.',
    'serengeti_mig_moving_nw' => 'En mouvement vers le nord-ouest',
    'serengeti_mig_rains' => 'Grandes pluies. Les colonnes se forment et traversent le Serengeti central vers le corridor occidental.',
    'serengeti_mig_western' => 'Corridor occidental',
    'serengeti_mig_grumeti' => 'Traversées de la rivière Grumeti. Plus petites que la Mara mais avec d\'énormes crocodiles et une fraction des véhicules.',
    'serengeti_mig_northern' => 'Serengeti du Nord et Masai Mara',
    'serengeti_mig_mara' => 'Traversées de la rivière Mara : l\'image classique. Août et septembre sont les mois de pointe.',
    'serengeti_mig_returning' => 'Retour vers le sud',
    'serengeti_mig_south' => 'Les petites pluies ramènent les troupeaux vers le Serengeti oriental en direction des zones de mise bas.',
    'serengeti_migration_note' => 'La pluie décale ce schéma de deux ou trois semaines dans un sens ou l\'autre. Aucun opérateur ne peut promettre une traversée à une date fixe.',

    'serengeti_wildlife_badge' => 'Faune',
    'serengeti_wildlife_title' => 'Faune : ce que vous verrez réellement',
    'serengeti_wildlife_intro' => 'Sur un safari de trois jours dans le Serengeti central, basé sur les registres d\'observations de nos guides.',
    'serengeti_animal_lion' => 'Lion, densité la plus élevée d\'Afrique',
    'serengeti_animal_leopard' => 'Léopard, vallée de Seronera',
    'serengeti_animal_elephant' => 'Éléphant',
    'serengeti_animal_buffalo' => 'Buffle',
    'serengeti_animal_cheetah' => 'Guépard, plaines du sud',
    'serengeti_animal_zebra' => 'Zèbre',
    'serengeti_animal_giraffe' => 'Girafe',
    'serengeti_animal_hyena' => 'Hyène tachetée',
    'serengeti_animal_rhino' => 'Rhinocéros noir, très rare, Moru Kopjes uniquement',
    'serengeti_wildlife_p1' => 'Lion, léopard, éléphant et buffle sont tous réalistes lors d\'un safari de trois jours au Serengeti. Le rhinocéros noir ne l\'est pas : une petite population protégée survit autour des Moru Kopjes, mais les observations sont rares et généralement lointaines. Si voir le rhinocéros compte pour vous, ajoutez le cratère du Ngorongoro à votre itinéraire.',
    'serengeti_wildlife_p2' => 'La population de lions du Serengeti, environ 3 000 individus, est la plus importante d\'Afrique, organisée en troupes qui détiennent un territoire pendant des générations. Les guépards privilégient les plaines ouvertes du sud où ils peuvent courir ; les léopards privilégient les acacias riverains. Les hyènes tachetées sont bien plus nombreuses que ne l\'imaginent la plupart des visiteurs et sont elles-mêmes des chasseuses accomplies.',

    'serengeti_when_badge' => 'Meilleure période',
    'serengeti_when_title' => 'Quand visiter',
    'serengeti_when_intro' => 'Il n\'y a pas de saison fermée. Ce qui change, c\'est ce que vous voyez, combien d\'autres véhicules sont présents à l\'observation, et ce que vous payez.',
    'serengeti_when_p1' => 'Premier safari, vous voulez que ce soit facile : juin à octobre. Végétation clairsemée, animaux concentrés près de l\'eau, météo fiable. Vous voulez le plus de spectacle animalier : fin janvier à février à Ndutu.',
    'serengeti_when_p2' => 'Vous voulez un bon rapport qualité-prix et de l\'espace : mars, avril, mai ou novembre. Vous aurez de la pluie, mais vous aurez aussi le parc presque pour vous seul à une fraction du prix.',

    'serengeti_stay_badge' => 'Hébergement',
    'serengeti_stay_title' => 'Où loger',
    'serengeti_stay_intro' => 'L\'hébergement est la plus grande variable dans le coût d\'un safari au Serengeti. Les distances sont si grandes que l\'endroit où vous dormez détermine la part de votre journée passée à conduire plutôt qu\'à observer.',
    'serengeti_stay_budget_title' => 'Économique',
    'serengeti_stay_budget_price' => 'à partir de 35,40 $/nuit de frais de camping',
    'serengeti_stay_budget_desc' => 'Camping public : votre propre tente, toilettes à la turque partagées et douches froides, le cuisinier prépare les repas sur place. À l\'intérieur du parc, pour les aventuriers.',
    'serengeti_stay_mid_title' => 'Milieu de gamme',
    'serengeti_stay_mid_price' => '150-400 $/nuit',
    'serengeti_stay_mid_desc' => 'Lodge ou camp tenté à l\'intérieur du parc : bâtiment permanent ou toile avec de vrais lits et salles de bain privées. Vous vous réveillez au milieu de l\'écosystème.',
    'serengeti_stay_luxury_title' => 'Luxe',
    'serengeti_stay_luxury_price' => '300-700 $+/nuit',
    'serengeti_stay_luxury_desc' => 'Camps mobiles qui se déplacent pour suivre la migration, ou camps tentés haut de gamme. Petits, isolés, peu de véhicules à proximité.',
    'serengeti_stay_note' => 'Dormir à l\'intérieur du parc coûte plus cher : des frais de concession de 59,00 $ par adulte et par nuit en plus du tarif de la chambre. Mais vous êtes déjà au cœur de l\'action à l\'aube et au crépuscule, quand les prédateurs sont les plus actifs.',

    'serengeti_fees_badge' => 'Coûts',
    'serengeti_fees_title' => 'Frais de parc (2026)',
    'serengeti_fees_intro' => 'Les frais sont fixés par la TANAPA, l\'autorité des parcs nationaux de Tanzanie, et sont identiques pour chaque opérateur.',
    'serengeti_table_category' => 'Catégorie',
    'serengeti_table_adult' => 'Adulte (16+)',
    'serengeti_table_child' => 'Enfant (5-15 ans)',
    'serengeti_fee_entry' => 'Entrée, par 24 heures',
    'serengeti_fee_concession' => 'Concession, dormir dans le parc (par nuit)',
    'serengeti_fee_campsite' => 'Camping public (par nuit)',
    'serengeti_fees_note' => 'Tous les montants incluent 18 % de TVA. Les enfants de moins de 5 ans entrent gratuitement. Les frais sont révisés par le gouvernement et peuvent changer sans préavis. Votre devis écrit indique toujours le montant exact pour vos dates.',

    'serengeti_gallery_badge' => 'Galerie',
    'serengeti_gallery_title' => 'Le Serengeti en images',
    'serengeti_gallery_caption_1' => 'Troupe de lions avec une proie',
    'serengeti_gallery_caption_2' => 'Léopard se reposant dans un arbre',
    'serengeti_gallery_caption_3' => 'Troupeau de zèbres dans la plaine',
    'serengeti_gallery_caption_4' => 'Guépards à l\'ombre',
    'serengeti_gallery_caption_5' => 'Lions traquant des zèbres',
    'serengeti_gallery_caption_6' => 'Léopard, vue large',

    'serengeti_back_to_parks' => 'Comparer tous les parcs',

    'serengeti_faq_badge' => 'FAQ',
    'serengeti_faq_title' => 'Parc national du Serengeti : questions fréquentes',
    'serengeti_faq_q1' => 'Combien coûte l\'entrée au Serengeti ?',
    'serengeti_faq_a1' => 'Les frais d\'entrée 2026 pour les non-résidents sont de 82,60 $ par adulte et 23,60 $ par enfant de 5 à 15 ans, par 24 heures, TVA de 18 % incluse. Les enfants de moins de 5 ans entrent gratuitement. Si vous dormez dans le parc, il y a aussi des frais de concession de 59,00 $ par adulte et par nuit, ou 35,40 $ pour un camping public.',
    'serengeti_faq_q2' => 'Combien de jours me faut-il au Serengeti ?',
    'serengeti_faq_a2' => 'Trois jours est le minimum réaliste, et quatre à cinq est l\'idéal. Avec moins de trois jours, le long trajet depuis Arusha consomme la majeure partie de votre voyage. Vous verriez plus de faune en visitant plutôt Tarangire, le lac Manyara et le cratère du Ngorongoro.',
    'serengeti_faq_q3' => 'Quelle est la meilleure période pour visiter le Serengeti ?',
    'serengeti_faq_a3' => 'Juin à octobre pour l\'observation la plus facile de la faune et les traversées de la rivière Mara. Fin janvier et février pour la saison des naissances à Ndutu, qui offre sans doute le meilleur spectacle animalier. Mars à mai est humide, désert et le moins cher.',
    'serengeti_faq_q4' => 'Verrai-je forcément une traversée de rivière ?',
    'serengeti_faq_a4' => 'Non, et méfiez-vous de quiconque en promet une. Les traversées sont imprévisibles : les troupeaux peuvent attendre sur la berge toute une journée puis repartir. Trois nuits à Kogatende entre juillet et octobre vous donnent une bonne chance, pas une garantie.',
    'serengeti_faq_q5' => 'Puis-je voir les Big Five au Serengeti ?',
    'serengeti_faq_a5' => 'Quatre d\'entre eux de manière fiable : lion, léopard, éléphant et buffle. Le rhinocéros noir ne survit qu\'en petit nombre autour des Moru Kopjes et est rarement observé. Pour le rhinocéros, ajoutez le cratère du Ngorongoro à votre itinéraire.',
    'serengeti_faq_q6' => 'Comment aller d\'Arusha au Serengeti ?',
    'serengeti_faq_a6' => 'Par la route, il y a environ 325 km et 7 à 8 heures jusqu\'à Seronera, généralement fractionnées avec un arrêt à Ngorongoro ou Karatu. En avion léger, c\'est environ 1 heure 15. De nombreux itinéraires font l\'aller en voiture et le retour en avion, ou l\'inverse.',
    'serengeti_faq_q7' => 'Puis-je faire un safari au Serengeti avec un petit budget ?',
    'serengeti_faq_a7' => 'Oui, les safaris en camping commencent à environ 200 € par personne et par jour. Vous avez le même guide, le même véhicule et les mêmes animaux ; vous économisez sur l\'hébergement. Voyager en groupe de quatre plutôt qu\'à deux réduit aussi considérablement le coût par personne.',
    'serengeti_faq_q8' => 'Le Serengeti est-il meilleur que le Masai Mara ?',
    'serengeti_faq_a8' => 'C\'est le même écosystème divisé par une frontière. Le Serengeti est environ quinze fois plus grand, a des habitats plus variés et bien plus d\'espace entre les véhicules ; la Mara est plus compacte, donc les observations arrivent plus vite mais avec plus de monde.',

    'serengeti_cta_title' => 'Prêt à planifier votre safari au Serengeti ?',
    'serengeti_cta_intro' => 'Envoyez-nous vos dates, la taille de votre groupe et votre budget. Nous répondons avec un itinéraire détaillé et une répartition complète des prix, sans engagement.',
    'serengeti_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'serengeti_cta_safaris' => 'Voir les itinéraires de safari',

    'ngorongoro_meta_title' => 'Cratère du Ngorongoro : le guide complet (2026) | Serengeti Budget Safari',
    'ngorongoro_meta_description' => 'Tout sur le cratère du Ngorongoro : chances de voir le rhinocéros noir, les frais de descente 2026 de 295 $, quand y aller, où loger et les Maasaï qui y vivent.',

    'ngorongoro_hero_badge' => 'Guide du parc',
    'ngorongoro_hero_title' => 'Cratère du Ngorongoro',
    'ngorongoro_hero_sub' => 'La plus grande caldeira intacte au monde, 25 000 animaux dans un bol de 260 km², et la meilleure chance de voir un rhinocéros noir en Tanzanie, le tout en une seule journée.',
    'ngorongoro_hero_cta_quote' => 'Demander un devis',

    'ngorongoro_intro_badge' => 'Introduction',
    'ngorongoro_intro_title' => 'Qu\'est-ce que le cratère du Ngorongoro ?',
    'ngorongoro_intro_p1' => 'Le cratère du Ngorongoro est la plus grande caldeira volcanique intacte au monde : un bol de 19 km de diamètre, 610 m de profondeur et 260 km² de superficie, avec des parois qui s\'élèvent presque verticalement depuis le fond. Environ 25 000 grands animaux y vivent en permanence, ce qui lui confère la plus forte densité de gros gibier de toute l\'Afrique.',
    'ngorongoro_intro_p2' => 'Le cratère se trouve au sein de la bien plus vaste zone de conservation du Ngorongoro, 8 292 km² de hautes terres, de forêt et de plaines qui contient aussi les gorges d\'Olduvai, les cratères d\'Empakaai et d\'Olmoti, et les plaines de Ndutu où la Grande Migration met bas. C\'est un site classé au patrimoine mondial de l\'UNESCO, inhabituel en Afrique pour être une zone à usages multiples : environ 100 000 Maasaï y vivent avec leur bétail aux côtés de la faune sauvage.',
    'ngorongoro_intro_p3' => 'Pour la plupart des visiteurs, un fait règle la question : c\'est l\'endroit le plus fiable de Tanzanie pour voir le rhinocéros noir, et donc l\'endroit où compléter les Big Five en une seule journée est véritablement possible.',

    'ngorongoro_fact_crater_area' => 'Fond du cratère',
    'ngorongoro_fact_nca_area' => 'Zone de conservation',
    'ngorongoro_fact_status' => 'Statut',
    'ngorongoro_fact_rhino' => 'Rhinocéros noir',
    'ngorongoro_fact_animals' => 'Animaux dans le cratère',
    'ngorongoro_fact_stay' => 'Séjour suggéré',
    'ngorongoro_fact_day' => 'jour',
    'ngorongoro_fact_from_arusha' => 'Depuis Arusha',
    'ngorongoro_fact_descent_limit' => 'Limite de descente au cratère',

    'ngorongoro_areas_badge' => 'Comprendre la zone',
    'ngorongoro_areas_title' => 'Le cratère contre la zone de conservation élargie',
    'ngorongoro_areas_intro' => 'Les gens disent souvent « Ngorongoro » pour désigner deux choses différentes. Voici la distinction, et pourquoi elle compte pour votre itinéraire.',
    'ngorongoro_area_floor_name' => 'Le fond du cratère',
    'ngorongoro_area_floor_desc' => 'La caldeira de 260 km² elle-même : un bol autonome où vivent la plupart des animaux toute l\'année car les parois les retiennent. C\'est ce que presque tout le monde entend par « cratère du Ngorongoro », et c\'est là que vous passez votre journée de game drive.',
    'ngorongoro_area_wider_name' => 'La zone de conservation',
    'ngorongoro_area_wider_desc' => 'La région entière de 8 292 km² entourant le cratère : hautes terres, forêt, les plaines de Ndutu et deux cratères supplémentaires, Empakaai et Olmoti. C\'est une zone à usages multiples classée par l\'UNESCO où environ 100 000 Maasaï vivent aux côtés de la faune, contrairement à un parc national où les populations sont exclues.',
    'ngorongoro_area_olduvai_name' => 'Gorges d\'Olduvai',
    'ngorongoro_area_olduvai_desc' => 'À une demi-heure du cratère, sur la route du Serengeti, les gorges d\'Olduvai s\'enfoncent sur 90 m à travers deux millions d\'années de sédiments volcaniques. Louis et Mary Leakey y ont travaillé à partir des années 1930 et y ont trouvé des restes d\'hominidés qui ont transformé les connaissances sur les origines humaines, dont Paranthropus boisei en 1959. Il y a un petit musée, et cela s\'intègre facilement dans le trajet entre le Ngorongoro et le Serengeti.',

    'ngorongoro_maasai_badge' => 'Population',
    'ngorongoro_maasai_title' => 'Les Maasaï qui vivent ici',
    'ngorongoro_maasai_intro' => 'Le Ngorongoro n\'est pas un parc national, et la distinction est délibérée.',
    'ngorongoro_maasai_p1' => 'Lorsque le Serengeti a été créé en 1959, les Maasaï qui y vivaient ont été déplacés ; le Ngorongoro a été créé comme une zone de conservation à usages multiples où humains, bétail et faune partagent la terre. Environ 100 000 Maasaï vivent aujourd\'hui dans la zone de conservation avec environ un million de têtes de bétail, faisant paître le fond du cratère le jour et retournant sur le bord la nuit.',
    'ngorongoro_maasai_p2' => 'Visiter un boma maasaï est possible et s\'organise via l\'autorité de conservation. La qualité varie. Certaines visites sont très mises en scène. Nous travaillons avec des communautés avec lesquelles nous entretenons des relations de longue date, où les frais parviennent au village et où vous pouvez véritablement poser des questions.',

    'ngorongoro_wildlife_badge' => 'Faune',
    'ngorongoro_wildlife_title' => 'Faune : ce que vous verrez réellement',
    'ngorongoro_wildlife_intro' => 'Probabilités d\'observation pour une seule journée complète sur le fond du cratère. Étonnamment élevées, car les animaux ne peuvent pas se disperser.',
    'ngorongoro_animal_lion' => 'Lion, environ 95 % de chances',
    'ngorongoro_animal_rhino' => 'Rhinocéros noir, environ 60 % de chances',
    'ngorongoro_animal_buffalo' => 'Buffle, quasi certain',
    'ngorongoro_animal_zebra' => 'Zèbre, quasi certain',
    'ngorongoro_animal_elephant' => 'Éléphant, mâles de la forêt de Lerai',
    'ngorongoro_animal_hippo' => 'Hippopotame, marais de Gorigor',
    'ngorongoro_animal_hyena' => 'Hyène tachetée',
    'ngorongoro_animal_flamingo' => 'Flamant rose, lac Magadi',
    'ngorongoro_animal_leopard' => 'Léopard, rare, forêt du bord uniquement',
    'ngorongoro_wildlife_p1' => 'Lion, buffle, éléphant et rhinocéros noir sont tous réalistes lors d\'une seule journée au cratère : une véritable chance de voir les Big Five en 24 heures, ce qui est inhabituel partout en Afrique. Seul le léopard est un véritable coup de chance : ils vivent dans la forêt du bord et sont rarement vus depuis le fond. Il n\'y a aucune girafe : les routes de descente sont trop raides pour elles.',
    'ngorongoro_wildlife_p2' => 'Les lions du cratère sont parmi les plus étudiés au monde et illustrent le coût de l\'isolement : la population est effectivement fermée, la diversité génétique est faible, et une épidémie en 1962 les a réduits à une poignée d\'individus. Le nombre actuel est d\'environ 60, et ils sont très habitués aux véhicules. Environ 30 rhinocéros noirs vivent dans le cratère sous la protection permanente de rangers, généralement observés à distance à travers l\'herbe ouverte, alors apportez des jumelles.',

    'ngorongoro_when_badge' => 'Meilleure période',
    'ngorongoro_when_title' => 'Quand visiter',
    'ngorongoro_when_intro' => 'Le cratère fonctionne chaque mois. Les animaux ne migrent pas, donc contrairement au Serengeti, il n\'y a pas de mauvaise saison pour l\'observation de la faune.',
    'ngorongoro_when_p1' => 'Juin à octobre est le plus sec, le plus froid à l\'aube et le plus fréquenté : attendez-vous à d\'autres véhicules à chaque observation. Mars à mai apporte les grandes pluies : routes de descente glissantes et brume qui peut persister sur le bord jusqu\'en milieu de matinée, mais aussi le cratère le plus vert et les tarifs les moins chers.',
    'ngorongoro_when_p2' => 'Plus important que le mois est d\'être sur le fond à 06h30. Les prédateurs sont actifs dans les deux premières heures, la lumière est douce, et vous devancez les véhicules qui descendent à neuf heures. Cette seule décision change la qualité de la journée plus que la saison.',

    'ngorongoro_stay_badge' => 'Hébergement',
    'ngorongoro_stay_title' => 'Où loger',
    'ngorongoro_stay_intro' => 'Trois grands choix, et la décision porte surtout sur l\'heure à laquelle vous pouvez être à la porte de descente.',
    'ngorongoro_stay_budget_title' => 'Économique',
    'ngorongoro_stay_budget_price' => 'à partir de 35,40 $/nuit de frais de camping',
    'ngorongoro_stay_budget_desc' => 'Camping public Simba, sur le bord même : votre propre tente, installations partagées basiques, et buffles ou zèbres errant parfois dans le camp la nuit. Froid à 2 400 m : un vrai sac de couchage n\'est pas optionnel.',
    'ngorongoro_stay_mid_title' => 'Karatu',
    'ngorongoro_stay_mid_price' => '60-200 $/nuit',
    'ngorongoro_stay_mid_desc' => 'Une vraie ville à 30-45 minutes de l\'entrée : bien meilleur rapport qualité-prix, plus chaud, plus de choix de restaurants. Le compromis est un départ matinal, vers 05h30, pour être le premier sur la route de descente.',
    'ngorongoro_stay_luxury_title' => 'Lodge sur le bord du cratère',
    'ngorongoro_stay_luxury_price' => '250-800 $+/nuit',
    'ngorongoro_stay_luxury_desc' => 'La vue plongeante sur le cratère depuis votre chambre, et à dix minutes de la route de descente pour être le premier sur le fond. Coûteux, froid la nuit, et souvent complet des mois à l\'avance.',
    'ngorongoro_stay_note' => 'Si vous ne visitez que pour une journée et que le coût n\'est pas le facteur décisif, logez sur le bord. Être le premier sur le fond vaut beaucoup. Si vous avez plusieurs jours dans la région, Karatu est la base sensée et l\'argent économisé peut payer une nuit supplémentaire au Serengeti.',

    'ngorongoro_fees_badge' => 'Coûts',
    'ngorongoro_fees_title' => 'Frais de parc (2026)',
    'ngorongoro_fees_intro' => 'Le Ngorongoro est administré par la NCAA, pas la TANAPA, et il comporte un frais qui surprend les gens : des frais séparés simplement pour descendre en voiture dans le cratère, facturés par véhicule plutôt que par personne.',
    'ngorongoro_table_category' => 'Catégorie',
    'ngorongoro_table_adult' => 'Adulte (16+)',
    'ngorongoro_table_child' => 'Enfant (5-15 ans)',
    'ngorongoro_fee_entry' => 'Entrée dans la zone de conservation, par 24 heures',
    'ngorongoro_fee_descent' => 'Frais de service du cratère (descente, par véhicule)',
    'ngorongoro_fee_descent_value' => '295,00 $ par véhicule',
    'ngorongoro_fee_concession' => 'Concession, dormir dans la NCA (par nuit)',
    'ngorongoro_fee_campsite' => 'Camping public (par nuit)',
    'ngorongoro_fees_note' => 'Tous les montants incluent 18 % de TVA. Les enfants de moins de 5 ans entrent gratuitement. Les frais de descente au cratère sont par véhicule, pas par personne, donc le coût par tête chute fortement avec la taille du groupe : environ 148 $ chacun pour deux personnes, moins de 50 $ chacun pour six. Ils s\'appliquent à chaque descente, donc une deuxième journée au cratère signifie les payer deux fois. Les frais peuvent changer sans préavis ; votre devis écrit indique toujours le montant exact pour vos dates.',

    'ngorongoro_gallery_badge' => 'Galerie',
    'ngorongoro_gallery_title' => 'Le Ngorongoro en images',
    'ngorongoro_gallery_caption_1' => 'Le cratère depuis le bord',
    'ngorongoro_gallery_caption_2' => 'Rhinocéros dans l\'herbe',
    'ngorongoro_gallery_caption_3' => 'Éléphant sous un acacia',
    'ngorongoro_gallery_caption_4' => 'Lion mâle sur le fond du cratère',
    'ngorongoro_gallery_caption_5' => 'Hyène tachetée dans la plaine',
    'ngorongoro_gallery_caption_6' => 'Famille d\'éléphants au coucher du soleil',

    'ngorongoro_back_to_parks' => 'Comparer tous les parcs',

    'ngorongoro_faq_badge' => 'FAQ',
    'ngorongoro_faq_title' => 'Cratère du Ngorongoro : questions fréquentes',
    'ngorongoro_faq_q1' => 'Combien coûte la visite du cratère du Ngorongoro ?',
    'ngorongoro_faq_a1' => 'En 2026, 82,60 $ par adulte pour 24 heures d\'entrée dans la zone de conservation, plus des frais de service du cratère de 295,00 $ par véhicule pour la descente. Les enfants de 5 à 15 ans paient 23,60 $ ; les moins de cinq ans sont gratuits. Tous les montants incluent 18 % de TVA.',
    'ngorongoro_faq_q2' => 'Pourquoi les frais de descente au cratère sont-ils si élevés ?',
    'ngorongoro_faq_a2' => 'Ils sont facturés par véhicule plutôt que par personne et financent la conservation et le programme de protection des rhinocéros. Comme c\'est par véhicule, le coût par tête chute fortement avec la taille du groupe : environ 148 $ chacun pour deux personnes, moins de 50 $ chacun pour six.',
    'ngorongoro_faq_q3' => 'Verrai-je le rhinocéros noir dans le cratère ?',
    'ngorongoro_faq_a3' => 'Environ 30 vivent dans le cratère et les chances sur une journée complète sont d\'environ 60 %, mais généralement à distance à travers l\'herbe ouverte. Apportez des jumelles. Le matin tôt offre la meilleure chance, avant qu\'ils ne se retirent vers les abords du marais.',
    'ngorongoro_faq_q4' => 'Puis-je voir les Big Five en une journée ?',
    'ngorongoro_faq_a4' => 'Au Ngorongoro, c\'est véritablement possible, ce qui est inhabituel. Lion, buffle et éléphant sont quasi certains, le rhinocéros est probable, et seul le léopard est un véritable coup de chance : ils vivent dans la forêt du bord et sont rarement vus depuis le fond.',
    'ngorongoro_faq_q5' => 'Combien de temps puis-je rester dans le cratère ?',
    'ngorongoro_faq_a5' => 'Six heures à partir du moment où vous descendez. La limite est appliquée à la porte de sortie et existe pour contrôler le nombre de véhicules sur un petit espace.',
    'ngorongoro_faq_q6' => 'À quelle distance est le Ngorongoro d\'Arusha, et puis-je le faire en excursion d\'une journée ?',
    'ngorongoro_faq_a6' => 'Environ 180 km, trois à quatre heures par la route. Oui, une excursion d\'une journée est possible, en partant vers 05h30 et en revenant après la tombée de la nuit, et cela reste l\'un de nos safaris d\'une journée les plus demandés, puisqu\'il se trouve directement sur la route du Serengeti.',
    'ngorongoro_faq_q7' => 'Quelle est la différence entre le cratère et la zone de conservation ?',
    'ngorongoro_faq_a7' => 'Le cratère est le fond de la caldeira de 260 km². La zone de conservation est la région de 8 292 km² qui l\'entoure, incluant aussi les gorges d\'Olduvai, les cratères d\'Empakaai et d\'Olmoti, les plaines de Ndutu et environ 100 000 résidents maasaï.',
    'ngorongoro_faq_q8' => 'Dois-je loger sur le bord ou à Karatu ?',
    'ngorongoro_faq_a8' => 'Les lodges du bord coûtent 250-800 $ et vous permettent d\'être le premier sur le fond. Karatu coûte 60-200 $ et ajoute un trajet de 30 à 45 minutes avant l\'aube. Pour une seule journée au cratère, le bord en vaut la peine ; pour des séjours plus longs, Karatu offre un meilleur rapport qualité-prix.',

    'ngorongoro_cta_title' => 'Prêt à planifier votre safari au Ngorongoro ?',
    'ngorongoro_cta_intro' => 'Envoyez-nous vos dates, la taille de votre groupe et votre budget. Nous répondons avec un itinéraire détaillé et une répartition complète des prix, sans engagement.',
    'ngorongoro_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'ngorongoro_cta_safaris' => 'Voir les itinéraires de safari',

    'tarangire_meta_title' => 'Parc national de Tarangire : le guide complet (2026) | Serengeti Budget Safari',
    'tarangire_meta_description' => 'Tout sur le parc national de Tarangire : éléphants, baobabs anciens, 550 espèces d\'oiseaux, frais de parc 2026, où loger et quand y aller.',

    'tarangire_hero_badge' => 'Guide du parc',
    'tarangire_hero_title' => 'Parc national de Tarangire',
    'tarangire_hero_sub' => 'Baobabs anciens, les plus grands troupeaux d\'éléphants du nord de la Tanzanie et plus d\'espèces d\'oiseaux que tout autre parc du pays. À deux heures d\'Arusha, et bien plus calme que ses voisins.',
    'tarangire_hero_cta_quote' => 'Demander un devis',

    'tarangire_intro_badge' => 'Introduction',
    'tarangire_intro_title' => 'Qu\'est-ce que Tarangire ?',
    'tarangire_intro_p1' => 'Le parc national de Tarangire couvre 2 850 km² de forêt sèche d\'acacias et de pays de baobabs à deux heures au sud d\'Arusha. C\'est le sixième plus grand parc de Tanzanie et, pour des raisons difficiles à justifier, le plus systématiquement négligé du circuit nord.',
    'tarangire_intro_p2' => 'Il tire son nom de la rivière Tarangire, qui traverse toute la longueur du parc et constitue la seule eau permanente à des kilomètres à la ronde. En saison sèche, ce seul fait transforme le lieu : des animaux venus d\'un écosystème bien plus vaste convergent vers la rivière, et la concentration de gibier entre juin et octobre rivalise avec tout ce que l\'on trouve au Serengeti.',
    'tarangire_intro_p3' => 'Tarangire est surtout connu pour deux choses : les éléphants, avec une population résidente de 2 500 à 3 000 individus où des troupeaux de cinquante ou plus sont banals ici, et les baobabs, ces arbres énormes au tronc renflé qui donnent au paysage un caractère introuvable ailleurs sur le circuit. Il abrite aussi plus de 550 espèces d\'oiseaux recensées, le compte le plus élevé de tous les parcs tanzaniens.',

    'tarangire_fact_area' => 'Superficie',
    'tarangire_fact_established' => 'Créé en',
    'tarangire_fact_elephants' => 'Éléphants',
    'tarangire_fact_baobabs' => 'Baobabs',
    'tarangire_fact_baobabs_value' => 'Milliers',
    'tarangire_fact_birds' => 'Espèces d\'oiseaux',
    'tarangire_fact_stay' => 'Séjour suggéré',
    'tarangire_fact_days' => 'jours',
    'tarangire_fact_from_arusha' => 'Depuis Arusha',
    'tarangire_fact_river' => 'Rivière Tarangire',
    'tarangire_fact_river_value' => 'Eau permanente',

    'tarangire_zones_badge' => 'Où aller',
    'tarangire_zones_title' => 'Les zones de Tarangire',
    'tarangire_zones_intro' => 'Le parc est plus petit que le Serengeti, mais l\'endroit où vous allez change quand même ce que vous voyez. Voici les principales zones, et ce pour quoi chacune est connue.',
    'tarangire_zone_river_name' => 'Le circuit de la rivière Tarangire',
    'tarangire_zone_river_desc' => 'Le cœur du parc et la première visite classique. La rivière retient de l\'eau toute l\'année, et en saison sèche elle attire éléphants, buffles, zèbres et lions venant boire et creuser pour l\'eau dans le lit sableux. La plupart des lodges et le réseau principal de game drives se trouvent le long de ce tronçon.',
    'tarangire_zone_silale_name' => 'Marais de Silale',
    'tarangire_zone_silale_desc' => 'Un grand marais saisonnier au centre du parc qui retient de l\'eau jusqu\'en saison sèche. Il attire éléphants, buffles et un nombre exceptionnel d\'oiseaux et de rapaces, et il vaut le détour supplémentaire depuis le circuit principal de la rivière.',
    'tarangire_zone_south_name' => 'Les étendues du sud',
    'tarangire_zone_south_desc' => 'Plus sec, plus sauvage et rarement visité par les excursionnistes à la journée. C\'est ici que vivent les antilopes de pays sec (oryx à oreilles frangées, petit koudou et gérénuk), et où les visiteurs de deux jours sont récompensés par l\'observation de la faune la plus tranquille du parc.',
    'tarangire_zone_north_name' => 'La zone de l\'entrée nord',
    'tarangire_zone_north_desc' => 'Autour de la porte d\'entrée de Kwa Kuchinja, la partie du parc la plus proche d\'Arusha. Des collines ondulantes parsemées de baobabs et une prairie ouverte en font le tronçon le plus facile pour une excursion à la journée, avec une bonne observation de la faune près de l\'entrée elle-même.',

    'tarangire_wildlife_badge' => 'Faune',
    'tarangire_wildlife_title' => 'Faune : ce que vous verrez réellement',
    'tarangire_wildlife_intro' => 'Probabilités d\'observation pour une journée complète en saison sèche (juin-octobre), basées sur les registres de nos guides. En saison des pluies, les animaux se dispersent et chaque chiffre chute considérablement.',
    'tarangire_animal_elephant' => 'Éléphant, immenses troupeaux, 99 %',
    'tarangire_animal_zebra' => 'Zèbre',
    'tarangire_animal_buffalo' => 'Buffle',
    'tarangire_animal_giraffe' => 'Girafe',
    'tarangire_animal_wildebeest' => 'Gnou',
    'tarangire_animal_lion' => 'Lion, parfois dans les arbres',
    'tarangire_animal_leopard' => 'Léopard, environ 25 %',
    'tarangire_animal_hyena' => 'Hyène tachetée',
    'tarangire_animal_oryx' => 'Oryx à oreilles frangées, étendues du sud',
    'tarangire_wildlife_p1' => 'Éléphant, buffle et lion sont tous réalistes lors d\'un safari à Tarangire, et l\'éléphant est presque une certitude en saison sèche. Le léopard est possible mais rare, environ 25 %, le guépard relève de la vraie chance, et il n\'y a aucun rhinocéros ici. Pour les Big Five complets, combinez Tarangire avec le cratère du Ngorongoro.',
    'tarangire_wildlife_p2' => 'Ce qui rend Tarangire digne d\'être observé plutôt que simplement compté, c\'est le comportement des éléphants : pendant les mois secs, vous pouvez voir des matriarches creuser des puits d\'un mètre de profondeur dans le sable du lit de la rivière, avec zèbres, impalas et babouins attendant à distance respectueuse pour boire une fois les éléphants partis. Les étendues sèches du sud de Tarangire abritent aussi trois antilopes difficiles à trouver ailleurs sur le circuit nord : l\'oryx à oreilles frangées, le petit koudou et le gérénuk, qui se dresse sur ses pattes arrière pour brouter.',

    'tarangire_when_badge' => 'Meilleure période',
    'tarangire_when_title' => 'Quand visiter',
    'tarangire_when_intro' => 'Tarangire est le parc le plus fortement saisonnier du circuit nord. La différence entre août et avril n\'est pas une question de degré. C\'est un parc différent.',
    'tarangire_when_p1' => 'Juillet à octobre est exceptionnel : la rivière est la seule eau à des kilomètres à la ronde et tout y converge, avec les plus grands troupeaux d\'éléphants. Juin est très bon et encore plus calme. Novembre et décembre apportent les petites pluies. Les animaux commencent à se disperser, mais c\'est superbe pour les oiseaux et les paysages verdoyants et photogéniques.',
    'tarangire_when_p2' => 'Mars à mai, les grandes pluies, est la période la plus faible pour le gibier, avec des animaux répartis sur une vaste zone, mais c\'est le meilleur moment pour l\'observation des oiseaux et pour avoir le parc pour vous seul. Si le gros gibier est votre priorité et que vous ne pouvez visiter que pendant les grandes pluies, envisagez de passer cette journée au Ngorongoro à la place, où les animaux du cratère ne se dispersent pas.',

    'tarangire_stay_badge' => 'Hébergement',
    'tarangire_stay_title' => 'Où loger',
    'tarangire_stay_intro' => 'Comme Tarangire n\'est qu\'à deux heures d\'Arusha, y passer la nuit est un choix plutôt qu\'une nécessité, mais cela change ce que vous voyez. La meilleure activité des éléphants est à l\'aube et au crépuscule, et les visiteurs à la journée manquent les deux.',
    'tarangire_stay_budget_title' => 'Économique',
    'tarangire_stay_budget_price' => 'à partir de 35,40 $/nuit de frais de parc + camping',
    'tarangire_stay_budget_desc' => 'Camping public à l\'intérieur du parc : votre propre tente, toilettes à la turque basiques et eau froide, le cuisinier prépare les repas sur place. La façon la moins chère de dormir à l\'intérieur de Tarangire.',
    'tarangire_stay_mid_title' => 'Milieu de gamme',
    'tarangire_stay_mid_price' => '150-400 $/nuit',
    'tarangire_stay_mid_desc' => 'Lodge ou camp tenté à l\'intérieur du parc, plusieurs situés sur l\'escarpement surplombant la rivière. Vous pouvez observer les éléphants depuis la terrasse et êtes le premier sur les pistes le matin.',
    'tarangire_stay_luxury_title' => 'À l\'extérieur de l\'entrée',
    'tarangire_stay_luxury_price' => '60-150 $/nuit',
    'tarangire_stay_luxury_desc' => 'Lodges juste à l\'extérieur de la limite du parc, à seulement 15-30 minutes de l\'entrée. L\'option hors parc la plus compétitive de tout le circuit, et comment nous recommandons de réduire un budget sans perdre l\'expérience.',
    'tarangire_stay_note' => 'Dormir à l\'intérieur du parc coûte plus cher : des frais de concession de 47,20 $ par adulte et par nuit en plus du tarif de la chambre. Mais vous êtes déjà au cœur de l\'action à l\'aube et au crépuscule, quand l\'activité des éléphants est à son maximum.',

    'tarangire_fees_badge' => 'Coûts',
    'tarangire_fees_title' => 'Frais de parc (2026)',
    'tarangire_fees_intro' => 'Tarangire est un parc « select » selon le tarif TANAPA, ce qui le rend nettement moins cher que le Serengeti ou le Ngorongoro, l\'une des raisons de son excellent rapport qualité-prix.',
    'tarangire_table_category' => 'Catégorie',
    'tarangire_table_adult' => 'Adulte (16+)',
    'tarangire_table_child' => 'Enfant (5-15 ans)',
    'tarangire_fee_entry' => 'Entrée, par 24 heures',
    'tarangire_fee_concession' => 'Concession, dormir dans le parc (par nuit)',
    'tarangire_fee_campsite' => 'Camping public (par nuit)',
    'tarangire_fees_note' => 'Tous les montants incluent 18 % de TVA. Les enfants de moins de 5 ans entrent gratuitement. Les frais sont révisés par le gouvernement et peuvent changer sans préavis. Votre devis écrit indique toujours le montant exact pour vos dates.',

    'tarangire_gallery_badge' => 'Galerie',
    'tarangire_gallery_title' => 'Tarangire en images',
    'tarangire_gallery_caption_1' => 'Famille d\'éléphants au coucher du soleil',
    'tarangire_gallery_caption_2' => 'Portrait rapproché d\'un éléphant',
    'tarangire_gallery_caption_3' => 'Lever de soleil sur la savane parmi les acacias',
    'tarangire_gallery_caption_4' => 'Éléphant s\'abritant sous un acacia',
    'tarangire_gallery_caption_5' => 'Troupeau de zèbres dans la plaine',
    'tarangire_gallery_caption_6' => 'Lion se reposant dans l\'herbe',

    'tarangire_back_to_parks' => 'Comparer tous les parcs',

    'tarangire_faq_badge' => 'FAQ',
    'tarangire_faq_title' => 'Parc national de Tarangire : questions fréquentes',
    'tarangire_faq_q1' => 'Combien coûte l\'entrée à Tarangire ?',
    'tarangire_faq_a1' => 'Les frais 2026 pour les non-résidents sont de 59,00 $ par adulte et 17,70 $ par enfant de 5 à 15 ans, par 24 heures, TVA de 18 % incluse. Les enfants de moins de 5 ans sont gratuits. Loger dans le parc ajoute des frais de concession de 47,20 $ par adulte et par nuit, ou 35,40 $ pour un camping public.',
    'tarangire_faq_q2' => 'Tarangire vaut-il la peine d\'être visité ?',
    'tarangire_faq_a2' => 'En saison sèche, sans équivoque. Les concentrations d\'éléphants le long de la rivière rivalisent avec tout ce que la Tanzanie offre, avec une fraction des véhicules et des frais d\'entrée plus bas que le Serengeti. Entre mars et mai, le gibier se disperse et c\'est le plus faible des parcs du nord.',
    'tarangire_faq_q3' => 'Quelle est la meilleure période pour visiter Tarangire ?',
    'tarangire_faq_a3' => 'Juillet à octobre. La rivière Tarangire est la seule eau permanente sur une longue distance dans toutes les directions, donc pendant les mois secs, tout l\'écosystème y converge. Juin est très bon et encore plus calme.',
    'tarangire_faq_q4' => 'Combien d\'éléphants y a-t-il à Tarangire ?',
    'tarangire_faq_a4' => 'Entre 2 500 et 3 000 individus résidents. Des troupeaux de cinquante ou plus sont routiniers en saison sèche, et plusieurs centaines d\'éléphants en une seule journée est normal.',
    'tarangire_faq_q5' => 'Puis-je visiter Tarangire en excursion d\'une journée ?',
    'tarangire_faq_a5' => 'Oui, et c\'est l\'un de nos safaris d\'une journée les plus populaires. Partez d\'Arusha vers 06h00, passez la journée dans le parc, revenez le soir. Passer une nuit est mieux, car la meilleure activité des éléphants est à l\'aube et au crépuscule.',
    'tarangire_faq_q6' => 'Puis-je voir les Big Five à Tarangire ?',
    'tarangire_faq_a6' => 'Trois d\'entre eux : éléphant, buffle et lion. Le léopard est possible mais rare, environ 25 %. Il n\'y a pas de rhinocéros. Pour les Big Five complets, combinez Tarangire avec le cratère du Ngorongoro.',
    'tarangire_faq_q7' => 'Comment aller d\'Arusha à Tarangire ?',
    'tarangire_faq_a7' => 'Environ 118 km, à peu près deux heures sur bon bitume avec un court tronçon de gravier jusqu\'à l\'entrée principale de Kwa Kuchinja. C\'est le plus proche des grands parcs du circuit nord, ce qui en fait une excursion pratique d\'une journée complète ou une première nuit facile sur un safari plus long.',
    'tarangire_faq_q8' => 'Pourquoi y a-t-il tant de baobabs ici ?',
    'tarangire_faq_a8' => 'Le sol et les précipitations leur conviennent, et le parc les protège depuis plus de cinquante ans. Certains ont plus de mille ans. Les profondes cicatrices verticales sur les troncs sont des marques de défenses laissées par les éléphants arrachant les fibres pour leur humidité.',

    'tarangire_cta_title' => 'Prêt à planifier votre safari à Tarangire ?',
    'tarangire_cta_intro' => 'Envoyez-nous vos dates, la taille de votre groupe et votre budget. Nous répondons avec un itinéraire détaillé et une répartition complète des prix, sans engagement.',
    'tarangire_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'tarangire_cta_safaris' => 'Voir les itinéraires de safari',

    'nyerere_meta_title' => 'Parc national de Nyerere (Selous) : le guide complet (2026) | Serengeti Budget Safari',
    'nyerere_meta_description' => 'Parc national de Nyerere, anciennement Selous : le plus grand parc d\'Afrique, safaris en bateau sur la rivière Rufiji, safaris à pied et lycaons. Frais 2026, quand y aller et comment s\'y rendre depuis Dar.',

    'nyerere_hero_badge' => 'Guide du parc',
    'nyerere_hero_title' => 'Parc national de Nyerere',
    'nyerere_hero_sub' => 'Anciennement Selous : le plus grand parc national d\'Afrique, où vous pouvez faire un safari en bateau, un safari à pied et un game drive le même jour.',
    'nyerere_hero_cta_quote' => 'Demander un devis',

    'nyerere_intro_badge' => 'Introduction',
    'nyerere_intro_title' => 'Qu\'est-ce que le parc national de Nyerere ?',
    'nyerere_intro_p1' => 'Le parc national de Nyerere a été créé en 2019 à partir de la section nord de l\'ancienne réserve de chasse de Selous, et avec plus de 30 893 km², c\'est le plus grand parc national d\'Afrique, plus grand que la Belgique, et environ deux fois la taille du Serengeti. Il se trouve dans le sud-est de la Tanzanie, accessible depuis Dar es Salaam plutôt qu\'Arusha, ce qui en fait la porte d\'entrée naturelle du circuit safari sud.',
    'nyerere_intro_p2' => 'La plupart des voyageurs le connaissent encore sous le nom de Selous. La portion sud restante conserve ce nom en tant que réserve de chasse ; la partie que vous visitez en tant que touriste est désormais Nyerere, nommée d\'après le premier président de la Tanzanie.',
    'nyerere_intro_p3' => 'Ce qui le distingue, c\'est l\'eau. La rivière Rufiji le traverse, se déployant en un réseau de lacs, chenaux et bancs de sable, et cela change ce qu\'est un safari ici : vous pouvez faire un safari en bateau, un safari à pied et un game drive le même jour, une combinaison tout simplement impossible au Serengeti.',

    'nyerere_fact_area' => 'Superficie',
    'nyerere_fact_rank' => 'Classement',
    'nyerere_fact_rank_value' => 'Le plus grand parc d\'Afrique',
    'nyerere_fact_established' => 'Créé en',
    'nyerere_fact_status' => 'Statut',
    'nyerere_fact_boat' => 'Safaris en bateau',
    'nyerere_fact_boat_value' => 'Oui, rivière Rufiji',
    'nyerere_fact_wilddog' => 'Lycaon',
    'nyerere_fact_wilddog_value' => 'Bastion majeur',
    'nyerere_fact_stay' => 'Séjour suggéré',
    'nyerere_fact_nights' => 'nuits',
    'nyerere_fact_from_dar' => 'Depuis Dar es Salaam',
    'nyerere_fact_minutes' => 'min en avion',

    'nyerere_regions_badge' => 'Où aller',
    'nyerere_regions_title' => 'Les zones de Nyerere',
    'nyerere_regions_intro' => 'Le parc est vaste, et presque tout le tourisme est concentré dans une petite section nord autour de la rivière et des lacs. Voici les principales zones, et ce que chacune offre.',
    'nyerere_region_rufiji_name' => 'La rivière Rufiji et le système de lacs',
    'nyerere_region_rufiji_desc' => 'La plus grande rivière d\'Afrique de l\'Est en volume ralentit, se déploie et se divise en un réseau de chenaux, de lacs en croissant et de bancs de sable en traversant le parc. Cinq lacs principaux (Tagalala, Manze, Nzerakera, Siwandu et Mzizimia) se trouvent dans la section où sont basés la plupart des camps, chacun avec ses propres groupes d\'hippopotames et oiseaux résidents. C\'est là que se déroulent les safaris en bateau, et c\'est différent de tout ce qu\'offre le circuit nord.',
    'nyerere_region_stieglers_name' => 'Gorges de Stiegler et la zone touristique nord',
    'nyerere_region_stieglers_desc' => 'La principale zone visitée, facilement accessible depuis les pistes d\'atterrissage proches des camps de la Rufiji. Les gorges de Stiegler, profondes de 100 m et larges de 100 m, traversent le nord du parc. Cette zone combine game drives, safaris à pied et excursions en bateau à courte distance de chaque lodge, ce qui explique pourquoi presque tous les visiteurs y séjournent.',
    'nyerere_region_south_name' => 'Le désert du sud',
    'nyerere_region_south_desc' => 'La grande majorité des 30 893 km² de Nyerere se trouve au sud de la zone touristique, et c\'est véritablement isolé : peu de routes, peu de camps, et rarement visité même selon les standards tanzaniens. Cela ne fait pas partie d\'un itinéraire typique, mais cela souligne ce qui rend ce parc différent du circuit nord : l\'espace, et une absence quasi totale d\'autres véhicules.',

    'nyerere_activities_badge' => 'Ce qui le rend différent',
    'nyerere_activities_title' => 'Safaris en bateau, safaris à pied et plus',
    'nyerere_activities_intro' => 'Voici pourquoi vous venez à Nyerere plutôt que d\'ajouter un autre parc du nord.',
    'nyerere_table_activity' => 'Activité',
    'nyerere_table_duration' => 'Durée',
    'nyerere_table_highlight' => 'Ce que cela vous offre',
    'nyerere_act_boat_name' => 'Safari en bateau sur la Rufiji',
    'nyerere_act_boat_desc' => 'Dériver sur la rivière et ses lacs au niveau des yeux des groupes d\'hippopotames et des crocodiles sur les bancs de sable, observer les éléphants venir boire et les pygargues pêcheurs travailler les chenaux. Le meilleur safari en bateau de Tanzanie.',
    'nyerere_act_walking_name' => 'Safari à pied',
    'nyerere_act_walking_desc' => 'Avec un ranger armé, généralement au lever du jour. Nyerere a été l\'un des premiers endroits de Tanzanie à proposer des safaris à pied et reste l\'un des meilleurs. Vous suivez les traces à pied et rencontrez les animaux au niveau du sol.',
    'nyerere_act_flycamp_name' => 'Fly-camping',
    'nyerere_act_flycamp_unit' => 'nuit',
    'nyerere_act_flycamp_desc' => 'Une nuit sous la tente loin du camp principal, avec un guide et un ranger. Simple, et souvent la nuit la plus mémorable de tout le voyage.',
    'nyerere_act_drive_name' => 'Game drive',
    'nyerere_act_drive_desc' => 'Safari classique en véhicule à travers la forêt de miombo et la prairie ouverte, généralement combiné avec une excursion en bateau ou une marche le même jour.',
    'nyerere_activities_note' => 'Les safaris en bateau, safaris à pied et fly-camping sont facturés séparément par les camps. Dites-nous à l\'avance ce que vous voulez, car c\'est la principale raison de venir.',

    'nyerere_wildlife_badge' => 'Faune',
    'nyerere_wildlife_title' => 'Faune : ce que vous verrez réellement',
    'nyerere_wildlife_intro' => 'Sur une visite de trois jours combinant game drives et safaris en bateau en saison sèche, basée sur les registres d\'observations de nos guides.',
    'nyerere_animal_hippo' => 'Hippopotame, immenses groupes sur la Rufiji',
    'nyerere_animal_crocodile' => 'Crocodile',
    'nyerere_animal_elephant' => 'Éléphant',
    'nyerere_animal_lion' => 'Lion',
    'nyerere_animal_buffalo' => 'Buffle',
    'nyerere_animal_wilddog' => 'Lycaon, bastion mondial',
    'nyerere_animal_leopard' => 'Léopard',
    'nyerere_animal_zebra' => 'Zèbre',
    'nyerere_animal_rhino' => 'Rhinocéros noir, presque plus aucun',
    'nyerere_wildlife_p1' => 'Hippopotame et crocodile sont quasi certains sur la rivière, et éléphant, lion et buffle sont tous réalistes sur un séjour de trois jours. Nyerere abrite l\'une des plus grandes populations restantes de lycaons du continent, environ 35 % de chances d\'observation sur une visite de trois jours, ce qui est exceptionnel pour une espèce comptant moins de 7 000 individus à l\'état sauvage.',
    'nyerere_wildlife_p2' => 'Le rhinocéros noir est pratiquement absent : un très petit nombre survit dans l\'écosystème élargi, mais en pratique, vous ne devriez pas planifier un voyage ici en espérant en voir un. Pour le rhinocéros en Tanzanie, le cratère du Ngorongoro est l\'option réaliste. Contrairement au Serengeti, Nyerere n\'a pas de migration. Il possède à la place de grandes populations résidentes présentes toute l\'année.',

    'nyerere_when_badge' => 'Meilleure période',
    'nyerere_when_title' => 'Quand visiter',
    'nyerere_when_intro' => 'Nyerere ferme effectivement pendant les grandes pluies, une réelle différence avec les parcs du nord, qui fonctionnent toute l\'année.',
    'nyerere_when_p1' => 'Juin à octobre est idéal : la saison sèche concentre le gibier le long de la Rufiji, les safaris en bateau sont à leur meilleur et les températures sont agréables. Novembre et décembre apportent les petites pluies : paysages verts, bonne observation des oiseaux et moins de visiteurs, toujours très praticable.',
    'nyerere_when_p2' => 'Janvier et février sont chauds et humides mais restent bons pour le gibier et excellents pour les oiseaux. Mars à mai, les grandes pluies, c\'est quand la plupart des camps ferment et que les routes sont inondées. Nous ne recommandons pas de voyager à cette période.',

    'nyerere_stay_badge' => 'Hébergement',
    'nyerere_stay_title' => 'Où loger',
    'nyerere_stay_intro' => 'Vérifiez soigneusement ce qui est inclus. Dans le haut de gamme, les safaris en bateau, safaris à pied et frais de parc sont souvent regroupés ; dans le milieu de gamme, ils ne le sont généralement pas, et les ajouter change considérablement le prix réel. Nous détaillons tout par écrit.',
    'nyerere_stay_budget_title' => 'Économique',
    'nyerere_stay_budget_price' => 'à partir de 35,40 $/nuit de frais de parc + camping',
    'nyerere_stay_budget_desc' => 'Camping public ou bandas simples près de l\'entrée de Mtemere, souvent utilisés par les voyages routiers depuis Dar. Installations basiques ; vous avez besoin de votre propre équipement ou du nôtre.',
    'nyerere_stay_mid_title' => 'Milieu de gamme',
    'nyerere_stay_mid_price' => '200-400 $/nuit',
    'nyerere_stay_mid_desc' => 'Camp tenté confortable près des lacs. Les activités comme les safaris en bateau et les marches sont généralement facturées séparément du tarif de la chambre.',
    'nyerere_stay_luxury_title' => 'Luxe',
    'nyerere_stay_luxury_price' => '450-1 000 $+/nuit',
    'nyerere_stay_luxury_desc' => 'Petits camps sur le lac Manze ou Siwandu, entièrement inclusifs avec safaris en bateau et à pied intégrés. Des hippopotames qui appellent devant la tente la nuit.',
    'nyerere_stay_note' => 'Où vous baser : la section nord des lacs autour de Manze et Siwandu est là où se déroulent les safaris en bateau et la majeure partie de l\'observation de la faune. Les camps plus au sud sont moins chers mais vous passez plus de temps à conduire jusqu\'à l\'eau.',

    'nyerere_fees_badge' => 'Coûts',
    'nyerere_fees_title' => 'Frais de parc (2026)',
    'nyerere_fees_intro' => 'Les frais sont fixés par la TANAPA, l\'autorité des parcs nationaux de Tanzanie, et sont identiques pour chaque opérateur.',
    'nyerere_table_category' => 'Catégorie',
    'nyerere_table_adult' => 'Adulte (16+)',
    'nyerere_table_child' => 'Enfant (5-15 ans)',
    'nyerere_fee_entry' => 'Entrée, par 24 heures',
    'nyerere_fee_concession' => 'Concession, dormir dans le parc (par nuit)',
    'nyerere_fee_campsite' => 'Camping public (par nuit)',
    'nyerere_fees_note' => 'Tous les montants incluent 18 % de TVA. Les enfants de moins de 5 ans entrent gratuitement. Les safaris en bateau, safaris à pied et fly-camping sont facturés séparément par les camps. Les frais sont révisés par le gouvernement et peuvent changer sans préavis. Votre devis écrit indique toujours le montant exact pour vos dates.',

    'nyerere_gallery_badge' => 'Galerie',
    'nyerere_gallery_title' => 'Nyerere en images',
    'nyerere_gallery_caption_1' => 'Observer les hippopotames depuis le bateau',
    'nyerere_gallery_caption_2' => 'Rhinocéros paissant au crépuscule',
    'nyerere_gallery_caption_3' => 'Famille d\'éléphants au coucher du soleil',
    'nyerere_gallery_caption_4' => 'Lion se reposant près de l\'eau',
    'nyerere_gallery_caption_5' => 'Hyène tachetée sur la savane',
    'nyerere_gallery_caption_6' => 'Éléphant sous un acacia',

    'nyerere_back_to_parks' => 'Comparer tous les parcs',

    'nyerere_faq_badge' => 'FAQ',
    'nyerere_faq_title' => 'Parc national de Nyerere : questions fréquentes',
    'nyerere_faq_q1' => 'Nyerere est-il la même chose que Selous ?',
    'nyerere_faq_a1' => 'Le parc national de Nyerere a été créé en 2019 à partir de la section nord de la réserve de chasse de Selous. La portion sud restante s\'appelle toujours Selous. La zone que visitent les touristes est désormais Nyerere, bien que de nombreux opérateurs utilisent encore l\'ancien nom.',
    'nyerere_faq_q2' => 'Combien coûte l\'entrée à Nyerere ?',
    'nyerere_faq_a2' => 'Les frais 2026 pour les non-résidents sont de 59,00 $ par adulte et 17,70 $ par enfant de 5 à 15 ans, par 24 heures, TVA de 18 % incluse. Les safaris en bateau, safaris à pied et fly-camping sont facturés séparément par les camps.',
    'nyerere_faq_q3' => 'Comment se rendre à Nyerere ?',
    'nyerere_faq_a3' => 'Environ 45 minutes en avion léger depuis Dar es Salaam, avec des vols réguliers quotidiens, ou cinq à six heures par la route. Nyerere est accessible depuis Dar, pas Arusha, ce qui change la logistique d\'un voyage par rapport aux parcs du nord.',
    'nyerere_faq_q4' => 'Puis-je faire un safari en bateau à Nyerere ?',
    'nyerere_faq_a4' => 'Oui, et c\'est la principale raison de venir. Deux à trois heures sur la rivière Rufiji et ses lacs vous mettent au niveau des groupes d\'hippopotames et des crocodiles, avec des éléphants venant boire. C\'est le meilleur safari en bateau de Tanzanie.',
    'nyerere_faq_q5' => 'Puis-je marcher à Nyerere ?',
    'nyerere_faq_a5' => 'Oui, avec un ranger armé, généralement au lever du jour pendant deux à trois heures. Nyerere a été parmi les premiers endroits de Tanzanie à proposer des safaris à pied et reste l\'un des meilleurs pour cela.',
    'nyerere_faq_q6' => 'Verrai-je des lycaons ?',
    'nyerere_faq_a6' => 'Environ 35 % de chances sur une visite de trois jours, exceptionnel pour une espèce comptant moins de 7 000 individus à l\'état sauvage. Nyerere abrite l\'une des plus grandes populations restantes d\'Afrique.',
    'nyerere_faq_q7' => 'Combien de jours me faut-il à Nyerere ?',
    'nyerere_faq_a7' => 'Trois à quatre jours. Cela vous donne un safari en bateau, un safari à pied et plusieurs game drives sans vous presser, ce qui est tout l\'intérêt de venir ici plutôt que d\'ajouter un autre parc du nord.',
    'nyerere_faq_q8' => 'Y a-t-il des rhinocéros à Nyerere ?',
    'nyerere_faq_a8' => 'Un très petit nombre de rhinocéros noirs survit dans l\'écosystème élargi, mais vous devriez supposer que vous n\'en verrez pas. Pour le rhinocéros en Tanzanie, le cratère du Ngorongoro est l\'option réaliste.',

    'nyerere_cta_title' => 'Prêt à planifier votre safari à Nyerere ?',
    'nyerere_cta_intro' => 'Envoyez-nous vos dates, la taille de votre groupe et votre budget. Nous répondons avec un itinéraire détaillé et une répartition complète des prix, sans engagement.',
    'nyerere_cta_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'nyerere_cta_safaris' => 'Voir les itinéraires de safari',

    // ===== Day Trips listing =====
    'daytrips_meta_title' => 'Excursions d\'une journée depuis Arusha | Tarangire, Ngorongoro et plus | Serengeti Budget Safari',
    'daytrips_meta_description' => 'Excursions d\'une journée depuis Arusha : Tarangire, cratère du Ngorongoro, lac Manyara, parc national d\'Arusha, cascades de Materuni, sources chaudes de Chemka, village maasaï et plus.',
    'daytrips_hero_badge' => 'Excursions',
    'daytrips_hero_title' => 'Excursions d\'une journée depuis Arusha',
    'daytrips_hero_sub' => 'Excursions d\'une journée pour les jours avant votre safari, après votre ascension du Kilimandjaro, ou chaque fois que vous avez une journée libre en ville.',
    'daytrips_hero_quote' => 'Demander un devis',
    'daytrips_hero_whatsapp' => 'WhatsApp',
    'daytrips_grid_badge' => 'Choisissez votre journée',
    'daytrips_grid_title' => 'Excursions et sorties d\'une journée',
    'daytrips_grid_intro' => 'Départ d\'Arusha tôt et retour le même soir ou après-midi. Prix par personne, deux personnes partageant, frais de parc inclus (le cas échéant), véhicule, guide et déjeuner.',
    'daytrips_1day' => 'Journée complète',
    'daytrips_halfday' => 'Demi-journée',
    'daytrips_from_pp' => 'à partir de · p.p.',
    'daytrips_ask_price' => 'Demander le prix',
    'daytrips_know_badge' => 'Bon à savoir',
    'daytrips_know_title' => 'Organiser votre excursion',
    'daytrips_pickup_title' => 'Prise en charge',
    'daytrips_pickup_desc' => 'Nous vous récupérons dans n\'importe quel hôtel d\'Arusha ou de Moshi. Le départ se fait généralement entre 06h00 et 08h00 selon la destination.',
    'daytrips_bring_title' => 'Quoi apporter',
    'daytrips_bring_desc' => 'Chaussures fermées, une veste légère pour le matin, crème solaire, un chapeau et un maillot de bain pour Chemka ou Materuni.',
    'daytrips_combine_title' => 'Combiner les excursions',
    'daytrips_combine_desc' => 'Materuni et Chemka s\'intègrent confortablement en une seule journée. De même pour le lac Duluti et une visite de la ville d\'Arusha. Demandez-nous et nous organiserons la journée autour de vos horaires de vol.',
    'daytrips_booking_title' => 'Réservation',
    'daytrips_booking_desc' => 'La plupart des excursions peuvent être organisées avec 24 heures de préavis. Les safaris dans les parcs sont mieux réservés quelques jours à l\'avance en haute saison.',
    'daytrips_final_title' => 'Organisez votre excursion avec nous',
    'daytrips_final_intro' => 'Envoyez-nous vos dates, la taille de votre groupe et votre budget. Nous répondons avec un itinéraire détaillé et une répartition complète des prix, sans engagement.',
    'daytrips_final_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'daytrips_final_contact' => 'Formulaire de contact',

    'daytrip_tarangire_title' => 'Tarangire',
    'daytrip_tarangire_desc' => 'À deux heures d\'Arusha. Baobabs et les plus grands troupeaux d\'éléphants du nord de la Tanzanie, surtout de juillet à octobre.',
    'daytrip_ngorongoro_title' => 'Cratère du Ngorongoro',
    'daytrip_ngorongoro_desc' => 'Une longue journée, mais la concentration de faune la plus dense d\'Afrique, et la meilleure chance de voir un rhinocéros noir dans tout le pays.',
    'daytrip_manyara_title' => 'Lac Manyara',
    'daytrip_manyara_desc' => 'Flamants roses sur le lac de soude, lions grimpeurs d\'arbres et forêt dense au pied de l\'escarpement de la vallée du Rift.',
    'daytrip_arushanp_title' => 'Parc national d\'Arusha',
    'daytrip_arushanp_desc' => 'Le plus proche de la ville, avec girafes, colobes et les lacs Momella. Les safaris à pied sont autorisés ici, ce qui est rare en Tanzanie.',
    'daytrip_materuni_title' => 'Cascades de Materuni et café',
    'daytrip_materuni_desc' => 'Une marche à travers les plantations de bananes et de café sur les pentes du Kilimandjaro jusqu\'à une cascade de 90 mètres, suivie de la torréfaction et de la mouture du café avec une famille chagga.',
    'daytrip_chemka_title' => 'Sources chaudes de Chemka',
    'daytrip_chemka_desc' => 'Une piscine naturelle turquoise au milieu de la brousse sèche, chaude toute l\'année et ombragée par des racines de figuier. La meilleure baignade de l\'après-midi dans la région.',
    'daytrip_maasai_title' => 'Village maasaï',
    'daytrip_maasai_desc' => 'Une visite d\'un boma en activité avec notre guide maasaï Elius : les maisons, l\'élevage, les danses, et du temps pour poser de vraies questions. Pas un spectacle mis en scène.',
    'daytrip_duluti_title' => 'Lac Duluti',
    'daytrip_duluti_desc' => 'Un lac de cratère à vingt minutes d\'Arusha : canoë parmi les cormorans et les varans, et une marche autour du bord boisé.',
    'daytrip_arushacity_title' => 'Visite de la ville d\'Arusha',
    'daytrip_arushacity_desc' => 'Le marché central, les négociants en tanzanite, le marché artisanal maasaï et la tour de l\'horloge dite marquant le point médian entre Le Caire et Le Cap.',
    'daytrip_kiliday_title' => 'Trek d\'un jour au Kilimandjaro',
    'daytrip_kiliday_desc' => 'Jusqu\'à la hutte de Mandara à 2 700 m à travers la forêt tropicale et retour le même jour : la montagne sans la semaine.',

