    // ===== Tarangire Day Trip (specific) =====
    'daytrip_tarangire_meta_title' => 'Safari d\'une journée à Tarangire depuis Arusha | Serengeti Budget Safari',
    'daytrip_tarangire_meta_description' => 'Un safari d\'une journée complète d\'Arusha au parc national de Tarangire : troupeaux d\'éléphants, baobabs anciens et un game drive avec prise en charge, déjeuner et frais de parc inclus.',
    'daytrip_tarangire_type' => 'Excursion',
    'daytrip_tarangire_budget' => 'Économique',
    'daytrip_tarangire_hero_title' => 'Safari faune sauvage d\'une journée à Tarangire',
    'daytrip_tarangire_hero_route' => 'Arusha → Parc national de Tarangire → Arusha',
    'daytrip_tarangire_start_val' => 'Arusha',
    'daytrip_tarangire_route_park' => 'Parc national de Tarangire',
    'daytrip_tarangire_overview_title' => 'Une journée de faune sauvage à Tarangire',
    'daytrip_tarangire_overview_p1' => 'Passez une journée complète à explorer le parc national de Tarangire, célèbre pour ses éléphants, ses immenses baobabs et sa faune diversifiée. Départ d\'Arusha le matin, game drive toute la journée et retour à Arusha le soir.',
    'daytrip_tarangire_love_1' => 'Game drive toute la journée',
    'daytrip_tarangire_love_2' => 'Excellentes observations d\'éléphants',
    'daytrip_tarangire_love_3' => 'Guide local professionnel',
    'daytrip_tarangire_love_4' => 'Déjeuner inclus',
    'daytrip_tarangire_love_5' => 'Retour à Arusha le jour même',
    'daytrip_tarangire_exp_wildlife_val' => 'Lions, éléphants, girafes, zèbres et plus',
    'daytrip_tarangire_exp_landscape_val' => 'Baobabs, savane et paysages spectaculaires',
    'daytrip_tarangire_tl1_title' => 'Prise en charge à l\'hôtel, Arusha',
    'daytrip_tarangire_tl1_desc' => 'Votre chauffeur-guide vous retrouve à votre hôtel juste après le lever du soleil, Land Cruiser chargé et prêt. Le temps que la plupart des gens commandent leur petit-déjeuner, vous êtes déjà sur la route vers le sud.',
    'daytrip_tarangire_tl2_title' => 'Entrée au pays des baobabs',
    'daytrip_tarangire_tl2_desc' => 'La porte du parc marque le début de Tarangire, abritant certains des plus vieux baobabs de Tanzanie et les plus grands troupeaux d\'éléphants en dehors de l\'écosystème du Serengeti. Le game drive matinal suit la rivière Tarangire, où la faune se rassemble même pendant les mois les plus secs.',
    'daytrip_tarangire_tl3_title' => 'Déjeuner pique-nique en brousse',
    'daytrip_tarangire_tl3_desc' => 'Un déjeuner à emporter dans un endroit pittoresque choisi par votre guide, souvent avec une vue sur la vallée de la rivière et ses familles d\'éléphants résidentes.',
    'daytrip_tarangire_tl4_title' => 'Game drive de l\'après-midi',
    'daytrip_tarangire_tl4_desc' => 'La lumière s\'adoucit et la brousse reprend vie après la chaleur de midi. C\'est le meilleur moment pour la photographie, et pour repérer les girafes, zèbres et éléphants pour lesquels Tarangire est connu.',
    'daytrip_tarangire_tl5_title' => 'Dernier regard, puis l\'entrée',
    'daytrip_tarangire_tl5_desc' => 'Un dernier passage le long de la rivière avant de sortir par l\'entrée principale, les baobabs capturant le soleil tardif alors que vous commencez le trajet de retour.',
    'daytrip_tarangire_tl6_title' => 'Retour à Arusha',
    'daytrip_tarangire_tl6_desc' => 'Dépose à votre hôtel le soir, avec une journée complète de faune sauvage derrière vous et, si vous continuez votre safari, seulement une nuit de sommeil avant d\'y retourner.',
    'daytrip_tarangire_wl_elephant' => 'Éléphants',
    'daytrip_tarangire_wl_lion' => 'Lions',
    'daytrip_tarangire_wl_giraffe' => 'Girafes',
    'daytrip_tarangire_wl_zebra' => 'Zèbres',
    'daytrip_tarangire_wl_buffalo' => 'Buffles',
    'daytrip_tarangire_wl_warthog' => 'Phacochères',
    'daytrip_tarangire_faq_q1' => 'Est-ce un safari privé ?',
    'daytrip_tarangire_faq_a1' => 'Oui, par défaut c\'est un véhicule privé pour votre groupe. Une option de groupe partagé est également disponible à un prix par personne inférieur. Demandez-nous les dates actuelles.',
    'daytrip_tarangire_faq_q2' => 'Puis-je rejoindre en tant que voyageur seul ?',
    'daytrip_tarangire_faq_a2' => 'Oui. Les voyageurs seuls paient le tarif 1 personne pour un voyage privé, ou peuvent nous demander de rejoindre un départ de groupe existant pour réduire le coût.',
    'daytrip_tarangire_faq_q3' => 'À quelle heure partons-nous d\'Arusha ?',
