    'about_meta_title' => 'À propos de nous | Serengeti Budget Safari : opérateur local de safaris en Tanzanie',
    'about_meta_description' => 'Découvrez l\'équipe locale derrière Serengeti Budget Safari, un opérateur basé en Tanzanie fondé sur la connaissance locale, des prix honnêtes et un service personnel à travers le Serengeti, le Ngorongoro et au-delà.',

    'about_hero_title' => 'Nous ne nous contentons pas d\'organiser des safaris. Nous partageons la Tanzanie.',
    'about_hero_sub' => 'Voyages authentiques. Connaissance locale. Expériences inoubliables.',
