    'about_intro_badge' => 'Qui sommes-nous',
    'about_intro_title' => 'Votre voyage commence avec des gens qui connaissent la Tanzanie',
    'about_intro_p1' => 'Nous sommes une société de safari basée en Tanzanie, dédiée à créer des voyages mémorables à travers les destinations les plus extraordinaires du pays. Des plaines infinies du Serengeti au spectaculaire cratère du Ngorongoro et aux plages de Zanzibar, nous combinons connaissance locale, guides expérimentés et planification réfléchie pour rendre chaque voyage spécial.',

    'about_story_badge' => 'Notre histoire',
