    'blogcost_s6_save2_d' => 'Le coût du véhicule se divise.',
    'blogcost_s6_save3_t' => 'Dormez hors des parcs.',
    'blogcost_s6_save3_d' => 'Économise les frais de concession et le tarif de la chambre ; coûte une heure de conduite chaque matin.',
    'blogcost_s6_save4_t' => 'Choisissez des parcs moins chers.',
    'blogcost_s6_save4_d' => 'Tarangire et Manyara sont à 59,00 $ contre 82,60 $ pour le Serengeti, et à deux heures d\'Arusha plutôt qu\'à huit.',
    'blogcost_s6_save5_t' => 'Campez.',
    'blogcost_s6_save5_d' => 'Même guide, même véhicule, mêmes animaux. Vous économisez sur le lit.',
    'blogcost_s6_save6_t' => 'Raccourcissez le Serengeti, pas le voyage.',
    'blogcost_s6_save6_d' => 'Deux nuits au Serengeti plus deux nuits à Tarangire coûtent bien moins que quatre nuits au Serengeti.',
    'blogcost_s6_sub2' => 'Les fausses économies',
    'blogcost_s6_false1_t' => 'Réduire le voyage à deux jours incluant le Serengeti.',
    'blogcost_s6_false1_d' => 'Vous payez les frais de parc complets pour passer la majeure partie du temps à conduire.',
    'blogcost_s6_false2_t' => 'Réserver le devis le moins cher que vous trouvez.',
    'blogcost_s6_false2_d' => 'Les frais de parc sont fixes, donc un prix très inférieur au marché est financé par autre chose, généralement l\'équipe, la nourriture ou le véhicule.',
    'blogcost_s6_false3_t' => 'Faire l\'impasse sur l\'assurance voyage.',
    'blogcost_s6_false3_d' => 'Une évacuation médicale depuis le Serengeti coûte plusieurs milliers de dollars.',
    'blogcost_s6_warn_t' => 'Un mot sur les devis suspicieusement bon marché :',
    'blogcost_s6_warn_d' => 'les frais de parc sur cette page sont publics et identiques pour tous. Si un devis pour quatre jours au Serengeti est à peine supérieur au total des frais, demandez à l\'opérateur de le détailler. Une entreprise réputée le fera sans hésitation.',
    'blogcost_s7_badge' => 'Exemples',
    'blogcost_s7_title' => 'Ce que coûtent de vrais itinéraires',
    'blogcost_s7_intro' => 'Prix indicatifs par personne, deux personnes partageant, frais de parc, véhicule, guide, hébergement et repas inclus. Votre devis écrit détaille chaque ligne.',
    'blogcost_t6_h1' => 'Itinéraire',
    'blogcost_days_tarangire_ngoro' => 'jours : Tarangire et Ngorongoro',
    'blogcost_days_serengeti_ngoro' => 'jours : Serengeti et Ngorongoro',
    'blogcost_days_bigfive' => 'jours : circuit Big Five',
    'blogcost_days_migration' => 'jours : safari migration',
    'blogcost_days_zanzibar' => 'jours : safari + Zanzibar',
    'blogcost_s7_note' => 'Indicatif uniquement. Les prix varient selon la saison, la taille du groupe et la disponibilité.',
    'blogcost_faq_badge' => 'FAQ',
    'blogcost_faq_title' => 'Coûts du safari : questions fréquentes',
    'blogcost_faq_q1' => 'Combien coûte un safari tanzanien par jour ?',
    'blogcost_faq_a1' => 'Environ 200-250 € par personne et par jour pour le camping économique, 250-350 € milieu de gamme, 400 $+ pour l\'avion et 600 $+ pour le luxe. Les frais de parc seuls en représentent une grande part, et ils sont identiques pour chaque opérateur.',
    'blogcost_faq_q2' => 'Qu\'est-ce qui est inclus dans un prix de safari ?',
    'blogcost_faq_a2' => 'Normalement : véhicule 4x4 avec chauffeur-guide, carburant, tous les frais d\'entrée de parc de l\'itinéraire, hébergement et repas comme décrit, et eau potable. Non inclus : vols internationaux, visa, assurance, boissons, pourboires et extras optionnels.',
    'blogcost_faq_q3' => 'Comment rendre un safari moins cher ?',
    'blogcost_faq_a3' => 'Voyagez en basse saison, soyez quatre plutôt que deux pour que le coût du véhicule se divise, dormez hors des parcs, choisissez Tarangire et Manyara plutôt que le Serengeti, et envisagez le camping.',
    'blogcost_faq_q4' => 'La taille du groupe change-t-elle vraiment le prix ?',
    'blogcost_faq_a4' => 'Considérablement. Le véhicule, le guide, le carburant et les frais de descente au cratère sont tous facturés par véhicule, pas par personne. Quatre personnes qui partagent paient nettement moins chacune que deux, et six paient encore moins.',
    'blogcost_faq_q5' => 'Dois-je me méfier des devis très bon marché ?',
    'blogcost_faq_a5' => 'Oui. Les frais de parc sont publics et fixes pour tous, donc un prix à peine supérieur au total des frais est financé ailleurs. Demandez à tout opérateur de détailler son devis.',
    'blogcost_faq_q6' => 'Combien dois-je budgétiser pour les pourboires ?',
    'blogcost_faq_a6' => 'Environ 20-25 $ par jour pour le chauffeur-guide, de la part du groupe dans son ensemble, plus 10-15 $ par jour pour le personnel de camp. Pour un voyage d\'une semaine à deux, prévoyez environ 200-300 $ au total.',
    'blogcost_faq_q7' => 'Combien coûte le visa tanzanien ?',
    'blogcost_faq_a7' => '50 $US pour la plupart des nationalités, obtenu en ligne sur visa.immigration.go.tz avant le voyage, ou à l\'arrivée. Méfiez-vous des sites non officiels facturant des frais supplémentaires pour la même chose.',
    'blogcost_faq_q8' => 'Puis-je payer en plusieurs fois ?',
    'blogcost_faq_a8' => 'Nos conditions standard sont un acompte de 30 % pour confirmer et le solde 30 jours avant l\'arrivée. Si vous réservez longtemps à l\'avance, nous pouvons généralement être flexibles sur le timing, demandez-nous simplement.',
    'blogcost_related_badge' => 'Continuer la lecture',
    'blogcost_related_title' => 'Continuer à explorer la Tanzanie',
    'blogcost_related_itineraries' => 'Nos itinéraires de safari',
    'blogcost_final_title' => 'Vous voulez un vrai chiffre pour votre voyage ?',
    'blogcost_final_intro' => 'Envoyez-nous vos dates et la taille de votre groupe et nous vous enverrons un devis détaillé : frais de parc, lits, véhicule et guide listés séparément, afin que vous voyiez exactement où va l\'argent.',
    'blogcost_final_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'blogcost_final_contact' => 'Formulaire de contact',

    // ===== Blog article: The Great Migration Month by Month =====
    'blogmig_meta_title' => 'La Grande Migration mois par mois (Guide 2026) | Serengeti Budget Safari',
    'blogmig_meta_description' => 'Où se trouvent les troupeaux de la Grande Migration chaque mois de l\'année, quand ont lieu la saison des naissances et les traversées de la rivière Mara, où loger pour chaque phase, et un compte rendu honnête de ce qui peut et ne peut pas être garanti.',
    'blogmig_h1' => 'La Grande Migration, mois par mois',
    'blogmig_hero_sub' => 'Où se trouvent les troupeaux chaque mois, quand ont lieu les naissances et les traversées de rivière, et ce qu\'aucun opérateur ne peut honnêtement vous promettre.',
    'blogmig_updated' => 'Mis à jour en 2026',
    'blogmig_quick_badge' => 'Réponses rapides',
    'blogmig_quick_title' => 'La migration en bref',
    'blogmig_quick_intro' => 'Les six questions qu\'on nous pose le plus souvent.',
    'blogmig_qq1_q' => 'Quand cela se passe-t-il ?',
    'blogmig_qq1_a' => 'Toute l\'année. Cela ne s\'arrête jamais, seul l\'emplacement change.',
    'blogmig_qq2_q' => 'Saison des naissances ?',
    'blogmig_qq2_a' => 'Fin janvier à février, à Ndutu.',
    'blogmig_qq3_q' => 'Traversées de rivière ?',
    'blogmig_qq3_a' => 'Juillet à octobre à la Mara, dans le nord.',
    'blogmig_qq4_q' => 'Où loger ?',
    'blogmig_qq4_a' => 'Ndutu déc-mars, Kogatende juil-oct. Cela compte énormément.',
    'blogmig_qq5_q' => 'Combien de nuits ?',
    'blogmig_qq5_a' => 'Trois minimum dans la zone de migration.',
    'blogmig_qq6_q' => 'Traversée garantie ?',
    'blogmig_qq6_a' => 'Non. Quiconque en promet une survend.',
    'blogmig_toc_title' => 'Sommaire',
    'blogmig_toc_1' => 'Ce que c\'est réellement',
    'blogmig_toc_2' => 'Mois par mois',
    'blogmig_toc_3' => 'La saison des naissances',
    'blogmig_toc_4' => 'Les traversées de rivière',
    'blogmig_toc_5' => 'Où loger selon le mois',
    'blogmig_toc_6' => 'Comment le planifier',
    'blogmig_toc_7' => 'Cinq mythes courants',
    'blogmig_toc_8' => 'FAQ',
    'blogmig_s1_badge' => 'Les bases',
    'blogmig_s1_title' => 'Ce qu\'est réellement la Grande Migration',
    'blogmig_s1_p1' => 'La Grande Migration est le mouvement continu d\'environ <strong>1,3 million de gnous</strong>, <strong>250 000 zèbres</strong> et plusieurs centaines de milliers de gazelles de Thomson et de Grant autour de l\'écosystème Serengeti-Masai Mara. C\'est le plus grand mouvement terrestre d\'animaux restant sur terre.',
    'blogmig_s1_p2' => 'La chose la plus utile à comprendre est celle-ci : <strong>ce n\'est pas un événement avec une date.</strong> Les troupeaux se trouvent quelque part dans l\'écosystème chaque mois de l\'année, se déplaçant selon un itinéraire à peu près circulaire dicté par les précipitations et la pousse de l\'herbe nouvelle. Il n\'y a ni début ni fin. Ce qui change mois par mois, c\'est <em>où</em> ils se trouvent, et donc où vous devez être.',
    'blogmig_s1_p3' => 'Une deuxième chose à savoir : les gnous ne voyagent pas comme un seul immense troupeau. Ils se déplacent en longues colonnes et groupes dispersés sur des dizaines de kilomètres, se rassemblant parfois en masses denses comme dans les documentaires, parfois dispersés sur la plaine ouverte. Les deux font partie de la migration.',
    'blogmig_fact_wildebeest' => 'Gnous',
    'blogmig_fact_zebra' => 'Zèbres',
    'blogmig_fact_gazelle' => 'Gazelles',
    'blogmig_fact_distance' => 'Distance annuelle',
    'blogmig_fact_calves' => 'Petits nés',
    'blogmig_fact_year' => 'an',
    'blogmig_fact_ecosystem' => 'Écosystème',
    'blogmig_s2_badge' => 'Le calendrier',
    'blogmig_s2_title' => 'Mois par mois : où se trouvent les troupeaux',
    'blogmig_s2_intro' => 'Le schéma ci-dessous se répète chaque année, mais les précipitations le décalent de deux ou trois semaines dans un sens ou l\'autre. Considérez-le comme une forte probabilité, jamais un horaire.',
    'blogmig_t1_h1' => 'Mois',
    'blogmig_t1_h2' => 'Où se trouvent les troupeaux',
    'blogmig_t1_h3' => 'Ce qui se passe',
    'blogmig_t1_h4' => 'Loger à',
    'blogmig_m1_name' => 'Janvier', 'blogmig_m1_where' => 'Plaines du sud et Ndutu', 'blogmig_m1_what' => 'Les troupeaux s\'installent sur les plaines à herbe courte. Les naissances commencent en fin de mois.', 'blogmig_m1_stay' => 'Ndutu',
    'blogmig_m2_name' => 'Février', 'blogmig_m2_where' => 'Ndutu et sud du Serengeti', 'blogmig_m2_what' => '<strong>Pic des naissances.</strong> Jusqu\'à 8 000 naissances par jour sur une fenêtre de trois semaines. Activité des prédateurs à son maximum de l\'année.', 'blogmig_m2_stay' => 'Ndutu',
    'blogmig_m3_name' => 'Mars', 'blogmig_m3_where' => 'Plaines du sud, début du mouvement', 'blogmig_m3_what' => 'Les petits se renforcent. Les grandes pluies commencent ; les troupeaux dérivent vers le nord-ouest.', 'blogmig_m3_stay' => 'Ndutu / Seronera',
    'blogmig_m4_name' => 'Avril', 'blogmig_m4_where' => 'Serengeti central et occidental', 'blogmig_m4_what' => 'Grandes pluies. Les colonnes se forment et se déplacent. Verdoyant, spectaculaire, presque vide de touristes.', 'blogmig_m4_stay' => 'Seronera / Moru',
    'blogmig_m5_name' => 'Mai', 'blogmig_m5_where' => 'Corridor occidental', 'blogmig_m5_what' => 'Rut : les mâles se battent pour le droit de s\'accoupler. De longues colonnes se dirigent vers l\'ouest.', 'blogmig_m5_stay' => 'Corridor occidental',
    'blogmig_m6_name' => 'Juin', 'blogmig_m6_where' => 'Corridor occidental et rivière Grumeti', 'blogmig_m6_what' => '<strong>Traversées de la Grumeti.</strong> Plus petites que la Mara mais avec d\'énormes crocodiles et très peu de véhicules.', 'blogmig_m6_stay' => 'Corridor occidental / Grumeti',
    'blogmig_m7_name' => 'Juillet', 'blogmig_m7_where' => 'Serengeti du Nord', 'blogmig_m7_what' => 'Les troupeaux atteignent la rivière Mara. Premières traversées, souvent hésitantes.', 'blogmig_m7_stay' => 'Kogatende',
    'blogmig_m8_name' => 'Août', 'blogmig_m8_where' => 'Serengeti du Nord et Masai Mara', 'blogmig_m8_what' => '<strong>Pic des traversées de la Mara.</strong> Les plus fréquentes et spectaculaires de l\'année.', 'blogmig_m8_stay' => 'Kogatende',
    'blogmig_m9_name' => 'Septembre', 'blogmig_m9_where' => 'Serengeti du Nord et Mara', 'blogmig_m9_what' => 'Les traversées continuent dans les deux sens alors que les troupeaux vont et viennent à travers la rivière.', 'blogmig_m9_stay' => 'Kogatende',
    'blogmig_m10_name' => 'Octobre', 'blogmig_m10_where' => 'Serengeti du Nord, dérivant vers le sud', 'blogmig_m10_what' => 'Dernières traversées. Les troupeaux entament le voyage de retour par l\'est du Serengeti.', 'blogmig_m10_stay' => 'Kogatende / Lobo',
    'blogmig_m11_name' => 'Novembre', 'blogmig_m11_where' => 'Serengeti oriental et central', 'blogmig_m11_what' => 'Les petites pluies ramènent les troupeaux vers le sud. Longues colonnes à travers Lobo et Seronera.', 'blogmig_m11_stay' => 'Lobo / Seronera',
    'blogmig_m12_name' => 'Décembre', 'blogmig_m12_where' => 'Plaines du sud', 'blogmig_m12_what' => 'Arrivée sur les plaines à herbe courte. Le circuit recommence.', 'blogmig_m12_stay' => 'Ndutu / Seronera',
    'blogmig_s3_badge' => 'Naissances',
    'blogmig_s3_title' => 'La saison des naissances : la partie que la plupart des gens manquent',
    'blogmig_s3_p1' => 'Entre fin janvier et février, environ <strong>400 000 petits gnous</strong> naissent sur les plaines à herbe courte autour de <strong>Ndutu</strong>, avec un pic pouvant atteindre <strong>8 000 naissances en une seule journée</strong>. Environ 80 % des femelles mettent bas dans la même fenêtre de trois semaines.',
    'blogmig_s3_sub1' => 'Pourquoi elles mettent toutes bas en même temps',
    'blogmig_s3_p2' => 'C\'est une stratégie de survie appelée saturation des prédateurs. En inondant les plaines de nouveau-nés en une brève période, le troupeau garantit que les prédateurs ne peuvent pas tous les prendre. Lions, hyènes et guépards sont simplement submergés. Un petit né en dehors de cette fenêtre a bien plus de risques d\'être tué.',
    'blogmig_s3_sub2' => 'Pourquoi Ndutu spécifiquement',
    'blogmig_s3_p3' => 'Les plaines du sud reposent sur des cendres volcaniques soufflées depuis les hautes terres du Ngorongoro, ce qui a créé une couche dure près de la surface. Les arbres ne peuvent pas y enraciner, donc les plaines restent ouvertes (bonne visibilité contre les prédateurs), et l\'herbe courte qui y pousse est exceptionnellement riche en calcium et en phosphore. C\'est exactement ce dont une mère allaitante a besoin pour construire les os d\'un petit.',
    'blogmig_s3_sub3' => 'Ce que vous voyez réellement',
    'blogmig_s3_p4' => 'Des nouveau-nés debout en quelques minutes après la naissance et courant en moins d\'une heure. Des groupes de nurserie de centaines de petits. Et, inévitablement, la prédation : c\'est le mois où lions, guépards et hyènes chassent le plus efficacement, et vous verrez des mises à mort. Certains voyageurs trouvent cela difficile, il vaut donc mieux le savoir à l\'avance.',
    'blogmig_s3_note_t' => 'Un avis honnête de nos guides :',
    'blogmig_s3_note_d' => 'la plupart des gens viennent en août pour les traversées de rivière. Si vous demandez aux guides quelle saison ils choisiraient pour eux-mêmes, une nette majorité dit février à Ndutu. L\'activité de la faune est plus constante, plus variée, et il y a bien moins de véhicules.',
    'blogmig_s4_badge' => 'Traversées',
    'blogmig_s4_title' => 'Les traversées de rivière, et la vérité à leur sujet',
    'blogmig_s4_p1' => 'L\'image que tout le monde a de la migration, des milliers de gnous plongeant dans une rivière pendant que les crocodiles attendent, est réelle, et elle se produit à la <strong>rivière Mara</strong> dans le nord du Serengeti entre juillet et octobre, et à la <strong>rivière Grumeti</strong> à l\'ouest vers juin.',
    'blogmig_s4_sub1' => 'Ce qui se passe réellement',
    'blogmig_s4_p2' => 'Les troupeaux se rassemblent sur la berge, souvent par milliers. Ils attendent. Parfois vingt minutes, parfois six heures, parfois toute la journée. Puis un animal se lance et les autres suivent en quelques minutes frénétiques, ou tout le troupeau fait demi-tour et repart sans traverser du tout.',
    'blogmig_s4_p3' => 'Personne ne contrôle cela et personne ne peut le prédire. Des troupeaux ont été connus pour traverser, brouter sur l\'autre rive pendant une heure, puis retraverser immédiatement.',
    'blogmig_s4_sub2' => 'Les chances honnêtes',
    'blogmig_s4_p4' => 'Avec <strong>trois nuits à Kogatende entre fin juillet et septembre</strong>, vous avez une bonne chance d\'assister à au moins une traversée. Avec une nuit, vous prenez un risque. Tout opérateur qui garantit une traversée à une date précise est soit mal informé, soit vous vend quelque chose qu\'il ne peut pas livrer.',
    'blogmig_s4_note_t' => 'Ce que nous disons à nos clients :',
    'blogmig_s4_note_d' => 'réservez trois nuits minimum dans le nord si une traversée est la raison de votre voyage, allez-y en août ou début septembre, et acceptez que les matinées passées à attendre sur une berge sans qu\'il ne se passe rien font partie de l\'expérience.',
    'blogmig_s4_sub3' => 'Grumeti contre Mara',
    'blogmig_s4_mara' => 'Rivière Mara',
    'blogmig_s4_grumeti' => 'Rivière Grumeti',
    'blogmig_s4_row_months' => 'Mois',
    'blogmig_s4_mara_months' => 'Juillet – Octobre',
    'blogmig_s4_grumeti_months' => 'Mai – Juillet',
    'blogmig_s4_row_scale' => 'Ampleur',
    'blogmig_s4_mara_scale' => 'Grande, spectaculaire',
    'blogmig_s4_grumeti_scale' => 'Plus petite, plus dispersée',
    'blogmig_s4_row_croc' => 'Crocodiles',
    'blogmig_s4_mara_croc' => 'Nombreux',
    'blogmig_s4_grumeti_croc' => 'Moins nombreux mais énormes',
    'blogmig_s4_row_vehicles' => 'Véhicules',
    'blogmig_s4_mara_vehicles' => 'Nombreux en haute saison',
    'blogmig_s4_grumeti_vehicles' => 'Très peu',
    'blogmig_s4_row_stay' => 'Où loger',
    'blogmig_s4_mara_stay' => 'Kogatende',
    'blogmig_s4_grumeti_stay' => 'Corridor occidental',
    'blogmig_s5_badge' => 'Hébergement',
    'blogmig_s5_title' => 'Où loger pour chaque phase',
    'blogmig_s5_p1' => 'C\'est là que la plupart des voyages de migration échouent. Réserver « un lodge au Serengeti » ne suffit pas : le parc fait 14 763 km², et un lodge au centre est à cinq heures de route des troupeaux s\'ils sont dans le nord.',
    'blogmig_t2_h1' => 'Si vous voyagez en…',
    'blogmig_t2_h2' => 'Logez à…',
    'blogmig_t2_h3' => 'Pourquoi',
    'blogmig_t2_r1_a' => 'Décembre – Mars', 'blogmig_t2_r1_b' => 'Ndutu', 'blogmig_t2_r1_c' => 'Saison des naissances sur les plaines du sud',
    'blogmig_t2_r2_a' => 'Avril – Mai', 'blogmig_t2_r2_b' => 'Seronera / Moru', 'blogmig_t2_r2_c' => 'Troupeaux traversant le centre et l\'ouest',
    'blogmig_t2_r3_a' => 'Mai – Juillet', 'blogmig_t2_r3_b' => 'Corridor occidental', 'blogmig_t2_r3_c' => 'Traversées de la rivière Grumeti',
    'blogmig_t2_r4_a' => 'Juillet – Octobre', 'blogmig_t2_r4_b' => 'Kogatende', 'blogmig_t2_r4_c' => 'Traversées de la rivière Mara dans le nord',
    'blogmig_t2_r5_a' => 'Novembre', 'blogmig_t2_r5_b' => 'Lobo / Seronera', 'blogmig_t2_r5_c' => 'Voyage de retour par l\'est',
    'blogmig_s5_sub1' => 'Camps mobiles',
    'blogmig_s5_p2' => 'Plusieurs opérateurs gèrent des camps tentés mobiles qui se déplacent physiquement deux ou trois fois par an pour suivre les troupeaux. C\'est le moyen le plus fiable de rester proche de la migration, ils sont généralement petits et isolés, et coûtent environ 300-700 $ par personne et par nuit. Si la migration est l\'objectif entier de votre voyage, c\'est ce qu\'il vous faut.',
    'blogmig_s5_link' => 'Parlez-nous des options d\'hébergement',
    'blogmig_s6_badge' => 'Planification',
    'blogmig_s6_title' => 'Comment planifier un safari de migration',
    'blogmig_s6_step1_t' => 'Étape 1 : décidez quelle phase vous voulez',
    'blogmig_s6_step1_d' => 'Naissances à Ndutu, ou traversées de rivière dans le nord. Ce sont les deux expériences phares et elles se produisent aux extrémités opposées du parc et du calendrier. Vous ne pouvez pas faire les deux en un seul voyage.',
    'blogmig_s6_step2_t' => 'Étape 2 : réservez tôt',
    'blogmig_s6_step2_d' => 'Les camps à Kogatende pour août et septembre, et à Ndutu pour février, se réservent complets <strong>six à douze mois à l\'avance</strong>. Ce n\'est pas une technique de vente. Ces zones ont un nombre limité de lits, et les bons petits camps partent en premier.',
    'blogmig_s6_step3_t' => 'Étape 3 : prévoyez assez de nuits',
    'blogmig_s6_step3_d' => 'Trois nuits minimum dans la zone de migration. Deux, c\'est un pari, une, c\'est un billet de loterie.',
    'blogmig_s6_step4_t' => 'Étape 4 : envisagez de prendre l\'avion',
    'blogmig_s6_step4_d' => 'Kogatende est à deux jours de route d\'Arusha. Un vol d\'1 heure 15 transforme quatre jours de conduite en quatre jours supplémentaires d\'observation de la faune. Pour un voyage dans le nord du Serengeti, l\'avion est presque toujours le meilleur choix.',
    'blogmig_s6_step5_t' => 'Étape 5 : intégrez le reste de l\'écosystème',
    'blogmig_s6_step5_d' => 'La migration n\'est pas la seule chose à voir. Les prédateurs résidents, le cratère du Ngorongoro et les éléphants de Tarangire sont tous là quel que soit l\'endroit où se trouvent les troupeaux, et un bon itinéraire les utilise pour remplir les jours autour de vos nuits de migration.',
    'blogmig_t3_h1' => 'Durée du voyage',
    'blogmig_t3_h2' => 'Structure suggérée',
    'blogmig_days' => 'jours',
    'blogmig_t3_r1_b' => 'Vol vers la zone de migration pour 3 nuits, Ngorongoro au retour',
    'blogmig_t3_r2_b' => 'Tarangire, Serengeti central 2 nuits, zone de migration 3 nuits, Ngorongoro',
    'blogmig_t3_r3_b' => 'Circuit nord complet avec 4 nuits dans la zone de migration, puis Zanzibar',
    'blogmig_s7_badge' => 'Mythes',
    'blogmig_s7_title' => 'Cinq idées reçues courantes',
    'blogmig_s7_myth1_t' => 'La migration a lieu en août',
    'blogmig_s7_myth1_d' => 'Les <em>traversées de la rivière Mara</em> ont lieu vers août. La migration elle-même est continue. Les troupeaux sont toujours quelque part, et il n\'y a aucun mois où rien ne se passe.',
    'blogmig_s7_myth2_t' => 'Je dois aller au Kenya pour la voir',
    'blogmig_s7_myth2_d' => 'Environ 80 % du circuit annuel de la migration se trouve en Tanzanie. Les troupeaux passent environ deux à trois mois dans le Masai Mara et le reste de l\'année dans l\'écosystème du Serengeti.',
    'blogmig_s7_myth3_t' => 'Une traversée est garantie si je vais au bon moment',
    'blogmig_s7_myth3_d' => 'Ce n\'est pas le cas. Être au bon endroit au bon mois vous donne une bonne chance sur plusieurs jours. Cela ne garantit rien pour une seule matinée.',
    'blogmig_s7_myth4_t' => 'La migration est un seul troupeau géant',
    'blogmig_s7_myth4_d' => 'Ce sont des colonnes et des groupes dispersés sur des dizaines de kilomètres, se rassemblant parfois et se dispersant d\'autres fois. L\'image documentaire d\'une masse compacte est un moment, pas l\'état normal.',
    'blogmig_s7_myth5_t' => 'La saison des pluies est un mauvais moment',
    'blogmig_s7_myth5_d' => 'Avril et mai sont verdoyants, spectaculaires, presque vides d\'autres véhicules et nettement moins chers, et les troupeaux traversent le centre et l\'ouest, ce qui offre une très bonne observation. Si votre priorité est le rapport qualité-prix et la solitude plutôt que les traversées de rivière, les mois humides sont sous-estimés.',
    'blogmig_faq_title' => 'La Grande Migration : questions fréquentes',
    'blogmig_faq_q1' => 'Quelle est la meilleure période pour voir la Grande Migration ?',
    'blogmig_faq_a1' => 'Cela dépend de la phase que vous voulez. Fin janvier à février pour la saison des naissances à Ndutu ; juillet à octobre pour les traversées de la rivière Mara dans le nord du Serengeti. Les deux sont exceptionnelles, et elles se produisent aux extrémités opposées du parc et du calendrier.',
    'blogmig_faq_q2' => 'Puis-je voir la migration toute l\'année ?',
    'blogmig_faq_a2' => 'Oui. Les troupeaux ne quittent jamais l\'écosystème. Ils se déplacent en un circuit continu. Ce qui change, c\'est où ils se trouvent, donc la région où vous logez doit correspondre à votre mois.',
    'blogmig_faq_q3' => 'Verrai-je forcément une traversée de rivière ?',
    'blogmig_faq_a3' => 'Non, et méfiez-vous de quiconque en promet une. Les troupeaux peuvent attendre sur la berge toute une journée puis repartir. Trois nuits à Kogatende entre fin juillet et septembre vous donnent une bonne chance, pas une garantie.',
    'blogmig_faq_q4' => 'Dois-je aller en Tanzanie ou au Kenya pour la migration ?',
    'blogmig_faq_a4' => 'Environ 80 % du circuit annuel se trouve en Tanzanie. Les troupeaux ne passent que deux à trois mois dans le Masai Mara. La Tanzanie vous offre aussi la saison des naissances, ce que le Kenya n\'offre pas.',
    'blogmig_faq_q5' => 'Où dois-je loger pour la saison des naissances ?',
    'blogmig_faq_a5' => 'Ndutu, sur les plaines à herbe courte du sud, entre décembre et mars. Notez que Ndutu se trouve techniquement dans la zone de conservation du Ngorongoro plutôt que dans le Serengeti, bien qu\'écologiquement ce soit la même plaine.',
    'blogmig_faq_q6' => 'Combien de jours me faut-il pour un safari de migration ?',
    'blogmig_faq_a6' => 'Trois nuits minimum dans la zone de migration elle-même, plus les jours de trajet. Deux nuits, c\'est un pari et une, c\'est un billet de loterie. Cinq à sept jours au total constituent un voyage confortable.',
    'blogmig_faq_q7' => 'Combien y a-t-il de gnous ?',
    'blogmig_faq_a7' => 'Environ 1,3 million de gnous, plus environ 250 000 zèbres et plusieurs centaines de milliers de gazelles. C\'est le plus grand mouvement terrestre d\'animaux restant sur terre.',
    'blogmig_faq_q8' => 'Qu\'est-ce qu\'un camp mobile ?',
    'blogmig_faq_a8' => 'Un camp tenté qui se déplace physiquement deux ou trois fois par an pour suivre les troupeaux. C\'est le moyen le plus fiable de rester proche de la migration, généralement 300-700 $ par personne et par nuit, et habituellement petit et isolé.',
    'blogmig_final_title' => 'Prêt à planifier votre safari de migration ?',
    'blogmig_final_intro' => 'Dites-nous vos dates et nous vous dirons honnêtement s\'il s\'agit de la saison des naissances, de la saison des traversées, ou d\'un entre-deux, et construirons l\'itinéraire en conséquence.',

    // Blog article: Kenya vs Tanzania safari
    'blogkenya_meta_title' => 'Safari Kenya contre Tanzanie : une comparaison honnête (2026)',
    'blogkenya_meta_description' => 'Kenya ou Tanzanie pour un safari ? Une comparaison honnête du Serengeti et du Masai Mara, des mois de migration, des frais de parc, de la densité de véhicules, des règles de conduite hors piste et du pays adapté à quel type de voyage.',
    'blogkenya_updated' => 'Mis à jour en 2026',
