    'blogkenya_toc_6' => 'FAQ',
    'blogkenya_s1_badge' => 'En bref',
    'blogkenya_s1_title' => 'La réponse courte',
    'blogkenya_s1_p1' => 'Ils partagent le même écosystème et la même migration, divisés par une frontière. En résumé :',
    'blogkenya_s1_li1_t' => 'Tanzanie',
    'blogkenya_s1_li1_d' => 'pour l\'échelle, la variété et la saison des naissances. Elle a aussi le Kilimandjaro, Zanzibar et le cratère du Ngorongoro.',
    'blogkenya_s1_li2_t' => 'Kenya',
    'blogkenya_s1_li2_d' => 'pour la commodité et le coût plus bas. Les observations arrivent plus vite dans une zone plus petite, et c\'est généralement moins cher.',
    'blogkenya_s1_p2' => 'Aucun n\'est objectivement meilleur. Ce qui suit est le détail honnête, écrit, il faut le dire clairement, par un opérateur tanzanien. Nous avons essayé d\'être équitables.',
    'blogkenya_s2_badge' => 'Comparaison',
