    'blogkenya_s3_badge' => 'Migration',
    'blogkenya_s3_title' => 'La migration : qui en a le plus ?',
    'blogkenya_s3_p1' => 'C\'est la question que la plupart des gens se posent vraiment, et la réponse est plus claire que ne le suggère le marketing de chaque côté.',
    'blogkenya_s3_p2' => 'Les troupeaux passent environ <strong>neuf à dix mois de l\'année en Tanzanie</strong> et deux à trois mois dans le Masai Mara au Kenya. Les célèbres traversées de la rivière Mara se produisent à la frontière, et peuvent être observées de chaque côté entre juillet et octobre.',
    'blogkenya_s3_p3' => '<strong>Ce que la Tanzanie a et pas le Kenya :</strong> la saison des naissances. Environ 400 000 gnous naissent à Ndutu fin janvier et février, et cela ne se produit nulle part ailleurs.',
    'blogkenya_s3_p4' => '<strong>Ce que le Kenya a et pas la Tanzanie :</strong> la compacité. La Mara fait un dixième de la taille du Serengeti, donc quand les troupeaux y sont, ils sont concentrés et faciles à atteindre.',
    'blogkenya_s4_badge' => 'Expérience',
    'blogkenya_s4_title' => 'À quoi ressemble vraiment l\'expérience',
    'blogkenya_s4_sub1' => 'Tanzanie',
    'blogkenya_s4_p1' => 'Plus grande, plus déserte et plus lente. Les trajets entre les parcs sont longs (Arusha au Serengeti, c\'est sept à huit heures), et les paysages changent radicalement au fil du trajet. La conduite hors piste est interdite, donc vous restez sur les pistes et les observations se font à distance respectueuse. Dans les parcs les moins visités, vous pouvez passer une matinée sans voir un autre véhicule.',
    'blogkenya_s4_sub2' => 'Kenya',
    'blogkenya_s4_p2' => 'Plus compact et plus rythmé. Les trajets sont plus courts, les observations arrivent plus vite, et dans les réserves privées bordant la Mara, la conduite hors piste, les safaris de nuit et la marche sont tous autorisés, ce que les parcs nationaux tanzaniens n\'autorisent pas. Le compromis, c\'est la densité de véhicules : une bonne observation dans la Mara en août peut attirer une foule.',
    'blogkenya_s4_note_t' => 'Le résumé honnête :',
    'blogkenya_s4_note_d' => 'si vous voulez la plus grande variété et le sentiment d\'un espace immense, la Tanzanie. Si vous voulez le plus de faune par jour et par dollar sur un voyage plus court, le Kenya. De nombreux voyageurs expérimentés finissent par faire les deux.',
    'blogkenya_s5_badge' => 'Choisir',
    'blogkenya_s5_title' => 'Lequel devriez-vous choisir ?',
    'blogkenya_t2_h1' => 'Si vous…',
    'blogkenya_t2_h2' => 'Choisissez',
    'blogkenya_t2_r1_a' => 'Voulez la saison des naissances',
    'blogkenya_t2_r2_a' => 'Voulez gravir le Kilimandjaro',
    'blogkenya_t2_r3_a' => 'Voulez une plage ensuite',
    'blogkenya_t2_r4_a' => 'Voulez le cratère du Ngorongoro',
    'blogkenya_t2_r5_a' => 'Avez 10 jours ou plus',
    'blogkenya_t2_r6_a' => 'Avez 5 jours ou moins',
    'blogkenya_t2_r7_a' => 'Avez un budget plus serré',
    'blogkenya_t2_r8_a' => 'Voulez des safaris de nuit et hors piste',
    'blogkenya_conservancies' => 'réserves privées',
    'blogkenya_t2_r9_a' => 'Voulez les traversées de rivière en juil-oct',
    'blogkenya_either' => 'L\'un ou l\'autre',
    'blogkenya_t2_r10_a' => 'Voulez le moins d\'autres véhicules',
    'blogkenya_southern_circuit' => '(circuit sud)',
    'blogkenya_s5_sub1' => 'Puis-je faire les deux ?',
    'blogkenya_s5_p1' => 'Oui. Le Serengeti et le Masai Mara sont adjacents, et les itinéraires combinés sont courants, généralement en avion entre les deux, car le passage de la frontière terrestre à Isebania est lent. Notez que le <strong>Visa Touristique Afrique de l\'Est ne couvre pas la Tanzanie</strong> : vous avez besoin de visas séparés pour chaque pays. Prévoyez 10 à 14 jours pour faire les deux correctement.',
    'blogkenya_faq_badge' => 'FAQ',
    'blogkenya_faq_title' => 'Kenya contre Tanzanie : questions fréquentes',
    'blogkenya_faq_q1' => 'La Tanzanie ou le Kenya est-il meilleur pour un safari ?',
    'blogkenya_faq_a1' => 'Aucun n\'est objectivement meilleur. La Tanzanie offre plus d\'échelle et de variété, la saison des naissances, le Kilimandjaro, le Ngorongoro et Zanzibar. Le Kenya est plus compact, généralement moins cher, et meilleur pour les voyages courts.',
    'blogkenya_faq_q2' => 'Où se trouve la Grande Migration : Tanzanie ou Kenya ?',
    'blogkenya_faq_a2' => 'Les deux, mais les troupeaux passent environ neuf à dix mois de l\'année en Tanzanie et seulement deux à trois dans le Masai Mara au Kenya. Les célèbres traversées de rivière se produisent à la frontière entre juillet et octobre.',
    'blogkenya_faq_q3' => 'Lequel est moins cher, le Kenya ou la Tanzanie ?',
    'blogkenya_faq_a3' => 'Le Kenya, généralement. Les frais de parc tanzaniens sont plus élevés (82,60 $ par jour au Serengeti) et les distances sont plus grandes, ce qui signifie plus de carburant et plus de jours. La compacité du Kenya réduit le coût total du voyage.',
    'blogkenya_faq_q4' => 'Le Serengeti est-il meilleur que le Masai Mara ?',
    'blogkenya_faq_a4' => 'C\'est le même écosystème divisé par une frontière. Le Serengeti est environ dix fois plus grand avec des habitats plus variés et une densité de véhicules plus basse ; la Mara est compacte donc les observations arrivent plus vite, mais avec plus de monde en haute saison.',
    'blogkenya_faq_q5' => 'Puis-je voir la saison des naissances au Kenya ?',
    'blogkenya_faq_a5' => 'Non. Les naissances se produisent sur les plaines à herbe courte du sud à Ndutu, en Tanzanie, fin janvier et février. C\'est l\'une des raisons les plus claires de choisir la Tanzanie.',
    'blogkenya_faq_q6' => 'Puis-je visiter les deux pays en un seul voyage ?',
    'blogkenya_faq_a6' => 'Oui, et les itinéraires combinés sont courants, généralement en avion entre le Serengeti et la Mara, car le passage de la frontière terrestre est lent. Prévoyez 10 à 14 jours, et notez que vous avez besoin de visas séparés pour chaque pays.',
    'blogkenya_faq_q7' => 'Le Visa Touristique Afrique de l\'Est couvre-t-il la Tanzanie ?',
    'blogkenya_faq_a7' => 'Non. Il couvre uniquement le Kenya, l\'Ouganda et le Rwanda. La Tanzanie nécessite son propre visa, actuellement 50 $ pour la plupart des nationalités.',
    'blogkenya_faq_q8' => 'Quel pays est meilleur pour les Big Five ?',
    'blogkenya_faq_a8' => 'Les deux offrent facilement quatre des cinq. Pour le rhinocéros noir, le Kenya a plusieurs options fiables dont Ol Pejeta et le lac Nakuru, tandis qu\'en Tanzanie, le cratère du Ngorongoro est essentiellement le seul endroit réaliste.',
    'blogkenya_faq_q9' => 'Où y a-t-il moins de touristes ?',
    'blogkenya_faq_a9' => 'La Tanzanie, en particulier le circuit sud : Ruaha, Nyerere et Mikumi ne voient qu\'une infime fraction des visiteurs du Serengeti ou de la Mara. Même Tarangire est calme selon les standards est-africains.',
    'blogkenya_faq_q10' => 'Puis-je faire des safaris de nuit et de la conduite hors piste ?',
    'blogkenya_faq_a10' => 'Dans les réserves privées du Kenya, oui. Dans les parcs nationaux tanzaniens, la conduite hors piste est interdite et les safaris de nuit ne sont pas autorisés sauf au lac Manyara, à Tarangire et dans certaines concessions privées.',
    'blogkenya_faq_q11' => 'Lequel est meilleur pour un premier safari ?',
    'blogkenya_faq_a11' => 'Si vous avez une semaine ou plus et voulez de la variété, la Tanzanie. Si vous avez quatre ou cinq jours, le Kenya offre plus de faune par jour car les distances sont bien plus courtes.',
    'blogkenya_faq_q12' => 'Et le Kilimandjaro : est-il au Kenya ou en Tanzanie ?',
    'blogkenya_faq_a12' => 'En Tanzanie, entièrement. La célèbre vue du Kilimandjaro s\'élevant derrière des éléphants est souvent photographiée depuis Amboseli au Kenya, mais la montagne elle-même et tous les itinéraires d\'ascension sont en Tanzanie.',
    'blogkenya_related_badge' => 'Continuer la lecture',
    'blogkenya_related_title' => 'Continuer à explorer la Tanzanie',
    'blogkenya_final_title' => 'Encore indécis ?',
    'blogkenya_final_intro' => 'Dites-nous vos dates et combien de temps vous avez. Si le Kenya convient véritablement mieux à votre voyage que la Tanzanie, nous vous le dirons. Nous préférons être utiles plutôt que de gagner une réservation que vous regretteriez.',
    'blogkenya_final_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'blogkenya_final_contact' => 'Formulaire de contact',

    // Blog article: Best time to visit Tanzania
    'blogbest_meta_title' => 'Meilleure période pour visiter la Tanzanie : mois par mois (2026) | Serengeti Budget Safari',
    'blogbest_meta_description' => 'Quand visiter la Tanzanie, mois par mois : saison sèche, les deux saisons des pluies, la saison des naissances et les traversées de la rivière Mara, températures par altitude, et les meilleurs mois pour le safari, le Kilimandjaro et Zanzibar.',
    'blogbest_h1' => 'Meilleure période pour visiter la Tanzanie',
    'blogbest_hero_sub' => 'Mois par mois : ce que vous voyez, avec combien d\'autres véhicules vous le partagez, et ce que vous payez. Il n\'y a pas de saison fermée, seulement des compromis.',
    'blogbest_updated' => 'Mis à jour en 2026',
    'blogbest_author' => 'Équipe Serengeti Budget Safari',
    'blogbest_date' => 'Août 2026',
    'blogbest_quick_badge' => 'Réponses rapides',
