    'blogbest_s1_badge' => 'En bref',
    'blogbest_s1_title' => 'La réponse courte',
    'blogbest_s1_p1' => '<strong>Juin à octobre</strong> est la saison sèche et la période la plus facile pour voir la faune presque partout en Tanzanie. <strong>Fin janvier et février</strong> apportent la saison des naissances dans le sud du Serengeti, que de nombreux guides considèrent comme le meilleur spectacle. <strong>Mars à mai</strong>, ce sont les grandes pluies : vert, calme et nettement moins cher.',
    'blogbest_s1_p2' => 'Il n\'y a pas de saison fermée. Ce qui change, c\'est ce que vous voyez, avec combien d\'autres véhicules vous le partagez, et ce que vous payez.',
