    'blogbest_s2_badge' => 'Saisons',
    'blogbest_s2_title' => 'La Tanzanie a deux saisons des pluies, pas une seule',
    'blogbest_s2_p1' => 'Les confondre est l\'erreur de planification la plus courante, et elles sont vraiment différentes.',
    'blogbest_s2_sub1_title' => 'Les grandes pluies : mars à mai',
    'blogbest_s2_sub1_p' => 'De la vraie pluie, souvent plusieurs heures par jour, la plus forte en avril. Certaines pistes deviennent impraticables, le sol argileux noir du corridor occidental se transforme en glu, et un certain nombre de camps saisonniers ferment entièrement, particulièrement à Ruaha et Nyerere. C\'est aussi la période la moins chère de l\'année de loin, le paysage est spectaculaire, et vous pouvez avoir les parcs presque pour vous seul.',
    'blogbest_s2_sub2_title' => 'Les petites pluies : novembre à décembre',
    'blogbest_s2_sub2_p' => 'De brèves et fortes averses en fin d\'après-midi, avec le reste de la journée généralement ensoleillé. Rien ne ferme, rien n\'est inondé, le pays devient vert et les prix restent modérés. Pour de nombreux voyageurs, c\'est le meilleur compromis de l\'année, et c\'est nettement sous-estimé.',
    'blogbest_s2_note_t' => 'Bon à savoir :',
    'blogbest_s2_note_d' => 'la pluie en Tanzanie signifie rarement une journée gâchée. Elle signifie généralement une forte heure puis un air clair, une lumière spectaculaire et un paysage bien plus photogénique qu\'en août poussiéreux.',
    'blogbest_s3_badge' => 'Le calendrier',
