    'blogbest_w2_want' => 'Traversées de la rivière Mara',
    'blogbest_w2_why' => 'Fréquence maximale dans le nord du Serengeti',
    'blogbest_w3_want' => 'Naissances et prédateurs',
    'blogbest_w3_why' => '400 000 naissances ; chasse constante',
    'blogbest_w4_want' => 'Prix les plus bas',
    'blogbest_w4_why' => 'Grandes pluies ; forts rabais dans les camps',
    'blogbest_w5_want' => 'Le moins de véhicules',
    'blogbest_w5_why' => 'Parcs presque vides',
    'blogbest_w6_want' => 'Observation des oiseaux',
    'blogbest_w6_why' => 'Migrateurs présents, résidents en plumage nuptial',
    'blogbest_w7_want' => 'Photographie',
    'blogbest_w7_why' => 'Paysages verts, ciels spectaculaires, air pur',
    'blogbest_w8_want' => 'Kilimandjaro',
    'blogbest_w8_why' => 'Le plus sec et le plus stable sur la montagne',
    'blogbest_w9_want' => 'Zanzibar',
    'blogbest_w9_why' => 'Sec, mer calme, bonne visibilité pour la plongée',
    'blogbest_w10_want' => 'Circuit sud',
    'blogbest_w10_why' => 'Ruaha et Nyerere ferment largement de mars à mai',
    'blogbest_s5_badge' => 'Climat',
    'blogbest_s5_title' => 'À quoi ressemble vraiment le climat',
    'blogbest_s5_p1' => 'La Tanzanie se trouve sur l\'équateur, mais l\'altitude compte bien plus que la latitude. Les parcs du nord sont entre 1 000 m et 2 400 m, c\'est pourquoi les matinées sont vraiment froides.',
    'blogbest_t4_h1' => 'Lieu',
    'blogbest_t4_h2' => 'Altitude',
    'blogbest_t4_h3' => 'Journée',
    'blogbest_t4_h4' => 'Aube',
    'blogbest_c1_place' => 'Bord du Ngorongoro',
    'blogbest_c2_place' => 'Serengeti',
    'blogbest_c3_place' => 'Arusha',
    'blogbest_c4_place' => 'Tarangire',
    'blogbest_c5_place' => 'Zanzibar',
    'blogbest_c6_place' => 'Sommet du Kilimandjaro',
    'blogbest_sea_level' => 'Niveau de la mer',
    'blogbest_colder' => 'Plus froid',
    'blogbest_s5_p2' => 'Le chiffre qui surprend les gens, c\'est le bord du Ngorongoro à l\'aube : environ 5 °C, dans un véhicule ouvert, en mouvement. Chaque visiteur qui n\'a fait ses bagages que pour « l\'Afrique » le regrette. Les couches ne sont pas optionnelles.',
    'blogbest_faq_badge' => 'FAQ',
    'blogbest_faq_title' => 'Quand visiter la Tanzanie : questions fréquentes',
    'blogbest_faq_q1' => 'Quelle est la meilleure période pour visiter la Tanzanie ?',
    'blogbest_faq_a1' => 'Juin à octobre pour l\'observation de la faune la plus facile partout, et fin janvier à février pour la saison des naissances au Serengeti. Mars à mai, ce sont les grandes pluies : vert, calme et de loin le moins cher.',
    'blogbest_faq_q2' => 'Quelle est la pire période pour visiter la Tanzanie ?',
    'blogbest_faq_a2' => 'Avril est le mois le plus humide et celui que la plupart des gens évitent. Les pistes deviennent difficiles, certains camps du sud ferment entièrement, et les vues sont souvent obscurcies. C\'est aussi le mois le moins cher et les parcs sont presque vides, ce qui convient très bien à certains voyageurs.',
    'blogbest_faq_q3' => 'Puis-je faire un safari en saison des pluies ?',
    'blogbest_faq_a3' => 'Oui. Les parcs du nord fonctionnent toute l\'année et la pluie tombe généralement en fortes averses plutôt que toute la journée. Ruaha et Nyerere au sud sont différents. La plupart des camps y ferment entre mars et mai.',
    'blogbest_faq_q4' => 'Quand ont lieu les traversées de la rivière Mara ?',
    'blogbest_faq_a4' => 'Juillet à octobre dans le nord du Serengeti, août et septembre étant les mois de pointe pour la fréquence. Être là au bon mois vous donne une bonne chance sur plusieurs jours, jamais une garantie pour une matinée donnée.',
    'blogbest_faq_q5' => 'Quand a lieu la saison des naissances ?',
    'blogbest_faq_a5' => 'Fin janvier et février, sur les plaines à herbe courte autour de Ndutu. Environ 400 000 petits naissent sur une fenêtre de trois semaines, et l\'activité des prédateurs est à son maximum de l\'année.',
    'blogbest_faq_q6' => 'Fait-il froid en Tanzanie ?',
    'blogbest_faq_a6' => 'En altitude, oui, et cela surprend la plupart des visiteurs. Le bord du Ngorongoro descend à environ 5 °C avant l\'aube, et le Serengeti à 13-15 °C. La journée est chaude, donc des couches plutôt qu\'un seul manteau épais est la réponse.',
    'blogbest_faq_q7' => 'Quelle est la période la moins chère pour un safari ?',
    'blogbest_faq_a7' => 'Avril et mai, pendant les grandes pluies, quand les camps offrent de forts rabais et que les parcs sont presque vides. Novembre est la deuxième option la moins chère et nettement plus sec : de brèves averses l\'après-midi plutôt que de la pluie toute la journée.',
    'blogbest_faq_q8' => 'Quelle est la meilleure période pour gravir le Kilimandjaro ?',
    'blogbest_faq_a8' => 'Janvier à début mars et juin à octobre. Janvier et février ont les nuits de sommet les plus chaudes ; juin à octobre est le plus sec et le plus fréquenté. Avril et mai sont les grandes pluies et mieux vaut les éviter sur la montagne.',
    'blogbest_faq_q9' => 'Quelle est la meilleure période pour Zanzibar ?',
    'blogbest_faq_a9' => 'Juin à octobre est sec et moins humide ; décembre à février est chaud avec une mer calme et une excellente visibilité pour la plongée. Mars à mai, ce sont les grandes pluies, quand certains hôtels ferment.',
    'blogbest_faq_q10' => 'Août est-il très fréquenté ?',
    'blogbest_faq_a10' => 'C\'est le mois de pointe. Les camps du nord du Serengeti se réservent complets six à douze mois à l\'avance, les prix sont à leur maximum, et vous partagerez les observations. La faune est superbe. Vous n\'êtes simplement pas seul avec elle.',
    'blogbest_faq_q11' => 'Novembre est-il un bon mois ?',
    'blogbest_faq_a11' => 'C\'est l\'un des plus sous-estimés. Les petites pluies apportent de brèves averses l\'après-midi, le paysage devient vert, les migrateurs arrivent pour les ornithologues, les prix sont modérés et les parcs sont calmes. Rien ne ferme.',
    'blogbest_faq_q12' => 'La migration s\'arrête-t-elle en saison des pluies ?',
    'blogbest_faq_a12' => 'Non. Les troupeaux sont dans l\'écosystème chaque mois de l\'année. Les pluies sont précisément ce qui les fait bouger. En avril et mai, ils traversent le centre et l\'ouest du Serengeti.',
    'blogbest_faq_q13' => 'Qu\'en est-il de Noël et du Nouvel An ?',
    'blogbest_faq_a13' => 'Fréquenté et cher. De nombreux camps facturent un supplément de haute saison d\'environ le 20 décembre au 3 janvier et exigent des séjours minimums. L\'observation de la faune est bonne, mais vous payez pour les dates.',
    'blogbest_faq_q14' => 'Puis-je combiner safari et Zanzibar à n\'importe quel moment de l\'année ?',
    'blogbest_faq_a14' => 'Les saisons s\'alignent bien : juin à octobre et décembre à février sont bons pour les deux. De mars à mai, vous combineriez un safari humide avec une côte humide, c\'est pourquoi cette période est la moins chère.',
    'blogbest_related_badge' => 'Continuer la lecture',
    'blogbest_related_title' => 'Continuer à explorer la Tanzanie',
    'blogbest_related_kili' => 'Guide du Kilimandjaro',
    'blogbest_final_title' => 'Indiquez-nous vos dates',
    'blogbest_final_intro' => 'Envoyez-nous les semaines où vous pouvez voyager et nous vous dirons honnêtement ce que vous verrez alors, où devraient être les troupeaux, et si décaler de deux semaines en vaudrait la peine.',
    'blogbest_final_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'blogbest_final_contact' => 'Formulaire de contact',

    // ===== Blog article: Tipping on Safari and Kilimanjaro =====
    'blogtip_meta_title' => 'Pourboires en safari et au Kilimandjaro : combien ? (2026) | Serengeti Budget Safari',
    'blogtip_meta_description' => 'Combien donner de pourboire en Tanzanie : montants indicatifs pour les guides de safari, le personnel de camp et les cuisiniers, ainsi que les montants bien plus élevés pour l\'équipe du Kilimandjaro, avec des exemples concrets et des conseils pratiques sur les espèces.',
    'blogtip_h1' => 'Pourboires en safari et au Kilimandjaro',
    'blogtip_hero_sub' => 'Ce qui est habituel, ce que cela représente au total, et pourquoi le chiffre du Kilimandjaro surprend les gens, expliqué avant de réserver plutôt que sur la montagne.',
    'blogtip_updated' => 'Mis à jour en 2026',
    'blogtip_author' => 'Équipe Serengeti Budget Safari',
    'blogtip_date' => 'Août 2026',
    'blogtip_quick_badge' => 'Réponses rapides',
    'blogtip_quick_title' => 'Les pourboires en bref',
    'blogtip_quick_intro' => 'Montants indicatifs, de la part du groupe dans son ensemble.',
    'blogtip_qq1_q' => 'Guide de safari ?',
    'blogtip_qq1_a' => '20-25 $ par jour, de la part du groupe.',
    'blogtip_qq2_q' => 'Personnel de camp ?',
    'blogtip_qq2_a' => '10-15 $ par jour dans la boîte commune.',
    'blogtip_qq3_q' => 'Total Kilimandjaro ?',
    'blogtip_qq3_a' => '400-500 $ par grimpeur sur un itinéraire de 7 jours.',
    'blogtip_qq4_q' => 'Espèces ou carte ?',
    'blogtip_qq4_a' => 'Espèces uniquement. Pas de distributeurs dans les parcs.',
    'blogtip_qq5_q' => 'Quand ?',
    'blogtip_qq5_a' => 'À la fin, pas quotidiennement.',
    'blogtip_qq6_q' => 'État des billets ?',
    'blogtip_qq6_a' => 'Les billets US doivent être émis après 2009.',
    'blogtip_see_faq' => 'Voir toutes les FAQ',
    'blogtip_toc_title' => 'Sommaire – Pourboires en safari et au Kilimandjaro',
    'blogtip_toc_1' => 'Pourquoi c\'est important',
    'blogtip_toc_2' => 'Pourboires en safari',
    'blogtip_toc_3' => 'Pourboires au Kilimandjaro',
    'blogtip_toc_4' => 'Points pratiques',
    'blogtip_toc_5' => 'FAQ',
    'blogtip_s1_badge' => 'Contexte',
    'blogtip_s1_title' => 'Pourquoi les pourboires comptent ici',
    'blogtip_s1_p1' => 'Le pourboire est une coutume en Tanzanie et constitue une part significative de ce que gagnent guides, cuisiniers, porteurs et personnel de camp. C\'est véritablement discrétionnaire (personne ne vous le réclamera), mais c\'est attendu, et les bénéficiaires le budgétisent.',
    'blogtip_s1_p2' => 'Les chiffres ci-dessous sont les indications que nous donnons à nos propres clients. Ce ne sont pas des règles, et vous devriez les ajuster selon le service, la taille du groupe et votre propre budget sans culpabilité.',
    'blogtip_s2_badge' => 'Safari',
    'blogtip_s2_title' => 'Indications pour les pourboires en safari',
    'blogtip_t1_h1' => 'Qui',
    'blogtip_t1_h2' => 'Montant',
    'blogtip_t1_h3' => 'Base',
    'blogtip_t1_r1_a' => 'Chauffeur-guide',
    'blogtip_t1_r1_c' => 'De la part du groupe dans son ensemble, pas par personne',
    'blogtip_t1_r2_a' => 'Personnel du camp / lodge',
    'blogtip_t1_r2_c' => 'Dans la boîte à pourboires commune, de la part du groupe',
    'blogtip_t1_r3_a' => 'Cuisinier (safaris en camping)',
    'blogtip_t1_r3_c' => 'De la part du groupe',
    'blogtip_t1_r4_a' => 'Chauffeur de transfert aéroport',
    'blogtip_t1_r4_c' => 'Par transfert',
    'blogtip_t1_r5_a' => 'Restaurant',
    'blogtip_t1_r5_c' => 'Si le service n\'est pas inclus',
    'blogtip_per_day' => 'par jour',
    'blogtip_s2_example_title' => 'Un exemple concret',
    'blogtip_s2_example_intro' => 'Deux personnes, safari de quatre jours, un chauffeur-guide, hébergement en lodge :',
    'blogtip_s2_ex_li1' => 'Guide : 22 $ × 4 jours = <strong>88 $</strong>',
    'blogtip_s2_ex_li2' => 'Personnel du lodge : 12 $ × 4 jours = <strong>48 $</strong>',
    'blogtip_s2_ex_li3' => '<strong>Total pour le groupe : environ 136 $</strong>, soit 68 $ chacun',
    'blogtip_s3_badge' => 'Kilimandjaro',
    'blogtip_s3_title' => 'Pourboires au Kilimandjaro',
    'blogtip_s3_p1' => 'Une ascension implique une équipe bien plus nombreuse, typiquement trois à quatre personnes par grimpeur, et le pourboire constitue une part substantielle et attendue de leurs revenus. Les montants sont <strong>par jour, de la part de tout le groupe</strong>.',
    'blogtip_t2_h1' => 'Rôle',
    'blogtip_t2_h2' => 'Par jour, de la part du groupe',
    'blogtip_t2_r1_a' => 'Guide principal',
    'blogtip_t2_r2_a' => 'Guide assistant',
    'blogtip_t2_r3_a' => 'Cuisinier',
    'blogtip_t2_r4_a' => 'Porteur (chacun)',
    'blogtip_s3_sub_title' => 'Ce que cela représente au total',
    'blogtip_s3_p2' => 'Deux grimpeurs sur un itinéraire Machame de sept jours, avec une équipe d\'environ onze personnes (un guide principal, un assistant, un cuisinier et huit porteurs) devraient prévoir un budget d\'environ <strong>800-1 000 $ au total en pourboires</strong>, soit 400-500 $ chacun.',
    'blogtip_s3_p3' => 'C\'est une somme importante et cela surprend les gens, c\'est exactement pourquoi nous vous le disons avant de réserver plutôt que sur la montagne. Intégrez-le à votre budget dès le départ.',
    'blogtip_s3_note_t' => 'Comment cela fonctionne en pratique :',
    'blogtip_s3_note_d' => 'les pourboires sont mis en commun par le groupe et remis lors d\'une cérémonie le dernier matin, généralement avec l\'équipe chantant la chanson du Kilimandjaro. Apportez les espèces avec vous. Il n\'y a pas de distributeurs sur la montagne.',
    'blogtip_s4_badge' => 'Pratique',
    'blogtip_s4_title' => 'Points pratiques',
    'blogtip_s4_i1_t' => 'Apportez des espèces.',
    'blogtip_s4_i1_d' => 'Les dollars américains sont la norme ; les shillings tanzaniens conviennent aussi. Il n\'y a pas de distributeurs à l\'intérieur des parcs ou sur la montagne.',
    'blogtip_s4_i2_t' => 'Les billets doivent être émis après 2009.',
    'blogtip_s4_i2_d' => 'Les anciens billets américains sont refusés dans toute la Tanzanie, y compris pour les pourboires.',
    'blogtip_s4_i3_t' => 'Apportez de petites coupures.',
    'blogtip_s4_i3_d' => 'Les billets de 1 $, 5 $ et 10 $ rendent le partage des pourboires pratique.',
    'blogtip_s4_i4_t' => 'Donnez le pourboire à la fin,',
    'blogtip_s4_i4_d' => 'pas quotidiennement, sauf pour les transferts ponctuels.',
    'blogtip_s4_i5_t' => 'Remettez les pourboires en personne',
    'blogtip_s4_i5_d' => 'quand vous le pouvez, ou utilisez la boîte commune pour le personnel de camp afin que la cuisine et le ménage soient inclus.',
    'blogtip_s4_i6_t' => 'Ajustez selon le service.',
    'blogtip_s4_i6_d' => 'Ce sont des indications. Un guidage exceptionnel mérite plus ; un service médiocre mérite moins, et vous devriez expliquer pourquoi.',
    'blogtip_faq_badge' => 'FAQ',
    'blogtip_faq_title' => 'Pourboires : questions fréquentes',
    'blogtip_faq_q1' => 'Combien donner de pourboire à un guide de safari ?',
    'blogtip_faq_a1' => 'Environ 20-25 $ par jour de la part du groupe dans son ensemble, pas par personne. Pour un safari de quatre jours, cela représente environ 80-100 $ au total, quel que soit le nombre de personnes dans le véhicule.',
    'blogtip_faq_q2' => 'Le pourboire est-il obligatoire en Tanzanie ?',
    'blogtip_faq_a2' => 'Non, c\'est discrétionnaire. Mais c\'est une coutume et cela constitue une part significative de ce que gagnent guides, cuisiniers et personnel de camp, et les bénéficiaires le budgétisent.',
    'blogtip_faq_q3' => 'Combien donner de pourboire lors d\'une ascension du Kilimandjaro ?',
    'blogtip_faq_a3' => 'Prévoyez environ 800-1 000 $ au total pour deux grimpeurs sur un itinéraire de sept jours avec une équipe d\'environ onze personnes, soit 400-500 $ chacun. Par jour de la part du groupe : 20-25 $ guide principal, 15-18 $ assistant, 12-15 $ cuisinier, 8-10 $ par porteur.',
    'blogtip_faq_q4' => 'Pourquoi les pourboires du Kilimandjaro sont-ils si élevés ?',
    'blogtip_faq_a4' => 'Parce que l\'équipe est nombreuse, typiquement trois à quatre personnes par grimpeur, portant votre équipement, nourriture et eau en altitude. Les pourboires constituent une part substantielle et attendue de leurs revenus, c\'est pourquoi nous vous donnons le chiffre avant de réserver.',
    'blogtip_faq_q5' => 'Dans quelle devise dois-je donner le pourboire ?',
    'blogtip_faq_a5' => 'Les dollars américains sont la norme et les shillings tanzaniens conviennent aussi. Les billets doivent être émis après 2009. Les anciens billets américains sont refusés dans tout le pays. Apportez des coupures de 1 $, 5 $ et 10 $.',
    'blogtip_faq_q6' => 'Quand dois-je donner le pourboire ?',
    'blogtip_faq_a6' => 'À la fin du safari ou de l\'ascension plutôt que quotidiennement, sauf pour les transferts aéroport ponctuels. Sur le Kilimandjaro, il y a généralement une cérémonie de pourboire le dernier matin.',
    'blogtip_faq_q7' => 'Dois-je donner le pourboire par personne ou par groupe ?',
    'blogtip_faq_a7' => 'Par groupe. Les chiffres indicatifs supposent que tout le véhicule ou toute l\'équipe de grimpeurs contribue ensemble, c\'est pourquoi un groupe de quatre ne paie pas quatre fois ce que paie un couple.',
    'blogtip_faq_q8' => 'Est-ce que je donne un pourboire séparé au personnel de camp ?',
    'blogtip_faq_a8' => 'Oui, généralement dans une boîte à pourboires commune afin que la cuisine, le ménage et le service soient tous inclus, des personnes que vous ne rencontrerez peut-être jamais mais qui ont fait une grande partie du travail.',
    'blogtip_faq_q9' => 'Puis-je donner le pourboire par carte ?',
    'blogtip_faq_a9' => 'Non. Apportez des espèces. Il n\'y a pas de distributeurs à l\'intérieur des parcs nationaux ou sur le Kilimandjaro, et les terminaux de carte des lodges dépendent d\'une connectivité souvent indisponible.',
    'blogtip_faq_q10' => 'Et si le service était médiocre ?',
    'blogtip_faq_a10' => 'Donnez moins, et dites-nous pourquoi. Les indications de pourboire ne sont pas des obligations, et un retour honnête nous est véritablement plus utile qu\'un pourboire donné par gêne.',
    'blogtip_faq_q11' => 'Dois-je donner un pourboire individuel aux porteurs ?',
    'blogtip_faq_a11' => 'Sur le Kilimandjaro, les pourboires sont normalement mis en commun et distribués par le guide principal lors de la cérémonie, ce qui garantit un partage équitable. Si vous voulez donner quelque chose en plus à un porteur spécifique, faites-le directement et en privé.',
    'blogtip_faq_q12' => 'Dois-je donner un pourboire si les frais de service sont inclus ?',
    'blogtip_faq_a12' => 'Dans les restaurants où des frais de service apparaissent sur l\'addition, aucun pourboire supplémentaire n\'est attendu. Les pourboires de safari et d\'ascension sont séparés et ne sont pas inclus dans le prix de votre voyage.',
    'blogtip_related_badge' => 'Continuer la lecture',
    'blogtip_related_title' => 'Continuer à explorer la Tanzanie',
    'blogtip_related_contact' => 'Posez-nous une question',
    'blogtip_final_title' => 'Vous établissez le budget de votre voyage ?',
    'blogtip_final_intro' => 'Demandez-nous un devis détaillé et nous inclurons une estimation réaliste des pourboires pour votre itinéraire et la taille de votre groupe spécifiques, afin qu\'il n\'y ait aucune surprise.',
    'blogtip_final_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'blogtip_final_contact' => 'Formulaire de contact',

    // Blog article: Tanzania visa and entry
    'blogvisa_meta_title' => 'Visa et conditions d\'entrée en Tanzanie (2026) | Serengeti Budget Safari',
    'blogvisa_meta_description' => 'Comment obtenir un visa tanzanien en 2026 : e-visa contre visa à l\'arrivée, le coût de 50 $, les conditions de passeport, la règle d\'assurance obligatoire à Zanzibar, les certificats de fièvre jaune et comment éviter les sites non officiels facturant des frais.',
    'blogvisa_updated' => 'Mis à jour en 2026',
    'blogvisa_h1' => 'Visa et entrée en Tanzanie',
    'blogvisa_hero_sub' => 'Ce dont vous avez besoin, ce que cela coûte, combien de temps cela prend, et les deux conditions qui surprennent les voyageurs à l\'aéroport.',
    'blogvisa_author' => 'Équipe Serengeti Budget Safari',
    'blogvisa_date' => 'Août 2026',

    'blogvisa_quick_badge' => 'Réponses rapides',
    'blogvisa_quick_title' => 'Le visa en bref',
    'blogvisa_quick_intro' => 'Ce que la plupart des voyageurs doivent savoir.',
    'blogvisa_qq1_q' => 'Combien ça coûte ?',
    'blogvisa_qq1_a' => '50 $ pour la plupart des nationalités. 100 $ pour les citoyens américains.',
    'blogvisa_qq2_q' => 'Où faire la demande ?',
    'blogvisa_qq2_a' => 'visa.immigration.go.tz, le seul site officiel.',
    'blogvisa_qq3_q' => 'Combien de temps cela prend-il ?',
    'blogvisa_qq3_a' => 'Jusqu\'à 10 jours ouvrables. Faites la demande trois semaines à l\'avance.',
    'blogvisa_qq4_q' => 'Validité du passeport ?',
    'blogvisa_qq4_a' => 'Six mois après l\'entrée, deux pages vierges.',
    'blogvisa_qq5_q' => 'Zanzibar ?',
    'blogvisa_qq5_a' => 'Même visa, mais assurance locale obligatoire (~44 $).',
    'blogvisa_qq6_q' => 'Fièvre jaune ?',
    'blogvisa_qq6_a' => 'Seulement en cas d\'arrivée depuis ou de transit par un pays à risque.',
    'blogvisa_see_faq' => 'Voir toutes les FAQ',

    'blogvisa_toc_title' => 'Sommaire – Visa et entrée en Tanzanie',
    'blogvisa_toc_1' => 'Les deux voies',
    'blogvisa_toc_2' => 'Ce dont vous avez besoin',
    'blogvisa_toc_3' => 'Conditions pour Zanzibar',
    'blogvisa_toc_4' => 'Fièvre jaune',
    'blogvisa_toc_5' => 'FAQ',

    'blogvisa_s1_badge' => 'Les options',
    'blogvisa_s1_title' => 'Deux façons d\'obtenir un visa',
    'blogvisa_s1_p1' => 'La plupart des visiteurs ont besoin d\'un visa pour la Tanzanie. Le visa touristique standard coûte <strong>50 $US</strong> pour la plupart des nationalités, est valable <strong>90 jours</strong>, et peut être obtenu en ligne à l\'avance ou à l\'arrivée.',
    'blogvisa_s1_sub1' => 'e-Visa en ligne, recommandé',
    'blogvisa_s1_p2' => 'Faites la demande sur <strong>visa.immigration.go.tz</strong>, téléchargez vos documents et payez par carte. Une décision prend généralement <strong>jusqu\'à 10 jours ouvrables</strong>, bien que cela puisse être plus long en période chargée. Commencez au moins <strong>trois semaines</strong> avant votre départ. Vous recevez un PDF à imprimer et à présenter à l\'arrivée.',
    'blogvisa_s1_sub2' => 'Visa à l\'arrivée',
    'blogvisa_s1_p3' => 'Disponible aux aéroports du Kilimandjaro (JRO), de Dar es Salaam et de Zanzibar. Cela fonctionne, mais cela signifie faire la queue après un long vol, souvent pendant une heure ou plus aux heures d\'affluence, et payer en espèces en dollars américains. Si vous avez le temps de faire la demande en ligne, faites-le.',
    'blogvisa_s1_warn_t' => 'Méfiez-vous des sites non officiels.',
    'blogvisa_s1_warn_d' => 'Rechercher un visa tanzanien renvoie de nombreux sites qui semblent officiels et facturent 50-100 € en « frais de service » pour quelque chose que vous pouvez faire vous-même en vingt minutes. Le seul site officiel est <strong>visa.immigration.go.tz</strong> et le visa coûte 50 $.',

    'blogvisa_s2_badge' => 'Conditions',
    'blogvisa_s2_title' => 'Ce dont vous avez besoin',
    'blogvisa_s2_i1_t' => 'Passeport',
    'blogvisa_s2_i1_d' => 'valide au moins six mois à partir de votre date d\'entrée, avec deux pages vierges',
    'blogvisa_s2_i2' => 'Une <strong>photo de passeport numérique</strong>',
    'blogvisa_s2_i3' => 'Votre <strong>billet de retour ou de continuation</strong>',
    'blogvisa_s2_i4' => 'L\'adresse de votre <strong>hébergement de la première nuit</strong>, que nous fournissons avec votre confirmation de réservation',
    'blogvisa_s2_i5' => 'Une carte de crédit ou de débit pour le paiement en ligne',
    'blogvisa_s2_sub1' => 'Nationalités qui paient plus',
    'blogvisa_s2_p1' => 'Les <strong>citoyens américains</strong> reçoivent un visa à entrées multiples coûtant <strong>100 $</strong> plutôt que le visa standard à entrée unique de 50 $. Un petit nombre de nationalités nécessitent des visas de recommandation avec un délai de traitement plus long. Si vous détenez un passeport hors Europe, Amérique du Nord ou Commonwealth, vérifiez bien à l\'avance.',

    'blogvisa_s3_badge' => 'Zanzibar',
    'blogvisa_s3_title' => 'Zanzibar : même visa, assurance supplémentaire',
    'blogvisa_s3_p1' => 'Zanzibar fait partie de la Tanzanie, donc <strong>vous n\'avez pas besoin d\'un second visa</strong>. Il existe cependant une condition supplémentaire qui surprend les gens.',
    'blogvisa_s3_p2' => 'Depuis 2024, tous les visiteurs étrangers à Zanzibar doivent détenir une <strong>assurance voyage obligatoire émise par un prestataire agréé de Zanzibar</strong>, coûtant environ <strong>44 $US</strong> et achetée en ligne avant l\'arrivée. Votre police voyage européenne ou américaine existante, aussi complète soit-elle, <strong>ne satisfait pas cette exigence</strong>. C\'est un produit distinct, émis localement.',
    'blogvisa_s3_p3' => 'Cela est vérifié à l\'aéroport de Zanzibar et au terminal des ferries. Achetez-la à l\'avance ; nous pouvons l\'organiser avec votre réservation.',

    'blogvisa_s4_badge' => 'Entrée sanitaire',
    'blogvisa_s4_title' => 'Certificat de fièvre jaune',
    'blogvisa_s4_p1' => 'Un certificat de fièvre jaune est requis <strong>uniquement</strong> si vous arrivez depuis, ou avez transité plus de 12 heures par, un pays à risque de fièvre jaune.',
    'blogvisa_s4_p2' => 'Les voyageurs volant directement depuis l\'Europe, l\'Amérique du Nord ou l\'Asie <strong>n\'en ont pas besoin</strong>. Les voyageurs faisant une correspondance à Nairobi, Addis-Abeba ou d\'autres hubs africains <strong>peuvent</strong> en avoir besoin, selon la durée de l\'escale. C\'est là que les gens se font surprendre.',
    'blogvisa_s4_p3' => 'Le certificat est vérifié à l\'arrivée, et sans celui-ci là où il est requis, vous serez vacciné à l\'aéroport à vos frais. Vérifiez votre itinéraire spécifique avant de voler.',

    'blogvisa_faq_badge' => 'FAQ',
    'blogvisa_faq_title' => 'Visa tanzanien : questions fréquentes',
    'blogvisa_faq_q1' => 'Ai-je besoin d\'un visa pour la Tanzanie ?',
    'blogvisa_faq_a1' => 'La plupart des nationalités en ont besoin. Le visa touristique standard coûte 50 $US, est valable 90 jours, et peut être obtenu en ligne à l\'avance ou à l\'arrivée dans les principaux aéroports.',
    'blogvisa_faq_q2' => 'Combien coûte un visa tanzanien ?',
    'blogvisa_faq_a2' => '50 $US pour la plupart des nationalités. Les citoyens américains paient 100 $ pour un visa à entrées multiples. Méfiez-vous des sites web non officiels facturant 50-100 € de frais de service supplémentaires pour la même chose.',
    'blogvisa_faq_q3' => 'Combien de temps prend l\'e-visa ?',
    'blogvisa_faq_a3' => 'Généralement jusqu\'à 10 jours ouvrables, parfois plus en période chargée. Faites la demande au moins trois semaines avant votre voyage par sécurité.',
    'blogvisa_faq_q4' => 'Quel est le site web officiel du visa ?',
    'blogvisa_faq_a4' => 'visa.immigration.go.tz est le seul portail officiel. De nombreux sites d\'apparence convaincante facturent des frais substantiels pour un service que vous pouvez effectuer vous-même en environ vingt minutes.',
    'blogvisa_faq_q5' => 'Puis-je obtenir un visa à l\'arrivée ?',
    'blogvisa_faq_a5' => 'Oui, aux aéroports du Kilimandjaro, de Dar es Salaam et de Zanzibar, en payant en espèces en dollars américains. Cela fonctionne, mais attendez-vous à faire la queue, parfois plus d\'une heure après un long vol. Faire la demande en ligne est l\'option la plus sereine.',
    'blogvisa_faq_q6' => 'Ai-je besoin d\'un visa séparé pour Zanzibar ?',
    'blogvisa_faq_a6' => 'Non. Zanzibar fait partie de la Tanzanie et le même visa la couvre. Mais depuis 2024, vous avez besoin d\'une assurance voyage obligatoire d\'un prestataire agréé de Zanzibar, coûtant environ 44 $US, achetée avant l\'arrivée.',
    'blogvisa_faq_q7' => 'Mon assurance voyage habituelle couvre-t-elle l\'exigence de Zanzibar ?',
    'blogvisa_faq_a7' => 'Non. L\'assurance obligatoire de Zanzibar est un produit distinct, émis localement. Votre police européenne ou américaine, aussi complète soit-elle, ne satisfait pas l\'exigence et elle est vérifiée à l\'arrivée.',
    'blogvisa_faq_q8' => 'Combien de temps mon passeport doit-il être valide ?',
    'blogvisa_faq_a8' => 'Au moins six mois après votre date d\'entrée, avec deux pages vierges. Ceci est vérifié et appliqué.',
    'blogvisa_faq_q9' => 'Ai-je besoin d\'un certificat de fièvre jaune ?',
    'blogvisa_faq_a9' => 'Seulement si vous arrivez depuis ou avez transité plus de 12 heures par un pays à risque de fièvre jaune. Les vols directs depuis l\'Europe n\'en nécessitent pas, mais une longue escale à Nairobi ou Addis-Abeba peut en nécessiter un.',
    'blogvisa_faq_q10' => 'Combien de temps puis-je rester ?',
    'blogvisa_faq_a10' => 'Le visa touristique standard est valable 90 jours. Des prolongations sont possibles via les bureaux d\'immigration en Tanzanie mais sont bureaucratiques, alors planifiez correctement vos dates.',
    'blogvisa_faq_q11' => 'Puis-je travailler ou faire du bénévolat avec un visa touristique ?',
    'blogvisa_faq_a11' => 'Non. Le bénévolat nécessite un permis différent même non rémunéré, et les règles sont appliquées. Si vous prévoyez du travail bénévole, organisez le bon permis bien à l\'avance.',
    'blogvisa_faq_q12' => 'Que se passe-t-il si mon visa est refusé ou retardé ?',
    'blogvisa_faq_a12' => 'Les retards sont plus courants que les refus. Si votre date de voyage approche et qu\'aucune décision n\'est arrivée, le visa à l\'arrivée reste disponible dans les principaux aéroports comme solution de repli. Apportez des espèces en dollars américains.',
    'blogvisa_faq_q13' => 'Les enfants ont-ils besoin d\'un visa ?',
    'blogvisa_faq_a13' => 'Oui, chaque voyageur a besoin de son propre visa quel que soit son âge, et chaque enfant a besoin de son propre passeport. Les enfants voyageant avec un seul parent peuvent se voir demander une lettre de consentement de l\'autre parent.',
    'blogvisa_faq_q14' => 'Le Visa Touristique Afrique de l\'Est est-il valable pour la Tanzanie ?',
    'blogvisa_faq_a14' => 'Non. Le Visa Touristique Afrique de l\'Est couvre le Kenya, l\'Ouganda et le Rwanda mais pas la Tanzanie. Si vous combinez la Tanzanie avec le Kenya, vous avez besoin de visas séparés pour chacun.',

    'blogvisa_related_badge' => 'Continuer la lecture',
    'blogvisa_related_title' => 'Continuer à explorer la Tanzanie',
    'blogvisa_related_contact' => 'Posez-nous une question',

    'blogvisa_final_title' => 'Besoin d\'aide avec les démarches ?',
    'blogvisa_final_intro' => 'Nous fournissons l\'adresse d\'hébergement nécessaire à votre demande de visa, et pouvons organiser l\'assurance obligatoire de Zanzibar avec votre réservation. Demandez-nous simplement.',
    'blogvisa_final_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'blogvisa_final_contact' => 'Formulaire de contact',

    // Blog article: Where to stay on safari
    'blogstay_meta_title' => 'Où loger en safari en Tanzanie : lodge, camp ou camping ? | Serengeti Budget Safari',
    'blogstay_meta_description' => 'L\'hébergement de safari en Tanzanie expliqué : campings, lodges, camps tentés et camps mobiles comparés avec de vrais prix, et s\'il faut dormir à l\'intérieur ou à l\'extérieur des parcs nationaux.',
    'blogstay_h1' => 'Où loger en safari',
    'blogstay_hero_sub' => 'Camping, lodge, camp tenté ou camp mobile : ce que chacun coûte réellement, à quoi chacun ressemble vraiment, et s\'il faut dormir à l\'intérieur du parc ou à l\'extérieur.',
