    'blogstay_qq2_a' => '47-59 $ par adulte et par nuit pour dormir dans un parc.',
    'blogstay_qq3_q' => 'Option la moins chère ?',
    'blogstay_qq3_a' => 'Camping : 35,40 $ de frais de parc plus les coûts de camping.',
