    'blogstay_s1_badge' => 'Les options',
    'blogstay_s1_title' => 'Les cinq types d\'hébergement de safari',
    'blogstay_s1_p1' => 'L\'endroit où vous dormez est la plus grande variable dans le coût d\'un safari, et, sur un court voyage, dans la quantité de faune que vous voyez réellement. Les animaux sont les mêmes quel que soit votre choix ; ce qui change, c\'est le confort, et à quelle distance vous êtes de l\'action à l\'aube.',
    'blogstay_t1_h1' => 'Type',
    'blogstay_t1_h2' => 'Par personne / nuit',
    'blogstay_t1_h3' => 'Ce que c\'est',
    'blogstay_t1_h4' => 'Idéal pour',
    'blogstay_t1_r1_a' => 'Camping public',
    'blogstay_t1_r1_b' => '35,40 $ de frais de parc<br>+ coûts de camping',
    'blogstay_t1_r1_c' => 'Votre propre tente dans le parc, toilettes à la turque partagées, douches froides, cuisinier préparant les repas sur place.',
    'blogstay_t1_r1_d' => 'Voyageurs économiques, groupes, aventuriers',
    'blogstay_t1_r2_a' => 'Lodge hors du parc',
    'blogstay_t1_r2_c' => 'Chambres solides, eau chaude, restaurant, généralement une piscine. À Karatu ou en bordure de parc.',
    'blogstay_t1_r2_d' => 'Réduire les coûts',
    'blogstay_t1_r3_a' => 'Lodge dans le parc',
    'blogstay_t1_r3_c' => 'Bâtiment permanent, électricité, restaurant, souvent une piscine avec vue sur un point d\'eau.',
    'blogstay_t1_r3_d' => 'Confort et commodité',
    'blogstay_t1_r4_a' => 'Camp tenté',
    'blogstay_t1_r4_c' => 'Toile permanente avec de vrais lits et salles de bain privées. Vous entendez tout la nuit.',
    'blogstay_t1_r4_d' => 'L\'expérience de safari classique',
    'blogstay_t1_r5_a' => 'Camp mobile',
    'blogstay_t1_r5_c' => 'Se déplace deux ou trois fois par an pour suivre la migration. Petit, isolé, peu d\'autres véhicules à proximité.',
    'blogstay_t1_r5_d' => 'Voyages centrés sur la migration',

    'blogstay_s2_badge' => 'La décision clé',
    'blogstay_s2_title' => 'Intérieur ou extérieur du parc ?',
    'blogstay_s2_p1' => 'C\'est la décision qui piège la plupart des primo-planificateurs, et elle compte plus que le classement en étoiles du lodge.',
    'blogstay_s2_sub1' => 'Dormir à l\'intérieur',
    'blogstay_s2_p2' => 'Vous payez des <strong>frais de concession</strong> en plus du tarif de la chambre : 59,00 $ par adulte et par nuit au Serengeti et au Ngorongoro, 47,20 $ à Tarangire, Manyara, au parc national d\'Arusha et à Nyerere. En retour, vous êtes déjà au milieu de l\'écosystème quand la lumière est la meilleure, à l\'aube et au crépuscule, précisément quand les prédateurs sont actifs.',
    'blogstay_s2_sub2' => 'Dormir à l\'extérieur',
    'blogstay_s2_p3' => 'Vous économisez les frais de concession et généralement une grande partie du tarif de la chambre. Le coût, c\'est le temps : l\'entrée la plus proche peut être à 30 à 90 minutes, ce qui signifie partir avant l\'aube et revenir après la tombée de la nuit, et perdre les deux meilleures heures de chaque journée à conduire.',
    'blogstay_t2_h1' => 'À l\'intérieur du parc',
    'blogstay_t2_h2' => 'À l\'extérieur du parc',
    'blogstay_t2_r1_a' => 'Coût',
    'blogstay_t2_r1_b' => 'Plus élevé : chambre + 47-59 $/nuit de concession',
    'blogstay_t2_r1_c' => 'Plus bas',
    'blogstay_t2_r2_a' => 'Game drive à l\'aube',
    'blogstay_t2_r2_b' => 'Commence immédiatement',
    'blogstay_t2_r2_c' => '30-90 min de trajet d\'abord',
    'blogstay_t2_r3_a' => 'Lumière du soir',
    'blogstay_t2_r3_b' => 'Pleinement utilisée',
    'blogstay_t2_r3_c' => 'Doit partir tôt pour atteindre l\'entrée',
    'blogstay_t2_r4_a' => 'Bruits la nuit',
    'blogstay_t2_r4_b' => 'Hyène, lion, hippopotame',
    'blogstay_t2_r4_c' => 'Généralement calme',
    'blogstay_t2_r5_a' => 'Installations',
    'blogstay_t2_r5_b' => 'Variables ; souvent plus simples',
    'blogstay_t2_r5_c' => 'Souvent meilleur rapport confort-prix',
    'blogstay_tip_t' => 'Ce que nous recommandons généralement :',
    'blogstay_tip_d' => 'sur un voyage de trois nuits ou moins, logez à l\'intérieur du parc même si cela signifie une chambre plus simple. Les heures supplémentaires à l\'aube valent plus que le confort supplémentaire. Sur une semaine ou plus, mélangez : quelques nuits à l\'intérieur au moment clé, des nuits moins chères à l\'extérieur pour le reste.',

    'blogstay_s3_badge' => 'La réalité',
    'blogstay_s3_title' => 'À quoi ressemble vraiment chaque type',
    'blogstay_s3_sub1' => 'Camping',
    'blogstay_s3_p1' => 'Une tente dôme pour deux personnes sur un camping public, un bloc sanitaire partagé avec eau froide, et un cuisinier qui prépare une nourriture vraiment bonne sur un feu. Vous entendrez des hyènes la nuit, et parfois des lions. Des buffles traversent certains campings. On vous donne une lampe torche et on vous dit de ne pas quitter la tente après la tombée de la nuit, et cette instruction n\'est pas décorative.',
    'blogstay_s3_p2' => 'C\'est basique, ce n\'est pas pour tout le monde, et les personnes qui le choisissent le décrivent généralement comme la meilleure partie du voyage.',
    'blogstay_s3_sub2' => 'Camp tenté',
    'blogstay_s3_p3' => 'Le mot « tente » est trompeur. Ce sont des structures en toile permanentes sur plateformes, avec de vrais lits, des salles de bain privées et de l\'eau chaude apportée à l\'aube. Ce qui les rend spéciaux, c\'est la toile : vous entendez tout, et la nuit, un askari vous escorte jusqu\'à votre tente car les animaux se déplacent dans le camp.',
    'blogstay_s3_sub3' => 'Lodge',
    'blogstay_s3_p4' => 'Un hôtel dans un parc national. Murs solides, électricité, restaurant, généralement une piscine. Confortable et fiable, et nettement moins atmosphérique que la toile. Les meilleurs sont construits sur des escarpements ou au-dessus de points d\'eau et la vue fait le travail.',
    'blogstay_s3_sub4' => 'Camp mobile',
    'blogstay_s3_p5' => 'Petit, généralement six à douze tentes, déplacé saisonnièrement pour suivre les troupeaux. Énergie solaire, douches au seau, pas de piscine, pas de Wi-Fi. Isolé et calme, et si la migration est la raison de votre venue, cela vous en rapproche le plus.',

    'blogstay_s4_badge' => 'Choisir',
    'blogstay_s4_title' => 'Comment choisir pour votre voyage',
    'blogstay_t3_h1' => 'Si vous…',
    'blogstay_t3_h2' => 'Choisissez',
    'blogstay_t3_h3' => 'Pourquoi',
    'blogstay_t3_r1_a' => 'N\'avez que 2-3 nuits',
    'blogstay_t3_r1_b' => 'À l\'intérieur du parc',
    'blogstay_t3_r1_c' => 'L\'aube et le crépuscule valent plus que le confort',
    'blogstay_t3_r2_a' => 'Avez une semaine ou plus',
    'blogstay_t3_r2_b' => 'Mélangez intérieur et extérieur',
    'blogstay_t3_r2_c' => 'Économisez sur les nuits ordinaires, dépensez sur les clés',
    'blogstay_t3_r3_a' => 'Avez un budget serré',
    'blogstay_t3_r3_b' => 'Camping ou lodges extérieurs',
    'blogstay_t3_r3_c' => 'Même guide, mêmes animaux, coût bien plus bas',
    'blogstay_t3_r4_a' => 'Suivez la migration',
    'blogstay_t3_r4_b' => 'Camp mobile',
    'blogstay_t3_r4_c' => 'Il se déplace avec les troupeaux',
    'blogstay_t3_r5_a' => 'Voyagez avec des enfants',
    'blogstay_t3_r5_b' => 'Lodge avec piscine',
    'blogstay_t3_r5_c' => 'Un endroit pour dépenser de l\'énergie aux heures chaudes',
    'blogstay_t3_r6_a' => 'Voulez l\'expérience classique',
    'blogstay_t3_r6_b' => 'Camp tenté',
    'blogstay_t3_r6_c' => 'Toile, bruits la nuit, un askari vous raccompagnant',
    'blogstay_t3_r7_a' => 'Êtes en lune de miel',
    'blogstay_t3_r7_b' => 'Petit camp tenté',
    'blogstay_t3_r7_c' => 'Privé, calme, et bien meilleur qu\'un grand lodge',

    'blogstay_s4_sub1' => 'Questions à poser avant de réserver',
    'blogstay_ask1' => 'Les frais de concession sont-ils inclus dans le tarif indiqué, ou ajoutés ?',
    'blogstay_ask2' => 'À quelle distance de l\'entrée se trouve-t-il, et combien de temps dure le trajet vers la zone principale de faune ?',
    'blogstay_ask3' => 'Y a-t-il de l\'électricité toute la nuit, ou seulement des heures de générateur ?',
    'blogstay_ask4' => 'Les boissons sont-elles incluses, et lesquelles ?',
    'blogstay_ask5' => 'Y a-t-il un âge minimum pour les enfants ?',
    'blogstay_ask6' => 'Le Wi-Fi est-il disponible, et où ?',

    'blogstay_faq_badge' => 'FAQ',
    'blogstay_faq_title' => 'Hébergement de safari : questions fréquentes',
    'blogstay_faq_q1' => 'Dois-je loger à l\'intérieur ou à l\'extérieur du parc national ?',
    'blogstay_faq_a1' => 'Sur un voyage de trois nuits ou moins, à l\'intérieur. Vous êtes déjà dans l\'écosystème à l\'aube et au crépuscule quand les prédateurs sont actifs. Sur un voyage plus long, mélangez : nuits moins chères à l\'extérieur, nuits clés à l\'intérieur. Dormir à l\'intérieur ajoute des frais de concession de 47-59 $ par adulte et par nuit.',
    'blogstay_faq_q2' => 'Qu\'est-ce qu\'un frais de concession ?',
    'blogstay_faq_a2' => 'Un montant par personne et par nuit prélevé par l\'autorité du parc lorsque vous dormez dans un lodge ou un camp à l\'intérieur d\'un parc national. C\'est 59,00 $ par adulte au Serengeti et au Ngorongoro et 47,20 $ à Tarangire, Manyara, au parc national d\'Arusha et à Nyerere, en plus du tarif de la chambre.',
    'blogstay_faq_q3' => 'Le camping en safari est-il sûr ?',
    'blogstay_faq_a3' => 'Oui, dans les campings publics désignés, avec les précautions normales : rester dans la tente après la tombée de la nuit, garder la nourriture scellée et loin de la tente, et suivre les instructions de votre guide. Les animaux traversent bien les campings, c\'est exactement pourquoi ces règles existent.',
    'blogstay_faq_q4' => 'Quelle est la différence entre un lodge et un camp tenté ?',
    'blogstay_faq_a4' => 'Un lodge est un bâtiment permanent avec des murs solides et de l\'électricité. Un camp tenté est une toile permanente sur une plateforme avec de vrais lits et des salles de bain privées. La toile, c\'est tout l\'intérêt. Vous entendez tout la nuit, ce qui reste le souvenir marquant pour la plupart des gens.',
    'blogstay_faq_q5' => 'Qu\'est-ce qu\'un camp mobile ?',
    'blogstay_faq_a5' => 'Un petit camp, généralement six à douze tentes, qui se déplace physiquement deux ou trois fois par an pour suivre la migration. Énergie solaire, douches au seau, pas de piscine. Si la migration est la raison de votre voyage, cela vous en rapproche le plus.',
    'blogstay_faq_q6' => 'Combien coûte l\'hébergement de safari par nuit ?',
    'blogstay_faq_a6' => 'Les campings publics sont à 35,40 $ de frais de parc plus les coûts de camping ; les lodges hors des parcs 60-150 $ ; les lodges à l\'intérieur 150-400 $ ; les camps tentés 200-600 $ ; les camps mobiles 300-700 $. L\'ultra-luxe commence à partir de 700 $.',
    'blogstay_faq_q7' => 'Dois-je réserver l\'hébergement à l\'avance ?',
    'blogstay_faq_a7' => 'Oui, particulièrement pour juin à octobre et pour Ndutu en février. Les camps du nord du Serengeti et de Ndutu se réservent complets six à douze mois à l\'avance car le nombre de lits dans ces zones est limité.',
    'blogstay_faq_q8' => 'Y a-t-il de l\'électricité et du Wi-Fi ?',
    'blogstay_faq_a8' => 'Les lodges ont généralement les deux. Les camps tentés font souvent fonctionner des générateurs à des heures fixes et fournissent un éclairage solaire le reste du temps. Les camps mobiles ont généralement l\'énergie solaire et aucun Wi-Fi du tout. Demandez avant de réserver si cela compte pour vous.',
    'blogstay_faq_q9' => 'Les repas sont-ils inclus ?',
    'blogstay_faq_a9' => 'Presque toujours en safari : la pension complète est la norme, et des déjeuners à emporter sont fournis pour les game drives d\'une journée complète. Les boissons autres que l\'eau et le thé sont généralement facturées séparément sauf en haut de gamme, où elles sont souvent incluses.',
    'blogstay_faq_q10' => 'Puis-je loger dans un lodge avec des enfants ?',
    'blogstay_faq_a10' => 'La plupart des lodges acceptent les enfants de tout âge. Certains camps tentés fixent un minimum de six ou douze ans, en raison des trajets à pied entre les tentes la nuit. Indiquez-nous les âges lors de votre demande et nous filtrerons en conséquence.',
    'blogstay_faq_q11' => 'Que se passe-t-il la nuit dans un camp tenté ?',
    'blogstay_faq_a11' => 'Un askari, un garde de nuit, vous escorte entre la zone de restauration et votre tente, car les animaux se déplacent dans le camp après la tombée de la nuit. Vous entendrez hippopotame, hyène et souvent lion. La tente se ferme avec une fermeture éclair et est entièrement sécurisée.',
    'blogstay_faq_q12' => 'Une piscine vaut-elle le coût supplémentaire ?',
    'blogstay_faq_a12' => 'Avec des enfants, vraiment oui. Les heures chaudes entre les game drives sont longues et une piscine les résout. Sans enfants, cela compte beaucoup moins, et l\'argent est généralement mieux dépensé sur l\'emplacement.',
    'blogstay_faq_q13' => 'Quelle est l\'option offrant le meilleur rapport qualité-prix ?',
    'blogstay_faq_a13' => 'Un lodge juste à l\'extérieur d\'une limite de parc, à 60-150 $ par personne. Vous évitez les frais de concession et obtenez de meilleures installations pour l\'argent, au prix de 30 à 90 minutes de conduite chaque matin et soir.',

    'blogstay_related_badge' => 'Continuer la lecture',
    'blogstay_related_title' => 'Continuer à explorer la Tanzanie',
    'blogstay_final_title' => 'Pas sûr de votre choix ?',
    'blogstay_final_intro' => 'Indiquez-nous votre budget et combien de nuits vous avez. Nous suggérerons un mélange de nuits intérieures et extérieures qui vous offre le plus de faune pour votre argent.',
    'blogstay_final_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'blogstay_final_contact' => 'Formulaire de contact',

    // Blog: The Big Five in Tanzania
    'blogbig5_meta_title' => 'Les Big Five en Tanzanie : où et quand les voir | Serengeti Budget Safari',
    'blogbig5_meta_description' => 'Où voir le lion, le léopard, l\'éléphant, le buffle et le rhinocéros noir en Tanzanie, avec des chances d\'observation honnêtes pour chacun, les itinéraires offrant la meilleure chance, et pourquoi le rhinocéros est le plus difficile.',
    'blogbig5_h1' => 'Les Big Five en Tanzanie',
    'blogbig5_hero_sub' => 'Où vit chacun, quelles sont vos chances réalistes, et comment planifier un itinéraire qui vous donne une véritable chance pour les cinq.',
    'blogbig5_updated' => 'Mis à jour en 2026',
    'blogbig5_quick_badge' => 'Réponses rapides',
    'blogbig5_quick_title' => 'Les Big Five en bref',
    'blogbig5_quick_intro' => 'Des chances honnêtes, avant le détail.',
    'blogbig5_qq1_q' => 'Lesquels sont faciles ?',
    'blogbig5_qq1_a' => 'Lion, éléphant et buffle : quasi certains.',
    'blogbig5_qq2_q' => 'Léopard ?',
    'blogbig5_qq2_a' => '55-60 % dans la vallée de Seronera sur trois jours.',
    'blogbig5_qq3_q' => 'Rhinocéros noir ?',
    'blogbig5_qq3_a' => '~60 % sur une journée complète dans le cratère du Ngorongoro. Nulle part ailleurs.',
    'blogbig5_qq4_q' => 'Combien de jours ?',
    'blogbig5_qq4_a' => 'Quatre à cinq pour une chance réaliste pour les cinq.',
    'blogbig5_qq5_q' => 'Que dois-je apporter ?',
    'blogbig5_qq5_a' => 'Les jumelles comptent plus qu\'un long téléobjectif pour le rhinocéros.',
    'blogbig5_qq6_q' => 'Garanti ?',
    'blogbig5_qq6_a' => 'Jamais. Quiconque promet les cinq survend.',
    'blogbig5_toc_title' => 'Sommaire – Les Big Five en Tanzanie',
    'blogbig5_toc_1' => 'Ce qu\'ils sont',
    'blogbig5_toc_2' => 'Où voir chacun',
    'blogbig5_toc_3' => 'Meilleurs itinéraires',
    'blogbig5_toc_4' => 'Au-delà des Big Five',
    'blogbig5_toc_5' => 'FAQ',
    'blogbig5_s1_badge' => 'Les bases',
    'blogbig5_s1_title' => 'Ce que sont les Big Five, et pourquoi',
    'blogbig5_s1_p1' => 'Lion, léopard, éléphant, buffle et rhinocéros noir. Le terme n\'a rien à voir avec la taille. L\'hippopotame et la girafe sont tous deux plus grands qu\'un léopard. Il vient de la chasse au gros gibier de l\'époque coloniale, et désignait les <strong>cinq animaux considérés comme les plus dangereux à chasser à pied</strong>.',
    'blogbig5_s1_p2' => 'Le nom a survécu à son origine et constitue désormais la liste de contrôle standard d\'un safari, ce qui est légèrement absurde mais vraiment utile : à eux cinq, ils couvrent la plupart des habitats et comportements qui valent le déplacement.',
    'blogbig5_s1_p3' => 'La position honnête sur la complétion de l\'ensemble : quatre des cinq sont simples sur un safari du circuit nord bien planifié. Le <strong>rhinocéros noir est la difficulté</strong>, et tout ce qui suit porte vraiment sur comment résoudre ce problème.',
    'blogbig5_fact_lion_label' => 'Lion',
    'blogbig5_fact_lion_value' => 'Facile, Serengeti, Ngorongoro',
    'blogbig5_fact_elephant_label' => 'Éléphant',
    'blogbig5_fact_elephant_value' => 'Facile, Tarangire, Ruaha',
    'blogbig5_fact_buffalo_label' => 'Buffle',
    'blogbig5_fact_buffalo_value' => 'Facile, partout',
    'blogbig5_fact_leopard_label' => 'Léopard',
    'blogbig5_fact_leopard_value' => 'Modéré, Serengeti',
    'blogbig5_fact_rhino_label' => 'Rhinocéros noir',
    'blogbig5_fact_rhino_value' => 'Difficile, Ngorongoro uniquement',
    'blogbig5_fact_days_label' => 'Jours pour les cinq',
    'blogbig5_fact_days_value' => '4-5 de manière réaliste',
    'blogbig5_s2_badge' => 'Les cinq',
    'blogbig5_s2_title' => 'Où voir chacun',
    'blogbig5_s2_lion_h' => 'Lion',
    'blogbig5_s2_lion_p' => 'Le plus facile. Le <strong>Serengeti</strong> en abrite environ 3 000 et a l\'une des densités les plus élevées d\'Afrique ; le <strong>cratère du Ngorongoro</strong> en a environ 60 dans 260 km², ils sont donc presque inévitables. <strong>Ruaha</strong> au sud a des troupes de vingt individus ou plus qui chassent le buffle et même le jeune éléphant.',
    'blogbig5_s2_lion_odds' => 'Meilleures chances : 90-95 % sur un safari de trois jours du circuit nord.',
    'blogbig5_s2_elephant_h' => 'Éléphant',
    'blogbig5_s2_elephant_p' => '<strong>Tarangire</strong> en saison sèche est le meilleur du circuit nord : 2 500 à 3 000 individus résidents, avec des troupeaux de cinquante ou plus le long de la rivière. <strong>Ruaha</strong> en a environ 12 000, la plus grande population d\'Afrique de l\'Est.',
    'blogbig5_s2_elephant_odds' => 'Meilleures chances : 95 %+ à Tarangire de juillet à octobre.',
    'blogbig5_s2_buffalo_h' => 'Buffle',
    'blogbig5_s2_buffalo_p' => 'Commun partout, généralement en grands troupeaux. Le cratère du Ngorongoro et le Serengeti en abritent tous deux des milliers. Les vieux mâles solitaires, appelés dagga boys, sont ceux à traiter avec respect.',
    'blogbig5_s2_buffalo_odds' => 'Meilleures chances : 90 %+ partout.',
    'blogbig5_s2_leopard_h' => 'Léopard',
    'blogbig5_s2_leopard_p' => 'Le plus insaisissable, mais loin d\'être impossible. La <strong>vallée de Seronera</strong> dans le centre du Serengeti est le meilleur endroit de Tanzanie : les léopards se reposent dans les acacias le long de la rivière pendant les heures chaudes. <strong>Ndutu</strong> est également excellent.',
    'blogbig5_s2_leopard_odds' => 'Meilleures chances : 55-60 % sur trois jours dans le centre du Serengeti.',
    'blogbig5_s2_rhino_h' => 'Rhinocéros noir',
    'blogbig5_s2_rhino_p1' => 'Le plus difficile. La population tanzanienne est petite et dispersée, et il y a un seul endroit où vous avez une véritable chance : le <strong>cratère du Ngorongoro</strong>, où environ 30 vivent sous protection armée 24h/24. Une poignée survit autour des Moru Kopjes au Serengeti, mais les observations y sont rares.',
    'blogbig5_s2_rhino_p2' => 'Attendez-vous à les voir à distance à travers l\'herbe ouverte plutôt que près du véhicule. Une bonne paire de jumelles compte plus ici qu\'un long téléobjectif, et le matin tôt est le moment où ils sont le plus susceptibles d\'être à découvert.',
    'blogbig5_s2_rhino_odds' => 'Meilleures chances : environ 60 % sur une journée complète dans le cratère.',
    'blogbig5_s3_badge' => 'Planification',
    'blogbig5_s3_title' => 'Itinéraires vous offrant les meilleures chances',
    'blogbig5_t1_h1' => 'Voyage',
    'blogbig5_t1_h2' => 'Parcs',
    'blogbig5_t1_h3' => 'Résultat réaliste',
    'blogbig5_t1_r1_a' => '2 jours',
    'blogbig5_t1_r1_b' => 'Tarangire + Ngorongoro',
    'blogbig5_t1_r1_c' => 'Lion, éléphant, buffle quasi certains ; rhinocéros probable ; léopard improbable. <strong>3-4 sur 5.</strong>',
    'blogbig5_t1_r2_a' => '4 jours',
    'blogbig5_t1_r2_b' => 'Tarangire, Serengeti, Ngorongoro',
    'blogbig5_t1_r2_c' => 'Les quatre espèces faciles, plus une vraie chance pour le léopard et le rhinocéros. <strong>4-5 sur 5.</strong>',
    'blogbig5_t1_r3_a' => '6 jours',
    'blogbig5_t1_r3_b' => 'Circuit nord complet',
    'blogbig5_t1_r3_c' => 'Le temps de travailler la vallée de Seronera pour le léopard et une journée complète au cratère pour le rhinocéros. <strong>Meilleure chance pour les cinq.</strong>',
    'blogbig5_s3_warn_t' => 'Personne ne peut garantir les Big Five.',
    'blogbig5_s3_warn_d' => 'Ce sont des animaux sauvages dans des zones immenses. Ce qu\'un bon opérateur peut faire, c\'est vous placer aux bons endroits aux bons moments de la journée et être honnête sur les chances, ce que sont les chiffres ci-dessus.',
    'blogbig5_s4_badge' => 'Au-delà des cinq',
    'blogbig5_s4_title' => 'Les animaux qui valent plus que la liste',
    'blogbig5_s4_intro' => 'Demandez à un guide ce qu\'il préférerait vous montrer, et les Big Five arrivent rarement en tête de liste.',
    'blogbig5_s4_i1_t' => 'Guépard',
    'blogbig5_s4_i1_d' => 'l\'animal terrestre le plus rapide, chassant sur les plaines ouvertes du sud. Une chasse au guépard est un meilleur spectacle que la plupart des observations de lions.',
    'blogbig5_s4_i2_t' => 'Lycaon',
    'blogbig5_s4_i2_d' => 'moins de 7 000 restants dans le monde. Nyerere et Ruaha sont deux des derniers bastions, et une meute en chasse est extraordinaire.',
    'blogbig5_s4_i3_t' => 'La Grande Migration',
    'blogbig5_s4_i3_d' => '1,3 million de gnous. Aucun animal unique ne rivalise.',
    'blogbig5_s4_i4_t' => 'Girafe',
    'blogbig5_s4_i4_d' => 'l\'animal national de la Tanzanie, et toujours plus impressionnant en personne que prévu.',
    'blogbig5_s4_i5_t' => 'Hippopotame',
    'blogbig5_s4_i5_d' => 'statistiquement l\'animal le plus dangereux d\'Afrique, et bien plus divertissant que ne le suggère la liste des Big Five.',
    'blogbig5_s4_i6_t' => 'Serval, caracal, ratel, oryctérope : les observations pour lesquelles les guides s\'enthousiasment vraiment.',
    'blogbig5_s4_outro' => 'Notre conseil : utilisez les Big Five pour façonner l\'itinéraire, puis oubliez la liste une fois sur place. Les meilleures matinées de safari ne sont presque jamais celles passées à cocher des cases.',
    'blogbig5_tag_lion' => 'Lion',
    'blogbig5_tag_leopard' => 'Léopard',
    'blogbig5_tag_elephant' => 'Éléphant',
    'blogbig5_tag_buffalo' => 'Buffle',
    'blogbig5_tag_rhino' => 'Rhinocéros noir',
    'blogbig5_tag_cheetah' => 'Guépard',
    'blogbig5_tag_wilddog' => 'Lycaon',
    'blogbig5_tag_giraffe' => 'Girafe',
    'blogbig5_tag_hippo' => 'Hippopotame',
    'blogbig5_faq_title' => 'Les Big Five : questions fréquentes',
    'blogbig5_faq_q1' => 'Que sont les Big Five ?',
    'blogbig5_faq_a1' => 'Lion, léopard, éléphant, buffle et rhinocéros noir. Le terme vient de la chasse au gros gibier coloniale et désignait les cinq animaux considérés comme les plus dangereux à chasser à pied, pas les plus grands.',
    'blogbig5_faq_q2' => 'Puis-je voir les Big Five en Tanzanie ?',
    'blogbig5_faq_a2' => 'Oui, et un safari du circuit nord de quatre à cinq jours offre une chance réaliste pour les cinq. Lion, éléphant et buffle sont quasi certains, le léopard est à environ 55-60 % au Serengeti, et le rhinocéros à environ 60 % sur une journée complète dans le cratère du Ngorongoro.',
    'blogbig5_faq_q3' => 'Où est le meilleur endroit pour voir le rhinocéros noir ?',
    'blogbig5_faq_a3' => 'Le cratère du Ngorongoro, où environ 30 vivent sous protection armée 24h/24. C\'est la seule option réaliste en Tanzanie. Attendez-vous à des observations lointaines à travers l\'herbe ouverte. Apportez des jumelles.',
    'blogbig5_faq_q4' => 'Où est le meilleur endroit pour voir le léopard ?',
    'blogbig5_faq_a4' => 'La vallée de Seronera dans le centre du Serengeti. Les léopards se reposent dans les acacias le long de la rivière pendant les heures chaudes, ce qui les rend repérables si vous savez où chercher. Ndutu est également excellent.',
    'blogbig5_faq_q5' => 'Quel parc a le plus d\'éléphants ?',
    'blogbig5_faq_a5' => 'Ruaha avec environ 12 000, la plus grande population d\'Afrique de l\'Est. Sur le circuit nord, Tarangire est le meilleur : 2 500 à 3 000 individus résidents et des troupeaux de saison sèche de cinquante ou plus.',
    'blogbig5_faq_q6' => 'Combien de jours me faut-il pour voir les Big Five ?',
    'blogbig5_faq_a6' => 'Quatre à cinq de manière réaliste. Deux jours en couvrent trois ou quatre. Six jours offrent la meilleure chance, car vous avez le temps de travailler la vallée de Seronera pour le léopard et une journée complète au cratère pour le rhinocéros.',
    'blogbig5_faq_q7' => 'Puis-je voir les Big Five au Serengeti seul ?',
    'blogbig5_faq_a7' => 'Quatre d\'entre eux, facilement. Le rhinocéros noir est l\'exception : une poignée survit près des Moru Kopjes mais les observations sont rares. Pour compléter l\'ensemble, ajoutez le cratère du Ngorongoro.',
    'blogbig5_faq_q8' => 'Les Big Five sont-ils garantis ?',
    'blogbig5_faq_a8' => 'Non, et méfiez-vous de quiconque affirme le contraire. Ce sont des animaux sauvages dans des zones de milliers de kilomètres carrés. Un bon opérateur améliore vos chances en étant au bon endroit au bon moment, et est honnête sur ces chances.',
    'blogbig5_faq_q9' => 'Pourquoi le rhinocéros noir est-il si rare ?',
    'blogbig5_faq_a9' => 'Le braconnage. La population de rhinocéros noirs de Tanzanie est passée de milliers dans les années 1970 à quelques dizaines dans les années 1990. Les chiffres se rétablissent lentement sous protection intensive, mais ils restent en danger critique.',
    'blogbig5_faq_q10' => 'Quelle est la différence entre le rhinocéros noir et le rhinocéros blanc ?',
    'blogbig5_faq_a10' => 'La forme de la bouche, principalement. Le rhinocéros noir a une lèvre crochue pour brouter les arbustes ; le rhinocéros blanc a une lèvre large et plate pour paître l\'herbe. La Tanzanie a le rhinocéros noir ; le rhinocéros blanc se trouve principalement en Afrique australe.',
    'blogbig5_faq_q11' => 'Qu\'est-ce qui est mieux que les Big Five ?',
    'blogbig5_faq_a11' => 'Demandez à un guide et la plupart diront une chasse au guépard, une meute de lycaons, ou la migration elle-même. Les Big Five sont un cadre de planification utile et une piètre description de ce qui rend un safari mémorable.',
    'blogbig5_faq_q12' => 'Où puis-je voir des guépards ?',
    'blogbig5_faq_a12' => 'Les plaines ouvertes du sud du Serengeti, particulièrement autour de Ndutu pendant la saison des naissances. Les guépards ont besoin d\'espace ouvert pour courir et évitent les zones à forte densité de lions, car les lions les tuent.',
    'blogbig5_faq_q13' => 'Les buffles sont-ils vraiment dangereux ?',
    'blogbig5_faq_a13' => 'Oui. Les vieux mâles solitaires, dagga boys, sont responsables de plus d\'attaques sur des personnes que la plupart des autres animaux africains. Depuis un véhicule, vous êtes entièrement en sécurité ; à pied, c\'est pourquoi les safaris à pied ont un ranger armé.',
    'blogbig5_faq_q14' => 'Ai-je besoin d\'un long téléobjectif pour les Big Five ?',
    'blogbig5_faq_a14' => 'Un objectif de 300 mm ou plus aide considérablement, particulièrement pour le rhinocéros et le léopard. Mais les jumelles comptent plus que ne l\'imaginent la plupart des gens. Beaucoup d\'observations, surtout le rhinocéros dans le cratère, sont trop lointaines pour tout objectif réaliste.',
    'blogbig5_related_title' => 'Continuer à explorer la Tanzanie',
    'blogbig5_related_ngorongoro' => 'Ngorongoro, pour le rhinocéros',
    'blogbig5_final_title' => 'Planifiez un itinéraire Big Five',
    'blogbig5_final_intro' => 'Dites-nous combien de jours vous avez et nous construirons l\'itinéraire qui vous offre la meilleure chance réelle, et vous dirons clairement si votre emploi du temps rend les cinq improbables.',

    // ===== Blog article: What to Pack for a Safari =====
    'blogpack_meta_title' => 'Quoi emporter pour un safari en Tanzanie (Liste 2026) | Serengeti Budget Safari',
    'blogpack_meta_description' => 'Une liste de bagages pratique pour safari : vêtements, trousse médicale, matériel photo, documents et argent, plus ce qu\'il faut laisser à la maison, y compris les articles réellement illégaux en Tanzanie.',
    'blogpack_h1' => 'Quoi emporter pour un safari',
    'blogpack_hero_sub' => 'Des couches, des couleurs neutres et 15 kg dans un sac souple, plus les articles que les voyageurs oublient le plus souvent, et ceux qui sont réellement illégaux en Tanzanie.',
    'blogpack_updated' => 'Mis à jour en 2026',
    'blogpack_author' => 'Équipe Serengeti Budget Safari',
    'blogpack_date' => 'Août 2026',
    'blogpack_quick_badge' => 'Réponses rapides',
    'blogpack_quick_title' => 'Les bagages en bref',
    'blogpack_quick_intro' => 'L\'essentiel, avant la liste complète.',
    'blogpack_qq1_q' => 'La seule règle ?',
    'blogpack_qq1_a' => 'Les couches. 14 °C à l\'aube, 28 °C à midi.',
    'blogpack_qq2_q' => 'Limite de bagages ?',
    'blogpack_qq2_a' => '15 kg en sac souple sur les vols intérieurs. Strictement appliquée.',
    'blogpack_qq3_q' => 'Quelles couleurs ?',
    'blogpack_qq3_a' => 'Kaki et olive. Évitez le bleu et le noir : mouches tsé-tsé.',
    'blogpack_qq4_q' => 'Article le plus oublié ?',
    'blogpack_qq4_a' => 'Les jumelles. Plus utiles qu\'un long téléobjectif.',
    'blogpack_qq5_q' => 'Qu\'est-ce qui est interdit ?',
    'blogpack_qq5_a' => 'Les vêtements de camouflage et les sacs plastiques à usage unique.',
    'blogpack_qq6_q' => 'Combien de vêtements ?',
    'blogpack_qq6_a' => 'Pour quatre jours. La blanchisserie est disponible presque partout.',
    'blogpack_see_faq' => 'Voir toutes les FAQ',
    'blogpack_toc_title' => 'Sommaire – Quoi emporter pour un safari',
    'blogpack_toc_1' => 'La seule règle',
    'blogpack_toc_2' => 'Vêtements',
    'blogpack_toc_3' => 'Trousse médicale',
    'blogpack_toc_4' => 'Matériel photo',
    'blogpack_toc_5' => 'Documents et argent',
    'blogpack_toc_6' => 'Quoi laisser à la maison',
    'blogpack_toc_7' => 'FAQ',
    'blogpack_s1_badge' => 'Le principe',
    'blogpack_s1_title' => 'La seule règle qui compte',
    'blogpack_s1_p1' => '<strong>Habillez-vous en couches.</strong> Une journée de safari commence à environ 14 °C (5 °C sur le bord du Ngorongoro) et atteint 28 °C à midi, et vous vivrez les deux depuis un véhicule ouvert. Un seul manteau chaud est la mauvaise réponse ; une couche de base, une polaire et une coque coupe-vent est la bonne.',
    'blogpack_s1_p2' => 'La deuxième règle, si vous avez des vols intérieurs : <strong>15 kg dans un sac souple</strong>. Les avions légers en Tanzanie l\'appliquent strictement, et les valises rigides sont refusées car elles ne rentrent pas dans la soute. La plupart des lodges offrent une blanchisserie le jour même, donc préparer des bagages pour quatre jours plutôt que dix est presque toujours le bon choix.',
    'blogpack_s2_badge' => 'Vêtements',
    'blogpack_s2_title' => 'Vêtements',
    'blogpack_s2_i1_t' => 'Polaire ou veste isolante',
    'blogpack_s2_i1_d' => 'essentiel, et l\'article le plus souvent oublié',
    'blogpack_s2_i2_t' => 'Coque coupe-vent',
    'blogpack_s2_i2_d' => 'le refroidissement éolien dans un véhicule ouvert à l\'aube est significatif',
    'blogpack_s2_i3_t' => 'Chemises à manches longues',
    'blogpack_s2_i3_d' => 'protection contre le soleil et les moustiques',
    'blogpack_s2_i4' => 'T-shirts en tissu respirant',
    'blogpack_s2_i5' => 'Pantalons légers longs, plus utiles que les shorts',
    'blogpack_s2_i6' => 'Chapeau à large bord et lunettes de soleil',
    'blogpack_s2_i7_t' => 'Chaussures fermées confortables',
    'blogpack_s2_i7_d' => 'des bottes seulement si vous faites du trekking',
    'blogpack_s2_i8_t' => 'Un tour de cou ou une écharpe',
    'blogpack_s2_i8_d' => 'la poussière de saison sèche est incessante',
    'blogpack_s2_i9' => 'Maillot de bain, de nombreux lodges ont des piscines',
    'blogpack_s2_i10' => 'Une tenue habillée décontractée pour le dîner dans les meilleurs lodges',
    'blogpack_s2_sub1' => 'Les couleurs comptent plus que vous ne le pensez',
    'blogpack_s2_p1' => 'Portez du <strong>kaki, olive, beige et marron</strong>. Il y a trois choses spécifiques à éviter :',
    'blogpack_s2_n1_t' => 'Le bleu et le noir',
    'blogpack_s2_n1_d' => 'attirent les mouches tsé-tsé, présentes à Tarangire et dans la forêt de miombo des parcs du sud. Leur piqûre est douloureuse.',
    'blogpack_s2_n2_t' => 'Le blanc',
    'blogpack_s2_n2_d' => 'cesse d\'être blanc après une demi-journée sur une piste poussiéreuse.',
    'blogpack_s2_n3_t' => 'Le camouflage est illégal pour les civils en Tanzanie.',
    'blogpack_s2_n3_d' => 'Il est réservé à l\'armée, et en porter peut vraiment causer des problèmes.',
    'blogpack_s3_badge' => 'Santé',
    'blogpack_s3_title' => 'Trousse médicale et articles de toilette',
    'blogpack_s3_i1_t' => 'Comprimés antipaludiques',
    'blogpack_s3_i1_d' => 'prescrits par votre médecin',
    'blogpack_s3_i2_t' => 'Répulsif au DEET',
    'blogpack_s3_i2_d' => 'la concentration la plus forte que vous tolérez',
    'blogpack_s3_i3_t' => 'Crème solaire haute protection',
    'blogpack_s3_i3_d' => 'et baume à lèvres avec SPF ; les UV en altitude sont intenses',
    'blogpack_s3_i4' => 'Antidouleurs, antidiarrhéiques et sels de réhydratation',
    'blogpack_s3_i5' => 'Pansements, antiseptique, traitement des ampoules',
    'blogpack_s3_i6' => 'Tout médicament sur ordonnance <strong>dans votre bagage à main</strong>, avec une copie de l\'ordonnance',
    'blogpack_s3_i7' => 'Gel hydroalcoolique et lingettes, vraiment utiles lors des longs trajets',
    'blogpack_s3_i8' => 'Comprimés contre le mal des transports si vous y êtes sujet ; les pistes sont accidentées',
    'blogpack_s3_link' => 'Guide complet des vaccinations et de la santé',
    'blogpack_s4_badge' => 'Photographie',
    'blogpack_s4_title' => 'Photographie et optique',
    'blogpack_tag_binoculars' => 'Jumelles',
    'blogpack_tag_lens' => 'Objectif 300 mm+',
    'blogpack_tag_wide' => 'Objectif grand angle',
    'blogpack_tag_battery' => 'Batteries de rechange',
    'blogpack_tag_memory' => 'Cartes mémoire',
    'blogpack_tag_dustbag' => 'Sac anti-poussière',
    'blogpack_tag_beanbag' => 'Sac de riz',
    'blogpack_s4_p1' => 'Les <strong>jumelles</strong> sont l\'article le plus sous-emporté. Beaucoup d\'observations, particulièrement le rhinocéros dans le cratère, sont simplement trop lointaines pour un appareil photo. Apportez <strong>un objectif de 300 mm ou plus</strong> si vous êtes sérieux sur les photos de faune, mais <strong>aussi un objectif grand angle</strong> : baobabs, le cratère, les plaines à l\'aube. Vous regretterez de n\'avoir apporté qu\'un téléobjectif. Les camps font souvent fonctionner des générateurs pendant des heures limitées seulement, alors apportez des batteries de rechange et plus de cartes mémoire que vous ne le pensez. Un sac anti-poussière compte : la poussière de saison sèche s\'infiltre partout, et changer d\'objectif dans un véhicule en mouvement est la façon dont les capteurs sont endommagés. Un sac de riz ou un substitut est utile pour stabiliser les longs objectifs sur la trappe du toit.',
    'blogpack_s5_badge' => 'Documents',
    'blogpack_s5_title' => 'Documents et argent',
    'blogpack_s5_i1_t' => 'Passeport',
    'blogpack_s5_i1_d' => 'valide au moins six mois après l\'entrée, avec deux pages vierges',
    'blogpack_s5_i2_t' => 'Confirmation de visa imprimée',
    'blogpack_s5_i2_d' => 'et police d\'assurance voyage',
    'blogpack_s5_i3_t' => 'Certificat de fièvre jaune',
    'blogpack_s5_i3_d' => 'si vous arrivez depuis ou transitez par un pays à risque',
    'blogpack_s5_i4' => '<strong>Des dollars américains en espèces</strong> pour les pourboires et les extras, et cela compte : <strong>les billets doivent être émis après 2009</strong>. Les anciens billets sont refusés dans toute la Tanzanie.',
    'blogpack_s5_i5' => 'Petites coupures pour les pourboires (1 $, 5 $, 10 $)',
    'blogpack_s5_i6' => 'Une carte de crédit en secours, bien que la connectivité soit peu fiable',
    'blogpack_s5_i7_t' => 'Adaptateur de prise type G',
    'blogpack_s5_i7_d' => 'le standard britannique à trois broches',
    'blogpack_s5_i8' => 'Copies numériques de tout, stockées quelque part accessible hors ligne',
    'blogpack_s6_badge' => 'Ne pas apporter',
    'blogpack_s6_title' => 'Quoi laisser à la maison',
    'blogpack_s6_i1_t' => 'Valises rigides',
    'blogpack_s6_i1_d' => 'si vous avez des vols intérieurs, elles seront refusées',
    'blogpack_s6_i2_t' => 'Vêtements de camouflage',
    'blogpack_s6_i2_d' => 'illégaux pour les civils',
    'blogpack_s6_i3_t' => 'Sacs plastiques à usage unique',
    'blogpack_s6_i3_d' => 'interdits dans toute la Tanzanie depuis 2019, et confisqués à l\'aéroport',
    'blogpack_s6_i4_t' => 'Drones',
    'blogpack_s6_i4_d' => 'ils nécessitent une autorisation écrite de la TANAPA, rarement accordée',
    'blogpack_s6_i5_t' => 'Un sèche-cheveux',
    'blogpack_s6_i5_d' => 'la plupart des lodges en ont, et ils épuisent la puissance limitée du générateur',
    'blogpack_s6_i6_t' => 'Dix jours de vêtements',
    'blogpack_s6_i6_d' => 'la blanchisserie est disponible presque partout et généralement le jour même',
    'blogpack_s6_i7_t' => 'Bijoux de valeur',
    'blogpack_s6_i7_d' => 'il n\'y a nulle part où les porter et nulle part de sûr où les laisser',
    'blogpack_tip_t' => 'Le conseil le plus utile :',
    'blogpack_tip_d' => 'préparez vos bagages pour quatre jours, pas dix, et utilisez la blanchisserie. Presque tous les voyageurs que nous accueillons disent après coup avoir apporté environ deux fois plus que nécessaire.',
    'blogpack_faq_badge' => 'FAQ',
    'blogpack_faq_title' => 'Bagages de safari : questions fréquentes',
    'blogpack_faq_q1' => 'Que dois-je porter en safari ?',
    'blogpack_faq_a1' => 'Des couches en couleurs neutres : kaki, olive, beige, marron. Les matinées sont à environ 14 °C et les après-midis près de 28 °C, et vous vivrez les deux depuis un véhicule ouvert. Évitez le bleu et le noir, qui attirent les mouches tsé-tsé.',
    'blogpack_faq_q2' => 'Pourquoi devrais-je éviter les vêtements bleus et noirs ?',
    'blogpack_faq_a2' => 'Les mouches tsé-tsé sont attirées par ces couleurs, et elles sont présentes à Tarangire et dans la forêt de miombo des parcs du sud. La piqûre est douloureuse, bien qu\'il n\'y ait pas de risque de maladie du sommeil dans les principales zones touristiques.',
    'blogpack_faq_q3' => 'Puis-je porter des vêtements de camouflage ?',
    'blogpack_faq_a3' => 'Non. Le camouflage est réservé à l\'armée en Tanzanie et est illégal pour les civils. En porter peut causer de vrais problèmes aux points de contrôle, alors laissez-le à la maison.',
    'blogpack_faq_q4' => 'Quelle est la limite de bagages sur les vols intérieurs ?',
    'blogpack_faq_a4' => '15 kg dans un sac souple, strictement appliquée sur les avions légers. Les valises rigides sont refusées car elles ne rentrent pas dans la soute. Si vous avez un sac plus grand, la plupart des hôtels d\'Arusha le stockeront pendant votre vol.',
    'blogpack_faq_q5' => 'Ai-je besoin de chaussures de randonnée pour un safari ?',
    'blogpack_faq_a5' => 'Non. Des chaussures fermées confortables suffisent pour un safari en véhicule, car vous passez la plupart de votre temps dans un véhicule. De vraies bottes ne sont nécessaires que pour le Kilimandjaro, le mont Meru ou de véritables safaris à pied.',
    'blogpack_faq_q6' => 'Fait-il vraiment froid ?',
    'blogpack_faq_a6' => 'Le bord du Ngorongoro descend à environ 5 °C avant l\'aube et le Serengeti à 13-15 °C. Dans un véhicule ouvert roulant à 30 km/h, cela paraît considérablement plus froid. Une polaire et une couche coupe-vent ne sont pas optionnelles.',
    'blogpack_faq_q7' => 'Dois-je apporter des jumelles ?',
    'blogpack_faq_a7' => 'Oui, et c\'est l\'article le plus souvent oublié. Beaucoup d\'observations, le rhinocéros dans le cratère du Ngorongoro par-dessus tout, sont trop lointaines pour un objectif d\'appareil photo mais parfaites avec des jumelles.',
    'blogpack_faq_q8' => 'Quel équipement photo me faut-il ?',
    'blogpack_faq_a8' => 'Un objectif de 300 mm ou plus pour la faune, plus un grand angle pour les paysages. Apportez des batteries de rechange, car les camps ne font souvent fonctionner les générateurs qu\'à des heures fixes, et un sac anti-poussière, car la poussière de saison sèche détruit les capteurs.',
    'blogpack_faq_q9' => 'Puis-je faire la lessive en safari ?',
    'blogpack_faq_a9' => 'Oui, dans presque tous les lodges et camps, généralement le jour même. C\'est pourquoi préparer des bagages pour quatre jours plutôt que dix est presque toujours la bonne décision, particulièrement avec une limite de vol de 15 kg.',
    'blogpack_faq_q10' => 'Quel argent dois-je apporter ?',
    'blogpack_faq_a10' => 'Des dollars américains en espèces pour les pourboires et les extras, en billets émis après 2009. Les anciens billets sont refusés dans toute la Tanzanie. Apportez de petites coupures pour les pourboires. Les cartes fonctionnent dans les lodges mais la connectivité est peu fiable.',
    'blogpack_faq_q11' => 'Les sacs plastiques sont-ils vraiment interdits ?',
    'blogpack_faq_a11' => 'Oui, depuis 2019, et c\'est appliqué à l\'aéroport où ils sont confisqués à l\'arrivée. Apportez plutôt des sacs en tissu ou en filet. Les sacs zippés pour les articles de toilette sont généralement tolérés mais l\'approche la plus sûre est de tous les éviter.',
    'blogpack_faq_q12' => 'Ai-je besoin d\'un adaptateur de prise ?',
    'blogpack_faq_a12' => 'Oui, type G, le standard britannique à trois broches. La tension est de 230V. Apportez un adaptateur multiprise si vous avez plusieurs appareils, car les camps n\'ont souvent qu\'une ou deux prises par tente.',
    'blogpack_faq_q13' => 'Puis-je apporter un drone ?',
    'blogpack_faq_a13' => 'Seulement avec une autorisation écrite de la TANAPA, rarement accordée pour le tourisme. Voler sans elle risque une confiscation et une amende. Supposez que la réponse est non sauf si vous avez les documents en main.',
    'blogpack_related_badge' => 'Continuer la lecture',
    'blogpack_related_title' => 'Continuer à explorer la Tanzanie',
    'blogpack_related_trekking' => 'Les bagages pour le Kilimandjaro diffèrent',
    'blogpack_final_title' => 'Des questions sur quoi apporter ?',
    'blogpack_final_intro' => 'Envoyez-nous votre itinéraire et nous vous dirons exactement ce dont vous avez besoin pour ces parcs spécifiques et cette saison, y compris si la limite de vol de 15 kg s\'applique à vous.',
    'blogpack_final_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'blogpack_final_contact' => 'Formulaire de contact',

