    'blogvax_s0_p1' => 'Cela dit, voici ce que la plupart des voyageurs en Tanzanie doivent considérer.',
    'blogvax_s1_badge' => 'Vaccinations',
    'blogvax_s1_title' => 'Vaccinations',
    'blogvax_s1_sub1' => 'Requise dans un cas spécifique',
    'blogvax_s1_p1' => 'La <strong>fièvre jaune</strong> est la seule vaccination qui constitue une exigence légale d\'entrée, et seulement si vous arrivez depuis, ou avez transité plus de 12 heures par, un pays à risque de fièvre jaune. Les vols directs depuis l\'Europe n\'en nécessitent pas ; une longue escale à Nairobi ou Addis-Abeba peut en nécessiter un.',
