    'blogvax_t1_r1_b' => 'Transmission par la nourriture et l\'eau',
    'blogvax_t1_r1_c' => 'Tous les voyageurs',
    'blogvax_t1_r2_a' => 'Typhoïde',
    'blogvax_t1_r2_b' => 'Transmission par la nourriture et l\'eau',
    'blogvax_t1_r2_c' => 'La plupart des voyageurs',
    'blogvax_t1_r3_a' => 'Tétanos, diphtérie, polio',
    'blogvax_t1_r3_b' => 'Rappels de routine',
    'blogvax_t1_r3_c' => 'Vérifiez que vous êtes à jour',
    'blogvax_t1_r4_a' => 'Hépatite B',
    'blogvax_t1_r4_b' => 'Sang et fluides corporels',
    'blogvax_t1_r4_c' => 'Séjours plus longs',
    'blogvax_t1_r5_a' => 'Rage',
    'blogvax_t1_r5_b' => 'Morsures d\'animaux',
    'blogvax_t1_r5_c' => 'Longs séjours ruraux, ou travail avec des animaux',
    'blogvax_t1_r6_a' => 'Méningite ACWY',
    'blogvax_t1_r6_b' => 'Risque saisonnier dans certaines parties de l\'Afrique',
    'blogvax_t1_r6_c' => 'Demandez à votre médecin',
    'blogvax_s2_badge' => 'Paludisme',
    'blogvax_s2_title' => 'Paludisme : celui qui compte le plus',
    'blogvax_s2_p1' => 'Le paludisme est présent dans toute la Tanzanie, <strong>y compris Zanzibar</strong>. Le risque est plus faible en altitude (Arusha, Ngorongoro et les hautes terres du Serengeti) et plus élevé sur la côte et dans les parcs du sud de basse altitude comme Nyerere et Mikumi.',
    'blogvax_s2_sub1' => 'Prophylaxie',
    'blogvax_s2_p2' => 'Votre médecin prescrira l\'une des options standard (atovaquone/proguanil, doxycycline ou méfloquine), chacune avec des schémas posologiques et effets secondaires différents. Prenez-la exactement comme indiqué, y compris les doses <em>après</em> votre retour, ce qui est la partie que les gens oublient.',
    'blogvax_s2_sub2' => 'La prévention des piqûres compte tout autant',
    'blogvax_s2_p3' => 'Aucune prophylaxie n\'est efficace à 100 %, donc les mesures physiques ne sont pas optionnelles :',
    'blogvax_s2_b1_t' => 'Répulsif au DEET',
    'blogvax_s2_b1_d' => 'sur la peau exposée, réappliqué au crépuscule',
    'blogvax_s2_b2_t' => 'Manches et pantalons longs',
    'blogvax_s2_b2_d' => 'après le coucher du soleil, car le moustique du paludisme pique entre le crépuscule et l\'aube',
    'blogvax_s2_b3_t' => 'Dormez sous la moustiquaire',
    'blogvax_s2_b3_d' => 'fournie ; vérifiez qu\'elle n\'a pas de trous',
    'blogvax_s2_b4_t' => 'Climatisation ou ventilateur',
    'blogvax_s2_b4_d' => 'la nuit lorsque disponible',
    'blogvax_s2_warn_t' => 'Après votre retour :',
    'blogvax_s2_warn_d' => 'si vous développez de la fièvre dans les douze mois suivant votre retour, et particulièrement dans les trois premiers mois, consultez un médecin immédiatement et dites-lui que vous avez séjourné dans une zone à paludisme. Le paludisme est entièrement traitable lorsqu\'il est détecté tôt et dangereux quand il ne l\'est pas.',
    'blogvax_s3_badge' => 'Nourriture et eau',
    'blogvax_s3_title' => 'Nourriture et eau',
    'blogvax_s3_i1_t' => 'Ne buvez que de l\'eau en bouteille ou filtrée.',
    'blogvax_s3_i1_d' => 'Elle est fournie dans nos véhicules pendant chaque game drive.',
    'blogvax_s3_i2' => 'Évitez la glace si vous n\'êtes pas sûr de la source d\'eau.',
    'blogvax_s3_i3' => 'Épluchez les fruits vous-même.',
    'blogvax_s3_i4' => 'La nourriture des lodges et des camps est préparée selon des normes élevées et est sûre.',
    'blogvax_s3_i5' => 'Pour la nourriture de rue, appliquez le test habituel : fraîchement cuisinée, servie chaude, et fréquentée par les locaux.',
    'blogvax_s3_i6' => 'Brossez-vous les dents avec de l\'eau en bouteille si votre estomac est sensible.',
    'blogvax_s3_p1' => 'La diarrhée du voyageur est la plainte la plus courante, et elle est généralement bénigne. Apportez des sels de réhydratation et un antidiarrhéique, et consultez un médecin si cela dure plus de deux jours ou implique de la fièvre ou du sang.',
    'blogvax_s4_badge' => 'Altitude',
    'blogvax_s4_title' => 'Altitude',
    'blogvax_s4_p1' => 'La plupart des voyageurs en safari n\'auront pas de problèmes d\'altitude, mais deux endroits méritent d\'être connus.',
    'blogvax_s4_p2' => 'Le bord du Ngorongoro se trouve à 2 200-2 400 m. Un léger mal de tête la première nuit est courant. Buvez plus d\'eau que vous ne le pensez nécessaire et cela passe généralement.',
    'blogvax_s4_p3' => 'Le Kilimandjaro est une tout autre affaire. À 5 895 m, il y a environ la moitié de l\'oxygène disponible au niveau de la mer, et le mal des montagnes est la principale raison d\'échec des ascensions. Les symptômes, la prévention et les signes d\'alerte sont couverts en détail dans notre',
    'blogvax_s4_link' => 'guide du Kilimandjaro',
    'blogvax_s5_badge' => 'Assurance',
    'blogvax_s5_title' => 'Assurance voyage',
    'blogvax_s5_p1' => 'L\'assurance voyage est <strong>obligatoire</strong> sur nos voyages, et ce n\'est pas une formalité. À l\'intérieur des parcs, l\'hôpital le plus proche peut être à des heures par la route, et les cas graves sont transportés par avion vers Arusha, Dar es Salaam ou Nairobi. L\'évacuation médicale coûte plusieurs milliers de dollars.',
    'blogvax_s5_p2' => 'Votre police doit couvrir :',
    'blogvax_s5_i1_t' => 'Frais médicaux',
    'blogvax_s5_i1_d' => 'et traitement hospitalier',
    'blogvax_s5_i2' => 'Évacuation d\'urgence et rapatriement',
    'blogvax_s5_i3_t' => 'Trekking jusqu\'à 6 000 m',
    'blogvax_s5_i3_d' => 'si vous gravissez le Kilimandjaro ou le Meru, de nombreuses polices standard excluent l\'activité en haute altitude, et c\'est la lacune la plus courante',
    'blogvax_s5_i4' => 'Annulation de voyage, que nous recommandons également',
    'blogvax_s5_p3' => 'Pour Zanzibar, rappelez-vous l\'<strong>assurance locale obligatoire séparée (~44 $)</strong> introduite en 2024, que votre police normale ne remplace pas.',
    'blogvax_s6_badge' => 'Pratique',
    'blogvax_s6_title' => 'Autres points de santé pratiques',
    'blogvax_s6_i1_t' => 'Le soleil.',
    'blogvax_s6_i1_d' => 'Les UV à 1 500-2 400 m près de l\'équateur sont sévères même quand l\'air est frais. Crème solaire haute protection, chapeau et lunettes de soleil, chaque jour.',
    'blogvax_s6_i2_t' => 'Les mouches tsé-tsé.',
    'blogvax_s6_i2_d' => 'Présentes à Tarangire et dans le miombo du sud. La piqûre fait mal ; la maladie du sommeil n\'est pas un risque pratique dans les zones touristiques. Évitez les vêtements bleus et noirs.',
    'blogvax_s6_i3_t' => 'La poussière.',
    'blogvax_s6_i3_d' => 'La poussière de saison sèche irrite les yeux et les voies respiratoires. Apportez un tour de cou, et des gouttes oculaires si vous portez des lentilles de contact.',
    'blogvax_s6_i4_t' => 'La schistosomiase (bilharziose).',
    'blogvax_s6_i4_d' => 'Présente dans certaines eaux douces. Ne nagez pas dans les lacs ou rivières sauf si votre guide confirme que c\'est sûr.',
    'blogvax_s6_i5_t' => 'Médicaments sur ordonnance.',
    'blogvax_s6_i5_d' => 'Transportez-les en bagage à main dans leur emballage d\'origine avec une copie de l\'ordonnance.',
    'blogvax_s6_i6_t' => 'Pharmacies.',
    'blogvax_s6_i6_d' => 'Arusha et Moshi en ont de bien approvisionnées. À l\'intérieur des parcs, il n\'y en a aucune, alors apportez ce dont vous avez besoin.',
    'blogvax_faq_badge' => 'FAQ',
    'blogvax_faq_title' => 'Santé et vaccinations : questions fréquentes',
    'blogvax_faq_q1' => 'De quelles vaccinations ai-je besoin pour la Tanzanie ?',
    'blogvax_faq_a1' => 'La fièvre jaune est une exigence légale uniquement si vous arrivez depuis ou transitez par un pays à risque. L\'hépatite A et la typhoïde sont recommandées pour la plupart des voyageurs, ainsi que les rappels de routine tétanos, diphtérie et polio. Consultez une clinique de voyage six à huit semaines à l\'avance.',
    'blogvax_faq_q2' => 'Ai-je besoin d\'une vaccination contre la fièvre jaune ?',
    'blogvax_faq_a2' => 'Seulement si vous arrivez depuis, ou avez transité plus de 12 heures par, un pays à risque de fièvre jaune. Les voyageurs volant directement depuis l\'Europe n\'en ont pas besoin, mais une longue escale à Nairobi ou Addis-Abeba peut déclencher l\'exigence.',
    'blogvax_faq_q3' => 'Y a-t-il du paludisme en Tanzanie ?',
    'blogvax_faq_a3' => 'Oui, dans tout le pays y compris Zanzibar. Le risque est plus faible en altitude à Arusha et dans les hautes terres du Ngorongoro, et plus élevé sur la côte et dans les parcs du sud de basse altitude. La prophylaxie plus la prévention des piqûres est l\'approche standard.',
    'blogvax_faq_q4' => 'Quel antipaludique dois-je prendre ?',
    'blogvax_faq_a4' => 'C\'est une décision pour votre médecin. Les options courantes sont atovaquone/proguanil, doxycycline et méfloquine, chacune avec un dosage et des effets secondaires différents. Prenez le traitement complet y compris les doses après votre retour.',
    'blogvax_faq_q5' => 'Y a-t-il du paludisme à Zanzibar ?',
    'blogvax_faq_a5' => 'Oui. Zanzibar est une zone à paludisme et être sur la côte signifie que le risque est plus élevé que dans les hautes terres du nord, pas plus faible. Prenez les mêmes précautions là-bas qu\'en safari.',
    'blogvax_faq_q6' => 'Puis-je boire l\'eau du robinet ?',
    'blogvax_faq_a6' => 'Non. Buvez uniquement de l\'eau en bouteille ou filtrée, évitez la glace si vous n\'êtes pas sûr de la source, et épluchez vos propres fruits. L\'eau potable est fournie dans nos véhicules pendant chaque game drive.',
    'blogvax_faq_q7' => 'Ai-je besoin d\'une assurance voyage ?',
    'blogvax_faq_a7' => 'Oui, elle est obligatoire sur nos voyages. Elle doit couvrir les frais médicaux et l\'évacuation d\'urgence, car l\'hôpital le plus proche d\'un parc peut être à des heures et les cas graves sont évacués par avion à un coût considérable.',
    'blogvax_faq_q8' => 'Mon assurance doit-elle couvrir l\'altitude ?',
    'blogvax_faq_a8' => 'Si vous gravissez le Kilimandjaro ou le mont Meru, oui, elle doit explicitement couvrir le trekking jusqu\'à 6 000 m. De nombreuses polices de voyage standard excluent l\'activité en haute altitude, et c\'est la lacune la plus courante que nous constatons.',
    'blogvax_faq_q9' => 'Que faire si je tombe malade en safari ?',
    'blogvax_faq_a9' => 'Informez immédiatement votre guide. Les guides transportent des trousses de premiers secours et connaissent les installations les plus proches. Arusha et Moshi ont de bonnes cliniques privées ; depuis les parcs isolés, les cas graves sont évacués par avion, c\'est à cela que sert votre assurance.',
    'blogvax_faq_q10' => 'Y a-t-il du mal des montagnes en safari ?',
    'blogvax_faq_a10' => 'Rarement. Le bord du Ngorongoro à 2 200-2 400 m peut causer un léger mal de tête la première nuit, généralement résolu en buvant plus d\'eau. Le Kilimandjaro est une tout autre affaire et est couvert dans notre guide du Kilimandjaro.',
    'blogvax_faq_q11' => 'Les mouches tsé-tsé sont-elles dangereuses ?',
    'blogvax_faq_a11' => 'La piqûre est douloureuse mais la maladie du sommeil n\'est pas un risque pratique dans les principales zones touristiques. Elles sont présentes à Tarangire et dans la forêt de miombo du sud, et sont attirées par les vêtements bleu foncé et noir.',
    'blogvax_faq_q12' => 'Puis-je nager dans les lacs et rivières ?',
    'blogvax_faq_a12' => 'Pas à moins que votre guide ne confirme que c\'est sûr. La bilharziose est présente dans certaines eaux douces, et les hippopotames et crocodiles sont présents dans une grande partie de celles-ci. Les piscines des lodges sont sûres, et les sources chaudes de Maji Moto à Nyerere sont sûres pour la baignade.',
    'blogvax_faq_q13' => 'Que faire si je développe de la fièvre après mon retour ?',
    'blogvax_faq_a13' => 'Consultez un médecin immédiatement et dites-lui que vous avez séjourné dans une zone à paludisme. Le paludisme peut apparaître jusqu\'à douze mois après l\'exposition, le plus souvent dans les trois mois. Il est entièrement traitable lorsqu\'il est détecté tôt.',
    'blogvax_related_badge' => 'Continuer la lecture',
    'blogvax_related_title' => 'Continuer à explorer la Tanzanie',
    'blogvax_related_contact' => 'Posez-nous une question',
    'blogvax_final_title' => 'Des questions sur votre voyage ?',
    'blogvax_final_intro' => 'Nous ne pouvons pas donner d\'avis médical, mais nous pouvons vous dire exactement quelles zones et altitudes couvre votre itinéraire, une information utile à apporter à votre clinique de voyage.',
    'blogvax_final_whatsapp' => 'Écrivez-nous sur WhatsApp',
    'blogvax_final_contact' => 'Formulaire de contact',

    // ===== Blog article: Serengeti vs Ngorongoro =====
    'blogsvn_meta_title' => 'Serengeti contre Ngorongoro : lequel choisir ? | Serengeti Budget Safari',
    'blogsvn_meta_description' => 'Serengeti ou cratère du Ngorongoro : une comparaison honnête de la taille, du coût, de la densité de faune et de ce que chacun offre réellement, par un opérateur qui gère les deux.',
    'blogsvn_updated' => 'Mis à jour en 2026',
    'blogsvn_h1' => 'Serengeti contre Ngorongoro',
    'blogsvn_hero_sub' => 'Deux des parcs les plus connus de Tanzanie, voisins et pourtant complètement différents. Lequel convient à votre voyage ?',
    'blogsvn_quick_badge' => 'Réponses rapides',
    'blogsvn_quick_title' => 'Serengeti ou Ngorongoro, en bref',
    'blogsvn_quick_intro' => 'Les différences principales avant le détail.',
    'blogsvn_qq1_q' => 'Lequel est le plus grand ?',
    'blogsvn_qq1_a' => 'Le Serengeti, de loin : 14 763 km² contre les 260 km² du cratère.',
    'blogsvn_qq2_q' => 'Lequel a des rhinocéros ?',
    'blogsvn_qq2_a' => 'Le Ngorongoro. Le Serengeti n\'en a presque aucun.',
    'blogsvn_qq3_q' => 'Lequel a la migration ?',
    'blogsvn_qq3_a' => 'Le Serengeti, la majeure partie de l\'année. Le Ngorongoro ne la voit que brièvement.',
    'blogsvn_qq4_q' => 'Lequel prend moins de temps ?',
    'blogsvn_qq4_a' => 'Le Ngorongoro, une journée complète couvre le cratère.',
    'blogsvn_qq5_q' => 'Lequel coûte plus cher ?',
    'blogsvn_qq5_a' => 'Le Ngorongoro, une fois ajoutés les frais de descente au cratère de 295 $.',
    'blogsvn_qq6_q' => 'Puis-je faire les deux ?',
    'blogsvn_qq6_a' => 'Oui, et la plupart des itinéraires le font. Ils sont voisins.',
    'blogsvn_see_faq' => 'Voir toutes les FAQ',
    'blogsvn_toc_title' => 'Sommaire – Serengeti contre Ngorongoro',
    'blogsvn_toc_1' => 'La réponse courte',
    'blogsvn_toc_2' => 'Côte à côte',
    'blogsvn_toc_3' => 'Ce que le Serengeti fait de mieux',
    'blogsvn_toc_4' => 'Ce que le Ngorongoro fait de mieux',
    'blogsvn_toc_5' => 'Faire les deux',
    'blogsvn_toc_6' => 'FAQ',
    'blogsvn_s1_badge' => 'En bref',
    'blogsvn_s1_title' => 'La réponse courte',
    'blogsvn_s1_p1' => 'Ils ne sont pas vraiment concurrents. La plupart des itinéraires visitent <strong>les deux</strong>, car ils sont voisins et remplissent des rôles différents. Le Serengeti est vaste, varié, et abrite la Grande Migration la majeure partie de l\'année. Le cratère du Ngorongoro est petit, autonome, et offre la concentration de faune la plus dense d\'Afrique en une seule journée, y compris le rhinocéros noir qui manque largement au Serengeti.',
    'blogsvn_s1_p2' => 'Si vous ne pouvez en choisir qu\'un : choisissez le Serengeti pour l\'échelle et la migration, choisissez le Ngorongoro si votre temps est très limité et que vous voulez le maximum de faune par heure.',
    'blogsvn_cta_label' => 'Voir les deux en un voyage',
    'blogsvn_s2_badge' => 'Comparaison',
    'blogsvn_s2_title' => 'Côte à côte',
    'blogsvn_t1_h1' => 'Facteur',
    'blogsvn_t1_r1_a' => 'Taille',
    'blogsvn_crater_floor' => 'fond du cratère',
    'blogsvn_t1_r2_a' => 'Créé en',
    'blogsvn_t1_r3_a' => 'Statut',
    'blogsvn_t1_r3_b' => 'Site du patrimoine mondial de l\'UNESCO',
    'blogsvn_t1_r3_c' => 'Site du patrimoine mondial de l\'UNESCO',
    'blogsvn_t1_r4_a' => 'Frais d\'entrée (2026)',
    'blogsvn_per_vehicle' => 'par véhicule pour descendre',
    'blogsvn_t1_r5_a' => 'Idéal pour',
    'blogsvn_t1_r5_b' => 'Échelle, variété, la migration',
    'blogsvn_t1_r5_c' => 'Densité, rhinocéros, une seule journée inoubliable',
    'blogsvn_t1_r6_a' => 'Lions',
    'blogsvn_t1_r6_c' => '~60 (dans 260 km²)',
    'blogsvn_t1_r7_a' => 'Rhinocéros noir',
    'blogsvn_t1_r8_a' => 'Durée de visite typique',
    'blogsvn_t1_r8_b' => '2 à 4 nuits',
    'blogsvn_t1_r8_c' => '1 journée complète',
    'blogsvn_s2_note' => 'Chiffres de nos propres guides de parc. Voir les pages complètes du Serengeti et du Ngorongoro pour plus de détails.',
    'blogsvn_s3_badge' => 'Serengeti',
    'blogsvn_s3_title' => 'Ce que le Serengeti fait de mieux',
    'blogsvn_s3_p1' => 'Le Serengeti est le parc phare de la Tanzanie pour une bonne raison : il est immense, écologiquement varié, et abrite l\'une des densités de lions les plus élevées d\'Afrique. C\'est aussi le foyer permanent de la Grande Migration. Les troupeaux sont quelque part dans l\'écosystème chaque mois, se déplaçant en un circuit continu dicté par les précipitations.',
    'blogsvn_s3_i1' => 'Des plaines infinies et des habitats variés, de la prairie ouverte à la forêt riveraine',
    'blogsvn_s3_i2' => 'La Grande Migration, sous une forme ou une autre, presque chaque mois de l\'année',
    'blogsvn_s3_i3' => 'Parmi les meilleures observations de léopards en Tanzanie, particulièrement la vallée de Seronera',
    'blogsvn_s3_p2' => 'Ce qu\'il n\'a pas : un nombre significatif de rhinocéros noirs, et un sentiment véritablement privé en haute saison près des zones centrales populaires.',
    'blogsvn_s3_link' => 'Guide complet du parc du Serengeti',
    'blogsvn_s4_badge' => 'Ngorongoro',
    'blogsvn_s4_title' => 'Ce que le Ngorongoro fait de mieux',
    'blogsvn_s4_p1' => 'Le cratère du Ngorongoro est une caldeira volcanique effondrée, 260 km² de prairie enfermés par un bord de 600 mètres. Rien n\'en migre, donc la densité de faune est extraordinaire. Environ 25 000 grands animaux y vivent toute l\'année, visibles lors d\'un seul game drive d\'une journée.',
    'blogsvn_s4_i1' => 'L\'endroit le plus fiable de Tanzanie pour voir le rhinocéros noir, avec environ 30 vivant sous protection',
    'blogsvn_s4_i2' => 'Une densité de faune inégalée pour le temps investi, une journée, pas plusieurs',
    'blogsvn_s4_i3' => 'Des paysages spectaculaires depuis le bord, plongeant sur le fond du cratère',
    'blogsvn_s4_warn_t' => 'Le piège :',
    'blogsvn_s4_warn_d' => 'des frais séparés de 295 $ par véhicule juste pour descendre dans le cratère, facturés à chaque descente, en plus de l\'entrée standard du parc. Il chute fortement par personne à mesure que votre groupe s\'agrandit.',
    'blogsvn_s4_p2' => 'Ce qu\'il n\'a pas : l\'échelle du Serengeti, ou la migration la majeure partie de l\'année. Le Ngorongoro fait techniquement partie du même écosystème (les zones de mise bas de Ndutu se trouvent dans la zone de conservation), mais le fond du cratère lui-même ne voit les troupeaux que brièvement.',
    'blogsvn_s4_link' => 'Guide complet du parc du Ngorongoro',
    'blogsvn_s5_badge' => 'Ensemble',
    'blogsvn_s5_title' => 'Pourquoi la plupart des gens font les deux',
    'blogsvn_s5_p1' => 'Les deux parcs sont adjacents, reliés par un court trajet, c\'est pourquoi la grande majorité des itinéraires du circuit nord les combinent plutôt que d\'en choisir un. Une structure typique : deux ou trois nuits au Serengeti pour l\'espace et la variété, puis une nuit sur ou près du bord du cratère pour une descente matinale le lendemain. Le cratère se fait mieux aux premières lueurs, avant l\'arrivée des excursionnistes de Karatu.',
    'blogsvn_s5_p2' => 'Notre propre <strong>Safari Serengeti & Ngorongoro 5 jours</strong> est construit exactement autour de cette combinaison.',
    'blogsvn_faq_badge' => 'FAQ',
    'blogsvn_faq_title' => 'Serengeti contre Ngorongoro : questions fréquentes',
    'blogsvn_faq_q1' => 'Le Ngorongoro fait-il partie du Serengeti ?',
    'blogsvn_faq_a1' => 'Non, ce sont des zones protégées séparées administrées différemment (le Serengeti par la TANAPA, le Ngorongoro par la NCAA), bien qu\'elles soient écologiquement connectées et adjacentes.',
    'blogsvn_faq_q2' => 'Lequel est meilleur pour les Big Five ?',
    'blogsvn_faq_a2' => 'Ensemble, pas séparément. Le Serengeti vous donne facilement lion, léopard, éléphant et buffle ; le Ngorongoro est essentiellement le seul endroit fiable de Tanzanie pour le rhinocéros noir. Visiter les deux est comment la plupart des voyageurs complètent l\'ensemble.',
    'blogsvn_faq_q3' => 'Combien de jours me faut-il pour le Ngorongoro ?',
    'blogsvn_faq_a3' => 'Une journée complète couvre entièrement le fond du cratère. Il est assez petit pour qu\'un seul game drive, fait tôt, voie la plupart de ce qu\'il y a à voir.',
    'blogsvn_faq_q4' => 'Combien de jours me faut-il pour le Serengeti ?',
    'blogsvn_faq_a4' => 'Deux à quatre nuits minimum pour apprécier son échelle. La région où vous logez devrait correspondre au mois, car la migration traverse différentes parties du parc au fil de l\'année.',
    'blogsvn_faq_q5' => 'Pourquoi le Ngorongoro est-il tellement plus cher par jour ?',
    'blogsvn_faq_a5' => 'Les frais de descente au cratère de 295 $, facturés par véhicule à chaque descente. Répartis sur un groupe, cela devient raisonnable, environ 50 $ chacun pour six personnes, mais pour deux personnes, c\'est un coût réel en plus de l\'entrée standard du parc.',
    'blogsvn_faq_q6' => 'Puis-je en sauter un et faire seulement l\'autre ?',
    'blogsvn_faq_a6' => 'Oui. Si votre temps est très limité, le Ngorongoro seul offre une observation dense de la faune en une seule journée. Si vous avez une semaine ou plus, le Serengeti seul vous donne échelle et variété. La plupart des voyageurs avec 4 jours ou plus font les deux.',
    'blogsvn_related_parks' => 'Tous les parcs comparés',
    'blogsvn_final_title' => 'Encore indécis entre les deux ?',
    'blogsvn_final_intro' => 'Dites-nous combien de jours vous avez et ce qui compte le plus pour vous. Nous vous dirons honnêtement s\'il faut faire l\'un, l\'autre, ou les deux.',

