    // ===== Privacy Policy =====
    'privacy_meta_title' => 'Politique de confidentialité | Serengeti Budget Safari',
    'privacy_meta_description' => 'Comment Serengeti Budget Safari collecte, utilise et protège vos données personnelles, et les droits dont vous disposez en vertu du RGPD.',
    'privacy_h1' => 'Politique de confidentialité',
    'privacy_intro' => 'Cet avis explique quelles données personnelles <strong>Serengeti Budget Safari</strong> collecte lorsque vous visitez ce site web ou nous demandez un devis, pourquoi nous les traitons, et quels droits vous avez. Nous traitons les données personnelles conformément au Règlement UE 2016/679 (RGPD).',
    'privacy_h2_1' => '1. Qui nous sommes',
    'privacy_h2_2' => '2. Ce que nous collectons',
    'privacy_h3_1' => 'Informations que vous nous donnez',
    'privacy_you_i1' => 'votre nom ;',
    'privacy_you_i2' => 'adresse e-mail et numéro de téléphone ;',
    'privacy_you_i3' => 'pays de résidence ;',
    'privacy_you_i4' => 'dates de voyage, nombre de voyageurs et préférences dans votre demande ;',
    'privacy_you_i5' => 'toute autre chose que vous choisissez de nous dire (régimes alimentaires, besoins d\'accessibilité, occasions spéciales).',
    'privacy_h3_2' => 'Informations collectées automatiquement',
    'privacy_auto_i1' => 'adresse IP, type de navigateur et d\'appareil ;',
    'privacy_auto_i2' => 'pages visitées et date et heure de votre visite ;',
    'privacy_auto_i3' => 'le site depuis lequel vous êtes arrivé.',
    'privacy_h2_3' => '3. Pourquoi nous les traitons',
    'privacy_why_i1' => '<strong>Pour répondre à votre demande</strong> et préparer un devis. Base légale : mesures prises à votre demande avant la conclusion d\'un contrat (art. 6(1)(b) RGPD).',
    'privacy_why_i2' => '<strong>Pour organiser et gérer le voyage</strong> que vous avez réservé. Base légale : exécution d\'un contrat (art. 6(1)(b) RGPD).',
    'privacy_why_i3' => '<strong>Pour respecter les obligations fiscales et comptables</strong>. Base légale : obligation légale (art. 6(1)(c) RGPD).',
    'privacy_why_i4' => '<strong>Pour améliorer ce site web</strong> grâce à des statistiques agrégées. Base légale : intérêt légitime (art. 6(1)(f) RGPD).',
    'privacy_why_note' => 'Nous n\'envoyons pas de messages marketing sans votre consentement explicite, et nous ne vendons jamais vos données.',
    'privacy_h2_4' => '4. Avec qui nous les partageons',
    'privacy_share_intro' => 'Nous ne partageons vos coordonnées qu\'avec ceux qui en ont besoin pour réaliser votre voyage :',
    'privacy_share_i1' => 'lodges, camps tentés et hôtels où vous séjournez ;',
    'privacy_share_i2' => 'compagnies aériennes exploitant les vols intérieurs, et sociétés de transfert ;',
    'privacy_share_i3' => 'autorités des parcs nationaux, lorsque les permis d\'entrée nécessitent les coordonnées des visiteurs ;',
    'privacy_share_i4' => 'fournisseurs techniques pour ce site web (hébergement, e-mail) ;',
    'privacy_share_i5' => 'autorités publiques, lorsque la loi l\'exige.',
    'privacy_share_note' => 'Comme nous opérons depuis la Tanzanie, vos données sont également traitées en dehors de l\'Espace économique européen. Ce transfert est effectué en vertu de l\'art. 49(1)(b) du RGPD, car il est nécessaire à l\'exécution du contrat de voyage que vous avez demandé.',
    'privacy_h2_5' => '5. Combien de temps nous les conservons',
    'privacy_keep_i1' => '<strong>Demandes n\'ayant pas abouti à une réservation :</strong> 24 mois à compter du dernier contact.',
    'privacy_keep_i2' => '<strong>Voyages confirmés :</strong> 10 ans, à des fins comptables et fiscales.',
    'privacy_keep_i3' => '<strong>Statistiques du site web :</strong> jusqu\'à 26 mois sous forme agrégée.',
    'privacy_h2_6' => '6. Cookies',
    'privacy_cookies_p1' => 'Ce site n\'utilise que le stockage technique nécessaire au fonctionnement des pages et pour se souvenir de la langue que vous avez choisie. Nous chargeons également des polices et icônes depuis des services externes (Google Fonts, Font Awesome via CDN), qui peuvent enregistrer votre adresse IP. Vous pouvez bloquer ou supprimer les cookies dans les paramètres de votre navigateur ; certaines fonctionnalités pourraient alors fonctionner moins bien. Voir notre',
    'privacy_cookies_link' => 'politique de cookies',
    'privacy_h2_7' => '7. Vos droits',
    'privacy_rights_intro' => 'En vertu des articles 15 à 22 du RGPD, vous avez le droit de :',
    'privacy_rights_i1' => 'accéder à vos données et en recevoir une copie ;',
    'privacy_rights_i2' => 'les faire corriger ou effacer ;',
    'privacy_rights_i3' => 'restreindre ou vous opposer au traitement ;',
    'privacy_rights_i4' => 'recevoir vos données dans un format portable ;',
    'privacy_rights_i5' => 'retirer votre consentement à tout moment ;',
    'privacy_rights_i6' => 'déposer une plainte auprès de votre autorité nationale de protection des données.',
    'privacy_rights_note' => 'Pour exercer l\'un de ces droits, envoyez un e-mail à <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a>. Nous répondons sous 30 jours.',
    'privacy_h2_8' => '8. Sécurité',
    'privacy_security_p1' => 'Nous appliquons des mesures techniques et organisationnelles raisonnables pour protéger vos données contre l\'accès non autorisé, la perte ou la divulgation. Aucune transmission internet n\'est totalement sûre : veuillez ne jamais nous envoyer de numéros de carte complets par e-mail ou WhatsApp.',
    'privacy_h2_9' => '9. Enfants',
    'privacy_children_p1' => 'Ce site web ne s\'adresse pas aux enfants de moins de 16 ans. Les informations des mineurs voyageant avec nous sont fournies par leurs parents ou tuteurs légaux.',
    'privacy_h2_10' => '10. Modifications',
    'privacy_changes_p1' => 'Nous pouvons mettre à jour cet avis ; la date en haut de la page indique toujours la version actuelle.',

    // ===== Terms & Conditions =====
    'terms_meta_title' => 'Conditions générales | Serengeti Budget Safari',
    'terms_meta_description' => 'Conditions de réservation pour Serengeti Budget Safari : acomptes, paiements, frais d\'annulation, exigences d\'assurance, responsabilité et réclamations.',
    'terms_h1' => 'Conditions générales',
    'terms_intro' => 'Ces conditions régissent les réservations de safaris, treks, excursions et séjours à Zanzibar organisés par <strong>Serengeti Budget Safari</strong>, basé à Arusha, Tanzanie. En confirmant une réservation, vous confirmez les avoir lues et acceptées.',
    'terms_note_title' => 'Important :',
    'terms_note_body' => 'les montants, pourcentages et délais ci-dessous sont nos conditions standard. Les conditions contraignantes pour votre voyage sont celles indiquées dans le devis écrit que nous vous envoyons. En cas de différence, le devis prévaut.',
    'terms_h2_1' => '1. Réservation et confirmation',
    'terms_booking_i1' => 'Demander un devis est gratuit et ne vous engage à rien.',
    'terms_booking_i2' => 'Une réservation est confirmée dès réception de notre confirmation écrite et de l\'acompte.',
    'terms_booking_i3' => 'Les places en lodge et en camp ne sont pas réservées avant confirmation. En haute saison, la disponibilité peut changer en quelques heures.',
    'terms_booking_i4' => 'Veuillez nous donner les noms exactement comme ils apparaissent sur votre passeport ; des corrections ultérieures peuvent entraîner des frais de la part des lodges et des compagnies aériennes.',
    'terms_h2_2' => '2. Prix',
    'terms_prices_i1' => 'Les prix sont indiqués en euros (EUR) ou dollars américains (USD) tel qu\'indiqué dans votre devis, par personne sauf indication contraire.',
    'terms_prices_i2' => 'Sauf indication contraire de votre devis, le prix couvre : un véhicule 4x4 avec chauffeur-guide, le carburant, les frais d\'entrée des parcs de votre itinéraire, l\'hébergement et les repas comme décrit, et l\'eau potable pendant les game drives.',
    'terms_prices_i3' => 'Le prix exclut : les vols internationaux, le visa, l\'assurance voyage, les boissons, les pourboires, les dépenses personnelles, les excursions optionnelles, et les vols intérieurs sauf mention expresse.',
    'terms_prices_i4' => 'Les frais d\'entrée des parcs sont fixés par les autorités tanzaniennes (TANAPA, NCAA). S\'ils augmentent après confirmation de votre réservation, la différence est payable par le voyageur.',
    'terms_h2_3' => '3. Paiement',
    'terms_pay_deposit_t' => 'Acompte :',
    'terms_pay_deposit_d' => '30 % du total à la confirmation.',
    'terms_pay_balance_t' => 'Solde :',
    'terms_pay_balance_d' => 'dû 30 jours avant le départ. Pour les réservations effectuées dans les 30 jours précédant le départ, le montant total est payable à la confirmation.',
    'terms_pay_i3' => 'Les frais bancaires et de transfert sont à la charge du voyageur.',
    'terms_pay_i4' => 'Si le solde n\'est pas payé à la date d\'échéance, nous pouvons considérer la réservation comme annulée et appliquer les frais de la clause 4.',
    'terms_h2_4' => '4. Annulation par vous',
    'terms_cancel_intro' => 'Les annulations doivent être faites par écrit. Les frais suivants s\'appliquent, calculés sur le prix total du voyage :',
    'terms_cancel_th1' => 'Préavis avant le départ',
    'terms_cancel_th2' => 'Frais',
    'terms_cancel_r1_a' => 'Plus de 60 jours',
    'terms_cancel_r1_b' => 'Acompte retenu (30 %)',
    'terms_cancel_r2_a' => '60 à 30 jours',
    'terms_cancel_r2_b' => '50 % du total',
    'terms_cancel_r3_a' => '29 à 15 jours',
    'terms_cancel_r3_b' => '75 % du total',
    'terms_cancel_r4_a' => 'Moins de 15 jours, ou non-présentation',
    'terms_cancel_r4_b' => '100 % du total',
    'terms_cancel_note' => 'Certains lodges, camps mobiles et vols intérieurs imposent leurs propres conditions plus strictes ; le cas échéant, nous vous en informons dans le devis.',
    'terms_h2_5' => '5. Modifications',
    'terms_changes_i1' => 'Les modifications demandées plus de 30 jours avant le départ sont gratuites, à l\'exception de toute différence dans le coût des services et des frais des fournisseurs.',
    'terms_changes_i2' => 'Les modifications demandées dans les 30 jours précédant le départ sont traitées comme une annulation et une nouvelle réservation.',
    'terms_changes_i3' => 'Nous pouvons modifier un itinéraire pour des raisons de sécurité, de météo, d\'état des routes, de fermetures de parcs ou de disponibilité d\'hébergement, en fournissant des services de standing équivalent.',
    'terms_h2_6' => '6. Assurance voyage',
    'terms_insurance_p1' => '<strong>L\'assurance voyage est obligatoire</strong> sur tous nos voyages. Elle doit couvrir les frais médicaux, l\'évacuation d\'urgence et le rapatriement. Pour le Kilimandjaro et le mont Meru, votre police doit explicitement couvrir le trekking en haute altitude jusqu\'à 6 000 m. Nous recommandons également une couverture d\'annulation. Nous ne sommes pas responsables des coûts résultant d\'une assurance inadéquate.',
    'terms_h2_7' => '7. Documents, santé et sécurité',
    'terms_docs_i1' => 'Votre passeport doit être valide au moins six mois à partir de la date d\'entrée et avoir deux pages vierges.',
    'terms_docs_i2' => 'L\'obtention d\'un visa tanzanien est la responsabilité du voyageur.',
    'terms_docs_i3' => 'Un certificat de fièvre jaune est requis si vous arrivez depuis, ou avez transité par, un pays à risque.',
    'terms_docs_i4' => 'Veuillez nous informer au moment de la réservation de toute condition médicale, allergie ou médicament pertinent pour le voyage.',
    'terms_docs_i5' => 'Lors des game drives, vous devez suivre les instructions de votre guide : ne quittez pas le véhicule sans permission et n\'approchez pas les animaux.',
    'terms_h2_8' => '8. Responsabilité',
    'terms_liability_i1' => 'Nous organisons votre voyage avec un soin professionnel et sommes responsables de la bonne exécution des services que nous fournissons directement.',
    'terms_liability_i2' => 'Nous ne sommes pas responsables des retards, annulations ou pertes causés par des événements échappant à notre contrôle raisonnable : météo, catastrophes naturelles, épidémies, troubles civils, grèves, décisions des autorités ou pannes d\'infrastructure publique.',
    'terms_liability_i3' => 'Nous ne sommes pas responsables des services que vous réservez indépendamment auprès de tiers.',
    'terms_liability_i4' => 'Les observations de faune se produisent dans la nature et ne peuvent être garanties.',
    'terms_liability_i5' => 'Les bagages et effets personnels restent sous la responsabilité du voyageur.',
    'terms_h2_9' => '9. Conduite',
    'terms_conduct_p1' => 'Nous nous réservons le droit d\'exclure d\'un voyage, sans remboursement, toute personne mettant en danger sa propre sécurité ou celle d\'autrui, endommageant l\'environnement ou la faune, ou se comportant avec un manque de respect grave envers les communautés locales ou notre personnel.',
    'terms_h2_10' => '10. Réclamations',
    'terms_complaints_p1' => 'Si quelque chose ne va pas pendant votre voyage, informez immédiatement votre guide ou notre bureau. La plupart des problèmes peuvent être résolus sur place. Les réclamations écrites doivent parvenir à <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a> dans les 30 jours suivant la fin de votre voyage.',
    'terms_h2_11' => '11. Droit applicable',
    'terms_law_p1' => 'Ce contrat est régi par le droit de la République-Unie de Tanzanie. Avant d\'engager une action en justice, les deux parties conviennent de tenter un règlement amiable.',
    'terms_contact_title' => 'Des questions avant de réserver ?',
    'terms_contact_body' => 'Envoyez un e-mail à <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a> ou écrivez-nous sur <a href="https://wa.me/255697612865" rel="noopener">WhatsApp +255 697 612 865</a>. Nous répondons chaque jour entre 07h00 et 21h00, heure tanzanienne.',

