    'cookies_intro' => 'Les cookies sont de petits fichiers texte qu\'un site web stocke sur votre appareil. Cette page explique ce que nous utilisons et comment vous pouvez le contrôler.',
    'cookies_h2_1' => '1. Stockage technique',
    'cookies_technical_intro' => 'Nécessaire au fonctionnement du site ; aucun consentement requis :',
    'cookies_th_name' => 'Nom',
    'cookies_th_purpose' => 'Objet',
    'cookies_th_duration' => 'Durée',
    'cookies_row_lang_purpose' => 'Se souvient de la langue que vous avez choisie afin de ne pas vous la redemander à chaque visite',
    'cookies_row_lang_duration' => 'Jusqu\'à ce que vous l\'effaciez',
    'cookies_technical_note' => 'Cette valeur est conservée dans le <em>stockage local</em> de votre navigateur. Elle reste sur votre appareil et n\'est jamais envoyée à nos serveurs.',
    'cookies_h2_2' => '2. Services tiers',
    'cookies_third_party_intro' => 'Pour afficher les pages, nous chargeons des ressources de fournisseurs externes, qui peuvent enregistrer votre adresse IP et les détails de votre navigateur :',
    'cookies_gfonts_purpose' => 'polices de caractères',
