    'cookies_google_notice' => 'avis de confidentialité de Google',
    'cookies_cloudflare_notice' => 'avis de confidentialité de Cloudflare',
    'cookies_h2_3' => '3. Contenu intégré',
    'cookies_embed_p1' => 'Certaines pages peuvent intégrer des vidéos ou des cartes hébergées ailleurs (par exemple YouTube ou Google Maps). Le cas échéant, ce fournisseur peut définir ses propres cookies dès que vous lancez la lecture ou interagissez avec la carte.',
    'cookies_h2_4' => '4. Ce que nous n\'utilisons pas',
    'cookies_notuse_p1' => 'Nous n\'utilisons pas de cookies publicitaires ou de profilage, et nous ne vendons pas de données de navigation à des annonceurs.',
    'cookies_h2_5' => '5. Gérer les cookies',
    'cookies_manage_intro' => 'Vous pouvez bloquer ou supprimer les cookies dans les paramètres de votre navigateur :',
