    'cookies_manage_edge' => 'Paramètres → Cookies et autorisations de site',
    'cookies_manage_note' => 'Si vous désactivez le stockage technique, le site fonctionne toujours, mais vous devrez choisir votre langue à chaque visite.',
    'cookies_h2_6' => '6. Contact',
    'cookies_contact_p1' => 'Pour toute question, envoyez un e-mail à <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a>.',

