    'bsg_meta_title' => 'Le guide ultime du safari économique en Tanzanie : parcs, prix et forfaits de confiance',
    'bsg_meta_description' => 'Le guide de safari économique en Tanzanie le plus complet. Vrais frais de parc, prix d\'hébergement, secrets locaux, exemples d\'itinéraires et forfaits de confiance d\'un opérateur local d\'Arusha.',

