    'bsg_intro_title' => 'Pourquoi la Tanzanie pour votre safari économique ?',
    'bsg_intro_p1' => 'La Tanzanie n\'est pas juste une autre destination safari. C\'est <strong>la</strong> destination safari. Avec plus de 20 parcs nationaux, la plus grande concentration de faune sur la planète, et la légendaire Grande Migration, la Tanzanie offre une expérience de safari inégalée nulle part ailleurs dans le monde.',
    'bsg_intro_p2' => 'Mais voici la vérité que la plupart des voyagistes ne vous diront pas : <strong>la Tanzanie peut se faire avec un budget limité.</strong> Pas un budget « routard », mais un safari confortable, authentique et inoubliable qui ne ruinera pas votre budget. Le secret est de comprendre le système : frais de parc, niveaux d\'hébergement, tarification saisonnière, dynamique de groupe et connaissance locale.',
    'bsg_intro_p3' => 'Ce guide provient de notre propre équipe de guides basés à Arusha. C\'est le guide que nous aurions aimé que chaque voyageur lise avant de demander un devis, car une fois que vous comprenez où va l\'argent, vous saurez exactement à quoi ressemble un prix équitable.',
    'bsg_intro_box' => '<strong>Ce qui rend ce guide différent :</strong> Chaque chiffre ici vient d\'une expérience réelle : nos propres véhicules, nos propres itinéraires, nos propres prix négociés dans chaque camping et lodge. Ce n\'est pas de la théorie, c\'est la connaissance pratique d\'un opérateur local qui vit et travaille en Tanzanie.',

    'bsg_quick_title' => 'Réponse rapide : combien coûte un safari économique en Tanzanie ?',
    'bsg_quick_p1' => 'Un safari économique en Tanzanie coûte généralement <strong>150 à 300 € par personne et par jour</strong>. La fourchette dépend de quelques facteurs :',
    'bsg_quick_li1' => '<strong>Taille du groupe :</strong> plus de personnes signifie un coût par personne plus bas : un groupe de 6 peut payer aussi peu que 150 € par personne et par jour.',
    'bsg_quick_li2' => '<strong>Saison :</strong> la saison verte (mars-mai) offre les tarifs les plus bas ; la saison sèche (juin-octobre) est plus chère.',
    'bsg_quick_li3' => '<strong>Type d\'hébergement :</strong> le camping est l\'option la plus abordable ; les camps tentés et les lodges augmentent le coût.',
    'bsg_quick_li4' => '<strong>Parcs visités :</strong> le Serengeti et le Ngorongoro ont des frais plus élevés que Tarangire ou le lac Manyara.',
    'bsg_quick_li5' => '<strong>Type de véhicule :</strong> le partage en groupe est moins cher qu\'un véhicule privé.',
    'bsg_quick_p2' => 'Pour un <strong>safari de 3 jours</strong>, prévoyez environ <strong>550-750 €</strong>. Pour un <strong>safari de 5 jours</strong>, attendez-vous à <strong>1 000-1 500 €</strong>. Pour un <strong>safari de 7 jours</strong>, prévoyez <strong>1 300-2 000 €</strong>.',
    'bsg_quick_pro' => '<strong>Conseil de pro :</strong> le facteur le plus important pour réduire les coûts est la <strong>taille du groupe</strong>. Voyagez à 4-6 personnes et vous économiserez 20-40 % par rapport à un safari privé. Le deuxième facteur le plus important est la <strong>saison</strong> : la saison verte offre le meilleur rapport qualité-prix.',
    'bsg_quick_see_breakdown' => 'Voir la répartition complète des coûts',

    'bsg_read_more' => 'Lire la suite',
    'bsg_read_less' => 'Lire moins',
    'bsg_toc_jump' => 'Aller à la section',

    'bsg_packages_title' => 'Forfaits de safari de confiance : réservez en toute confiance',
    'bsg_packages_p1' => 'Nous comprenons que réserver un safari est une décision importante. C\'est pourquoi chaque forfait ci-dessous est construit avec une transparence totale, aucun frais caché, et un engagement envers la qualité. Chaque forfait inclut :',
