    'bsg_cost_title' => 'Répartition détaillée des coûts : où va chaque euro',
    'bsg_cost_p1' => 'L\'une des plus grandes craintes des voyageurs concerne les frais cachés. Nous croyons en une transparence totale. Voici exactement où va l\'argent de votre safari.',
    'bsg_cost_th1' => 'Composant',
    'bsg_cost_th2' => 'Ce qu\'il couvre',
    'bsg_cost_th3' => '% typique du total',
    'bsg_cost_row1_label' => 'Frais de parc et taxes de conservation',
    'bsg_cost_row1_desc' => 'Entrée dans les parcs nationaux, frais de cratère, rangers anti-braconnage, conservation des habitats',
    'bsg_cost_row1_pct' => '30-40 %',
    'bsg_cost_row2_label' => 'Transport et location de véhicule',
    'bsg_cost_row2_desc' => 'Véhicule de safari 4x4, carburant, salaire du chauffeur-guide, entretien, assurance',
    'bsg_cost_row2_pct' => '25-35 %',
    'bsg_cost_row3_label' => 'Hébergement',
    'bsg_cost_row3_desc' => 'Frais de camping, camp tenté, ou lodge, varie selon le type',
    'bsg_cost_row3_pct' => '15-20 %',
    'bsg_cost_row4_label' => 'Repas',
    'bsg_cost_row4_desc' => 'Pension complète : petit-déjeuner, déjeuner (souvent pique-nique en brousse), dîner',
    'bsg_cost_row4_pct' => '10-15 %',
    'bsg_cost_row5_label' => 'Guide et personnel',
    'bsg_cost_row5_desc' => 'L\'expertise de votre guide, ses compétences de repérage, sa formation à la sécurité',
    'bsg_cost_row5_pct' => '8-12 %',
    'bsg_cost_insider' => '<strong>Secret d\'initié :</strong> les frais de parc représentent 30-40 % du coût total. C\'est pourquoi choisir les bons parcs compte. Un safari de 5 jours avec le Serengeti et le Ngorongoro aura environ 300-400 € de frais de parc seuls ; un safari de 5 jours avec Tarangire, Manyara et le parc national d\'Arusha aura environ 150-200 €.',

    'bsg_parks_title' => 'Analyse approfondie des parcs : frais et meilleure période',
    'bsg_parks_p1' => 'Chaque parc a ses propres frais d\'entrée, son caractère et sa saison idéale. Voici une répartition honnête des parcs où nous organisons le plus souvent des safaris.',
    'bsg_park1_name' => 'Serengeti',
    'bsg_park1_tier' => 'élevé',
    'bsg_park1_fee' => 'Entrée : 82 $/jour',
    'bsg_park1_desc' => 'Le parc le plus célèbre du monde. Plaines infinies, la Grande Migration, et la plus forte densité de prédateurs sur Terre.',
    'bsg_park1_best' => 'Meilleure période : déc-juil pour la migration, août-oct pour les traversées de rivière. Recommandé : 2-4 nuits.',
    'bsg_park2_name' => 'Cratère du Ngorongoro',
    'bsg_park2_tier' => 'moyen',
    'bsg_park2_fee' => 'Entrée : 71 $/jour + 295 $ cratère',
    'bsg_park2_desc' => 'Un amphithéâtre naturel avec la plus forte densité de faune d\'Afrique : les Big Five présents, y compris le rhinocéros noir.',
    'bsg_park2_best' => 'Meilleure période : toute l\'année. Recommandé : 1-2 nuits.',
    'bsg_park3_name' => 'Tarangire',
    'bsg_park3_tier' => 'bas',
    'bsg_park3_fee' => 'Entrée : 53 $/jour',
    'bsg_park3_desc' => 'Abrite les plus grands troupeaux d\'éléphants de Tanzanie et des baobabs emblématiques, avec moins de monde que le Serengeti.',
    'bsg_park3_best' => 'Meilleure période : juin-oct (saison sèche). Recommandé : 1-2 nuits.',
    'bsg_park4_name' => 'Lac Manyara',
    'bsg_park4_tier' => 'bas',
    'bsg_park4_fee' => 'Entrée : 53 $/jour',
    'bsg_park4_desc' => 'Célèbre pour ses lions grimpeurs d\'arbres, ses flamants roses sur le lac de soude, et sa forêt luxuriante d\'eaux souterraines.',
    'bsg_park4_best' => 'Meilleure période : toute l\'année. Recommandé : 1 nuit.',
    'bsg_park5_name' => 'Parc national d\'Arusha',
    'bsg_park5_tier' => 'bas',
    'bsg_park5_fee' => 'Entrée : 53 $/jour',
    'bsg_park5_desc' => 'Safaris à pied, vues sur le mont Meru et colobes : une excellente option d\'une demi-journée ou d\'une journée complète.',
    'bsg_park5_best' => 'Meilleure période : toute l\'année. Recommandé : 1 jour.',
    'bsg_park6_name' => 'Mikumi',
    'bsg_park6_tier' => 'bas',
    'bsg_park6_fee' => 'Entrée : 35 $/jour',
    'bsg_park6_desc' => '« Petit Serengeti » : faune de savane classique, accès facile depuis Dar es Salaam. Excellent pour des safaris courts et économiques.',
    'bsg_park6_best' => 'Meilleure période : toute l\'année. Recommandé : 1-2 nuits.',
    'bsg_park7_name' => 'Nyerere (Selous)',
    'bsg_park7_tier' => 'moyen',
    'bsg_park7_fee' => 'Entrée : 53 $/jour',
    'bsg_park7_desc' => 'La plus grande zone protégée d\'Afrique. Safaris en bateau sur la rivière Rufiji, safaris à pied, lycaons, éléphants et hippopotames.',
    'bsg_park7_best' => 'Meilleure période : juin-oct (sec). Recommandé : 2-3 nuits.',
    'bsg_park8_name' => 'Ruaha',
    'bsg_park8_tier' => 'moyen',
    'bsg_park8_fee' => 'Entrée : 35 $/jour',
    'bsg_park8_desc' => 'Isolé, sauvage et magnifique : immenses troupeaux d\'éléphants, lycaons et superbes paysages de baobabs.',
    'bsg_park8_best' => 'Meilleure période : juin-oct (sec). Recommandé : 2-4 nuits.',
    'bsg_parks_legend' => '$ = le plus abordable (moins de 40 $ d\'entrée) · $$ = modéré (40-60 $) · $$$ = coût plus élevé (plus de 60 $)',
    'bsg_parks_strategy' => '<strong>Stratégie budget :</strong> si votre budget est serré, concentrez-vous sur les parcs avec des frais d\'entrée plus bas : Mikumi (35 $), Ruaha (35 $), Tarangire (53 $) et le lac Manyara (53 $). Le Serengeti et le Ngorongoro coûtent plus cher mais offrent une faune inégalée. La plupart des voyageurs combinent 2 jours à Tarangire, 2 au Serengeti, 1 au Ngorongoro et 1 à Manyara.',

    'bsg_acc_title' => 'Hébergement économique : vrais prix 2026',
    'bsg_acc_p1' => 'Votre choix d\'hébergement a le plus grand impact sur votre budget de safari. Voici des options honnêtes près des principaux parcs, avec les prix actuels.',
    'bsg_acc1_name' => 'Campings publics (à l\'intérieur des parcs)',
    'bsg_acc1_price' => '25-30 $ <small>par personne / nuit</small>',
    'bsg_acc1_loc' => 'Serengeti, Ngorongoro, Tarangire',
    'bsg_acc1_desc' => 'Installations basiques, sons de la faune incroyables. Les campings de Seronera, Simba et Kikoti sont les plus populaires. Réservez tôt.',
    'bsg_acc2_name' => 'Camps tentés économiques',
    'bsg_acc2_price' => '80-120 $ <small>par personne / nuit</small>',
    'bsg_acc2_loc' => 'Divers parcs',
    'bsg_acc2_desc' => 'Tentes de safari avec de vrais lits et salles de bain privées : un excellent compromis entre le camping et les lodges.',
    'bsg_acc3_name' => 'Lodges économiques de Karatu',
    'bsg_acc3_price' => '50-80 $ <small>par chambre / nuit</small>',
    'bsg_acc3_loc' => 'Karatu (près du Ngorongoro)',
    'bsg_acc3_desc' => 'Lodges abordables juste à l\'extérieur du Ngorongoro, bien moins chers que le bord du cratère, avec un accès similaire.',
    'bsg_acc4_name' => 'Pensions à Arusha et Moshi',
    'bsg_acc4_price' => '35-60 $ <small>par chambre / nuit</small>',
    'bsg_acc4_loc' => 'Arusha / Moshi',
    'bsg_acc4_desc' => 'Chambres basiques mais propres avec petit-déjeuner : une bonne base avant et après votre safari.',
    'bsg_acc_tip' => '<strong>Conseil d\'hébergement :</strong> les campings publics à l\'intérieur des parcs nationaux se remplissent rapidement en haute saison (juin-octobre). Réservez 2-3 mois à l\'avance. Pour les lodges économiques, vérifiez les endroits juste à l\'extérieur des parcs : souvent 30-50 % moins chers qu\'à l\'intérieur.',

    'bsg_tips_title' => 'Secrets locaux : de nos propres guides',
    'bsg_tips_p1' => 'Conseils d\'initiés de notre équipe de guides tanzaniens, des choses que vous ne trouverez pas dans un guide de voyage. Ils vous feront économiser de l\'argent et amélioreront votre expérience.',
    'bsg_tip1' => '<strong>Le secret de « l\'heure dorée »</strong> — les game drives sont meilleurs au lever du soleil (6h00-8h30) et en fin d\'après-midi (16h00-18h30). Beaucoup de voyageurs économiques sautent le trajet matinal — ne soyez pas l\'un d\'eux.',
    'bsg_tip2' => '<strong>Économisez sur les frais de cratère</strong> — les frais de descente au Ngorongoro (295 $ par véhicule) sont chers, mais loger sur le bord pour un game drive d\'une journée complète offre bien plus de valeur qu\'une demi-journée.',
    'bsg_tip3' => '<strong>Mangez comme un local</strong> — une assiette d\'ugali avec du poisson ou de la viande dans un stand local « mama lishe » coûte 3-5 $ : sûr, délicieux et une fraction des prix des restaurants touristiques.',
    'bsg_tip4' => '<strong>Le choix du véhicule compte</strong> — pour les safaris économiques, insistez sur un 4x4 à toit ouvrant. Les minibus sont moins chers mais offrent une mauvaise visibilité et peinent sur les routes accidentées des parcs.',
    'bsg_tip5' => '<strong>Le bon plan de la saison intermédiaire</strong> — novembre et décembre (petites pluies) sont généralement de brèves averses l\'après-midi, pas de la pluie constante — et offrent des tarifs plus bas avec la même faune incroyable.',
    'bsg_tip6' => '<strong>Logez à l\'extérieur du parc</strong> — des villes comme Mto wa Mbu (près de Manyara) ou Karatu (près du Ngorongoro) sont 50-70 % moins chères que les lodges à l\'intérieur du parc, tout en faisant des game drives d\'une journée complète.',
    'bsg_tip7' => '<strong>La stratégie du « lève-tôt »</strong> — partez du camp à 5h30 pour être le premier dans le parc, surprendre les prédateurs en chasse, et devancer la foule qui commence à arriver vers 9h.',
    'bsg_tip8' => '<strong>La basse saison est sous-estimée</strong> — avril et mai apportent de brèves averses, des paysages incroyablement verts, une avifaune spectaculaire, et les parcs presque pour vous seul.',
    'bsg_tip9' => '<strong>Donnez un bon pourboire, judicieusement</strong> — la norme est de 10-20 $ par jour pour votre guide et 5-10 $ par jour pour le personnel de camp, en espèces.',
    'bsg_tip10' => '<strong>Faites des bagages légers</strong> — les véhicules de safari ont un espace limité. Un sac souple bat une valise rigide.',

    'bsg_best_time_title' => 'Meilleure période pour y aller : guide saisonnier',
    'bsg_best_time_p1' => 'La Tanzanie est une destination toute l\'année, mais l\'expérience de la faune change avec les saisons.',
    'bsg_month_jan' => 'Les naissances commencent · Chaud et sec',
    'bsg_month_feb' => 'Pic des naissances · Observation excellente',
    'bsg_month_mar' => 'Fin des naissances · Paysages luxuriants',
    'bsg_month_apr' => 'Grandes pluies · Tarifs les plus bas',
    'bsg_month_may' => 'Les pluies diminuent · Excellent rapport qualité-prix',
    'bsg_month_jun' => 'Saison sèche · Traversées de la Grumeti',
    'bsg_month_jul' => 'Traversées de la Mara · Haute saison',
    'bsg_month_aug' => 'Traversées de la Mara · Mois le plus fréquenté',
    'bsg_month_sep' => 'Troupeaux du nord · Toujours fréquenté',
    'bsg_month_oct' => 'Les troupeaux se dirigent vers le sud · Bon rapport qualité-prix',
    'bsg_month_nov' => 'Petites pluies · Excellent rapport qualité-prix',
    'bsg_month_dec' => 'Saison verte · Excellente photographie',
    'bsg_best_time_box' => '<strong>Meilleures périodes économiques :</strong> novembre-décembre (petites pluies) et mars-mai (grandes pluies) offrent des tarifs plus bas, moins de monde et des paysages luxuriants : idéal pour les chercheurs de bon rapport qualité-prix.',

    'bsg_itin_title' => 'Exemples d\'itinéraires',
    'bsg_itin_p1' => 'Un aperçu jour par jour de ce que nos forfaits économiques les plus populaires incluent réellement.',
    'bsg_itin1_name' => 'Safari classique de 3 jours au Serengeti',
    'bsg_itin1_days' => '3 jours / 2 nuits',
    'bsg_itin1_route' => 'Arusha → Serengeti central → Ngorongoro → Arusha',
    'bsg_itin1_detail' => '<strong>Jour 1 :</strong> Arusha → Serengeti, game drive en route, nuit en camp tenté.<br><strong>Jour 2 :</strong> Game drive toute la journée au Serengeti, nuit en camp tenté.<br><strong>Jour 3 :</strong> Descente au cratère du Ngorongoro, retour à Arusha.',
    'bsg_itin1_price' => 'À partir de 1 000 € par personne',
    'bsg_itin2_name' => 'Circuit nord classique de 5 jours',
    'bsg_itin2_days' => '5 jours / 4 nuits',
    'bsg_itin2_route' => 'Arusha → Tarangire → Serengeti → Ngorongoro → Arusha',
    'bsg_itin2_detail' => '<strong>Jour 1 :</strong> Arusha → Tarangire, game drive de l\'après-midi.<br><strong>Jour 2 :</strong> Tarangire → Serengeti, game drive en route.<br><strong>Jour 3 :</strong> Game drive toute la journée au Serengeti.<br><strong>Jour 4 :</strong> Serengeti → Ngorongoro, descente au cratère.<br><strong>Jour 5 :</strong> Retour à Arusha.',
    'bsg_itin2_price' => 'À partir de 1 450 € par personne',

    'bsg_faq_title' => 'Questions fréquentes',
    'bsg_faq_q1' => 'Combien coûte un safari économique en Tanzanie ?',
    'bsg_faq_a1' => 'Généralement 150-300 € par personne et par jour, selon la taille du groupe, la saison, l\'hébergement et les parcs visités.',
    'bsg_faq_q2' => 'Quel est le mois le moins cher pour un safari en Tanzanie ?',
    'bsg_faq_a2' => 'Avril et mai (les grandes pluies) offrent les tarifs les plus bas, avec des paysages luxuriants et verts et moins de monde.',
    'bsg_faq_q3' => 'Quel est le parc national le moins cher de Tanzanie ?',
    'bsg_faq_a3' => 'Mikumi, le parc national d\'Arusha et le lac Manyara ont les frais d\'entrée les plus bas.',
    'bsg_faq_q4' => 'Le camping est-il sûr lors d\'un safari en Tanzanie ?',
    'bsg_faq_a4' => 'Oui, les campings publics à l\'intérieur des parcs nationaux sont patrouillés et largement utilisés par les voyageurs économiques. Les guides vous informent sur la sécurité du camp à l\'arrivée.',
    'bsg_faq_q5' => 'Puis-je négocier les prix des safaris en Tanzanie ?',
    'bsg_faq_a5' => 'Les prix des opérateurs locaux agréés sont généralement déjà équitables et transparents. Méfiez-vous des devis inhabituellement bon marché, car ils cachent souvent des coûts supplémentaires à l\'entrée.',
    'bsg_faq_q6' => 'Ai-je besoin d\'un véhicule privé pour un safari économique ?',
    'bsg_faq_a6' => 'Non, les safaris en groupe partagé avec 4-6 voyageurs réduisent considérablement le coût par personne tout en donnant à chacun une place fenêtre.',
    'bsg_faq_q7' => 'Qu\'est-ce qui est inclus dans un forfait safari économique ?',
    'bsg_faq_a7' => 'Généralement un chauffeur-guide, un véhicule 4x4, les frais de parc, l\'hébergement comme spécifié, les repas en pension complète et l\'eau potable. Confirmez toujours les inclusions exactes avant de réserver.',
    'bsg_faq_q8' => 'Combien de temps à l\'avance dois-je réserver ?',
    'bsg_faq_a8' => 'Pour la haute saison (juin-octobre), réservez 3-6 mois à l\'avance. Pour la saison intermédiaire et basse, 4-6 semaines suffisent généralement.',

    'bsg_book_title' => 'Réservez votre safari économique',
    'bsg_book_p1' => 'Remplissez les détails ci-dessous et notre équipe répondra sous 24 heures avec la disponibilité et un prix exact.',
    'bsg_cta_title' => 'Prêt à découvrir la Tanzanie à votre façon ?',
    'bsg_cta_p' => 'Obtenez un devis gratuit et sans engagement d\'un opérateur local d\'Arusha : prix honnêtes, sans intermédiaires.',
    'bsg_cta_button' => 'Obtenir votre devis gratuit',
    'bsg_share_label' => 'Partager ce guide :',
    'bsg_print' => 'Imprimer le guide',
    'bsg_form_name' => 'Nom complet',
    'bsg_form_email' => 'Adresse e-mail',
    'bsg_form_phone' => 'Téléphone (avec indicatif pays)',

