    'lsg_meta_title' => 'Le guide ultime du safari de luxe en Tanzanie : lodges exclusifs, prix et forfaits sur mesure',
    'lsg_meta_description' => 'Le guide de référence du safari de luxe en Tanzanie. Lodges exclusifs, guidage privé, analyse détaillée des coûts, conseils d\'initiés et forfaits sur mesure d\'un opérateur local d\'Arusha.',

    'lsg_badge' => 'Le guide de luxe complet 2026',
    'lsg_h1' => 'Le guide ultime du safari de luxe en Tanzanie',
    'lsg_price_highlight' => 'À partir de 1 800 €',
    'lsg_price_highlight_small' => 'par personne',
    'lsg_hero_intro' => 'Tout ce dont vous avez besoin avant de réserver : ce que signifie vraiment le luxe en safari, lodges exclusifs, guidage privé, répartitions honnêtes des coûts, et, une fois que vous savez ce que vous payez, nos forfaits sur mesure.',
