    'lsg_intro_title' => 'L\'art du safari de luxe',
    'lsg_intro_p1' => 'Un safari de luxe en Tanzanie n\'est pas juste des vacances. C\'est une expérience qui change une vie. Se réveiller au lever de soleil doré africain, le rugissement lointain d\'un lion à travers les plaines, traquer un léopard avec un guide qui a passé des décennies à apprendre les secrets de la nature sauvage.',
    'lsg_intro_p2' => 'Mais le luxe ne se résume pas simplement au prix. Il s\'agit d\'<strong>exclusivité, de personnalisation et d\'attention méticuleuse aux détails</strong>. Un véhicule privé et un guide dédié qui anticipe vos besoins. Des lodges qui sont des merveilles architecturales se fondant dans le paysage tout en offrant tout le confort moderne.',
    'lsg_intro_p3' => 'Ce guide provient de notre propre équipe de spécialistes basés à Arusha qui organisent des safaris de luxe depuis des années. Chaque lodge et expérience listés ici ont été personnellement vérifiés. Nous ne vendons pas simplement du luxe, nous le sélectionnons.',
    'lsg_intro_box' => '<strong>Ce qui nous distingue :</strong> nous ne sommes pas une plateforme de réservation. Nous sommes une équipe locale qui conçoit des safaris de luxe depuis des années. Chaque lodge et chaque expérience sont personnellement vérifiés, afin que vous ayez accès à une connaissance d\'initié que vous ne trouverez nulle part ailleurs.',

    'lsg_quick_title' => 'Réponse rapide : combien coûte un safari de luxe en Tanzanie ?',
    'lsg_quick_p1' => 'Un safari de luxe en Tanzanie coûte généralement <strong>350-1 200 €+ par personne et par nuit</strong>. Cette large fourchette reflète la diversité des offres de luxe, des camps tentés de charme aux villas privées ultra-exclusives.',
    'lsg_quick_li1' => '<strong>Luxe premium :</strong> 350-600 €/nuit : excellents camps tentés, véhicule privé, service élevé.',
    'lsg_quick_li2' => '<strong>Ultra-luxe :</strong> 600-900 €/nuit : lodges de classe mondiale, guides d\'élite, souvent des vols charters privés.',
    'lsg_quick_li3' => '<strong>Privé exclusif :</strong> 900-1 200 €+/nuit : villas privées, service de majordome, exclusivité complète.',
    'lsg_quick_li4' => '<strong>Saison :</strong> les mois intermédiaires (novembre-décembre, février) offrent les mêmes lodges à des tarifs 20-30 % plus bas.',
    'lsg_quick_li5' => '<strong>Privé contre groupe :</strong> un véhicule et un guide privés coûtent plus cher mais définissent ce que signifie vraiment le « luxe ».',
    'lsg_quick_p2' => 'Pour un <strong>safari de luxe de 5 jours</strong>, prévoyez environ <strong>1 800-3 500 € par personne</strong>. Pour un <strong>safari de 7 jours</strong>, attendez-vous à <strong>2 500-5 000 €</strong>. Pour un <strong>safari de 10 jours avec Zanzibar</strong>, prévoyez <strong>3 800-7 000 €+</strong>.',
    'lsg_quick_pro' => '<strong>Conseil de pro :</strong> le meilleur rapport qualité-prix des safaris de luxe vient du voyage pendant les <strong>saisons intermédiaires</strong> (novembre-décembre et février). Mêmes lodges exclusifs, mêmes guides experts, souvent des tarifs 20-30 % plus bas, avec moins de monde et une expérience plus intime.',

    'lsg_packages_title' => 'Forfaits de safari de luxe : conçus pour les voyageurs exigeants',
    'lsg_packages_p1' => 'Chaque forfait est conçu par nos spécialistes du safari de luxe, de la sélection des lodges au timing des game drives. Chaque forfait inclut :',
    'lsg_packages_inc1' => 'Véhicule de safari 4x4 privé avec toit ouvrant',
    'lsg_packages_inc2' => 'Guide certifié d\'élite avec des années d\'expérience en safari de luxe',
    'lsg_packages_inc3' => 'Lodges de luxe triés sur le volet, personnellement vérifiés par notre équipe',
    'lsg_packages_inc4' => 'Repas gastronomiques en pension complète et boissons premium',
    'lsg_packages_inc5' => 'Tous les frais de parc et taxes de conservation',
    'lsg_packages_inc6' => 'Support dédié 24/7, de la réservation au départ',
    'lsg_packages_custom' => 'Besoin d\'un itinéraire entièrement personnalisé ? <a href="%s">Contactez nos spécialistes du safari de luxe</a>. Nous concevrons le safari parfait pour votre groupe, votre budget et vos rêves.',

