    'lsg_cost_row5_pct' => '5-10 %',
    'lsg_cost_insider' => '<strong>La vraie différence :</strong> un safari « premium » offre une bonne qualité mais vous partagerez probablement un véhicule et aurez moins de flexibilité. Un <strong>safari de luxe</strong> signifie une exclusivité complète : un véhicule privé, un guide dédié qui connaît vos préférences, et des expériences entièrement adaptées à vous.',

    'lsg_lodges_title' => 'Meilleurs lodges de luxe : triés sur le volet pour l\'excellence',
    'lsg_lodges_p1' => 'Voici parmi les plus beaux lodges de luxe de Tanzanie, personnellement vérifiés par notre équipe. Chacun offre un cadre unique, un service exceptionnel et une expérience inoubliable.',
    'lsg_lodge1_name' => 'Singita Sasakwa Lodge',
    'lsg_lodge1_tier' => 'élevé',
    'lsg_lodge1_fee' => '1 800-3 200 $/nuit',
    'lsg_lodge1_desc' => 'Lodge de style édouardien avec vues panoramiques sur le Serengeti, piscines à débordement privées et service de majordome.',
    'lsg_lodge1_best' => 'Emplacement : Serengeti (réserve de Grumeti). Idéal pour : observation exceptionnelle des grands félins.',
