    'lsg_lodge2_tier' => 'élevé',
    'lsg_lodge2_fee' => '1 200-1 900 $/nuit',
    'lsg_lodge2_desc' => 'Un camp de luxe mobile qui suit la migration, avec l\'élégance classique du safari et le confort moderne.',
    'lsg_lodge2_best' => 'Emplacement : Serengeti (mobile). Idéal pour : observation inégalée de la migration.',
