    'lsg_lodge3_tier' => 'moyen',
    'lsg_lodge3_fee' => '950-1 600 $/nuit',
    'lsg_lodge3_desc' => 'Un luxe de classe mondiale avec une piscine à débordement surplombant un point d\'eau, un spa primé et un service adapté aux familles.',
    'lsg_lodge3_best' => 'Emplacement : Serengeti. Idéal pour : familles et primo-voyageurs de luxe.',
