    'lsg_lodge4_desc' => 'Une architecture époustouflante perchée sur le bord du cratère, avec des suites opulentes et des vues inégalées sur le cratère.',
    'lsg_lodge4_best' => 'Emplacement : bord du Ngorongoro. Idéal pour : le cadre le plus spectaculaire d\'Afrique.',
