    'lsg_lodge5_desc' => 'Des suites cabanes surélevées surplombant Tarangire, avec d\'immenses troupeaux d\'éléphants et des baobabs emblématiques.',
    'lsg_lodge5_best' => 'Emplacement : Tarangire. Idéal pour : un séjour unique et inoubliable.',
    'lsg_lodge6_name' => 'Zuri Zanzibar',
    'lsg_lodge6_tier' => 'moyen',
    'lsg_lodge6_fee' => '600-1 200 $/nuit',
    'lsg_lodge6_desc' => 'Un complexe de luxe en bord de mer avec piscines à débordement, un spa de classe mondiale et une restauration exceptionnelle.',
    'lsg_lodge6_best' => 'Emplacement : Zanzibar. Idéal pour : la finale plage parfaite pour une lune de miel.',

    'lsg_exp_title' => 'Expériences exclusives : la différence du luxe',
    'lsg_exp_p1' => 'Ce qui distingue vraiment un safari de luxe, ce sont des expériences que l\'argent ne peut normalement pas acheter, mais que nous pouvons organiser.',
    'lsg_exp1' => '<strong>Safari en montgolfière</strong> — flottez silencieusement au-dessus du Serengeti au lever du soleil avec un petit-déjeuner au champagne en brousse. À partir de 500 € par personne.',
    'lsg_exp2' => '<strong>Dîner privé en brousse</strong> — un dîner aux chandelles dans la nature sauvage avec un chef privé, de bons vins et un serveur personnel. À partir de 300 € par couple.',
    'lsg_exp3' => '<strong>Safari en avion</strong> — évitez les longs trajets et volez directement vers votre lodge en vol charter privé, avec des avions modernes aux excellents antécédents de sécurité. À partir de 500 € par vol.',
    'lsg_exp4' => '<strong>Safari à pied avec un guide d\'élite</strong> — traquez les animaux et découvrez la brousse à pied avec un guide expert. À partir de 200 € par personne.',
    'lsg_exp5' => '<strong>Safari photographique privé</strong> — des game drives dédiés avec un guide formé à la photographie animalière, se positionnant pour la meilleure lumière. À partir de 300 € de plus par jour.',
    'lsg_exp6' => '<strong>Retraite spa et bien-être</strong> — détendez-vous après les game drives avec des soins inspirés des traditions africaines. À partir de 100 € par soin.',
    'lsg_exp_box' => '<strong>Notre promesse :</strong> chaque expérience que nous offrons est personnellement vérifiée. Nous travaillons avec les meilleurs opérateurs, guides et lieux pour garantir la perfection. Si ce n\'est pas à la hauteur de nos standards, nous ne le recommandons pas.',

    'lsg_best_time_title' => 'Meilleure période pour un safari de luxe : guide saisonnier',
    'lsg_best_time_p1' => 'Pour les voyageurs de luxe, la meilleure période est souvent les saisons intermédiaires : les mêmes lodges et guides exclusifs à un tarif nettement plus bas.',
    'lsg_month_jan' => 'Naissances · Premium',
    'lsg_month_feb' => 'Pic des naissances · Meilleur rapport qualité-prix',
    'lsg_month_mar' => 'Saison verte · Excellent rapport qualité-prix',
    'lsg_month_apr' => 'Grandes pluies · Tarifs plus bas',
    'lsg_month_may' => 'Les pluies diminuent · Bon rapport qualité-prix',
    'lsg_month_jun' => 'Saison sèche · Premium',
    'lsg_month_jul' => 'Traversées de la Mara · Pic d\'affluence',
    'lsg_month_aug' => 'Mois le plus fréquenté · Premium',
    'lsg_month_sep' => 'Troupeaux du nord · Premium',
    'lsg_month_oct' => 'Bon rapport qualité-prix · Affluence en baisse',
    'lsg_month_nov' => 'Petites pluies · Meilleur rapport qualité-prix',
    'lsg_month_dec' => 'Saison verte · Excellent rapport qualité-prix',
    'lsg_best_time_box' => '<strong>Meilleure période économique :</strong> novembre-décembre et février offrent les mêmes lodges et guides exclusifs à des tarifs 20-30 % plus bas, avec moins de monde et une expérience plus intime.',

    'lsg_itin_title' => 'Exemples d\'itinéraires de luxe',
    'lsg_itin_p1' => 'Un aperçu jour par jour de ce que nos forfaits de luxe les plus demandés incluent réellement.',
    'lsg_itin1_name' => 'Safari de luxe classique de 5 jours',
    'lsg_itin1_days' => '5 jours / 4 nuits',
    'lsg_itin1_route' => 'Tarangire + Ngorongoro + Serengeti',
    'lsg_itin1_detail' => '<strong>Jour 1 :</strong> Arrivée à Arusha, vol charter privé vers Tarangire, game drive de l\'après-midi.<br><strong>Jour 2 :</strong> Tarangire → Ngorongoro, descente au cratère toute la journée avec un guide privé.<br><strong>Jour 3 :</strong> Ngorongoro → Serengeti, vol charter privé, game drive de l\'après-midi.<br><strong>Jour 4 :</strong> Journée complète au Serengeti : game drives du matin et de l\'après-midi, montgolfière optionnelle.<br><strong>Jour 5 :</strong> Game drive matinal, vol charter privé vers Arusha, départ.',
    'lsg_itin1_price' => 'À partir de 2 300 € par personne',
    'lsg_itin2_name' => 'Serengeti et cratère ultime de 7 jours',
    'lsg_itin2_days' => '7 jours / 6 nuits',
    'lsg_itin2_route' => 'Serengeti + Ngorongoro + Manyara',
    'lsg_itin2_detail' => '<strong>Jours 1-2 :</strong> Serengeti : 2 nuits dans un lodge ultra-luxe, couverture complète de la migration.<br><strong>Jours 3-4 :</strong> Serengeti : 2 nuits dans un camp mobile suivant la migration.<br><strong>Jour 5 :</strong> Serengeti → Ngorongoro, vol charter privé, nuit sur le bord du cratère.<br><strong>Jour 6 :</strong> Ngorongoro → Manyara, vol charter privé.<br><strong>Jour 7 :</strong> Manyara → Arusha, départ.',
    'lsg_itin2_price' => 'À partir de 6 900 € par personne',

    'lsg_faq_title' => 'Questions fréquentes',
    'lsg_faq_q1' => 'Combien coûte un safari de luxe en Tanzanie ?',
    'lsg_faq_a1' => 'Généralement 350-1 200 €+ par personne et par nuit, selon le niveau du lodge, si le véhicule et le guide sont privés, et la saison.',
    'lsg_faq_q2' => 'Quel est le lodge le plus exclusif du Serengeti ?',
    'lsg_faq_a2' => 'Singita Sasakwa, &Beyond Serengeti Under Canvas et Ngorongoro Crater Lodge sont parmi les établissements les plus exclusifs avec lesquels nous travaillons.',
    'lsg_faq_q3' => 'Qu\'est-ce qui est inclus dans un safari de luxe ?',
    'lsg_faq_a3' => 'Un véhicule 4x4 privé, un guide d\'élite, un hébergement de luxe, tous les repas, des boissons premium, les frais de parc, et souvent des vols charters privés.',
    'lsg_faq_q4' => 'Un véhicule privé est-il toujours inclus ?',
    'lsg_faq_a4' => 'Oui, dans chaque forfait de cette page, le véhicule et le guide sont privés pour votre groupe, non partagés avec d\'autres voyageurs.',
    'lsg_faq_q5' => 'Quelle est la meilleure période pour un safari de luxe ?',
    'lsg_faq_a5' => 'Novembre-décembre et février offrent les mêmes lodges exclusifs à des tarifs 20-30 % plus bas. Juin-septembre est la haute saison pour l\'observation de la migration mais la plus fréquentée et la plus chère.',
    'lsg_faq_q6' => 'Les enfants peuvent-ils participer à un safari de luxe ?',
    'lsg_faq_a6' => 'Oui, plusieurs de nos lodges partenaires (Four Seasons, Zuri Zanzibar) offrent des suites familiales et des programmes pour enfants.',
    'lsg_faq_q7' => 'Les forfaits de luxe incluent-ils les vols intérieurs ?',
    'lsg_faq_a7' => 'Les forfaits en avion incluent les vols charters intérieurs ; les itinéraires terrestres peuvent les ajouter en option pour économiser du temps de conduite.',
    'lsg_faq_q8' => 'Combien de temps à l\'avance dois-je réserver un safari de luxe ?',
    'lsg_faq_a8' => 'Les meilleurs lodges se réservent complets 6-12 mois à l\'avance pour la haute saison (juin-septembre). Pour la saison intermédiaire, 3-4 mois suffisent généralement.',

    'lsg_book_title' => 'Renseignez-vous sur votre safari de luxe',
    'lsg_book_p1' => 'Remplissez les détails ci-dessous et notre spécialiste du safari de luxe répondra sous 12 heures avec un itinéraire personnalisé.',
    'lsg_cta_title' => 'Prêt pour un safari conçu autour de vous ?',
    'lsg_cta_p' => 'Obtenez une proposition sur mesure et sans engagement d\'un spécialiste local d\'Arusha : lodges exclusifs, tarification honnête.',
    'lsg_cta_button' => 'Demander maintenant',
