    'mgg_meta_title' => 'Le guide de la Grande Migration : mois par mois, traversées de rivière, prix et forfaits',
    'mgg_meta_description' => 'Le guide de référence de la Grande Migration au Serengeti. Mouvements mois par mois, stratégie des traversées de rivière, saison des naissances, hébergement et forfaits de safari de migration de confiance.',

    'mgg_badge' => 'Le guide complet de la migration 2026',
    'mgg_h1' => 'La Grande Migration : le guide complet',
    'mgg_price_highlight' => 'À partir de 200 €',
    'mgg_price_highlight_small' => 'par personne / jour',
    'mgg_hero_intro' => 'Tout ce dont vous avez besoin avant de réserver : où se trouvent les troupeaux chaque mois, comment fonctionnent réellement les traversées de rivière, prix d\'hébergement honnêtes, et, une fois que vous savez ce que vous poursuivez, nos forfaits de migration de confiance.',
