    'mgg_intro_title' => 'Le plus grand spectacle animalier sur Terre',
    'mgg_intro_p1' => 'La Grande Migration n\'est pas juste un événement animalier. C\'est le plus grand spectacle animalier de la planète. Chaque année, plus de <strong>1,5 million de gnous</strong>, rejoints par <strong>200 000 zèbres</strong>, se déplacent en un pèlerinage continu et circulaire à travers l\'écosystème Serengeti-Mara, parcourant environ <strong>800 kilomètres</strong> par an.',
    'mgg_intro_p2' => 'Mais la Grande Migration ne se résume pas aux chiffres. Il s\'agit de drame, de survie et de la puissance brute de la nature. C\'est le tonnerre des sabots à travers les plaines, le spectacle à couper le souffle des traversées de rivière, et les moments intimes de naissance et de prédation.',
    'mgg_intro_p3' => 'Ce guide provient de notre propre équipe de guides basés à Arusha qui suivent les troupeaux toute l\'année. Nous savons où les trouver, quand les trouver, et comment vous offrir la meilleure expérience possible.',
    'mgg_intro_box' => '<strong>Pourquoi ce guide est différent :</strong> nous ne nous contentons pas de lire sur la Migration. Nos guides sont dans le Serengeti à suivre les troupeaux et à prédire leurs mouvements. Chaque conseil ici vient d\'une expérience réelle, pas d\'informations génériques.',

    'mgg_route_title' => 'L\'itinéraire de la migration : comprendre le cycle',
    'mgg_route_p1' => 'La migration suit un itinéraire circulaire à travers l\'écosystème Serengeti-Mara, entièrement dicté par les précipitations et la disponibilité d\'herbe fraîche. Comprendre cet itinéraire est essentiel pour planifier votre safari.',
    'mgg_route_box' => '<strong>Serengeti du Sud (Ndutu)</strong> → Janvier-Mars (Naissances)<br><strong>Serengeti central et occidental</strong> → Avril-Mai (Dispersion)<br><strong>Corridor occidental (Grumeti)</strong> → Juin-Juillet (Traversées de la Grumeti)<br><strong>Serengeti du Nord (rivière Mara)</strong> → Juillet-Septembre (Traversées de la Mara)<br><strong>Serengeti central</strong> → Octobre-Novembre (Retour vers le sud)<br><strong>Serengeti du Sud (Ndutu)</strong> → Décembre (Avant les naissances)',
    'mgg_route_tip' => '<strong>Point clé :</strong> la migration n\'est pas un seul troupeau se déplaçant ensemble. C\'est une série de troupeaux se déplaçant dans différentes directions. Comprendre le schéma général vous aide à planifier, mais les guides locaux peuvent vous dire exactement où se trouvent les troupeaux à un moment donné.',

    'mgg_months_title' => 'Mois par mois : où, quoi et pourquoi',
    'mgg_months_p1' => 'Une répartition détaillée, mois par mois, de la Grande Migration. Pour chaque mois, exactement où se trouvent les troupeaux et ce que vous pouvez espérer voir.',
    'mgg_m_jan_loc' => 'Serengeti du Sud (Ndutu)',
    'mgg_m_jan_desc' => 'Les troupeaux arrivent sur les plaines à herbe courte. La saison des naissances commence, avec des prédateurs actifs à proximité.',
    'mgg_m_feb_loc' => 'Serengeti du Sud (Ndutu)',
    'mgg_m_feb_desc' => 'Pic de la saison des naissances : plus de 8 000 petits naissent chaque jour. L\'un des moments les plus spectaculaires pour assister au cycle de la vie.',
    'mgg_m_mar_loc' => 'Serengeti central et occidental',
    'mgg_m_mar_desc' => 'Les troupeaux commencent à se déplacer vers l\'ouest et le nord alors que les plaines du sud commencent à s\'assécher.',
    'mgg_m_apr_loc' => 'Corridor occidental (Grumeti)',
    'mgg_m_apr_desc' => 'Les grandes pluies arrivent et les troupeaux se rassemblent dans le corridor occidental, préparant les premières traversées.',
    'mgg_m_may_loc' => 'Corridor occidental (rivière Grumeti)',
    'mgg_m_may_desc' => 'Les troupeaux se concentrent autour de la rivière Grumeti. Les premières traversées spectaculaires commencent.',
    'mgg_m_jun_loc' => 'Serengeti occidental et du Nord',
    'mgg_m_jun_desc' => 'Les troupeaux poussent vers le nord en direction de la rivière Mara alors que la saison sèche commence.',
    'mgg_m_jul_loc' => 'Serengeti du Nord (rivière Mara)',
    'mgg_m_jul_desc' => 'Les troupeaux arrivent à la rivière Mara. Les traversées emblématiques commencent.',
    'mgg_m_aug_loc' => 'Serengeti du Nord (rivière Mara)',
    'mgg_m_aug_desc' => 'Pic des traversées de la rivière Mara : le moment le plus fréquenté et spectaculaire pour assister à la migration.',
    'mgg_m_sep_loc' => 'Serengeti du Nord (rivière Mara)',
    'mgg_m_sep_desc' => 'Les traversées continuent avec un peu moins de monde. L\'observation de la faune reste exceptionnelle.',
    'mgg_m_oct_loc' => 'Serengeti du Nord et central',
    'mgg_m_oct_desc' => 'Les troupeaux commencent leur voyage vers le sud. Bon rapport qualité-prix avec moins de monde.',
    'mgg_m_nov_loc' => 'Serengeti central et du Sud',
    'mgg_m_nov_desc' => 'Les petites pluies commencent et les troupeaux retournent vers les plaines du sud, se préparant pour la prochaine saison des naissances.',
    'mgg_m_dec_loc' => 'Serengeti du Sud (Ndutu)',
    'mgg_m_dec_desc' => 'Les troupeaux s\'installent sur les plaines du sud, paissant sur l\'herbe riche en nutriments alors que le cycle recommence.',

    'mgg_packages_title' => 'Forfaits de migration de confiance : réservez en toute confiance',
    'mgg_packages_p1' => 'Programmés selon la phase de migration que vous voulez voir, chaque forfait ci-dessous est construit avec une transparence totale et aucun frais caché. Chaque forfait inclut :',
    'mgg_packages_inc1' => 'Chauffeur-guide professionnel, parlant couramment anglais',
    'mgg_packages_inc2' => 'Véhicule de safari 4x4 moderne avec toit ouvrant',
