    'mgg_packages_inc5' => 'Repas en pension complète et eau potable',
    'mgg_packages_inc6' => 'Support 24/7 et annulation gratuite jusqu\'à 14 jours avant le départ',
    'mgg_packages_custom' => 'Pas sûr de quelle phase poursuivre ? <a href="%s">Contactez-nous et indiquez-nous vos dates de voyage</a>. Nous vous dirons exactement ce que vous verrez.',

