    'mgg_crossings_title' => 'Traversées de rivière : le guide expert ultime',
    'mgg_crossings_p1' => 'Les traversées de rivière sont les moments les plus emblématiques et spectaculaires de la Grande Migration. Deux rivières servent de scène : la rivière Grumeti dans le corridor occidental et la rivière Mara dans le nord.',
    'mgg_crossings_grumeti_title' => 'Traversées de la rivière Grumeti : le drame occidental',
    'mgg_crossings_grumeti_p' => 'Les traversées de la Grumeti sont les premiers grands obstacles aquatiques que rencontrent les troupeaux. Moins célèbres que la rivière Mara, mais tout aussi spectaculaires et bien moins fréquentées, elles abritent certains des plus grands crocodiles d\'Afrique.',
    'mgg_crossings_grumeti_tip' => '<strong>Meilleure période :</strong> fin mai à début juillet. <strong>Secret d\'initié :</strong> les traversées de la Grumeti sont souvent plus chaotiques que celles de la Mara. Les gnous sont moins expérimentés, ce qui rend les traversées plus sauvages.',
    'mgg_crossings_mara_title' => 'Traversées de la rivière Mara : le spectacle mondialement célèbre',
    'mgg_crossings_mara_p' => 'Les traversées de la rivière Mara sont le spectacle animalier le plus célèbre sur Terre. Des centaines de milliers de gnous et de zèbres se rassemblent sur les berges avant de plonger dans des eaux infestées de crocodiles.',
    'mgg_crossings_mara_tip' => '<strong>Meilleure période :</strong> mi-juillet à fin août. <strong>Conseil d\'observation :</strong> les traversées sont imprévisibles. Il se peut que vous deviez attendre plusieurs heures, le plus probablement tôt le matin ou en fin d\'après-midi.',
    'mgg_crossings_pro' => '<strong>Conseil de pro :</strong> pour éviter la foule à la rivière Mara, envisagez les traversées de la rivière Grumeti en juin : un drame similaire, une fraction des touristes, et des prix plus bas.',

    'mgg_calving_title' => 'Saison des naissances : le cycle de la vie',
    'mgg_calving_p1' => 'Entre <strong>janvier et mars</strong>, le sud du Serengeti devient la scène de l\'un des événements les plus remarquables de la nature : la saison des naissances des gnous. Plus de <strong>500 000 petits</strong> naissent en l\'espace de quelques semaines, avec jusqu\'à <strong>8 000 naissances par jour</strong> au pic.',
    'mgg_calving_p2' => 'C\'est une période d\'action intense des prédateurs : lions, guépards, léopards et hyènes suivent de près les troupeaux, profitant de l\'abondance de nouveau-nés.',
    'mgg_calving_box' => '<strong>Faits rapides sur la saison des naissances :</strong> plus de 500 000 petits nés annuellement, plus de 8 000 naissances par jour au pic, meilleure observation dans la zone de Ndutu, excellent pour la photographie grâce à l\'herbe courte et la douce lumière du matin.',

    'mgg_acc_title' => 'Où loger : hébergement de migration',
    'mgg_acc_p1' => 'Choisir le bon hébergement pour la bonne phase de migration compte. Voici des options honnêtes pour tous les budgets.',
    'mgg_acc1_name' => 'Campings publics Serengeti et Ndutu',
    'mgg_acc1_price' => '25-30 $ <small>par personne / nuit</small>',
    'mgg_acc1_loc' => 'Seronera, Ndutu, Grumeti',
    'mgg_acc1_desc' => 'Installations basiques, sons de la faune incroyables, à l\'intérieur du parc. Réservez tôt. Ils se remplissent vite en haute saison.',
    'mgg_acc2_name' => 'Camps tentés milieu de gamme',
    'mgg_acc2_price' => '150-250 $ <small>par personne / nuit</small>',
    'mgg_acc2_loc' => 'Serengeti central et occidental',
    'mgg_acc2_desc' => 'Salles de bain privées, restauration centrale, excellent accès à la migration sans le prix de l\'ultra-luxe.',
    'mgg_acc3_name' => 'Camps mobiles suivant les troupeaux',
    'mgg_acc3_price' => '120-180 $ <small>par personne / nuit</small>',
    'mgg_acc3_loc' => 'Se déplace avec la migration',
    'mgg_acc3_desc' => 'Camps qui se déplacent au fil de la saison pour rester proches de l\'action : un accès à la faune imbattable.',
    'mgg_acc4_name' => 'Lodges de luxe sur le bord du cratère',
    'mgg_acc4_price' => '750-1 300 $ <small>par personne / nuit</small>',
    'mgg_acc4_loc' => 'Bord du cratère du Ngorongoro',
    'mgg_acc4_desc' => 'Vues époustouflantes et service exceptionnel, idéal pour combiner un safari de migration avec le cratère.',
    'mgg_acc_tip' => '<strong>Conseil de réservation :</strong> pour les mois de pointe de la migration (juillet-septembre), réservez 6-12 mois à l\'avance. Les camps les mieux situés se réservent complets en premier, quel que soit le niveau de budget.',

    'mgg_best_time_title' => 'Meilleure période pour visiter : un guide saisonnier',
    'mgg_best_time_p1' => 'La meilleure période dépend entièrement de ce que vous voulez voir. Chaque saison offre une expérience unique.',
    'mgg_month_jan' => 'Les naissances commencent · Ndutu',
    'mgg_month_feb' => 'Pic des naissances · Action des prédateurs',
    'mgg_month_mar' => 'Fin des naissances · Les troupeaux se dispersent',
    'mgg_month_apr' => 'Grandes pluies · Préparation Grumeti',
    'mgg_month_may' => 'Les traversées de la Grumeti commencent',
    'mgg_month_jun' => 'Les troupeaux poussent vers le nord · Traversées',
    'mgg_month_jul' => 'Les traversées de la Mara commencent',
    'mgg_month_aug' => 'Pic des traversées de la Mara',
    'mgg_month_sep' => 'Les traversées continuent',
    'mgg_month_oct' => 'Les troupeaux se dirigent vers le sud · Bon rapport qualité-prix',
    'mgg_month_nov' => 'Petites pluies · Les troupeaux retournent au sud',
    'mgg_month_dec' => 'Avant les naissances · Plaines du sud',
    'mgg_best_time_box' => '<strong>Conseil d\'expert de la migration :</strong> « Il n\'y a pas de mauvais moment pour voir la Migration. Chaque saison offre quelque chose d\'unique. Vous voulez du spectacle ? Visitez en août. Vous voulez de l\'intimité ? Visitez en février. Vous voulez la solitude ? Visitez en avril. »',

    'mgg_itin_title' => 'Exemples d\'itinéraires de migration',
    'mgg_itin_p1' => 'Un aperçu jour par jour de ce que nos forfaits de migration les plus demandés incluent réellement.',
    'mgg_itin1_name' => 'Safari saison des naissances de 5 jours',
    'mgg_itin1_days' => '5 jours / 4 nuits',
    'mgg_itin1_route' => 'Ndutu + Ngorongoro + Serengeti central (janv-mars)',
    'mgg_itin1_detail' => '<strong>Jour 1 :</strong> Arrivée à Arusha → transfert vers Ndutu, game drive de l\'après-midi.<br><strong>Jour 2 :</strong> Journée complète à Ndutu : observation des naissances et action des prédateurs.<br><strong>Jour 3 :</strong> Ndutu → cratère du Ngorongoro, descente toute la journée.<br><strong>Jour 4 :</strong> Ngorongoro → Serengeti central, game drive en route.<br><strong>Jour 5 :</strong> Game drive matinal, retour à Arusha.',
    'mgg_itin1_price' => 'À partir de 1 150 € par personne',
    'mgg_itin2_name' => 'Safari traversées de la rivière Mara de 8 jours',
    'mgg_itin2_days' => '8 jours / 7 nuits',
    'mgg_itin2_route' => 'Serengeti du Nord + Ngorongoro (juil-sept)',
    'mgg_itin2_detail' => '<strong>Jour 1 :</strong> Arrivée à Arusha → transfert vers le Serengeti du Nord.<br><strong>Jours 2-4 :</strong> Journées complètes à la rivière Mara, en attente des traversées.<br><strong>Jour 5 :</strong> Nord → Serengeti central, game drive.<br><strong>Jour 6 :</strong> Journée complète au Serengeti central.<br><strong>Jour 7 :</strong> Serengeti → Ngorongoro, descente au cratère.<br><strong>Jour 8 :</strong> Ngorongoro → Arusha, départ.',
    'mgg_itin2_price' => 'À partir de 2 450 € par personne',

    'mgg_tips_title' => 'Conseils locaux : de guides qui suivent les troupeaux',
    'mgg_tips_p1' => 'Conseils d\'initiés de nos spécialistes de la migration, des choses que vous ne trouverez pas dans un guide de voyage.',
    'mgg_tip1' => '<strong>Le jeu de l\'attente</strong> — pour les traversées de rivière, préparez-vous à attendre. Les troupeaux peuvent mettre des heures à décider de traverser. Apportez des collations, de l\'eau et de la patience — le résultat en vaut la peine.',
    'mgg_tip2' => '<strong>Prédiction des traversées</strong> — les guides expérimentés peuvent prédire les traversées en observant les gnous se rassembler et faire les cent pas sur la berge. La tension est palpable avant une traversée.',
    'mgg_tip3' => '<strong>Le choix du camp compte</strong> — pour la saison des naissances, logez à Ndutu, pour les traversées de la Grumeti, logez dans le corridor occidental, pour les traversées de la Mara, logez dans le Serengeti du Nord. Choisir la bonne base économise des heures de conduite quotidiennes.',
    'mgg_tip4' => '<strong>Réservez tôt — vraiment tôt</strong> — pour la haute saison de migration (juillet-septembre), réservez l\'hébergement 6-12 mois à l\'avance. Les camps les mieux situés se réservent complets plus d\'un an à l\'avance.',
    'mgg_tip5' => '<strong>Suivez les prédateurs</strong> — la migration ne concerne pas seulement les gnous. Lions, guépards et léopards suivent les troupeaux, et les suivre mène souvent aux moments les plus spectaculaires.',
    'mgg_tip6' => '<strong>Photographie à l\'heure dorée</strong> — la meilleure lumière pour les traversées est au lever et au coucher du soleil. La lumière chaude rend le drame encore plus puissant.',
    'mgg_tip7' => '<strong>Bon rapport qualité-prix en saison intermédiaire</strong> — octobre-décembre et février offrent un excellent rapport qualité-prix, avec moins de monde et des prix plus bas tandis que l\'observation de la faune reste exceptionnelle.',
    'mgg_tip8' => '<strong>L\'assurance voyage est essentielle</strong> — l\'évacuation médicale depuis le Serengeti est coûteuse mais nécessaire. Assurez-vous que votre police couvre les activités de safari.',

    'mgg_faq_title' => 'Questions fréquentes',
    'mgg_faq_q1' => 'Quelle est la meilleure période pour voir la Grande Migration ?',
    'mgg_faq_a1' => 'Cela dépend de ce que vous voulez voir : naissances en janvier-février, traversées de la Grumeti en juin-juillet, traversées de la Mara en juillet-septembre, et retour au sud en octobre-décembre.',
    'mgg_faq_q2' => 'Où est le meilleur endroit pour voir la traversée des gnous ?',
    'mgg_faq_a2' => 'Les traversées de la rivière Mara dans le nord du Serengeti (juillet-septembre) sont les plus célèbres, tandis que les traversées de la rivière Grumeti (juin-juillet) sont également spectaculaires avec bien moins de monde.',
    'mgg_faq_q3' => 'Combien coûte un safari de migration ?',
    'mgg_faq_a3' => 'De 150-300 € par personne et par jour pour le camping économique, 300-600 € pour le milieu de gamme, et 800 €+ pour les lodges de luxe et camps mobiles.',
    'mgg_faq_q4' => 'Puis-je voir la migration en saison verte ?',
    'mgg_faq_a4' => 'Oui. La saison verte (mars-mai) offre des paysages luxuriants, moins de monde et des prix plus bas, avec les troupeaux se répartissant à travers le corridor occidental.',
    'mgg_faq_q5' => 'Combien de temps à l\'avance dois-je réserver un safari de migration ?',
    'mgg_faq_a5' => 'Pour la haute saison (juillet-septembre), réservez 6-12 mois à l\'avance. Pour la saison des naissances et les mois intermédiaires, 3-4 mois suffisent généralement.',
    'mgg_faq_q6' => 'La migration est-elle prévisible ?',
    'mgg_faq_a6' => 'La migration suit les pluies, mais le timing exact peut varier de quelques semaines chaque année. Les guides locaux suivent les conditions en temps réel pour prédire les mouvements.',
    'mgg_faq_q7' => 'Les enfants peuvent-ils participer à un safari de migration ?',
    'mgg_faq_a7' => 'Oui, la plupart des safaris de migration sont adaptés aux familles, et plusieurs lodges partenaires offrent des suites familiales et des activités pour enfants.',
    'mgg_faq_q8' => 'Quelle est la différence entre les traversées de la Grumeti et de la Mara ?',
    'mgg_faq_a8' => 'Les traversées de la Grumeti (juin-juillet) sont moins fréquentées avec de grands crocodiles. Les traversées de la Mara (juillet-septembre) sont plus célèbres, plus grandes en ampleur, et plus fréquentées.',

    'mgg_book_title' => 'Réservez votre safari de migration',
    'mgg_book_p1' => 'Indiquez-nous vos dates de voyage et notre spécialiste de la migration répondra sous 24 heures avec exactement ce que vous verrez et un prix exact.',
    'mgg_cta_title' => 'Prêt à assister au plus grand spectacle animalier ?',
    'mgg_cta_p' => 'Obtenez un devis gratuit et sans engagement d\'un opérateur local d\'Arusha qui suit les troupeaux toute l\'année.',
    'mgg_cta_button' => 'Obtenir votre devis gratuit',
    'mgg_share_label' => 'Partager ce guide :',
    'mgg_print' => 'Imprimer le guide',

