    'dtg_meta_title' => 'Le guide ultime des excursions d\'une journée en Tanzanie : circuits, prix et conseils locaux',
    'dtg_meta_description' => 'Le guide d\'excursions d\'une journée en Tanzanie le plus complet. Excursions safari, circuits culturels, randonnées d\'une journée au Kilimandjaro, prix, conseils locaux et forfaits de confiance d\'un opérateur local d\'Arusha.',

    'dtg_badge' => 'Le guide complet des excursions 2026',
    'dtg_h1' => 'Le guide ultime des excursions d\'une journée en Tanzanie',
    'dtg_price_highlight' => 'À partir de 50 €',
    'dtg_price_highlight_small' => 'par personne',
    'dtg_hero_intro' => 'Tout ce dont vous avez besoin avant de réserver : chaque option d\'excursion d\'une journée depuis Arusha et Moshi, prix honnêtes, secrets locaux, et, une fois que vous savez ce qui convient à votre journée, nos forfaits de confiance.',
