    'dtg_toc_faq' => 'FAQ',
    'dtg_toc_book' => 'Réserver maintenant',

    'dtg_intro_title' => 'La ressource ultime pour les excursions d\'une journée',
    'dtg_intro_p1' => 'La Tanzanie est un vaste pays avec une diversité incroyable d\'expériences, et vous n\'avez pas besoin d\'une semaine pour en profiter. Les excursions d\'une journée sont le moyen idéal d\'explorer les points forts, que vous soyez à Arusha, Moshi ou juste de passage lors d\'un safari plus long.',
    'dtg_intro_p2' => 'Ce qui rend ce guide différent ? Chaque excursion ici a été personnellement testée par notre équipe de guides locaux. Nous avons inclus des conseils d\'initiés et des astuces pratiques que vous ne trouverez nulle part ailleurs, que vous soyez un voyageur seul, un couple ou une famille.',
    'dtg_intro_box' => '<strong>Pourquoi nous faire confiance ?</strong> Notre équipe organise des excursions d\'une journée depuis plus de 15 ans. Nous connaissons les meilleurs guides, les meilleurs moments pour visiter et les endroits cachés que la plupart des touristes manquent. Ce guide est basé sur une expérience réelle, pas des informations génériques.',

    'dtg_trips_title' => 'Toutes les excursions : par catégorie',
    'dtg_trips_p1' => 'Ci-dessous, vous trouverez les principales catégories d\'excursions d\'une journée, organisées par type. Chacune a une tarification détaillée et des conseils locaux plus loin dans ce guide.',
    'dtg_trip1_name' => 'Excursions safari',
    'dtg_trip1_desc' => 'Cratère du Ngorongoro, Tarangire, lac Manyara et parc national d\'Arusha : une observation incroyable de la faune en quelques heures depuis Arusha ou Moshi.',
