    'dtg_tips_title' => 'Conseils locaux : de nos propres guides',
    'dtg_tips_p1' => 'Conseils d\'initiés de notre équipe de guides tanzaniens, des choses qui vous feront économiser du temps, de l\'argent et des déceptions.',
    'dtg_tip1' => '<strong>Partez tôt</strong> — pour le Ngorongoro, quittez Arusha avant 5h30 pour profiter de la meilleure action matinale des prédateurs. Le cratère devient fréquenté après 10h.',
    'dtg_tip2' => '<strong>La saison sèche concentre la faune</strong> — Tarangire de juin à octobre offre d\'incroyables troupeaux d\'éléphants autour de la rivière à mesure que l\'eau se raréfie ailleurs.',
    'dtg_tip3' => '<strong>Ne manquez pas la marche en forêt</strong> — au lac Manyara, la marche en forêt d\'eaux souterraines est souvent négligée mais c\'est un excellent moyen de voir de près les cercopithèques et les guibs harnachés.',
    'dtg_tip4' => '<strong>Réservez les excursions Hadzabe le matin</strong> — les Hadzabe chassent à l\'aube, donc une visite matinale vous offre l\'expérience la plus authentique de leur vie quotidienne.',
    'dtg_tip5' => '<strong>Combinez les excursions intelligemment</strong> — le lac Manyara et le village de Mto wa Mbu peuvent être combinés en une journée sans se sentir pressé, vous économisant une journée de voyage.',
    'dtg_tip6' => '<strong>Emportez des couches</strong> — les matinées peuvent être fraîches, surtout près du Ngorongoro et du Kilimandjaro, mais le soleil de midi est intense. Habillez-vous en couches que vous pouvez retirer.',
    'dtg_tip7' => '<strong>Confirmez l\'heure de prise en charge la veille</strong> — la circulation à Arusha peut varier ; une confirmation rapide par WhatsApp la veille au soir évite tout malentendu.',
    'dtg_tip8' => '<strong>Apportez des espèces pour les pourboires et souvenirs</strong> — les visites de villages et excursions culturelles sont un excellent endroit pour acheter de l\'artisanat authentique directement auprès des artisans, mais le paiement par carte est rarement disponible.',

    'dtg_prices_title' => 'Guide des prix des excursions',
    'dtg_prices_p1' => 'Les prix varient principalement selon la distance depuis Arusha et les frais d\'entrée de parc. Voici une répartition honnête.',
    'dtg_prices_th1' => 'Excursion',
    'dtg_prices_th2' => 'Distance depuis Arusha',
    'dtg_prices_th3' => 'Prix typique',
