    'dtg_prices_row5_price' => '140 €',
    'dtg_prices_row6_label' => 'Cratère du Ngorongoro',
    'dtg_prices_row6_dist' => '3 heures',
    'dtg_prices_row6_price' => '250 €',
    'dtg_prices_insider' => '<strong>Conseil d\'initié :</strong> la taille du groupe compte aussi ici : partager un véhicule avec 3-4 autres voyageurs peut réduire le prix par personne de 20-30 % par rapport à une excursion privée.',

    'dtg_best_time_title' => 'Meilleure période pour les excursions',
    'dtg_best_time_p1' => 'La plupart des excursions fonctionnent bien toute l\'année, mais quelques éléments changent avec les saisons.',
    'dtg_best_time_li1' => '<strong>Cratère du Ngorongoro :</strong> bon toute l\'année, mais les départs matinaux comptent le plus en saison sèche (juin-octobre) quand le cratère devient le plus fréquenté.',
    'dtg_best_time_li2' => '<strong>Tarangire :</strong> meilleur de juin à octobre quand la faune se concentre autour de la rivière pendant la saison sèche.',
    'dtg_best_time_li3' => '<strong>Excursions culturelles (Hadzabe, Mto wa Mbu) :</strong> bonnes toute l\'année, bien que les routes vers le lac Eyasi puissent être plus difficiles pendant les grandes pluies de mars à mai.',
    'dtg_best_time_li4' => '<strong>Randonnées d\'une journée au Kilimandjaro :</strong> vues les plus dégagées de juin à octobre et de janvier à mars, évitez les grandes pluies (mars-mai).',
    'dtg_best_time_box' => '<strong>Règle générale :</strong> si vous n\'avez qu\'une journée et voulez la plus grande chance de superbes photos de faune, visez juin-octobre et partez avant 6h.',

    'dtg_packing_title' => 'Quoi apporter',
    'dtg_packing_p1' => 'Une excursion d\'une journée nécessite bien moins qu\'un safari de plusieurs jours, mais quelques essentiels font une réelle différence.',
    'dtg_packing_li1' => 'Vêtements de couleurs neutres (kaki, olive, beige), évitez les couleurs vives et le blanc pur',
    'dtg_packing_li2' => 'Une veste légère ou une polaire pour les départs matinaux',
    'dtg_packing_li3' => 'Crème solaire, lunettes de soleil et chapeau à large bord',
    'dtg_packing_li4' => 'Jumelles, la plupart des véhicules d\'excursion ont de la place pour l\'équipement personnel',
    'dtg_packing_li5' => 'Un appareil photo avec zoom, plus des batteries de rechange',
    'dtg_packing_li6' => 'Des espèces (shillings tanzaniens ou USD) pour les pourboires et souvenirs',
    'dtg_packing_li7' => 'Une bouteille d\'eau réutilisable, l\'eau potable est fournie mais apportez une bouteille à remplir',

    'dtg_faq_title' => 'Questions fréquentes',
    'dtg_faq_q1' => 'Quelle est la meilleure excursion d\'une journée depuis Arusha ?',
    'dtg_faq_a1' => 'L\'excursion au cratère du Ngorongoro est la plus populaire pour la faune, mais Tarangire et l\'excursion culturelle Hadzabe sont d\'excellentes alternatives selon vos intérêts.',
    'dtg_faq_q2' => 'Combien coûte un safari d\'une journée en Tanzanie ?',
    'dtg_faq_a2' => 'Les safaris d\'une journée coûtent généralement entre 90 et 250 € par personne, selon le parc et la taille du groupe.',
    'dtg_faq_q3' => 'Puis-je visiter les Hadzabe en une journée ?',
    'dtg_faq_a3' => 'Oui, depuis Arusha ou Karatu, une excursion d\'une journée vers les tribus Hadzabe et Datoga près du lac Eyasi est tout à fait possible.',
    'dtg_faq_q4' => 'À quelle heure partent les excursions ?',
    'dtg_faq_a4' => 'La plupart partent entre 5h30 et 7h00 pour les excursions de faune, et vers 8h00 pour les excursions culturelles. Les départs plus précoces signifient généralement une meilleure observation de la faune.',
    'dtg_faq_q5' => 'Le déjeuner est-il inclus ?',
    'dtg_faq_a5' => 'Oui, chaque forfait d\'excursion inclut un déjeuner pique-nique et de l\'eau potable.',
    'dtg_faq_q6' => 'Puis-je combiner deux excursions en une journée ?',
    'dtg_faq_a6' => 'Certaines combinaisons fonctionnent bien (comme le lac Manyara avec le village de Mto wa Mbu), mais le Ngorongoro et Tarangire sont chacun mieux faits comme une journée complète dédiée.',
    'dtg_faq_q7' => 'Dois-je réserver à l\'avance ?',
    'dtg_faq_a7' => 'Un préavis de 2-3 jours suffit généralement, bien que la haute saison (juin-octobre) bénéficie d\'une réservation une semaine à l\'avance.',
    'dtg_faq_q8' => 'La prise en charge à l\'hôtel est-elle incluse ?',
    'dtg_faq_a8' => 'Oui, chaque excursion inclut la prise en charge et la dépose à votre hôtel à Arusha ou Moshi.',

    'dtg_book_title' => 'Réservez votre excursion',
    'dtg_book_p1' => 'Remplissez les détails ci-dessous et notre équipe répondra sous 24 heures avec la disponibilité et un prix exact.',
    'dtg_cta_title' => 'Prêt à profiter au maximum de votre journée ?',
    'dtg_cta_p' => 'Obtenez un devis gratuit et sans engagement d\'un opérateur local d\'Arusha : prix honnêtes, sans intermédiaires.',
    'dtg_cta_button' => 'Obtenir votre devis gratuit',
    'dtg_share_label' => 'Partager ce guide :',
    'dtg_print' => 'Imprimer le guide',

