    'carrental_why_intro' => 'Les routes, la circulation et les points de contrôle en Tanzanie sont plus faciles à gérer pour quelqu\'un qui les emprunte tous les jours. Vous vous détendez, nous gérons la route.',
    'carrental_why1_title' => 'Connaissance locale',
    'carrental_why1_desc' => 'Nos chauffeurs connaissent les raccourcis, les itinéraires sûrs et les meilleurs arrêts en chemin.',
